(** A stored value in its field's own terms. *)
type nonrec entry_field_value =
  | Text of { value : string  (** Free text. *) }  (** Free text. *)
  | Number of { value : float  (** A number. *) }  (** A number. *)
  | Checkbox of { value : bool  (** True or false. *) }  (** True or false. *)
  | Date of { value : string  (** A date-time. *) }  (** A date-time. *)
  | Date_range of {
      value : string;
          (** A span of time, written start/end: 2026-10-12/2026-10-16. *)
    }  (** A span of time, written start/end: 2026-10-12/2026-10-16. *)
  | Labels of {
      value : string list;  (** Option labels, in the cell's order. *)
    }  (** Option labels, in the cell's order. *)
  | Links of { value : string list  (** URLs. *) }  (** URLs. *)
  | References of {
      value : string list;
          (** Macro ids: people as macro| user ids, records or other items. *)
    }  (** Macro ids: people as macro| user ids, records or other items. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let entry_field_value_of_yojson : Yojson.Safe.t -> entry_field_value =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "text" -> Text { value = Json.required fields "value" Json.string }
  | "number" -> Number { value = Json.required fields "value" Json.float }
  | "checkbox" -> Checkbox { value = Json.required fields "value" Json.bool }
  | "date" -> Date { value = Json.required fields "value" Json.string }
  | "date_range" ->
      Date_range { value = Json.required fields "value" Json.string }
  | "labels" ->
      Labels { value = Json.required fields "value" (Json.list Json.string) }
  | "links" ->
      Links { value = Json.required fields "value" (Json.list Json.string) }
  | "references" ->
      References
        { value = Json.required fields "value" (Json.list Json.string) }
  | _ -> Unknown json

and yojson_of_entry_field_value : entry_field_value -> Yojson.Safe.t =
 fun value ->
  match value with
  | Text case ->
      Json.record
        [
          ("type", Some (`String "text"));
          ("value", Some (Json.of_string case.value));
        ]
  | Number case ->
      Json.record
        [
          ("type", Some (`String "number"));
          ("value", Some (Json.of_float case.value));
        ]
  | Checkbox case ->
      Json.record
        [
          ("type", Some (`String "checkbox"));
          ("value", Some (Json.of_bool case.value));
        ]
  | Date case ->
      Json.record
        [
          ("type", Some (`String "date"));
          ("value", Some (Json.of_string case.value));
        ]
  | Date_range case ->
      Json.record
        [
          ("type", Some (`String "date_range"));
          ("value", Some (Json.of_string case.value));
        ]
  | Labels case ->
      Json.record
        [
          ("type", Some (`String "labels"));
          ("value", Some ((Json.of_list Json.of_string) case.value));
        ]
  | Links case ->
      Json.record
        [
          ("type", Some (`String "links"));
          ("value", Some ((Json.of_list Json.of_string) case.value));
        ]
  | References case ->
      Json.record
        [
          ("type", Some (`String "references"));
          ("value", Some ((Json.of_list Json.of_string) case.value));
        ]
  | Unknown json -> json

let make_entry_field_value_text ~(value : string) () =
  (Text { value } : entry_field_value)

let make_entry_field_value_number ~(value : float) () =
  (Number { value } : entry_field_value)

let make_entry_field_value_checkbox ~(value : bool) () =
  (Checkbox { value } : entry_field_value)

let make_entry_field_value_date ~(value : string) () =
  (Date { value } : entry_field_value)

let make_entry_field_value_date_range ~(value : string) () =
  (Date_range { value } : entry_field_value)

let make_entry_field_value_labels ~(value : string list) () =
  (Labels { value } : entry_field_value)

let make_entry_field_value_links ~(value : string list) () =
  (Links { value } : entry_field_value)

let make_entry_field_value_references ~(value : string list) () =
  (References { value } : entry_field_value)

