and yojson_of_agent_mcp_server : agent_mcp_server -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("app_slug", Some (Json.of_string value.app_slug));
      ("server_name", Some (Json.of_string value.server_name));
    ]

let make_agent_mcp_server ~(app_slug : string) ~(server_name : string) () =
  ({ app_slug; server_name } : agent_mcp_server)

(** Which Pipedream MCP servers an agent's sessions are handed.

One value for the whole choice, so a selection can never travel without
its scope or a scope without its selection. Serialized with a [scope] tag,
which the generated TypeScript sees as a discriminated union. *)
type nonrec agent_mcp_servers =
  | Owner_connections
      (** Whatever apps the person running the session has connected. *)
  | Selected of {
      servers : agent_mcp_server list;
          (** The apps, in the order the agent's author picked them. *)
    }  (** Exactly these apps, connected or not. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let agent_mcp_servers_of_yojson : Yojson.Safe.t -> agent_mcp_servers =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "scope" with
  | "owner_connections" -> Owner_connections
  | "selected" ->
      Selected
        {
          servers =
            Json.required fields "servers"
              (Json.list agent_mcp_server_of_yojson);
        }
  | _ -> Unknown json

and yojson_of_agent_mcp_servers : agent_mcp_servers -> Yojson.Safe.t =
 fun value ->
  match value with
  | Owner_connections ->
      Json.record [ ("scope", Some (`String "owner_connections")) ]
  | Selected case ->
      Json.record
        [
          ("scope", Some (`String "selected"));
          ( "servers",
            Some ((Json.of_list yojson_of_agent_mcp_server) case.servers) );
        ]
  | Unknown json -> json

let make_agent_mcp_servers_selected ~(servers : agent_mcp_server list) () =
  (Selected { servers } : agent_mcp_servers)

(** Why an agent cannot run right now. *)
type nonrec agent_stopped_reason =
  | No_runtime_access
  | Unknown of string  (** A value this SDK version does not know. *)

let agent_stopped_reason_of_yojson : Yojson.Safe.t -> agent_stopped_reason =
 fun json ->
