  | "no_runtime_access" -> No_runtime_access
  | other -> Unknown other

and yojson_of_agent_stopped_reason : agent_stopped_reason -> Yojson.Safe.t =
 fun value ->
  match value with
  | No_runtime_access -> `String "no_runtime_access"
  | Unknown other -> `String other

type nonrec agent = {
  auto_accept_permissions : bool option;
      (** Whether the agent's sessions approve ACP permission requests without
asking. [None] means always prompt. Bypass also requires the harness's opt-in. *)
  bot : bot;
      (** The bot identity used for mentions and channel participation. *)
  channel_ids : string list;
      (** Selected channel ids. Empty for a global agent. *)
  channel_scope : agent_channel_scope;
      (** Whether the agent is global or channel-specific. *)
  default_model : string;  (** Model selected specifically for this agent. *)
  harness : string;  (** Harness used to run the agent. *)
  harness_id : harness_id option;
  instructions : string;
      (** Instructions supplied to the agent at the start of a conversation. *)
  is_coding : bool;
      (** Whether the agent works in a repository, which decides how it answers
a channel mention: a coding agent posts a magic chip into its live
session, a chat agent replies in the thread. Chosen in the agent's
settings; the persona's word, not the runtime's. *)
  mcp : agent_mcp_servers;
      (** Which MCP servers sessions of this agent are handed. *)
  stopped_reason : agent_stopped_reason option;
}
(** A persisted user- or team-owned AI agent. *)

let agent_of_yojson : Yojson.Safe.t -> agent =
 fun json ->
  let fields = Json.obj json in
  {
    auto_accept_permissions =
      Json.optional fields "auto_accept_permissions" Json.bool;
    bot = Json.required fields "bot" bot_of_yojson;
    channel_ids = Json.required fields "channel_ids" (Json.list Json.string);
    channel_scope =
      Json.required fields "channel_scope" agent_channel_scope_of_yojson;
    default_model = Json.required fields "default_model" Json.string;
    harness = Json.required fields "harness" Json.string;
    harness_id = Json.optional fields "harness_id" harness_id_of_yojson;
    instructions = Json.required fields "instructions" Json.string;
    is_coding = Json.required fields "is_coding" Json.bool;
    mcp = Json.required fields "mcp" agent_mcp_servers_of_yojson;
    stopped_reason =
      Json.optional fields "stopped_reason" agent_stopped_reason_of_yojson;
  }

and yojson_of_agent : agent -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "auto_accept_permissions",
        Option.map Json.of_bool value.auto_accept_permissions );
      ("bot", Some (yojson_of_bot value.bot));
      ("channel_ids", Some ((Json.of_list Json.of_string) value.channel_ids));
      ("channel_scope", Some (yojson_of_agent_channel_scope value.channel_scope));
      ("default_model", Some (Json.of_string value.default_model));
      ("harness", Some (Json.of_string value.harness));
      ("harness_id", Option.map yojson_of_harness_id value.harness_id);
      ("instructions", Some (Json.of_string value.instructions));
      ("is_coding", Some (Json.of_bool value.is_coding));
      ("mcp", Some (yojson_of_agent_mcp_servers value.mcp));
      ( "stopped_reason",
        Option.map yojson_of_agent_stopped_reason value.stopped_reason );
    ]

let make_agent ?auto_accept_permissions ~(bot : bot)
    ~(channel_ids : string list) ~(channel_scope : agent_channel_scope)
    ~(default_model : string) ~(harness : string) ?harness_id
    ~(instructions : string) ~(is_coding : bool) ~(mcp : agent_mcp_servers)
    ?stopped_reason () =
  ({
     auto_accept_permissions;
     bot;
     channel_ids;
     channel_scope;
     default_model;
     harness;
     harness_id;
     instructions;
     is_coding;
     mcp;
     stopped_reason;
   }
    : agent)

type nonrec agent_action_id = string
(** Identifies one accepted \[[AgentAction]\] end to end: returned by the
control endpoint, written as the JSON-RPC request id on the action's wire
frame, and read back off that frame as [request_id] on the folded message
it derives.

A v7 uuid, so ids sort by mint time. Minted by the server at accept time,
or by a client that speculated the action and named it in the control
request - either way the server is the only writer of runtime-bound
frames, so a uuid-shaped request id remains the whole ownership test. The
machine's own handshake request ids ([agent_session:{session}:{n}]) are
not uuids and stay [None]. *)

let agent_action_id_of_yojson : Yojson.Safe.t -> agent_action_id =
 fun json -> Json.string json

and yojson_of_agent_action_id : agent_action_id -> Yojson.Safe.t =
 fun value -> Json.of_string value

