(** Events publishable to \[[MacroAgentSessionLifecycleTopic]\].

The serde tag and \[[AgentSessionLifecycleEventName]\] spell the same wire
names: subscribers filter on them, so they are API. The
[event_names_match_the_wire] test holds the two in step. Exhaustive on
purpose: a consumer's match should break when a variant is added. *)
type nonrec agent_session_lifecycle_event =
  | Agent_session_opened of {
      metadata : session_opened_metadata;  (** A session was created. *)
    }  (** A session was created. *)
  | Agent_session_turn_started of {
      metadata : turn_started_metadata;
          (** A prompt was delivered to the runtime. *)
    }  (** A prompt was delivered to the runtime. *)
  | Agent_session_turn_ended of {
      metadata : turn_ended_metadata;  (** The runtime answered a turn. *)
    }  (** The runtime answered a turn. *)
  | Agent_session_command_rejected of {
      metadata : command_rejected_metadata;
          (** An accepted command was refused before runtime execution. *)
    }  (** An accepted command was refused before runtime execution. *)
  | Agent_session_settled of {
      metadata : session_settled_metadata;
          (** A turn ended with nothing queued behind it. *)
    }  (** A turn ended with nothing queued behind it. *)
  | Agent_session_waiting_for_input of {
      metadata : waiting_for_input_metadata;
          (** The agent is blocked on a question to its owner. *)
    }  (** The agent is blocked on a question to its owner. *)
  | Agent_session_input_received of {
      metadata : input_received_metadata;
          (** The question was answered or withdrawn. *)
    }  (** The question was answered or withdrawn. *)
  | Agent_session_mentioned of {
      metadata : session_mentioned_metadata;
          (** A prompt named other users who can open the session. *)
    }  (** A prompt named other users who can open the session. *)
  | Agent_session_stopped of {
      metadata : session_stopped_metadata;
          (** The session's live actor is gone. *)
    }  (** The session's live actor is gone. *)
  | Agent_session_renamed of {
      metadata : session_renamed_metadata;  (** The session was renamed. *)
    }  (** The session was renamed. *)
  | Agent_session_deleted of {
      metadata : session_deleted_metadata;  (** The session was deleted. *)
    }  (** The session was deleted. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let agent_session_lifecycle_event_of_yojson :
    Yojson.Safe.t -> agent_session_lifecycle_event =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "event_type" with
  | "agent_session.opened" ->
      Agent_session_opened
        {
          metadata =
            Json.required fields "metadata" session_opened_metadata_of_yojson;
        }
  | "agent_session.turn_started" ->
      Agent_session_turn_started
        {
          metadata =
            Json.required fields "metadata" turn_started_metadata_of_yojson;
        }
  | "agent_session.turn_ended" ->
      Agent_session_turn_ended
        {
          metadata =
            Json.required fields "metadata" turn_ended_metadata_of_yojson;
        }
  | "agent_session.command_rejected" ->
      Agent_session_command_rejected
        {
          metadata =
            Json.required fields "metadata" command_rejected_metadata_of_yojson;
        }
  | "agent_session.settled" ->
      Agent_session_settled
        {
          metadata =
            Json.required fields "metadata" session_settled_metadata_of_yojson;
        }
  | "agent_session.waiting_for_input" ->
      Agent_session_waiting_for_input
        {
          metadata =
            Json.required fields "metadata" waiting_for_input_metadata_of_yojson;
        }
  | "agent_session.input_received" ->
      Agent_session_input_received
        {
          metadata =
            Json.required fields "metadata" input_received_metadata_of_yojson;
        }
  | "agent_session.mentioned" ->
      Agent_session_mentioned
        {
          metadata =
            Json.required fields "metadata" session_mentioned_metadata_of_yojson;
        }
  | "agent_session.stopped" ->
      Agent_session_stopped
        {
          metadata =
            Json.required fields "metadata" session_stopped_metadata_of_yojson;
        }
  | "agent_session.renamed" ->
      Agent_session_renamed
        {
          metadata =
            Json.required fields "metadata" session_renamed_metadata_of_yojson;
        }
  | "agent_session.deleted" ->
      Agent_session_deleted
        {
          metadata =
            Json.required fields "metadata" session_deleted_metadata_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_agent_session_lifecycle_event :
    agent_session_lifecycle_event -> Yojson.Safe.t =
 fun value ->
  match value with
  | Agent_session_opened case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.opened"));
          ("metadata", Some (yojson_of_session_opened_metadata case.metadata));
        ]
  | Agent_session_turn_started case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.turn_started"));
          ("metadata", Some (yojson_of_turn_started_metadata case.metadata));
        ]
  | Agent_session_turn_ended case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.turn_ended"));
          ("metadata", Some (yojson_of_turn_ended_metadata case.metadata));
        ]
  | Agent_session_command_rejected case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.command_rejected"));
          ("metadata", Some (yojson_of_command_rejected_metadata case.metadata));
        ]
  | Agent_session_settled case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.settled"));
          ("metadata", Some (yojson_of_session_settled_metadata case.metadata));
        ]
  | Agent_session_waiting_for_input case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.waiting_for_input"));
          ("metadata", Some (yojson_of_waiting_for_input_metadata case.metadata));
        ]
  | Agent_session_input_received case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.input_received"));
          ("metadata", Some (yojson_of_input_received_metadata case.metadata));
        ]
  | Agent_session_mentioned case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.mentioned"));
          ("metadata", Some (yojson_of_session_mentioned_metadata case.metadata));
        ]
  | Agent_session_stopped case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.stopped"));
          ("metadata", Some (yojson_of_session_stopped_metadata case.metadata));
        ]
  | Agent_session_renamed case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.renamed"));
          ("metadata", Some (yojson_of_session_renamed_metadata case.metadata));
        ]
  | Agent_session_deleted case ->
      Json.record
        [
          ("event_type", Some (`String "agent_session.deleted"));
          ("metadata", Some (yojson_of_session_deleted_metadata case.metadata));
        ]
  | Unknown json -> json

let make_agent_session_lifecycle_event_agent_session_opened
    ~(metadata : session_opened_metadata) () =
  (Agent_session_opened { metadata } : agent_session_lifecycle_event)

