type nonrec annotation_incremental_update =
  | Create_anchor of {
      payload : annotation_incremental_update_create_anchor_payload;
    }
  | Edit_anchor of {
      payload : annotation_incremental_update_edit_anchor_payload;
    }
  | Delete_anchor of {
      payload : annotation_incremental_update_delete_anchor_payload;
    }
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let annotation_incremental_update_of_yojson :
    Yojson.Safe.t -> annotation_incremental_update =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "updateType" with
  | "create-anchor" ->
      Create_anchor
        {
          payload =
            Json.required fields "payload"
              annotation_incremental_update_create_anchor_payload_of_yojson;
        }
  | "edit-anchor" ->
      Edit_anchor
        {
          payload =
            Json.required fields "payload"
              annotation_incremental_update_edit_anchor_payload_of_yojson;
        }
  | "delete-anchor" ->
      Delete_anchor
        {
          payload =
            Json.required fields "payload"
              annotation_incremental_update_delete_anchor_payload_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_annotation_incremental_update :
    annotation_incremental_update -> Yojson.Safe.t =
 fun value ->
  match value with
  | Create_anchor case ->
      Json.record
        [
          ("updateType", Some (`String "create-anchor"));
          ( "payload",
            Some
              (yojson_of_annotation_incremental_update_create_anchor_payload
                 case.payload) );
        ]
  | Edit_anchor case ->
      Json.record
        [
          ("updateType", Some (`String "edit-anchor"));
          ( "payload",
            Some
              (yojson_of_annotation_incremental_update_edit_anchor_payload
                 case.payload) );
        ]
  | Delete_anchor case ->
      Json.record
        [
          ("updateType", Some (`String "delete-anchor"));
          ( "payload",
            Some
              (yojson_of_annotation_incremental_update_delete_anchor_payload
                 case.payload) );
        ]
  | Unknown json -> json

let make_annotation_incremental_update_create_anchor
    ~(payload : annotation_incremental_update_create_anchor_payload) () =
  (Create_anchor { payload } : annotation_incremental_update)

let make_annotation_incremental_update_edit_anchor
    ~(payload : annotation_incremental_update_edit_anchor_payload) () =
  (Edit_anchor { payload } : annotation_incremental_update)

let make_annotation_incremental_update_delete_anchor
    ~(payload : annotation_incremental_update_delete_anchor_payload) () =
  (Delete_anchor { payload } : annotation_incremental_update)

type nonrec date_range = {
  end_ : string;  (** Where it ends; never before the start. *)
  start : string;  (** Where it starts. *)
}
(** A span of time from [start] to [end], both included. A write whose end
comes before its start is refused. *)

let date_range_of_yojson : Yojson.Safe.t -> date_range =
 fun json ->
  let fields = Json.obj json in
  {
    end_ = Json.required fields "end" Json.string;
    start = Json.required fields "start" Json.string;
  }

and yojson_of_date_range : date_range -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("end", Some (Json.of_string value.end_));
      ("start", Some (Json.of_string value.start));
    ]

let make_date_range ~(end_ : string) ~(start : string) () =
  ({ end_; start } : date_range)

(** A select option, by its id or by its label. *)
type nonrec option_ref =
  | Id of string  (** An option the column has. *)
  | Label of string
      (** An option's label, matched without regard to case. An unknown label
is refused. *)

let option_ref_of_yojson : Yojson.Safe.t -> option_ref =
 fun json ->
  match Json.external_case json with
  | "id", value -> Id (Json.string (Json.payload "id" value))
  | "label", value -> Label (Json.string (Json.payload "label" value))
  | name, _ -> Json.fail "unknown case %S" name

and yojson_of_option_ref : option_ref -> Yojson.Safe.t =
 fun value ->
  match value with
  | Id inner -> Json.external_value "id" (Json.of_string inner)
  | Label inner -> Json.external_value "label" (Json.of_string inner)

(** A kind of Macro entity a reference column can point at. *)
type nonrec entity_kind =
  | User
  | Document
  | Task
  | Company
  | Contact
  | Call_record
  | Channel
  | Chat
  | Project
  | Thread
  | Calendar_event
  | Initiative
  | Unknown of string  (** A value this SDK version does not know. *)

let entity_kind_of_yojson : Yojson.Safe.t -> entity_kind =
 fun json ->
  match Json.string json with
  | "USER" -> User
  | "DOCUMENT" -> Document
  | "TASK" -> Task
  | "COMPANY" -> Company
  | "CONTACT" -> Contact
  | "CALL_RECORD" -> Call_record
  | "CHANNEL" -> Channel
  | "CHAT" -> Chat
  | "PROJECT" -> Project
  | "THREAD" -> Thread
  | "CALENDAR_EVENT" -> Calendar_event
  | "INITIATIVE" -> Initiative
  | other -> Unknown other

and yojson_of_entity_kind : entity_kind -> Yojson.Safe.t =
 fun value ->
  match value with
  | User -> `String "USER"
  | Document -> `String "DOCUMENT"
  | Task -> `String "TASK"
  | Company -> `String "COMPANY"
  | Contact -> `String "CONTACT"
  | Call_record -> `String "CALL_RECORD"
  | Channel -> `String "CHANNEL"
  | Chat -> `String "CHAT"
  | Project -> `String "PROJECT"
  | Thread -> `String "THREAD"
  | Calendar_event -> `String "CALENDAR_EVENT"
  | Initiative -> `String "INITIATIVE"
  | Unknown other -> `String other

type nonrec entity_ref = {
  entity_id : string;  (** The entity's id. *)
  entity_type : entity_kind;
      (** What kind of entity it is; it must be the kind the column points at. *)
}
(** A reference to one Macro entity. *)

let entity_ref_of_yojson : Yojson.Safe.t -> entity_ref =
 fun json ->
  let fields = Json.obj json in
  {
    entity_id = Json.required fields "entityId" Json.string;
    entity_type = Json.required fields "entityType" entity_kind_of_yojson;
  }

and yojson_of_entity_ref : entity_ref -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("entityId", Some (Json.of_string value.entity_id));
      ("entityType", Some (yojson_of_entity_kind value.entity_type));
    ]

let make_entity_ref ~(entity_id : string) ~(entity_type : entity_kind) () =
  ({ entity_id; entity_type } : entity_ref)

(** A cell's value. It must fit the column's type: text for a text column,
options of the column for a select, and so on. *)
type nonrec cell_value =
  | Text of { value : string  (** Free text. *) }  (** Free text. *)
  | Number of { value : float  (** A finite number. *) }
      (** A finite number. *)
  | Boolean of { value : bool  (** A checkbox. *) }  (** A checkbox. *)
  | Date of { value : string  (** A date-time. *) }  (** A date-time. *)
  | Date_range of {
      value : date_range;
          (** A span of time; its end may not come before its start. *)
    }  (** A span of time; its end may not come before its start. *)
  | Link of {
      value : string list;
          (** Complete http or https URLs; at most one for a single-valued column. *)
    }
      (** Complete http or https URLs; at most one for a single-valued column. *)
  | Options of {
      value : option_ref list;
          (** Options of a select or tag column; at most one for a single-valued
column. *)
    }
      (** Options of a select or tag column; at most one for a single-valued
column. *)
  | Entities of {
      value : entity_ref list;
          (** References to Macro entities of the kind the column points at; at
most one for a single-valued column. *)
    }
      (** References to Macro entities of the kind the column points at; at
most one for a single-valued column. *)
  | Rows of {
      value : string list;  (** Rows of the table a relation column points at. *)
    }  (** Rows of the table a relation column points at. *)
  | Clear  (** No value: the cell is emptied. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let cell_value_of_yojson : Yojson.Safe.t -> cell_value =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "text" -> Text { value = Json.required fields "value" Json.string }
  | "number" -> Number { value = Json.required fields "value" Json.float }
  | "boolean" -> Boolean { value = Json.required fields "value" Json.bool }
  | "date" -> Date { value = Json.required fields "value" Json.string }
  | "date_range" ->
      Date_range { value = Json.required fields "value" date_range_of_yojson }
  | "link" ->
      Link { value = Json.required fields "value" (Json.list Json.string) }
  | "options" ->
      Options
        {
          value = Json.required fields "value" (Json.list option_ref_of_yojson);
        }
  | "entities" ->
      Entities
        {
          value = Json.required fields "value" (Json.list entity_ref_of_yojson);
        }
  | "rows" ->
      Rows { value = Json.required fields "value" (Json.list Json.string) }
  | "clear" -> Clear
  | _ -> Unknown json

and yojson_of_cell_value : cell_value -> Yojson.Safe.t =
 fun value ->
  match value with
  | Text case ->
      Json.record
        [
          ("type", Some (`String "text"));
          ("value", Some (Json.of_string case.value));
        ]
  | Number case ->
      Json.record
        [
          ("type", Some (`String "number"));
          ("value", Some (Json.of_float case.value));
        ]
  | Boolean case ->
      Json.record
        [
          ("type", Some (`String "boolean"));
          ("value", Some (Json.of_bool case.value));
        ]
  | Date case ->
      Json.record
        [
          ("type", Some (`String "date"));
          ("value", Some (Json.of_string case.value));
        ]
  | Date_range case ->
      Json.record
        [
          ("type", Some (`String "date_range"));
          ("value", Some (yojson_of_date_range case.value));
        ]
  | Link case ->
      Json.record
        [
          ("type", Some (`String "link"));
          ("value", Some ((Json.of_list Json.of_string) case.value));
        ]
  | Options case ->
      Json.record
        [
          ("type", Some (`String "options"));
          ("value", Some ((Json.of_list yojson_of_option_ref) case.value));
        ]
  | Entities case ->
      Json.record
        [
          ("type", Some (`String "entities"));
          ("value", Some ((Json.of_list yojson_of_entity_ref) case.value));
        ]
  | Rows case ->
      Json.record
        [
          ("type", Some (`String "rows"));
          ("value", Some ((Json.of_list Json.of_string) case.value));
        ]
  | Clear -> Json.record [ ("type", Some (`String "clear")) ]
  | Unknown json -> json

let make_cell_value_text ~(value : string) () = (Text { value } : cell_value)
let make_cell_value_number ~(value : float) () = (Number { value } : cell_value)

let make_cell_value_boolean ~(value : bool) () =
  (Boolean { value } : cell_value)

let make_cell_value_date ~(value : string) () = (Date { value } : cell_value)

let make_cell_value_date_range ~(value : date_range) () =
  (Date_range { value } : cell_value)

let make_cell_value_link ~(value : string list) () =
  (Link { value } : cell_value)

let make_cell_value_options ~(value : option_ref list) () =
  (Options { value } : cell_value)

let make_cell_value_entities ~(value : entity_ref list) () =
  (Entities { value } : cell_value)

let make_cell_value_rows ~(value : string list) () =
  (Rows { value } : cell_value)

type nonrec answer = {
  question : string;  (** The question. *)
  value : cell_value;  (** The value; [clear] for no answer. *)
}
(** One question's answer: a value for its column, typed as the column's
cells are. *)

let answer_of_yojson : Yojson.Safe.t -> answer =
 fun json ->
  let fields = Json.obj json in
  {
    question = Json.required fields "question" Json.string;
    value = Json.required fields "value" cell_value_of_yojson;
  }

and yojson_of_answer : answer -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("question", Some (Json.of_string value.question));
      ("value", Some (yojson_of_cell_value value.value));
    ]

let make_answer ~(question : string) ~(value : cell_value) () =
  ({ question; value } : answer)

