    ?next_cursor () =
  ({ items; next_cursor } : api_channel_list_page)

(** The CRM record an association filter names. *)
type nonrec crm_association =
  | Company of string
      (** Items associated with the company or with any of its contacts. *)
  | Contact of string  (** Items associated with the contact. *)
  | Activity
      (** Activity across visible CRM-enabled teams, excluding hidden records. *)

let crm_association_of_yojson : Yojson.Safe.t -> crm_association =
 fun json ->
  match Json.external_case json with
  | "company", value -> Company (Json.string (Json.payload "company" value))
  | "contact", value -> Contact (Json.string (Json.payload "contact" value))
  | "activity", None -> Activity
  | name, _ -> Json.fail "unknown case %S" name

and yojson_of_crm_association : crm_association -> Yojson.Safe.t =
 fun value ->
  match value with
  | Company inner -> Json.external_value "company" (Json.of_string inner)
  | Contact inner -> Json.external_value "contact" (Json.of_string inner)
  | Activity -> `String "activity"

type nonrec api_entity_filter_ast = {
  asf : Yojson.Safe.t option;
      (** Filters applied to agent sessions (wire key [asf]). An empty or
omitted filter returns **no** agent sessions: they are opt-in, so the
caller must send [inc], an id, or an owner to get any. *)
  calf : Yojson.Safe.t option;
      (** filters applied to canonical calendar events *)
  callf : Yojson.Safe.t option;
      (** the filters that should be applied to the call entity *)
  ccf : Yojson.Safe.t option;
      (** Filters applied to the crm_company entity (wire key [ccf]).
Empty/omitted = team's full visible list. *)
  cf : Yojson.Safe.t option;
      (** the filters that should be applied to the chat entity *)
  chanf : Yojson.Safe.t option;
      (** the filters that should be applied to the channel entity *)
  crma : crm_association option;
  crmf : Yojson.Safe.t option;
      (** Opt-in filters for viewer-accessible CRM contacts (wire key [crmf]). *)
  cthf : Yojson.Safe.t option;
      (** the filters that should be applied to the channel-thread entity *)
  df : Yojson.Safe.t option;
      (** the filters that should be applied to the document entity *)
  eca : string list option;
      (** CRM-scoped address filter (wire key: [eca]). Symmetric counterpart
to [ecd] for fully-qualified email addresses. *)
  ecd : string list option;
      (** CRM-scoped domain filter (wire key: [ecd]). Parallel to the
freeform [ef] AST. Expanded by the router into an any-direction
OR sub-tree AND-merged into [ef], plus a [CrmScope] tag stamped
on the resulting \[[item_filters::ast::EmailFilterAst::crm_scope]\].
Drives the per-team CRM authorization pre-check and candidate-set
widening downstream. Mutually exclusive with [eca]. *)
  ef : Yojson.Safe.t option;
      (** the filters that should be applied to the email entity (raw AST
tree only; CRM scope is carried by the [ecd] / [eca] sibling
fields). On this endpoint the email filter stays a bare tree,
unlike the materialized \[[EntityFilterAst]\] used for cursors. *)
  favorites_only : bool option;
      (** Restrict to the authenticated viewer's favorites before pagination when true. *)
  fef : Yojson.Safe.t option;
      (** the filters that should be applied to foreign entity records *)
  ghprf : Yojson.Safe.t option;
      (** the filters that should be applied to GitHub pull request records, on top of [fef] *)
  if_ : Yojson.Safe.t option;
      (** Filters applied to initiatives (wire key [if]). Opt-in like agent
sessions: an omitted filter returns no initiatives, and any literal,
a notification state included, opts them in. *)
  pf : Yojson.Safe.t option;
      (** the filters that should be applied to the project entity *)
  propf : Yojson.Safe.t option;
      (** the filters that should be applied based on entity properties *)
}
(** Wire-format entity filter AST accepted by soup AST endpoints. *)

let api_entity_filter_ast_of_yojson : Yojson.Safe.t -> api_entity_filter_ast =
 fun json ->
  let fields = Json.obj json in
  {
    asf = Json.optional fields "asf" Json.json;
    calf = Json.optional fields "calf" Json.json;
    callf = Json.optional fields "callf" Json.json;
    ccf = Json.optional fields "ccf" Json.json;
    cf = Json.optional fields "cf" Json.json;
    chanf = Json.optional fields "chanf" Json.json;
    crma = Json.optional fields "crma" crm_association_of_yojson;
    crmf = Json.optional fields "crmf" Json.json;
    cthf = Json.optional fields "cthf" Json.json;
    df = Json.optional fields "df" Json.json;
    eca = Json.optional fields "eca" (Json.list Json.string);
    ecd = Json.optional fields "ecd" (Json.list Json.string);
    ef = Json.optional fields "ef" Json.json;
    favorites_only = Json.optional fields "favorites_only" Json.bool;
    fef = Json.optional fields "fef" Json.json;
    ghprf = Json.optional fields "ghprf" Json.json;
    if_ = Json.optional fields "if" Json.json;
    pf = Json.optional fields "pf" Json.json;
    propf = Json.optional fields "propf" Json.json;
  }

and yojson_of_api_entity_filter_ast : api_entity_filter_ast -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("asf", Option.map Json.of_json value.asf);
      ("calf", Option.map Json.of_json value.calf);
      ("callf", Option.map Json.of_json value.callf);
      ("ccf", Option.map Json.of_json value.ccf);
      ("cf", Option.map Json.of_json value.cf);
      ("chanf", Option.map Json.of_json value.chanf);
      ("crma", Option.map yojson_of_crm_association value.crma);
      ("crmf", Option.map Json.of_json value.crmf);
      ("cthf", Option.map Json.of_json value.cthf);
      ("df", Option.map Json.of_json value.df);
      ("eca", Option.map (Json.of_list Json.of_string) value.eca);
      ("ecd", Option.map (Json.of_list Json.of_string) value.ecd);
      ("ef", Option.map Json.of_json value.ef);
      ("favorites_only", Option.map Json.of_bool value.favorites_only);
      ("fef", Option.map Json.of_json value.fef);
      ("ghprf", Option.map Json.of_json value.ghprf);
      ("if", Option.map Json.of_json value.if_);
      ("pf", Option.map Json.of_json value.pf);
      ("propf", Option.map Json.of_json value.propf);
    ]

let make_api_entity_filter_ast ?asf ?calf ?callf ?ccf ?cf ?chanf ?crma ?crmf
    ?cthf ?df ?eca ?ecd ?ef ?favorites_only ?fef ?ghprf ?if_ ?pf ?propf () =
  ({
     asf;
     calf;
     callf;
     ccf;
     cf;
     chanf;
     crma;
     crmf;
     cthf;
     df;
     eca;
     ecd;
     ef;
     favorites_only;
     fef;
     ghprf;
     if_;
     pf;
     propf;
   }
    : api_entity_filter_ast)

type nonrec property_date_range = {
  end_ : string option;  (** Exclusive end, or positive infinity. *)
  key : string;  (** Unique caller-supplied group key. *)
  start : string option;  (** Inclusive start, or negative infinity. *)
}
(** A half-open UTC interval. An absent start or end extends to infinity. *)

let property_date_range_of_yojson : Yojson.Safe.t -> property_date_range =
 fun json ->
  let fields = Json.obj json in
  {
    end_ = Json.optional fields "end" Json.string;
    key = Json.required fields "key" Json.string;
    start = Json.optional fields "start" Json.string;
  }

and yojson_of_property_date_range : property_date_range -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("end", Option.map Json.of_string value.end_);
      ("key", Some (Json.of_string value.key));
      ("start", Option.map Json.of_string value.start);
    ]

let make_property_date_range ?end_ ~(key : string) ?start () =
  ({ end_; key; start } : property_date_range)

type nonrec property_date_ranges = {
  missing_value_bucket_key : string;
      (** Caller-supplied group key for entities with no date value. *)
  ranges : property_date_range list;
      (** Ordered, contiguous ranges covering every present date. *)
}
(** A complete partition of present dates plus one bucket for absent values. *)

let property_date_ranges_of_yojson : Yojson.Safe.t -> property_date_ranges =
 fun json ->
  let fields = Json.obj json in
  {
    missing_value_bucket_key =
      Json.required fields "missing_value_bucket_key" Json.string;
    ranges =
      Json.required fields "ranges" (Json.list property_date_range_of_yojson);
  }

and yojson_of_property_date_ranges : property_date_ranges -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "missing_value_bucket_key",
        Some (Json.of_string value.missing_value_bucket_key) );
      ( "ranges",
        Some ((Json.of_list yojson_of_property_date_range) value.ranges) );
    ]

let make_property_date_ranges ~(missing_value_bucket_key : string)
    ~(ranges : property_date_range list) () =
  ({ missing_value_bucket_key; ranges } : property_date_ranges)

(** Optional transformation of a selected property's stored value into group keys. *)
type nonrec property_bucketing =
  | Date_ranges of property_date_ranges
      (** Caller-defined, ordered UTC date ranges and a separate missing-value key. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let property_bucketing_of_yojson : Yojson.Safe.t -> property_bucketing =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "date_ranges" -> Date_ranges (property_date_ranges_of_yojson json)
  | _ -> Unknown json

and yojson_of_property_bucketing : property_bucketing -> Yojson.Safe.t =
 fun value ->
  match value with
  | Date_ranges inner ->
      Json.with_tag "type" "date_ranges" (yojson_of_property_date_ranges inner)
  | Unknown json -> json

