type nonrec table_version = int64
(** Monotonic per-table version, bumped once by every committed change to a
table's schema or rows. Schema edits name the version they were made
against, and change events carry the new one. *)

let table_version_of_yojson : Yojson.Safe.t -> table_version =
 fun json -> Json.int64 json

and yojson_of_table_version : table_version -> Yojson.Safe.t =
 fun value -> Json.of_int64 value

type nonrec committed_change = {
  change : int64;  (** The journal's id of the change. *)
  table : string;  (** The table. *)
  version : table_version;  (** The version the batch produced. *)
}
(** One change a committed batch journaled: a table, the version the batch
produced, and the journal's id for it. *)

let committed_change_of_yojson : Yojson.Safe.t -> committed_change =
 fun json ->
  let fields = Json.obj json in
  {
    change = Json.required fields "change" Json.int64;
    table = Json.required fields "table" Json.string;
    version = Json.required fields "version" table_version_of_yojson;
  }

and yojson_of_committed_change : committed_change -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("change", Some (Json.of_int64 value.change));
      ("table", Some (Json.of_string value.table));
      ("version", Some (yojson_of_table_version value.version));
    ]

let make_committed_change ~(change : int64) ~(table : string)
    ~(version : table_version) () =
  ({ change; table; version } : committed_change)

