(** What happened to a table. *)
type nonrec table_result =
  | Created  (** It was added. *)
  | Renamed  (** It was renamed. *)
  | Deleted  (** It was removed. *)
  | Columns_reordered  (** Its columns were reordered. *)
  | Views_reordered of {
      positions : view_position list;
          (** Every view's key, in their new order. *)
    }  (** Its views were reordered. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let table_result_of_yojson : Yojson.Safe.t -> table_result =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "created" -> Created
  | "renamed" -> Renamed
  | "deleted" -> Deleted
  | "columns_reordered" -> Columns_reordered
  | "views_reordered" ->
      Views_reordered
        {
          positions =
            Json.required fields "positions" (Json.list view_position_of_yojson);
        }
  | _ -> Unknown json

and yojson_of_table_result : table_result -> Yojson.Safe.t =
 fun value ->
  match value with
  | Created -> Json.record [ ("kind", Some (`String "created")) ]
  | Renamed -> Json.record [ ("kind", Some (`String "renamed")) ]
  | Deleted -> Json.record [ ("kind", Some (`String "deleted")) ]
  | Columns_reordered ->
      Json.record [ ("kind", Some (`String "columns_reordered")) ]
  | Views_reordered case ->
      Json.record
        [
          ("kind", Some (`String "views_reordered"));
          ( "positions",
            Some ((Json.of_list yojson_of_view_position) case.positions) );
        ]
  | Unknown json -> json

let make_table_result_views_reordered ~(positions : view_position list) () =
  (Views_reordered { positions } : table_result)

(** What happened to a column. *)
type nonrec column_result =
  | Created  (** It was added. *)
  | Renamed  (** It was renamed. *)
  | Type_changed  (** Its type changed, and its cells with it. *)
  | Deleted  (** It was removed. *)
  | Options_added of {
      added : string list;
          (** The options created, in order: those sent, less any whose label
the column already had. *)
    }  (** It gained options. *)
  | Option_updated  (** One of its options was relabelled or recoloured. *)
  | Option_deleted  (** One of its options was removed. *)
  | Formula_set  (** Its formula changed. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let column_result_of_yojson : Yojson.Safe.t -> column_result =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "created" -> Created
  | "renamed" -> Renamed
  | "type_changed" -> Type_changed
  | "deleted" -> Deleted
  | "options_added" ->
      Options_added
        { added = Json.required fields "added" (Json.list Json.string) }
  | "option_updated" -> Option_updated
  | "option_deleted" -> Option_deleted
  | "formula_set" -> Formula_set
  | _ -> Unknown json

and yojson_of_column_result : column_result -> Yojson.Safe.t =
 fun value ->
  match value with
  | Created -> Json.record [ ("kind", Some (`String "created")) ]
  | Renamed -> Json.record [ ("kind", Some (`String "renamed")) ]
  | Type_changed -> Json.record [ ("kind", Some (`String "type_changed")) ]
  | Deleted -> Json.record [ ("kind", Some (`String "deleted")) ]
  | Options_added case ->
      Json.record
        [
          ("kind", Some (`String "options_added"));
          ("added", Some ((Json.of_list Json.of_string) case.added));
        ]
  | Option_updated -> Json.record [ ("kind", Some (`String "option_updated")) ]
  | Option_deleted -> Json.record [ ("kind", Some (`String "option_deleted")) ]
  | Formula_set -> Json.record [ ("kind", Some (`String "formula_set")) ]
  | Unknown json -> json

let make_column_result_options_added ~(added : string list) () =
  (Options_added { added } : column_result)

(** What happened to a table's rows. *)
type nonrec rows_result =
  | Inserted of {
      rows : string list;  (** The new rows, in the order they were sent. *)
    }  (** Rows were added. *)
  | Updated of { affected : int  (** How many rows the op updated. *) }
      (** Rows' cells were written. *)
  | Deleted of { affected : int  (** How many rows the op deleted. *) }
      (** Rows were removed. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let rows_result_of_yojson : Yojson.Safe.t -> rows_result =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "inserted" ->
      Inserted { rows = Json.required fields "rows" (Json.list Json.string) }
  | "updated" -> Updated { affected = Json.required fields "affected" Json.int }
  | "deleted" -> Deleted { affected = Json.required fields "affected" Json.int }
  | _ -> Unknown json

and yojson_of_rows_result : rows_result -> Yojson.Safe.t =
 fun value ->
  match value with
  | Inserted case ->
      Json.record
        [
          ("kind", Some (`String "inserted"));
          ("rows", Some ((Json.of_list Json.of_string) case.rows));
        ]
  | Updated case ->
      Json.record
        [
          ("kind", Some (`String "updated"));
          ("affected", Some (Json.of_int case.affected));
        ]
  | Deleted case ->
      Json.record
        [
          ("kind", Some (`String "deleted"));
          ("affected", Some (Json.of_int case.affected));
        ]
  | Unknown json -> json

let make_rows_result_inserted ~(rows : string list) () =
  (Inserted { rows } : rows_result)

let make_rows_result_updated ~(affected : int) () =
  (Updated { affected } : rows_result)

let make_rows_result_deleted ~(affected : int) () =
