  {
    hidden = Json.optional fields "hidden" Json.bool;
    key = Json.required fields "key" lane_key_of_yojson;
  }

and yojson_of_lane : lane -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("hidden", Option.map Json.of_bool value.hidden);
      ("key", Some (yojson_of_lane_key value.key));
    ]

