(** How a view draws its rows. *)
type nonrec view_layout =
  | Table of {
      columns : view_column list;
          (** How columns show, in display order. A column left out shows
after the listed ones, in the table's order. *)
    }  (** A grid with a row per row. *)
  | Board of {
      card_fields : string list;
          (** The columns a card shows under its title, in order. *)
      group_by : string;
          (** The single-select or single-person column whose values are the
lanes; moving a card to another lane sets this column. *)
      hide_empty_lanes : bool;  (** Whether a lane with no cards is hidden. *)
      lanes : lane list;
          (** How lanes show, in display order. A lane left out shows after the
listed ones: the lane of empty cells first, then options in the
column's order, or people by id. *)
      title : string;
          (** The column a card is titled by, of any type. Removing it titles
the cards by the table's first remaining column. *)
    }
      (** Cards in lanes: one lane per option of a single-select column, or
one per person a single-person column names, plus one for cards
with an empty cell. A multi-valued column cannot group a board: a
card is in exactly one lane, so a card in several would need a place
in each. *)
  | Timeline of {
      bar_fields : string list option;
          (** The columns a bar shows after its title, in order. *)
      color_by : string option;
          (** The select or tag column whose options color the bars, if any. *)
      group_by : string option;
          (** The single-select or single-person column whose values group the
bars, if any; moving a bar to another group sets this column. *)
      range : string;  (** The date-range column whose cells are the bars. *)
      title : string;
          (** The column a bar is labelled by, of any type. Removing it labels
the bars by the table's first remaining column. *)
    }
      (** Bars on a calendar, one per row, spanning its date-range cell. Rows
with an empty range are listed apart as undated. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let view_layout_of_yojson : Yojson.Safe.t -> view_layout =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "table" ->
      Table
        {
          columns =
            Json.required fields "columns" (Json.list view_column_of_yojson);
        }
  | "board" ->
      Board
        {
          card_fields =
            Json.required fields "cardFields" (Json.list Json.string);
          group_by = Json.required fields "groupBy" Json.string;
          hide_empty_lanes = Json.required fields "hideEmptyLanes" Json.bool;
          lanes = Json.required fields "lanes" (Json.list lane_of_yojson);
          title = Json.required fields "title" Json.string;
        }
  | "timeline" ->
      Timeline
        {
          bar_fields = Json.optional fields "barFields" (Json.list Json.string);
          color_by = Json.optional fields "colorBy" Json.string;
          group_by = Json.optional fields "groupBy" Json.string;
          range = Json.required fields "range" Json.string;
          title = Json.required fields "title" Json.string;
        }
  | _ -> Unknown json

and yojson_of_view_layout : view_layout -> Yojson.Safe.t =
 fun value ->
  match value with
  | Table case ->
      Json.record
        [
          ("kind", Some (`String "table"));
          ("columns", Some ((Json.of_list yojson_of_view_column) case.columns));
        ]
  | Board case ->
      Json.record
        [
          ("kind", Some (`String "board"));
          ("cardFields", Some ((Json.of_list Json.of_string) case.card_fields));
          ("groupBy", Some (Json.of_string case.group_by));
          ("hideEmptyLanes", Some (Json.of_bool case.hide_empty_lanes));
          ("lanes", Some ((Json.of_list yojson_of_lane) case.lanes));
          ("title", Some (Json.of_string case.title));
        ]
  | Timeline case ->
      Json.record
        [
          ("kind", Some (`String "timeline"));
          ("barFields", Option.map (Json.of_list Json.of_string) case.bar_fields);
          ("colorBy", Some ((Json.of_option Json.of_string) case.color_by));
          ("groupBy", Some ((Json.of_option Json.of_string) case.group_by));
          ("range", Some (Json.of_string case.range));
          ("title", Some (Json.of_string case.title));
        ]
  | Unknown json -> json

let make_view_layout_table ~(columns : view_column list) () =
  (Table { columns } : view_layout)

let make_view_layout_board ~(card_fields : string list) ~(group_by : string)
    ~(hide_empty_lanes : bool) ~(lanes : lane list) ~(title : string) () =
  (Board { card_fields; group_by; hide_empty_lanes; lanes; title }
    : view_layout)

let make_view_layout_timeline ?bar_fields ?color_by ?group_by ~(range : string)
    ~(title : string) () =
  (Timeline { bar_fields; color_by; group_by; range; title } : view_layout)

(** Whether a cell is empty. *)
type nonrec presence_operator =
  | Is_empty
  | Is_not_empty
  | Unknown of string  (** A value this SDK version does not know. *)

let presence_operator_of_yojson : Yojson.Safe.t -> presence_operator =
 fun json ->
  match Json.string json with
  | "isEmpty" -> Is_empty
  | "isNotEmpty" -> Is_not_empty
  | other -> Unknown other

and yojson_of_presence_operator : presence_operator -> Yojson.Safe.t =
 fun value ->
  match value with
  | Is_empty -> `String "isEmpty"
  | Is_not_empty -> `String "isNotEmpty"
  | Unknown other -> `String other

(** How a text cell compares to a text. *)
type nonrec text_operator =
  | Is
  | Is_not
  | Contains
  | Does_not_contain
  | Starts_with
  | Ends_with
  | Unknown of string  (** A value this SDK version does not know. *)

let text_operator_of_yojson : Yojson.Safe.t -> text_operator =
 fun json ->
  match Json.string json with
  | "is" -> Is
  | "isNot" -> Is_not
  | "contains" -> Contains
  | "doesNotContain" -> Does_not_contain
  | "startsWith" -> Starts_with
  | "endsWith" -> Ends_with
  | other -> Unknown other

and yojson_of_text_operator : text_operator -> Yojson.Safe.t =
 fun value ->
  match value with
  | Is -> `String "is"
  | Is_not -> `String "isNot"
  | Contains -> `String "contains"
  | Does_not_contain -> `String "doesNotContain"
  | Starts_with -> `String "startsWith"
  | Ends_with -> `String "endsWith"
  | Unknown other -> `String other

(** How a number cell compares to a number. *)
type nonrec number_operator =
  | Is
  | Is_not
  | Greater_than
  | Greater_than_or_equal
  | Less_than
  | Less_than_or_equal
  | Unknown of string  (** A value this SDK version does not know. *)

let number_operator_of_yojson : Yojson.Safe.t -> number_operator =
 fun json ->
  match Json.string json with
  | "is" -> Is
  | "isNot" -> Is_not
  | "greaterThan" -> Greater_than
  | "greaterThanOrEqual" -> Greater_than_or_equal
  | "lessThan" -> Less_than
  | "lessThanOrEqual" -> Less_than_or_equal
  | other -> Unknown other

and yojson_of_number_operator : number_operator -> Yojson.Safe.t =
 fun value ->
  match value with
  | Is -> `String "is"
  | Is_not -> `String "isNot"
  | Greater_than -> `String "greaterThan"
  | Greater_than_or_equal -> `String "greaterThanOrEqual"
  | Less_than -> `String "lessThan"
  | Less_than_or_equal -> `String "lessThanOrEqual"
  | Unknown other -> `String other

(** How a date cell compares to a date-time. *)
type nonrec date_operator =
  | Before
  | After
  | On_or_before
  | On_or_after
  | Unknown of string  (** A value this SDK version does not know. *)

let date_operator_of_yojson : Yojson.Safe.t -> date_operator =
 fun json ->
  match Json.string json with
  | "before" -> Before
  | "after" -> After
  | "onOrBefore" -> On_or_before
  | "onOrAfter" -> On_or_after
  | other -> Unknown other

and yojson_of_date_operator : date_operator -> Yojson.Safe.t =
 fun value ->
  match value with
  | Before -> `String "before"
  | After -> `String "after"
  | On_or_before -> `String "onOrBefore"
  | On_or_after -> `String "onOrAfter"
  | Unknown other -> `String other

(** How a date-range cell stands to a day: the whole day starting at the
test's date-time, so a range from 1 PM to 5 PM contains its day. *)
type nonrec date_range_operator =
  | Contains
  | Does_not_contain
  | Ends_before
  | Ends_on_or_after
  | Starts_after
  | Starts_on_or_before
  | Unknown of string  (** A value this SDK version does not know. *)

let date_range_operator_of_yojson : Yojson.Safe.t -> date_range_operator =
 fun json ->
  match Json.string json with
  | "contains" -> Contains
  | "doesNotContain" -> Does_not_contain
  | "endsBefore" -> Ends_before
  | "endsOnOrAfter" -> Ends_on_or_after
  | "startsAfter" -> Starts_after
  | "startsOnOrBefore" -> Starts_on_or_before
  | other -> Unknown other

and yojson_of_date_range_operator : date_range_operator -> Yojson.Safe.t =
 fun value ->
  match value with
  | Contains -> `String "contains"
  | Does_not_contain -> `String "doesNotContain"
  | Ends_before -> `String "endsBefore"
  | Ends_on_or_after -> `String "endsOnOrAfter"
  | Starts_after -> `String "startsAfter"
  | Starts_on_or_before -> `String "startsOnOrBefore"
  | Unknown other -> `String other

(** How a cell's options or references relate to a set of them. The first
two fit a column holding one value, the last three one holding several. *)
type nonrec set_operator =
  | Is_any_of
  | Is_none_of
  | Has_any
  | Has_all
  | Has_none
  | Unknown of string  (** A value this SDK version does not know. *)

let set_operator_of_yojson : Yojson.Safe.t -> set_operator =
 fun json ->
  match Json.string json with
  | "isAnyOf" -> Is_any_of
  | "isNoneOf" -> Is_none_of
  | "hasAny" -> Has_any
  | "hasAll" -> Has_all
  | "hasNone" -> Has_none
  | other -> Unknown other

and yojson_of_set_operator : set_operator -> Yojson.Safe.t =
 fun value ->
  match value with
  | Is_any_of -> `String "isAnyOf"
  | Is_none_of -> `String "isNoneOf"
  | Has_any -> `String "hasAny"
  | Has_all -> `String "hasAll"
  | Has_none -> `String "hasNone"
  | Unknown other -> `String other

(** What a column's cell must be, by the kind of value the column holds. *)
type nonrec filter_test =
  | Presence of { operator : presence_operator  (** Empty, or not. *) }
      (** Whether the cell is empty; fits a column of any type. *)
  | Text of {
      operator : text_operator;  (** How the cell compares. *)
      value : string;
          (** The text compared against, ignoring case for the containment
tests. *)
    }  (** A text or link column. *)
  | Number of {
      operator : number_operator;  (** How the cell compares. *)
      value : float;  (** The number compared against; finite. *)
    }  (** A number column. *)
  | Date of {
      operator : date_operator;  (** How the cell compares. *)
      value : string;  (** The date-time compared against. *)
    }  (** A date column. *)
  | Date_range of {
      operator : date_range_operator;
          (** How the cell's range stands to the day. *)
      value : string;  (** The start of the day compared against. *)
    }  (** A date-range column. *)
  | Checkbox of { checked : bool  (** Whether the box is checked. *) }
      (** A checkbox column. An unchecked box and an empty cell are the same. *)
  | Options of {
      operator : set_operator;  (** How the cell's options relate to these. *)
      options : string list;  (** Options of the column; at least one. *)
    }  (** A select or tag column. *)
  | Entities of {
      entities : string list;
          (** Entity ids, or for a relation the related rows' ids; at least
one. *)
      operator : set_operator;  (** How the cell's references relate to these. *)
    }  (** A reference or relation column. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let filter_test_of_yojson : Yojson.Safe.t -> filter_test =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "presence" ->
      Presence
        {
          operator = Json.required fields "operator" presence_operator_of_yojson;
        }
  | "text" ->
      Text
        {
          operator = Json.required fields "operator" text_operator_of_yojson;
          value = Json.required fields "value" Json.string;
        }
  | "number" ->
      Number
        {
          operator = Json.required fields "operator" number_operator_of_yojson;
          value = Json.required fields "value" Json.float;
        }
  | "date" ->
      Date
        {
          operator = Json.required fields "operator" date_operator_of_yojson;
          value = Json.required fields "value" Json.string;
        }
  | "dateRange" ->
      Date_range
        {
          operator =
            Json.required fields "operator" date_range_operator_of_yojson;
          value = Json.required fields "value" Json.string;
        }
  | "checkbox" ->
      Checkbox { checked = Json.required fields "checked" Json.bool }
  | "options" ->
      Options
        {
          operator = Json.required fields "operator" set_operator_of_yojson;
          options = Json.required fields "options" (Json.list Json.string);
        }
  | "entities" ->
      Entities
        {
          entities = Json.required fields "entities" (Json.list Json.string);
          operator = Json.required fields "operator" set_operator_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_filter_test : filter_test -> Yojson.Safe.t =
 fun value ->
  match value with
  | Presence case ->
      Json.record
        [
          ("kind", Some (`String "presence"));
          ("operator", Some (yojson_of_presence_operator case.operator));
        ]
  | Text case ->
      Json.record
        [
          ("kind", Some (`String "text"));
          ("operator", Some (yojson_of_text_operator case.operator));
          ("value", Some (Json.of_string case.value));
        ]
  | Number case ->
      Json.record
        [
          ("kind", Some (`String "number"));
          ("operator", Some (yojson_of_number_operator case.operator));
          ("value", Some (Json.of_float case.value));
        ]
  | Date case ->
      Json.record
        [
          ("kind", Some (`String "date"));
          ("operator", Some (yojson_of_date_operator case.operator));
          ("value", Some (Json.of_string case.value));
        ]
  | Date_range case ->
      Json.record
        [
          ("kind", Some (`String "dateRange"));
          ("operator", Some (yojson_of_date_range_operator case.operator));
          ("value", Some (Json.of_string case.value));
        ]
  | Checkbox case ->
      Json.record
        [
          ("kind", Some (`String "checkbox"));
          ("checked", Some (Json.of_bool case.checked));
        ]
  | Options case ->
      Json.record
        [
          ("kind", Some (`String "options"));
          ("operator", Some (yojson_of_set_operator case.operator));
          ("options", Some ((Json.of_list Json.of_string) case.options));
        ]
  | Entities case ->
      Json.record
        [
          ("kind", Some (`String "entities"));
          ("entities", Some ((Json.of_list Json.of_string) case.entities));
          ("operator", Some (yojson_of_set_operator case.operator));
        ]
  | Unknown json -> json

let make_filter_test_presence ~(operator : presence_operator) () =
  (Presence { operator } : filter_test)

let make_filter_test_text ~(operator : text_operator) ~(value : string) () =
  (Text { operator; value } : filter_test)

let make_filter_test_number ~(operator : number_operator) ~(value : float) () =
  (Number { operator; value } : filter_test)

let make_filter_test_date ~(operator : date_operator) ~(value : string) () =
  (Date { operator; value } : filter_test)

let make_filter_test_date_range ~(operator : date_range_operator)
    ~(value : string) () =
  (Date_range { operator; value } : filter_test)

let make_filter_test_checkbox ~(checked : bool) () =
  (Checkbox { checked } : filter_test)

let make_filter_test_options ~(operator : set_operator) ~(options : string list)
    () =
  (Options { operator; options } : filter_test)

let make_filter_test_entities ~(entities : string list)
    ~(operator : set_operator) () =
  (Entities { entities; operator } : filter_test)

type nonrec filter_condition = {
  column : string;  (** The column tested. *)
  test : filter_test;
      (** What its cell must be. The test's kind must fit the column's type. *)
}
(** A test of one column's cells. *)

let filter_condition_of_yojson : Yojson.Safe.t -> filter_condition =
 fun json ->
  let fields = Json.obj json in
  {
    column = Json.required fields "column" Json.string;
    test = Json.required fields "test" filter_test_of_yojson;
  }

and yojson_of_filter_condition : filter_condition -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("column", Some (Json.of_string value.column));
      ("test", Some (yojson_of_filter_test value.test));
    ]

let make_filter_condition ~(column : string) ~(test : filter_test) () =
  ({ column; test } : filter_condition)

(** How a group's conditions combine. *)
type nonrec conjunction =
  | And
  | Or
  | Unknown of string  (** A value this SDK version does not know. *)

let conjunction_of_yojson : Yojson.Safe.t -> conjunction =
 fun json ->
  match Json.string json with
  | "and" -> And
  | "or" -> Or
  | other -> Unknown other

and yojson_of_conjunction : conjunction -> Yojson.Safe.t =
 fun value ->
  match value with
  | And -> `String "and"
  | Or -> `String "or"
  | Unknown other -> `String other

type filter_group = {
  conditions : filter_node list;
      (** The conditions and nested groups. A group without any keeps every
row. *)
  conjunction : conjunction;
      (** Whether every condition must hold, or any one. *)
}
(** Conditions joined by one conjunction. *)

(** One entry of a group: a condition, or a group of its own. *)
and filter_node =
  | Condition of filter_condition  (** A test of one column. *)
  | Group of filter_group  (** A nested group. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let rec filter_group_of_yojson : Yojson.Safe.t -> filter_group =
 fun json ->
  let fields = Json.obj json in
  {
    conditions =
      Json.required fields "conditions" (Json.list filter_node_of_yojson);
    conjunction = Json.required fields "conjunction" conjunction_of_yojson;
  }

and yojson_of_filter_group : filter_group -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "conditions",
        Some ((Json.of_list yojson_of_filter_node) value.conditions) );
      ("conjunction", Some (yojson_of_conjunction value.conjunction));
    ]

and filter_node_of_yojson : Yojson.Safe.t -> filter_node =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "condition" -> Condition (filter_condition_of_yojson json)
  | "group" -> Group (filter_group_of_yojson json)
  | _ -> Unknown json

and yojson_of_filter_node : filter_node -> Yojson.Safe.t =
 fun value ->
  match value with
  | Condition inner ->
      Json.with_tag "kind" "condition" (yojson_of_filter_condition inner)
  | Group inner -> Json.with_tag "kind" "group" (yojson_of_filter_group inner)
  | Unknown json -> json

let make_filter_group ~(conditions : filter_node list)
    ~(conjunction : conjunction) () =
  ({ conditions; conjunction } : filter_group)

(** A sort direction. Empty cells sort last either way. *)
type nonrec sort_direction =
  | Ascending
  | Descending
  | Unknown of string  (** A value this SDK version does not know. *)

let sort_direction_of_yojson : Yojson.Safe.t -> sort_direction =
 fun json ->
  match Json.string json with
  | "ascending" -> Ascending
  | "descending" -> Descending
  | other -> Unknown other

and yojson_of_sort_direction : sort_direction -> Yojson.Safe.t =
 fun value ->
  match value with
  | Ascending -> `String "ascending"
  | Descending -> `String "descending"
  | Unknown other -> `String other

type nonrec sort_key = {
  column : string;  (** The column sorted on. *)
  direction : sort_direction;  (** Which way. *)
}
(** One sort key. *)

let sort_key_of_yojson : Yojson.Safe.t -> sort_key =
 fun json ->
  let fields = Json.obj json in
  {
    column = Json.required fields "column" Json.string;
    direction = Json.required fields "direction" sort_direction_of_yojson;
  }

and yojson_of_sort_key : sort_key -> Yojson.Safe.t =
 fun value ->
