type nonrec view_query = {
  filter : filter_group option;
  sort : sort_key list option;
      (** The sort keys, first key first. Rows the keys leave tied keep the
table's own order; with no keys, the table's order is the view's. *)
}
(** Which rows of the table a view shows, and in what order: a filter and a
sort, nothing that joins, groups or reshapes rows. *)

let view_query_of_yojson : Yojson.Safe.t -> view_query =
 fun json ->
  let fields = Json.obj json in
  {
    filter = Json.optional fields "filter" filter_group_of_yojson;
    sort = Json.optional fields "sort" (Json.list sort_key_of_yojson);
  }

and yojson_of_view_query : view_query -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("filter", Some ((Json.of_option yojson_of_filter_group) value.filter));
      ("sort", Option.map (Json.of_list yojson_of_sort_key) value.sort);
    ]

let make_view_query ?filter ?sort () = ({ filter; sort } : view_query)

type nonrec database_view = {
  created_at : string;  (** When it was created. *)
  database_id : string;  (** The database the table belongs to. *)
  id : string;  (** The view. *)
  layout : view_layout;  (** How it draws them. *)
  name : string;  (** Its name, unique among the table's views ignoring case. *)
  position : string;
      (** Where it sorts among the table's views: a fractional key. *)
  query : view_query;  (** Which rows it shows, in what order. *)
  table_id : string;  (** The table it shows. *)
  updated_at : string;  (** When it last changed. *)
}
(** A view of one table, as stored. *)

let database_view_of_yojson : Yojson.Safe.t -> database_view =
 fun json ->
  let fields = Json.obj json in
  {
    created_at = Json.required fields "createdAt" Json.string;
    database_id = Json.required fields "databaseId" Json.string;
    id = Json.required fields "id" Json.string;
    layout = Json.required fields "layout" view_layout_of_yojson;
    name = Json.required fields "name" Json.string;
    position = Json.required fields "position" Json.string;
    query = Json.required fields "query" view_query_of_yojson;
    table_id = Json.required fields "tableId" Json.string;
    updated_at = Json.required fields "updatedAt" Json.string;
  }

and yojson_of_database_view : database_view -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("createdAt", Some (Json.of_string value.created_at));
      ("databaseId", Some (Json.of_string value.database_id));
      ("id", Some (Json.of_string value.id));
      ("layout", Some (yojson_of_view_layout value.layout));
      ("name", Some (Json.of_string value.name));
      ("position", Some (Json.of_string value.position));
      ("query", Some (yojson_of_view_query value.query));
      ("tableId", Some (Json.of_string value.table_id));
      ("updatedAt", Some (Json.of_string value.updated_at));
    ]

let make_database_view ~(created_at : string) ~(database_id : string)
    ~(id : string) ~(layout : view_layout) ~(name : string) ~(position : string)
    ~(query : view_query) ~(table_id : string) ~(updated_at : string) () =
  ({
     created_at;
     database_id;
     id;
     layout;
     name;
     position;
     query;
     table_id;
     updated_at;
   }
    : database_view)

type nonrec card_position = {
  lane : lane_key;  (** The lane. *)
  position : string;  (** The card's key in that lane. *)
  row : string;  (** The card's row. *)
}
(** Where one card sits on a board: its lane, and its fractional key there.
A card whose row has since moved to another lane has no place until it is
moved again. *)

let card_position_of_yojson : Yojson.Safe.t -> card_position =
 fun json ->
  let fields = Json.obj json in
  {
    lane = Json.required fields "lane" lane_key_of_yojson;
    position = Json.required fields "position" Json.string;
    row = Json.required fields "row" Json.string;
  }

and yojson_of_card_position : card_position -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("lane", Some (yojson_of_lane_key value.lane));
      ("position", Some (Json.of_string value.position));
      ("row", Some (Json.of_string value.row));
    ]

let make_card_position ~(lane : lane_key) ~(position : string) ~(row : string)
    () =
