(** What happened to a view. *)
type nonrec view_result =
  | Created of { view : database_view  (** The view as stored. *) }
      (** It was added. *)
  | Updated of { view : database_view  (** The view as stored. *) }
      (** It was changed. *)
  | Deleted  (** It was removed. *)
  | Card_moved of {
      positions : card_position list;
          (** The positions written, the moved card's last. *)
    }  (** One of its cards moved. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let view_result_of_yojson : Yojson.Safe.t -> view_result =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "created" ->
      Created { view = Json.required fields "view" database_view_of_yojson }
  | "updated" ->
      Updated { view = Json.required fields "view" database_view_of_yojson }
  | "deleted" -> Deleted
  | "card_moved" ->
      Card_moved
        {
          positions =
            Json.required fields "positions" (Json.list card_position_of_yojson);
        }
  | _ -> Unknown json

and yojson_of_view_result : view_result -> Yojson.Safe.t =
 fun value ->
  match value with
  | Created case ->
      Json.record
        [
          ("kind", Some (`String "created"));
          ("view", Some (yojson_of_database_view case.view));
        ]
  | Updated case ->
      Json.record
        [
          ("kind", Some (`String "updated"));
          ("view", Some (yojson_of_database_view case.view));
        ]
  | Deleted -> Json.record [ ("kind", Some (`String "deleted")) ]
  | Card_moved case ->
      Json.record
        [
          ("kind", Some (`String "card_moved"));
          ( "positions",
            Some ((Json.of_list yojson_of_card_position) case.positions) );
        ]
  | Unknown json -> json

let make_view_result_created ~(view : database_view) () =
  (Created { view } : view_result)

let make_view_result_updated ~(view : database_view) () =
  (Updated { view } : view_result)

let make_view_result_card_moved ~(positions : card_position list) () =
  (Card_moved { positions } : view_result)

type nonrec versioned_table = {
  table : string;  (** The table. *)
  version : table_version;  (** Its version. *)
}
(** A table and its version. *)

let versioned_table_of_yojson : Yojson.Safe.t -> versioned_table =
 fun json ->
  let fields = Json.obj json in
  {
    table = Json.required fields "table" Json.string;
    version = Json.required fields "version" table_version_of_yojson;
  }

and yojson_of_versioned_table : versioned_table -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("table", Some (Json.of_string value.table));
      ("version", Some (yojson_of_table_version value.version));
    ]

let make_versioned_table ~(table : string) ~(version : table_version) () =
  ({ table; version } : versioned_table)

(** What one op did, in the order the ops were sent, grouped as the ops are:
a result's [kind] is its op's, naming the same resource, and its
[change] says what happened to it. *)
type nonrec op_result =
  | Table of {
      change : table_result;  (** What happened to it. *)
      table : string;  (** The table. *)
      table_version : table_version option;
          (** Its version once the request committed; left out when the op
removed it. *)
    }  (** What a table op did. *)
  | Column of {
      change : column_result;  (** What happened to it. *)
      column : string;  (** The column. *)
      table : string;  (** The table. *)
      table_version : table_version;
          (** The table's version once the request committed. *)
    }  (** What a column op did. *)
  | Rows of {
      change : rows_result;  (** What happened to them. *)
      table : string;  (** The table. *)
      table_version : table_version;
          (** The table's version once the request committed. *)
    }  (** What a rows op did. *)
  | View of {
      change : view_result;  (** What happened to it. *)
      table : string;  (** The view's table. *)
      table_version : table_version;
          (** The table's version once the request committed. *)
      view : string;  (** The view. *)
    }  (** What a view op did. *)
  | Reorder_tables of {
      tables : versioned_table list;
          (** Every table, in its new order, with its version once the request
committed. *)
    }  (** The database's tables in their new order. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let op_result_of_yojson : Yojson.Safe.t -> op_result =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "table" ->
      Table
        {
          change = Json.required fields "change" table_result_of_yojson;
          table = Json.required fields "table" Json.string;
          table_version =
            Json.optional fields "tableVersion" table_version_of_yojson;
        }
  | "column" ->
      Column
        {
          change = Json.required fields "change" column_result_of_yojson;
          column = Json.required fields "column" Json.string;
          table = Json.required fields "table" Json.string;
          table_version =
            Json.required fields "tableVersion" table_version_of_yojson;
        }
  | "rows" ->
      Rows
        {
          change = Json.required fields "change" rows_result_of_yojson;
          table = Json.required fields "table" Json.string;
          table_version =
            Json.required fields "tableVersion" table_version_of_yojson;
        }
  | "view" ->
      View
        {
          change = Json.required fields "change" view_result_of_yojson;
          table = Json.required fields "table" Json.string;
          table_version =
            Json.required fields "tableVersion" table_version_of_yojson;
          view = Json.required fields "view" Json.string;
        }
  | "reorder_tables" ->
      Reorder_tables
        {
          tables =
            Json.required fields "tables" (Json.list versioned_table_of_yojson);
        }
  | _ -> Unknown json

and yojson_of_op_result : op_result -> Yojson.Safe.t =
 fun value ->
  match value with
  | Table case ->
      Json.record
        [
          ("kind", Some (`String "table"));
          ("change", Some (yojson_of_table_result case.change));
          ("table", Some (Json.of_string case.table));
          ("tableVersion", Option.map yojson_of_table_version case.table_version);
        ]
  | Column case ->
      Json.record
        [
          ("kind", Some (`String "column"));
          ("change", Some (yojson_of_column_result case.change));
          ("column", Some (Json.of_string case.column));
          ("table", Some (Json.of_string case.table));
          ("tableVersion", Some (yojson_of_table_version case.table_version));
        ]
  | Rows case ->
      Json.record
        [
          ("kind", Some (`String "rows"));
          ("change", Some (yojson_of_rows_result case.change));
          ("table", Some (Json.of_string case.table));
          ("tableVersion", Some (yojson_of_table_version case.table_version));
        ]
  | View case ->
      Json.record
        [
          ("kind", Some (`String "view"));
          ("change", Some (yojson_of_view_result case.change));
          ("table", Some (Json.of_string case.table));
          ("tableVersion", Some (yojson_of_table_version case.table_version));
          ("view", Some (Json.of_string case.view));
        ]
  | Reorder_tables case ->
      Json.record
        [
          ("kind", Some (`String "reorder_tables"));
          ("tables", Some ((Json.of_list yojson_of_versioned_table) case.tables));
        ]
  | Unknown json -> json

let make_op_result_table ~(change : table_result) ~(table : string)
    ?table_version () =
  (Table { change; table; table_version } : op_result)

let make_op_result_column ~(change : column_result) ~(column : string)
    ~(table : string) ~(table_version : table_version) () =
  (Column { change; column; table; table_version } : op_result)

let make_op_result_rows ~(change : rows_result) ~(table : string)
    ~(table_version : table_version) () =
  (Rows { change; table; table_version } : op_result)

let make_op_result_view ~(change : view_result) ~(table : string)
    ~(table_version : table_version) ~(view : string) () =
  (View { change; table; table_version; view } : op_result)

let make_op_result_reorder_tables ~(tables : versioned_table list) () =
  (Reorder_tables { tables } : op_result)

type nonrec applied_ops = {
  changes : committed_change list;  (** The journal's changes. *)
  results : op_result list;  (** One result per op, in order. *)
}
(** What a committed batch answers: a result per op, and the journal's change
for each table version it produced. *)

let applied_ops_of_yojson : Yojson.Safe.t -> applied_ops =
 fun json ->
  let fields = Json.obj json in
  {
    changes =
      Json.required fields "changes" (Json.list committed_change_of_yojson);
    results = Json.required fields "results" (Json.list op_result_of_yojson);
  }

and yojson_of_applied_ops : applied_ops -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("changes", Some ((Json.of_list yojson_of_committed_change) value.changes));
      ("results", Some ((Json.of_list yojson_of_op_result) value.results));
    ]

let make_applied_ops ~(changes : committed_change list)
    ~(results : op_result list) () =
  ({ changes; results } : applied_ops)

(** A change to a table itself. *)
type nonrec table_change =
  | Create of {
      name : string;  (** Its name, unique within the database ignoring case. *)
    }
      (** Add the table, after the database's other tables. It starts with no
columns and no rows. *)
  | Rename of {
      name : string;
          (** Its new name, unique within the database ignoring case. *)
      previous_name : string option;
          (** The name the caller saw. Given, the rename is refused if the
table goes by another one now, so a concurrent rename is not
overwritten. *)
    }  (** Rename the table. Its id, columns and rows stay. *)
  | Delete
      (** Remove the table with its columns, rows and views. A database keeps
at least one table, and a table another table's relation points at
stays until that relation goes. *)
  | Reorder_columns of {
      order : string list;  (** Its columns, in their new order. *)
    }
      (** Set the order of the table's columns: [order] names every one of
them once. *)
  | Reorder_views of {
      order : string list;  (** Its views, in their new order. *)
    }
      (** Set the order of the table's views: [order] names every one of them
once. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let table_change_of_yojson : Yojson.Safe.t -> table_change =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "create" -> Create { name = Json.required fields "name" Json.string }
  | "rename" ->
      Rename
        {
          name = Json.required fields "name" Json.string;
          previous_name = Json.optional fields "previousName" Json.string;
        }
  | "delete" -> Delete
  | "reorder_columns" ->
      Reorder_columns
        { order = Json.required fields "order" (Json.list Json.string) }
  | "reorder_views" ->
      Reorder_views
        { order = Json.required fields "order" (Json.list Json.string) }
  | _ -> Unknown json

and yojson_of_table_change : table_change -> Yojson.Safe.t =
 fun value ->
  match value with
  | Create case ->
      Json.record
        [
          ("kind", Some (`String "create"));
          ("name", Some (Json.of_string case.name));
        ]
  | Rename case ->
      Json.record
        [
          ("kind", Some (`String "rename"));
          ("name", Some (Json.of_string case.name));
          ("previousName", Option.map Json.of_string case.previous_name);
        ]
  | Delete -> Json.record [ ("kind", Some (`String "delete")) ]
  | Reorder_columns case ->
      Json.record
        [
          ("kind", Some (`String "reorder_columns"));
          ("order", Some ((Json.of_list Json.of_string) case.order));
        ]
  | Reorder_views case ->
      Json.record
        [
          ("kind", Some (`String "reorder_views"));
          ("order", Some ((Json.of_list Json.of_string) case.order));
        ]
  | Unknown json -> json

let make_table_change_create ~(name : string) () =
  (Create { name } : table_change)

let make_table_change_rename ~(name : string) ?previous_name () =
  (Rename { name; previous_name } : table_change)

let make_table_change_reorder_columns ~(order : string list) () =
  (Reorder_columns { order } : table_change)

let make_table_change_reorder_views ~(order : string list) () =
  (Reorder_views { order } : table_change)

type nonrec new_option = {
  id : string;
      (** Its id, minted by the client; later ops of the request may name it. *)
  label : string;
      (** Its label, unique within the column ignoring case. A numeric
select's labels are numbers. *)
}
(** A select or tag option to create. *)

let new_option_of_yojson : Yojson.Safe.t -> new_option =
 fun json ->
  let fields = Json.obj json in
  {
    id = Json.required fields "id" Json.string;
    label = Json.required fields "label" Json.string;
  }

and yojson_of_new_option : new_option -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("id", Some (Json.of_string value.id));
      ("label", Some (Json.of_string value.label));
    ]

let make_new_option ~(id : string) ~(label : string) () =
  ({ id; label } : new_option)

(** A type a column can have. *)
type nonrec column_kind =
  | Text  (** Free text. *)
  | Number  (** A number. *)
  | Boolean  (** A checkbox. *)
  | Date  (** A date-time. *)
  | Date_range  (** A span from one date-time to another. *)
  | Link  (** A URL. *)
  | Select of { multi : bool  (** Whether a cell holds several options. *) }
      (** Text options. *)
  | Select_number of {
      multi : bool;  (** Whether a cell holds several options. *)
    }  (** Numeric options. *)
  | Tag  (** Colored labels; always several per cell. *)
  | Entity of {
      multi : bool;  (** Whether a cell holds several references. *)
      target : entity_kind;  (** What the references point at. *)
    }  (** References to Macro entities. *)
  | Relation of {
      database : string;  (** The database of the related table. *)
      table : string;  (** The related table. *)
    }  (** Rows of another table. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let column_kind_of_yojson : Yojson.Safe.t -> column_kind =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "text" -> Text
  | "number" -> Number
  | "boolean" -> Boolean
  | "date" -> Date
  | "date_range" -> Date_range
  | "link" -> Link
  | "select" -> Select { multi = Json.required fields "multi" Json.bool }
  | "select_number" ->
      Select_number { multi = Json.required fields "multi" Json.bool }
  | "tag" -> Tag
  | "entity" ->
      Entity
        {
          multi = Json.required fields "multi" Json.bool;
          target = Json.required fields "target" entity_kind_of_yojson;
        }
  | "relation" ->
      Relation
        {
          database = Json.required fields "database" Json.string;
          table = Json.required fields "table" Json.string;
        }
  | _ -> Unknown json

and yojson_of_column_kind : column_kind -> Yojson.Safe.t =
 fun value ->
  match value with
  | Text -> Json.record [ ("type", Some (`String "text")) ]
  | Number -> Json.record [ ("type", Some (`String "number")) ]
  | Boolean -> Json.record [ ("type", Some (`String "boolean")) ]
  | Date -> Json.record [ ("type", Some (`String "date")) ]
  | Date_range -> Json.record [ ("type", Some (`String "date_range")) ]
  | Link -> Json.record [ ("type", Some (`String "link")) ]
  | Select case ->
      Json.record
        [
          ("type", Some (`String "select"));
          ("multi", Some (Json.of_bool case.multi));
        ]
  | Select_number case ->
      Json.record
        [
          ("type", Some (`String "select_number"));
          ("multi", Some (Json.of_bool case.multi));
        ]
  | Tag -> Json.record [ ("type", Some (`String "tag")) ]
  | Entity case ->
      Json.record
        [
          ("type", Some (`String "entity"));
          ("multi", Some (Json.of_bool case.multi));
          ("target", Some (yojson_of_entity_kind case.target));
        ]
  | Relation case ->
      Json.record
        [
          ("type", Some (`String "relation"));
          ("database", Some (Json.of_string case.database));
          ("table", Some (Json.of_string case.table));
        ]
  | Unknown json -> json

let make_column_kind_select ~(multi : bool) () =
  (Select { multi } : column_kind)

let make_column_kind_select_number ~(multi : bool) () =
  (Select_number { multi } : column_kind)

let make_column_kind_entity ~(multi : bool) ~(target : entity_kind) () =
  (Entity { multi; target } : column_kind)

let make_column_kind_relation ~(database : string) ~(table : string) () =
  (Relation { database; table } : column_kind)

(** An arithmetic operator. *)
type nonrec operator =
  | Add
  | Subtract
  | Multiply
  | Divide
  | Unknown of string  (** A value this SDK version does not know. *)

let operator_of_yojson : Yojson.Safe.t -> operator =
 fun json ->
  match Json.string json with
  | "add" -> Add
  | "subtract" -> Subtract
  | "multiply" -> Multiply
  | "divide" -> Divide
  | other -> Unknown other

and yojson_of_operator : operator -> Yojson.Safe.t =
 fun value ->
  match value with
  | Add -> `String "add"
  | Subtract -> `String "subtract"
  | Multiply -> `String "multiply"
  | Divide -> `String "divide"
  | Unknown other -> `String other

(** An expression over one row's cells. *)
type formula =
  | Column of { column : string  (** The column placement. *) }
      (** The row's cell in another column of the table: a number, date or
derived column. *)
  | Number of { value : float  (** The value; finite. *) }
      (** A constant. Added to or subtracted from a date, it counts days. *)
  | Binary of {
      left : formula;  (** The left operand. *)
      operator : operator;  (** How. *)
      right : formula;  (** The right operand. *)
    }  (** Two expressions combined. *)
  | Negate of { operand : formula  (** The expression negated; a number. *) }
      (** An expression's negation. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let rec formula_of_yojson : Yojson.Safe.t -> formula =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "column" -> Column { column = Json.required fields "column" Json.string }
  | "number" -> Number { value = Json.required fields "value" Json.float }
  | "binary" ->
      Binary
        {
          left = Json.required fields "left" formula_of_yojson;
          operator = Json.required fields "operator" operator_of_yojson;
          right = Json.required fields "right" formula_of_yojson;
        }
  | "negate" ->
      Negate { operand = Json.required fields "operand" formula_of_yojson }
  | _ -> Unknown json

and yojson_of_formula : formula -> Yojson.Safe.t =
 fun value ->
  match value with
  | Column case ->
      Json.record
        [
          ("kind", Some (`String "column"));
          ("column", Some (Json.of_string case.column));
        ]
  | Number case ->
      Json.record
        [
          ("kind", Some (`String "number"));
          ("value", Some (Json.of_float case.value));
        ]
  | Binary case ->
      Json.record
        [
          ("kind", Some (`String "binary"));
          ("left", Some (yojson_of_formula case.left));
          ("operator", Some (yojson_of_operator case.operator));
          ("right", Some (yojson_of_formula case.right));
        ]
  | Negate case ->
      Json.record
        [
          ("kind", Some (`String "negate"));
          ("operand", Some (yojson_of_formula case.operand));
        ]
  | Unknown json -> json

let make_formula_column ~(column : string) () = (Column { column } : formula)
let make_formula_number ~(value : float) () = (Number { value } : formula)

let make_formula_binary ~(left : formula) ~(operator : operator)
    ~(right : formula) () =
  (Binary { left; operator; right } : formula)

let make_formula_negate ~(operand : formula) () = (Negate { operand } : formula)

(** What a new column holds. *)
type nonrec new_column =
  | New of {
      infer_type : bool option;
          (** Let the column's first value settle its type: only for a plain
text column. *)
      name : string;
          (** The column's name, unique within the table ignoring case. *)
      options : new_option list option;
          (** For a select or tag column, the options it starts with, in
order, each under an id the client mints. A select column with
none accepts nothing until options are added. *)
      type_ : column_kind;
          (** Its type. A relation names the table whose rows it holds, one the
caller can see. *)
    }  (** A new property the database owns. *)
  | Derived of {
      formula : formula;
          (** How its cells are computed: arithmetic over the table's number,
date and other derived columns. *)
      name : string;
          (** The column's name, unique within the table ignoring case. *)
    }
      (** A derived column: its cells are what [formula] computes from the
row's other cells, and nothing writes them. *)
  | Existing of { property : string  (** The property's definition. *) }
      (** An existing property, a person's, a team's or a system one, bound
into the table under its own name. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let new_column_of_yojson : Yojson.Safe.t -> new_column =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "source" with
  | "new" ->
      New
        {
          infer_type = Json.optional fields "inferType" Json.bool;
          name = Json.required fields "name" Json.string;
          options =
            Json.optional fields "options" (Json.list new_option_of_yojson);
          type_ = Json.required fields "type" column_kind_of_yojson;
        }
  | "derived" ->
      Derived
        {
          formula = Json.required fields "formula" formula_of_yojson;
          name = Json.required fields "name" Json.string;
        }
  | "existing" ->
      Existing { property = Json.required fields "property" Json.string }
  | _ -> Unknown json

and yojson_of_new_column : new_column -> Yojson.Safe.t =
 fun value ->
  match value with
  | New case ->
      Json.record
        [
          ("source", Some (`String "new"));
          ("inferType", Option.map Json.of_bool case.infer_type);
          ("name", Some (Json.of_string case.name));
          ( "options",
            Option.map (Json.of_list yojson_of_new_option) case.options );
          ("type", Some (yojson_of_column_kind case.type_));
        ]
  | Derived case ->
      Json.record
        [
          ("source", Some (`String "derived"));
          ("formula", Some (yojson_of_formula case.formula));
          ("name", Some (Json.of_string case.name));
        ]
  | Existing case ->
      Json.record
        [
          ("source", Some (`String "existing"));
          ("property", Some (Json.of_string case.property));
        ]
  | Unknown json -> json

let make_new_column_new ?infer_type ~(name : string) ?options
    ~(type_ : column_kind) () =
  (New { infer_type; name; options; type_ } : new_column)

let make_new_column_derived ~(formula : formula) ~(name : string) () =
  (Derived { formula; name } : new_column)

let make_new_column_existing ~(property : string) () =
  (Existing { property } : new_column)

(** A change to one column. *)
type nonrec column_change =
  | Create of {
      after : string option;
          (** The column it goes right after; left out, it goes after the
table's last column. *)
      definition : new_column;  (** What the column holds. *)
    }
      (** Add the column to the table: a new property the database owns, or an
existing one bound into the table. *)
  | Rename of {
      name : string;
          (** Its new name, unique within the table ignoring case. *)
      previous_name : string option;
          (** The name the caller saw. Given, the rename is refused if the
column goes by another one now. *)
    }
      (** Rename the column. Its id, type and cells stay; SQL names it by its
new name. *)
  | Change_type of { to_ : column_kind  (** The type it becomes. *) }
      (** Convert the column to another type, converting its cells; its id
survives the change. A value that does not fit refuses the change,
counting and quoting the misfits: a type change never empties a
cell. To keep the original, create a column of the new type and
write it the values that convert. *)
  | Delete
      (** Remove the column and its cells. The views naming it forget it; a
board grouped by it must go or regroup first. A property shared
beyond the database stays, unbound here. *)
  | Add_options of {
      options : new_option list;
          (** The options, each under an id the client mints. *)
    }
      (** Add options to a select or tag column, after its others. An option
whose label the column already has, ignoring case, is left out, so
re-sending a list adds only what is new. Like
\[[ColumnChange::UpdateOption]\], an option of a property shared beyond
the database goes everywhere it is used. *)
  | Update_option of {
      color : string option;
          (** Its new colour, a hex string like [#RRGGBB], or [null] to clear
it; left out, it keeps its own. A tag option always has one. *)
      label : string option;
          (** Its new label; left out, it keeps its own. Labels are unique
within a column, ignoring case. *)
      option : string;  (** The option. *)
    }
      (** Relabel or recolour one option of a select or tag column. Every cell
holding it keeps it. A column bound to a property shared outside the
database changes wherever that property is used, so it takes the
right to edit that property. *)
  | Set_formula of {
      formula : formula;  (** The formula, over the table's other columns. *)
    }
      (** Give a derived column a new formula. Its cells follow at once: it
stores none. *)
  | Delete_option of { option : string  (** The option. *) }
      (** Remove one option of a select or tag column, and take it out of every
cell holding it: a single-valued cell is emptied, a multi-valued one
keeps its other options. Like \[[ColumnChange::UpdateOption]\], an
option of a shared property goes everywhere it is used. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let column_change_of_yojson : Yojson.Safe.t -> column_change =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "create" ->
      Create
        {
          after = Json.optional fields "after" Json.string;
          definition = Json.required fields "definition" new_column_of_yojson;
        }
  | "rename" ->
      Rename
        {
          name = Json.required fields "name" Json.string;
          previous_name = Json.optional fields "previousName" Json.string;
        }
  | "change_type" ->
      Change_type { to_ = Json.required fields "to" column_kind_of_yojson }
  | "delete" -> Delete
  | "add_options" ->
      Add_options
        {
          options =
            Json.required fields "options" (Json.list new_option_of_yojson);
        }
  | "update_option" ->
      Update_option
        {
          color = Json.optional fields "color" Json.string;
          label = Json.optional fields "label" Json.string;
          option = Json.required fields "option" Json.string;
        }
  | "set_formula" ->
      Set_formula { formula = Json.required fields "formula" formula_of_yojson }
  | "delete_option" ->
      Delete_option { option = Json.required fields "option" Json.string }
  | _ -> Unknown json

and yojson_of_column_change : column_change -> Yojson.Safe.t =
 fun value ->
  match value with
  | Create case ->
      Json.record
        [
          ("kind", Some (`String "create"));
          ("after", Option.map Json.of_string case.after);
          ("definition", Some (yojson_of_new_column case.definition));
        ]
  | Rename case ->
      Json.record
        [
          ("kind", Some (`String "rename"));
          ("name", Some (Json.of_string case.name));
          ("previousName", Option.map Json.of_string case.previous_name);
        ]
  | Change_type case ->
      Json.record
        [
          ("kind", Some (`String "change_type"));
          ("to", Some (yojson_of_column_kind case.to_));
        ]
  | Delete -> Json.record [ ("kind", Some (`String "delete")) ]
  | Add_options case ->
      Json.record
        [
          ("kind", Some (`String "add_options"));
          ("options", Some ((Json.of_list yojson_of_new_option) case.options));
        ]
  | Update_option case ->
      Json.record
        [
          ("kind", Some (`String "update_option"));
          ("color", Option.map Json.of_string case.color);
          ("label", Option.map Json.of_string case.label);
          ("option", Some (Json.of_string case.option));
        ]
  | Set_formula case ->
      Json.record
        [
          ("kind", Some (`String "set_formula"));
          ("formula", Some (yojson_of_formula case.formula));
        ]
  | Delete_option case ->
      Json.record
        [
          ("kind", Some (`String "delete_option"));
          ("option", Some (Json.of_string case.option));
        ]
  | Unknown json -> json

let make_column_change_create ?after ~(definition : new_column) () =
  (Create { after; definition } : column_change)

let make_column_change_rename ~(name : string) ?previous_name () =
  (Rename { name; previous_name } : column_change)

let make_column_change_change_type ~(to_ : column_kind) () =
  (Change_type { to_ } : column_change)

let make_column_change_add_options ~(options : new_option list) () =
  (Add_options { options } : column_change)

let make_column_change_update_option ?color ?label ~(option : string) () =
  (Update_option { color; label; option } : column_change)

let make_column_change_set_formula ~(formula : formula) () =
  (Set_formula { formula } : column_change)

let make_column_change_delete_option ~(option : string) () =
  (Delete_option { option } : column_change)

type nonrec cell_write = {
  column : string;  (** The column placement. *)
  value : cell_value;
      (** The value, or \[[CellValue::Clear]\] to empty the cell. *)
}
(** One cell of a row: which column, and its new value. *)

let cell_write_of_yojson : Yojson.Safe.t -> cell_write =
 fun json ->
  let fields = Json.obj json in
  {
    column = Json.required fields "column" Json.string;
    value = Json.required fields "value" cell_value_of_yojson;
  }

and yojson_of_cell_write : cell_write -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("column", Some (Json.of_string value.column));
      ("value", Some (yojson_of_cell_value value.value));
    ]

let make_cell_write ~(column : string) ~(value : cell_value) () =
  ({ column; value } : cell_write)

type nonrec row_change = {
  cells : cell_write list;  (** Its new cells. *)
  row : string;  (** The row. *)
}
(** One row's cells in a \[[RowChanges::PerRow]\] update. *)

let row_change_of_yojson : Yojson.Safe.t -> row_change =
 fun json ->
  let fields = Json.obj json in
  {
    cells = Json.required fields "cells" (Json.list cell_write_of_yojson);
    row = Json.required fields "row" Json.string;
  }

and yojson_of_row_change : row_change -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("cells", Some ((Json.of_list yojson_of_cell_write) value.cells));
      ("row", Some (Json.of_string value.row));
    ]

let make_row_change ~(cells : cell_write list) ~(row : string) () =
  ({ cells; row } : row_change)

(** Which rows an update writes, and with what. *)
type nonrec row_changes =
  | Uniform of {
      cells : cell_write list;  (** The cells each of them gets. *)
      rows : string list;  (** The rows. *)
    }  (** The same cells on every row. *)
  | Per_row of {
      rows : row_change list;  (** The rows and their cells, in order. *)
    }  (** Each row its own cells. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let row_changes_of_yojson : Yojson.Safe.t -> row_changes =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "uniform" ->
      Uniform
        {
          cells = Json.required fields "cells" (Json.list cell_write_of_yojson);
          rows = Json.required fields "rows" (Json.list Json.string);
        }
  | "per_row" ->
      Per_row
        { rows = Json.required fields "rows" (Json.list row_change_of_yojson) }
  | _ -> Unknown json

and yojson_of_row_changes : row_changes -> Yojson.Safe.t =
 fun value ->
  match value with
  | Uniform case ->
      Json.record
        [
          ("kind", Some (`String "uniform"));
          ("cells", Some ((Json.of_list yojson_of_cell_write) case.cells));
          ("rows", Some ((Json.of_list Json.of_string) case.rows));
        ]
  | Per_row case ->
      Json.record
        [
          ("kind", Some (`String "per_row"));
          ("rows", Some ((Json.of_list yojson_of_row_change) case.rows));
        ]
  | Unknown json -> json

let make_row_changes_uniform ~(cells : cell_write list) ~(rows : string list) ()
    =
  (Uniform { cells; rows } : row_changes)

let make_row_changes_per_row ~(rows : row_change list) () =
  (Per_row { rows } : row_changes)

(** A write to a table's rows. *)
type nonrec rows_change =
  | Insert of {
      ids : string list option;
          (** The new rows' ids, minted by the client (UUIDv7), one per row in
order, so later ops of the request and a retry can name them;
left out, the server mints them. *)
      rows : cell_write list list;
          (** One entry per new row: the cells it starts with. Columns left out
start empty. *)
    }
      (** Append rows to the table, in order, each with the cells it starts
with. *)
  | Update of { changes : row_changes  (** Which rows get which cells. *) }
      (** Write cells of existing rows. Last write wins: there is no version
check. *)
  | Delete of { rows : string list  (** The rows, each named once. *) }
      (** Remove rows and their cells. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let rows_change_of_yojson : Yojson.Safe.t -> rows_change =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "insert" ->
      Insert
        {
          ids = Json.optional fields "ids" (Json.list Json.string);
          rows =
            Json.required fields "rows"
              (Json.list (Json.list cell_write_of_yojson));
        }
  | "update" ->
      Update { changes = Json.required fields "changes" row_changes_of_yojson }
  | "delete" ->
      Delete { rows = Json.required fields "rows" (Json.list Json.string) }
  | _ -> Unknown json

and yojson_of_rows_change : rows_change -> Yojson.Safe.t =
 fun value ->
  match value with
  | Insert case ->
      Json.record
        [
          ("kind", Some (`String "insert"));
          ("ids", Option.map (Json.of_list Json.of_string) case.ids);
          ( "rows",
            Some ((Json.of_list (Json.of_list yojson_of_cell_write)) case.rows)
          );
        ]
  | Update case ->
      Json.record
        [
          ("kind", Some (`String "update"));
          ("changes", Some (yojson_of_row_changes case.changes));
        ]
  | Delete case ->
      Json.record
        [
          ("kind", Some (`String "delete"));
          ("rows", Some ((Json.of_list Json.of_string) case.rows));
        ]
  | Unknown json -> json

let make_rows_change_insert ?ids ~(rows : cell_write list list) () =
  (Insert { ids; rows } : rows_change)

let make_rows_change_update ~(changes : row_changes) () =
  (Update { changes } : rows_change)

let make_rows_change_delete ~(rows : string list) () =
  (Delete { rows } : rows_change)

(** A layout as an op asks for it: a board or timeline may leave its title
out. *)
type nonrec requested_layout =
  | Table of {
      columns : view_column list;
          (** How columns show, in display order. A column left out shows
after the listed ones, in the table's order. *)
    }  (** A grid with a row per row. *)
  | Board of {
      card_fields : string list;
          (** The columns a card shows under its title, in order. *)
      group_by : string;
          (** The single-select or single-person column whose values are the
lanes. *)
      hide_empty_lanes : bool;  (** Whether a lane with no cards is hidden. *)
      lanes : lane list;  (** How lanes show, in display order. *)
      title : string option;
          (** The column a card is titled by. Left out, a board keeps the
title it has, and a new board takes the table's first column. *)
    }
      (** Cards in lanes, one per option of a single-select column or per
person of a single-person column, plus one for empty cells. *)
  | Timeline of {
      bar_fields : string list option;
          (** The columns a bar shows after its title, in order. *)
      color_by : string option;
          (** The select or tag column whose options color the bars, if any. *)
      group_by : string option;
          (** The single-select or single-person column grouping the bars, if
any. *)
      range : string;  (** The date-range column whose cells are the bars. *)
      title : string option;
          (** The column a bar is labelled by. Left out, a timeline keeps the
title it has, and a new timeline takes the table's first column. *)
    }  (** Bars on a calendar, one per row, spanning its date-range cell. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let requested_layout_of_yojson : Yojson.Safe.t -> requested_layout =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "table" ->
      Table
        {
          columns =
            Json.required fields "columns" (Json.list view_column_of_yojson);
        }
  | "board" ->
      Board
        {
          card_fields =
            Json.required fields "cardFields" (Json.list Json.string);
          group_by = Json.required fields "groupBy" Json.string;
          hide_empty_lanes = Json.required fields "hideEmptyLanes" Json.bool;
          lanes = Json.required fields "lanes" (Json.list lane_of_yojson);
          title = Json.optional fields "title" Json.string;
        }
  | "timeline" ->
      Timeline
        {
          bar_fields = Json.optional fields "barFields" (Json.list Json.string);
          color_by = Json.optional fields "colorBy" Json.string;
          group_by = Json.optional fields "groupBy" Json.string;
          range = Json.required fields "range" Json.string;
          title = Json.optional fields "title" Json.string;
        }
  | _ -> Unknown json

and yojson_of_requested_layout : requested_layout -> Yojson.Safe.t =
 fun value ->
  match value with
  | Table case ->
      Json.record
        [
          ("kind", Some (`String "table"));
          ("columns", Some ((Json.of_list yojson_of_view_column) case.columns));
        ]
  | Board case ->
      Json.record
        [
          ("kind", Some (`String "board"));
          ("cardFields", Some ((Json.of_list Json.of_string) case.card_fields));
          ("groupBy", Some (Json.of_string case.group_by));
          ("hideEmptyLanes", Some (Json.of_bool case.hide_empty_lanes));
          ("lanes", Some ((Json.of_list yojson_of_lane) case.lanes));
          ("title", Option.map Json.of_string case.title);
        ]
  | Timeline case ->
      Json.record
        [
          ("kind", Some (`String "timeline"));
          ("barFields", Option.map (Json.of_list Json.of_string) case.bar_fields);
          ("colorBy", Some ((Json.of_option Json.of_string) case.color_by));
          ("groupBy", Some ((Json.of_option Json.of_string) case.group_by));
          ("range", Some (Json.of_string case.range));
          ("title", Option.map Json.of_string case.title);
        ]
  | Unknown json -> json

let make_requested_layout_table ~(columns : view_column list) () =
  (Table { columns } : requested_layout)

let make_requested_layout_board ~(card_fields : string list)
    ~(group_by : string) ~(hide_empty_lanes : bool) ~(lanes : lane list) ?title
    () =
  (Board { card_fields; group_by; hide_empty_lanes; lanes; title }
    : requested_layout)

let make_requested_layout_timeline ?bar_fields ?color_by ?group_by
    ~(range : string) ?title () =
  (Timeline { bar_fields; color_by; group_by; range; title } : requested_layout)

type nonrec new_view = {
  layout : requested_layout;
      (** How it draws them; a board left without a card title gets the
table's first column. *)
  name : string;  (** Its name. *)
  query : view_query option;  (** Which rows it shows, in what order. *)
}
(** A view's contents as an op creates it; the server gives it its id,
position and times. *)

let new_view_of_yojson : Yojson.Safe.t -> new_view =
 fun json ->
  let fields = Json.obj json in
  {
    layout = Json.required fields "layout" requested_layout_of_yojson;
    name = Json.required fields "name" Json.string;
    query = Json.optional fields "query" view_query_of_yojson;
  }

and yojson_of_new_view : new_view -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("layout", Some (yojson_of_requested_layout value.layout));
      ("name", Some (Json.of_string value.name));
      ("query", Option.map yojson_of_view_query value.query);
    ]

let make_new_view ~(layout : requested_layout) ~(name : string) ?query () =
  ({ layout; name; query } : new_view)

(** A change to one view. *)
type nonrec view_change =
  | Create of { view : new_view  (** What it shows and how. *) }
      (** Add the view to the table, after its other views. *)
  | Update of {
      layout : requested_layout option;
          (** Its new layout. A board grouped by another column forgets where
its cards were; a board left without a card title keeps the one
it has, or takes the table's first column. *)
      name : string option;  (** Its new name. *)
      query : view_query option;  (** Its new query. *)
    }  (** Change the view's name, query or layout; what is left out stays. *)
  | Delete  (** Remove the view, with where its cards were. *)
  | Move_card of {
      after : string option;
          (** The card that ends up just after it, if any. Given with [before],
it must be the card right after [before]; with neither, the card
goes to the end of the lane. *)
      before : string option;
          (** The card that ends up just before it (it lands right after this
one), if any. *)
      lane : lane_key;
          (** The lane it goes to: an option of a select board's column, a
person for a board grouped by people, or the lane of empty cells. *)
      row : string;  (** The card's row. *)
    }
      (** Move one of the board's cards: into a lane, which sets the row's
grouping cell to the lane's option or person (or empties it for the
lane of empty cells), and to a place there, between two of its
cards. Only an unsorted board's cards move by hand. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let view_change_of_yojson : Yojson.Safe.t -> view_change =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "create" -> Create { view = Json.required fields "view" new_view_of_yojson }
  | "update" ->
      Update
        {
          layout = Json.optional fields "layout" requested_layout_of_yojson;
          name = Json.optional fields "name" Json.string;
          query = Json.optional fields "query" view_query_of_yojson;
        }
  | "delete" -> Delete
  | "move_card" ->
      Move_card
        {
          after = Json.optional fields "after" Json.string;
          before = Json.optional fields "before" Json.string;
          lane = Json.required fields "lane" lane_key_of_yojson;
          row = Json.required fields "row" Json.string;
        }
  | _ -> Unknown json

and yojson_of_view_change : view_change -> Yojson.Safe.t =
 fun value ->
  match value with
  | Create case ->
      Json.record
        [
          ("kind", Some (`String "create"));
          ("view", Some (yojson_of_new_view case.view));
        ]
  | Update case ->
      Json.record
        [
          ("kind", Some (`String "update"));
          ("layout", Option.map yojson_of_requested_layout case.layout);
          ("name", Option.map Json.of_string case.name);
          ("query", Option.map yojson_of_view_query case.query);
        ]
  | Delete -> Json.record [ ("kind", Some (`String "delete")) ]
  | Move_card case ->
      Json.record
        [
          ("kind", Some (`String "move_card"));
          ("after", Option.map Json.of_string case.after);
          ("before", Option.map Json.of_string case.before);
          ("lane", Some (yojson_of_lane_key case.lane));
          ("row", Some (Json.of_string case.row));
        ]
  | Unknown json -> json

let make_view_change_create ~(view : new_view) () =
  (Create { view } : view_change)

let make_view_change_update ?layout ?name ?query () =
  (Update { layout; name; query } : view_change)

let make_view_change_move_card ?after ?before ~(lane : lane_key) ~(row : string)
    () =
  (Move_card { after; before; lane; row } : view_change)

(** One write to a database: its tables, columns, options, rows or views,
grouped by the resource it changes. A request's ops apply in order and
together, or not at all, and every op names a table of the database the
request is for (or, creating one, adds it there). *)
type nonrec database_op =
  | Table of {
      change : table_change;  (** What changes. *)
      table : string;
          (** The table; for a creation, its new id, minted by the client, which
later ops of the request may name. *)
    }
      (** A change to a table itself: its creation, name, removal, or the
order of its columns or views. *)
  | Column of {
      change : column_change;  (** What changes. *)
      column : string;
          (** The column; for a creation, its new id, minted by the client,
which later ops of the request may name. *)
      table : string;  (** The table. *)
    }
      (** A change to one column of a table: its creation, name, type, removal
or options. *)
  | Rows of {
      change : rows_change;  (** What changes. *)
      table : string;  (** The table the rows belong to. *)
    }  (** A write to a table's rows. *)
  | View of {
      change : view_change;  (** What changes. *)
      table : string;  (** The view's table. *)
      view : string;
          (** The view; for a creation, its new id, minted by the client. *)
    }  (** A change to one view of a table. *)
  | Reorder_tables of {
      order : string list;  (** Every table, in its new order. *)
    }
      (** Set the order of the database's tables: [order] names every one of
them once. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let database_op_of_yojson : Yojson.Safe.t -> database_op =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "table" ->
      Table
        {
          change = Json.required fields "change" table_change_of_yojson;
          table = Json.required fields "table" Json.string;
        }
  | "column" ->
      Column
        {
          change = Json.required fields "change" column_change_of_yojson;
          column = Json.required fields "column" Json.string;
          table = Json.required fields "table" Json.string;
        }
  | "rows" ->
      Rows
        {
          change = Json.required fields "change" rows_change_of_yojson;
          table = Json.required fields "table" Json.string;
        }
  | "view" ->
      View
        {
          change = Json.required fields "change" view_change_of_yojson;
          table = Json.required fields "table" Json.string;
          view = Json.required fields "view" Json.string;
        }
  | "reorder_tables" ->
      Reorder_tables
        { order = Json.required fields "order" (Json.list Json.string) }
  | _ -> Unknown json

and yojson_of_database_op : database_op -> Yojson.Safe.t =
 fun value ->
  match value with
  | Table case ->
      Json.record
        [
          ("kind", Some (`String "table"));
          ("change", Some (yojson_of_table_change case.change));
          ("table", Some (Json.of_string case.table));
        ]
  | Column case ->
      Json.record
        [
          ("kind", Some (`String "column"));
          ("change", Some (yojson_of_column_change case.change));
          ("column", Some (Json.of_string case.column));
          ("table", Some (Json.of_string case.table));
        ]
  | Rows case ->
      Json.record
        [
          ("kind", Some (`String "rows"));
          ("change", Some (yojson_of_rows_change case.change));
          ("table", Some (Json.of_string case.table));
        ]
  | View case ->
      Json.record
        [
          ("kind", Some (`String "view"));
          ("change", Some (yojson_of_view_change case.change));
          ("table", Some (Json.of_string case.table));
          ("view", Some (Json.of_string case.view));
        ]
  | Reorder_tables case ->
      Json.record
        [
          ("kind", Some (`String "reorder_tables"));
          ("order", Some ((Json.of_list Json.of_string) case.order));
        ]
  | Unknown json -> json

let make_database_op_table ~(change : table_change) ~(table : string) () =
  (Table { change; table } : database_op)

let make_database_op_column ~(change : column_change) ~(column : string)
    ~(table : string) () =
  (Column { change; column; table } : database_op)

let make_database_op_rows ~(change : rows_change) ~(table : string) () =
  (Rows { change; table } : database_op)

let make_database_op_view ~(change : view_change) ~(table : string)
    ~(view : string) () =
  (View { change; table; view } : database_op)

let make_database_op_reorder_tables ~(order : string list) () =
  (Reorder_tables { order } : database_op)

type nonrec apply_ops_request = {
  base_versions : (string * table_version) list option;
      (** The version each named table must still be at, as the caller read
it. A table that moved refuses the batch as a conflict, so a schema
edit made against what the caller saw does not overwrite another's.
Left out, ops are last-write-wins. *)
  ops : database_op list;
      (** The ops, in the order they apply, each grouped by the resource it
changes ([table], [column], [rows], [view], [reorder_tables]) with a
[change] saying how. Every one names a table of this database, or one
an earlier op of the batch creates: tables, columns, options and
views carry ids the client mints (UUIDv7), so a later op can name
them. An id that already names something refuses the batch. *)
}
(** A batch of ops for one database, applied in order, in one transaction,
together or not at all. *)

let apply_ops_request_of_yojson : Yojson.Safe.t -> apply_ops_request =
 fun json ->
  let fields = Json.obj json in
  {
    base_versions =
      Json.optional fields "baseVersions" (Json.map table_version_of_yojson);
    ops = Json.required fields "ops" (Json.list database_op_of_yojson);
  }

and yojson_of_apply_ops_request : apply_ops_request -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "baseVersions",
        Option.map (Json.of_map yojson_of_table_version) value.base_versions );
      ("ops", Some ((Json.of_list yojson_of_database_op) value.ops));
    ]

let make_apply_ops_request ?base_versions ~(ops : database_op list) () =
  ({ base_versions; ops } : apply_ops_request)

type nonrec apply_ops_response = {
  changes : committed_change list;
      (** The journal's change for each table version the batch produced: the
ids [POST /databases/{id}/changes/{change}/undo] takes. *)
  results : op_result list;
      (** One result per op, in the order the ops were sent. Each is grouped as
its op is: the same outer [kind], naming the same ids, with a
[change] saying what happened. *)
}
(** What each op of a batch did. *)

let apply_ops_response_of_yojson : Yojson.Safe.t -> apply_ops_response =
 fun json ->
  let fields = Json.obj json in
  {
    changes =
      Json.required fields "changes" (Json.list committed_change_of_yojson);
    results = Json.required fields "results" (Json.list op_result_of_yojson);
  }

and yojson_of_apply_ops_response : apply_ops_response -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("changes", Some ((Json.of_list yojson_of_committed_change) value.changes));
      ("results", Some ((Json.of_list yojson_of_op_result) value.results));
    ]

let make_apply_ops_response ~(changes : committed_change list)
    ~(results : op_result list) () =
  ({ changes; results } : apply_ops_response)

