type nonrec attachment_change_delta_value = {
  add : new_attachment list;  (** New attachments to append. *)
  remove : string list;  (** Existing attachment UUIDs to remove. *)
}
(** Remove stored attachment identities and append new references. *)

let attachment_change_delta_value_of_yojson :
    Yojson.Safe.t -> attachment_change_delta_value =
 fun json ->
  let fields = Json.obj json in
  {
    add = Json.required fields "add" (Json.list new_attachment_of_yojson);
    remove = Json.required fields "remove" (Json.list Json.string);
  }

and yojson_of_attachment_change_delta_value :
    attachment_change_delta_value -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("add", Some ((Json.of_list yojson_of_new_attachment) value.add));
      ("remove", Some ((Json.of_list Json.of_string) value.remove));
    ]

let make_attachment_change_delta_value ~(add : new_attachment list)
    ~(remove : string list) () =
  ({ add; remove } : attachment_change_delta_value)

(** Attachment changes interpreted by the common command boundary. *)
type nonrec attachment_change =
  | Preserve  (** Keep current attachments. *)
  | Replace of { value : new_attachment list  (** Replace all attachments. *) }
      (** Replace all attachments. *)
  | Delta of {
      value : attachment_change_delta_value;
          (** Remove stored attachment identities and append new references. *)
    }  (** Remove stored attachment identities and append new references. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let attachment_change_of_yojson : Yojson.Safe.t -> attachment_change =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "preserve" -> Preserve
  | "replace" ->
      Replace
        {
          value =
            Json.required fields "value" (Json.list new_attachment_of_yojson);
        }
  | "delta" ->
      Delta
        {
          value =
            Json.required fields "value" attachment_change_delta_value_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_attachment_change : attachment_change -> Yojson.Safe.t =
 fun value ->
  match value with
  | Preserve -> Json.record [ ("type", Some (`String "preserve")) ]
  | Replace case ->
      Json.record
        [
          ("type", Some (`String "replace"));
          ("value", Some ((Json.of_list yojson_of_new_attachment) case.value));
        ]
  | Delta case ->
      Json.record
        [
          ("type", Some (`String "delta"));
          ("value", Some (yojson_of_attachment_change_delta_value case.value));
        ]
  | Unknown json -> json

let make_attachment_change_replace ~(value : new_attachment list) () =
  (Replace { value } : attachment_change)

let make_attachment_change_delta ~(value : attachment_change_delta_value) () =
  (Delta { value } : attachment_change)

