type nonrec awareness = {
  column_id : string option;
      (** The column placement of the focused cell, if any. *)
  editing : bool option;  (** Whether the cell is open for editing. *)
  end_column_id : string option;
      (** The opposite column corner of a selected rectangle, if any. *)
  end_row_id : string option;
      (** The opposite row corner of a selected rectangle, if any. *)
  left : bool option;
      (** Whether the viewer left the database; other viewers drop their state. *)
  peer_id : string option;
      (** This mounted client's random peer id, distinct from its authenticated user.
Older clients omit it and remain visible as one peer per user. *)
  row_id : string option;  (** The row of the focused cell, if any. *)
  table_id : string;  (** The table the viewer is looking at. *)
}
(** Where one viewer is inside a database right now: ephemeral, relayed to
the other viewers and never stored. A missing row or column means the
viewer is on the table but on no cell. Optional end row and column IDs
mark the opposite corner of a rectangular cell selection. *)

let awareness_of_yojson : Yojson.Safe.t -> awareness =
 fun json ->
  let fields = Json.obj json in
  {
    column_id = Json.optional fields "columnId" Json.string;
    editing = Json.optional fields "editing" Json.bool;
    end_column_id = Json.optional fields "endColumnId" Json.string;
    end_row_id = Json.optional fields "endRowId" Json.string;
    left = Json.optional fields "left" Json.bool;
    peer_id = Json.optional fields "peerId" Json.string;
    row_id = Json.optional fields "rowId" Json.string;
    table_id = Json.required fields "tableId" Json.string;
  }

and yojson_of_awareness : awareness -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("columnId", Option.map Json.of_string value.column_id);
      ("editing", Option.map Json.of_bool value.editing);
      ("endColumnId", Option.map Json.of_string value.end_column_id);
      ("endRowId", Option.map Json.of_string value.end_row_id);
      ("left", Option.map Json.of_bool value.left);
      ("peerId", Option.map Json.of_string value.peer_id);
      ("rowId", Option.map Json.of_string value.row_id);
      ("tableId", Some (Json.of_string value.table_id));
    ]

let make_awareness ?column_id ?editing ?end_column_id ?end_row_id ?left ?peer_id
    ?row_id ~(table_id : string) () =
  ({
     column_id;
     editing;
     end_column_id;
     end_row_id;
     left;
     peer_id;
     row_id;
     table_id;
   }
    : awareness)

