type nonrec border_edges =
  | All
  | Outside
  | Inside
  | Top
  | Bottom
  | Left
  | Right
  | Inside_horizontal
  | Inside_vertical
  | Unknown of string  (** A value this SDK version does not know. *)

let border_edges_of_yojson : Yojson.Safe.t -> border_edges =
 fun json ->
  match Json.string json with
  | "all" -> All
  | "outside" -> Outside
  | "inside" -> Inside
  | "top" -> Top
  | "bottom" -> Bottom
  | "left" -> Left
  | "right" -> Right
  | "insideHorizontal" -> Inside_horizontal
  | "insideVertical" -> Inside_vertical
  | other -> Unknown other

and yojson_of_border_edges : border_edges -> Yojson.Safe.t =
 fun value ->
  match value with
  | All -> `String "all"
  | Outside -> `String "outside"
  | Inside -> `String "inside"
  | Top -> `String "top"
  | Bottom -> `String "bottom"
  | Left -> `String "left"
  | Right -> `String "right"
  | Inside_horizontal -> `String "insideHorizontal"
  | Inside_vertical -> `String "insideVertical"
  | Unknown other -> `String other

