(** Bullet style for paragraphs. *)
type nonrec bullet_spec =
  | None_  (** No bullet. *)
  | Inherit
      (** Inherit from the layout/master (removes explicit bullet settings). *)
  | Char of { char : string  (** The bullet character. *) }
      (** A character bullet. *)
  | Number of {
      scheme : string;  (** Numbering scheme. *)
      start : int option;  (** First number. *)
    }
      (** Automatic numbering ([arabicPeriod], [romanUcPeriod], [alphaLcParenR]...). *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let bullet_spec_of_yojson : Yojson.Safe.t -> bullet_spec =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "none" -> None_
  | "inherit" -> Inherit
  | "char" -> Char { char = Json.required fields "char" Json.string }
  | "number" ->
      Number
        {
          scheme = Json.required fields "scheme" Json.string;
          start = Json.optional fields "start" Json.int;
        }
  | _ -> Unknown json

and yojson_of_bullet_spec : bullet_spec -> Yojson.Safe.t =
 fun value ->
  match value with
  | None_ -> Json.record [ ("kind", Some (`String "none")) ]
  | Inherit -> Json.record [ ("kind", Some (`String "inherit")) ]
  | Char case ->
      Json.record
        [
          ("kind", Some (`String "char"));
          ("char", Some (Json.of_string case.char));
        ]
  | Number case ->
      Json.record
        [
          ("kind", Some (`String "number"));
          ("scheme", Some (Json.of_string case.scheme));
          ("start", Option.map Json.of_int case.start);
        ]
  | Unknown json -> json

let make_bullet_spec_char ~(char : string) () = (Char { char } : bullet_spec)

let make_bullet_spec_number ~(scheme : string) ?start () =
  (Number { scheme; start } : bullet_spec)

