type nonrec spreadsheet_cell_value_value =
  | Bool of bool  (** TRUE or FALSE. *)
  | Float of float  (** A number, passed to the engine exactly as written. *)
  | String of string
      (** Text, or a formula starting with =, at most 10,000 characters. Macro links render as mention pills.
For named pills, use the same inline tags as docs: <m-user-mention>\{"userId":"macro|person\@example.com","email":"person\@example.com","displayName":"Person"\}</m-user-mention>
or <m-document-mention>\{"documentId":"UUID","documentName":"Budget","blockName":"spreadsheet"\}</m-document-mention>.
A date chip is <m-date-mention>\{"date":"2026-09-28T00:00:00.000Z","displayFormat":"Sep 28"\}</m-date-mention>; a cell holding only that chip calculates as the date.
Plain dates such as 9/28/2026 or =DATE(2026,9,28) display as dates without a number format.
Tags can be mixed with ordinary text. Use IDs from search/read results; do not invent them. Other Markdown is literal. *)

let spreadsheet_cell_value_value_of_yojson :
    Yojson.Safe.t -> spreadsheet_cell_value_value =
 fun json ->
  Json.first_ok
    [
      (fun json -> Bool (Json.bool json));
      (fun json -> Float (Json.float json));
      (fun json -> String (Json.string json));
    ]
    json

and yojson_of_spreadsheet_cell_value_value :
    spreadsheet_cell_value_value -> Yojson.Safe.t =
 fun value ->
  match value with
  | Bool inner -> Json.of_bool inner
  | Float inner -> Json.of_float inner
  | String inner -> Json.of_string inner

type nonrec spreadsheet_cell_value = spreadsheet_cell_value_value option
(** A cell's new input, typed as the caller has it. *)

let spreadsheet_cell_value_of_yojson : Yojson.Safe.t -> spreadsheet_cell_value =
 fun json -> (Json.option spreadsheet_cell_value_value_of_yojson) json

and yojson_of_spreadsheet_cell_value : spreadsheet_cell_value -> Yojson.Safe.t =
 fun value -> (Json.of_option yojson_of_spreadsheet_cell_value_value) value

type nonrec spreadsheet_cell_input = {
  address : string;  (** A1 address, from A1 through XFD100000. *)
  value : spreadsheet_cell_value;
      (** The new input: text or a formula, a number, true/false, or null to empty the cell. *)
}
(** Source text for one cell. Formulas start with =; a leading apostrophe forces literal text. *)

let spreadsheet_cell_input_of_yojson : Yojson.Safe.t -> spreadsheet_cell_input =
