and yojson_of_spreadsheet_cell_input : spreadsheet_cell_input -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("address", Some (Json.of_string value.address));
      ("value", Some (yojson_of_spreadsheet_cell_value value.value));
    ]

let make_spreadsheet_cell_input ~(address : string)
    ~(value : spreadsheet_cell_value) () =
  ({ address; value } : spreadsheet_cell_input)

