type nonrec calculate_spreadsheet_request = {
  formulas : spreadsheet_formula list;
      (** At most 20 formulas beginning with =. *)
  overrides : spreadsheet_override list option;
      (** Hypothetical cell inputs, never saved. *)
  sheet_id : string option;
      (** Sheet for unqualified references; defaults to the first sheet. *)
}
(** Scratch formulas to evaluate against a workbook, without writing anything. *)

let calculate_spreadsheet_request_of_yojson :
    Yojson.Safe.t -> calculate_spreadsheet_request =
 fun json ->
  let fields = Json.obj json in
  {
    formulas =
      Json.required fields "formulas" (Json.list spreadsheet_formula_of_yojson);
    overrides =
