let call_active_response_of_yojson : Yojson.Safe.t -> call_active_response =
 fun json ->
  let fields = Json.obj json in
  {
    call_id = Json.required fields "callId" Json.string;
    channel_id = Json.required fields "channelId" Json.string;
    created_at = Json.required fields "createdAt" Json.string;
    created_by = Json.required fields "createdBy" Json.string;
  }

and yojson_of_call_active_response : call_active_response -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("callId", Some (Json.of_string value.call_id));
      ("channelId", Some (Json.of_string value.channel_id));
      ("createdAt", Some (Json.of_string value.created_at));
      ("createdBy", Some (Json.of_string value.created_by));
    ]

let make_call_active_response ~(call_id : string) ~(channel_id : string)
    ~(created_at : string) ~(created_by : string) () =
  ({ call_id; channel_id; created_at; created_by } : call_active_response)

(** Where a call's discussion lives, decided once when the call is created.
[channel_id] cannot decide this: past channel calls keep their own thread. *)
type nonrec call_discussion =
  | Channel_thread of {
      channel_id : string;  (** The channel holding the thread. *)
      root_id : string;  (** The thread's root message. *)
    }
      (** A thread in the call's channel, rooted at the message with the call's id. *)
  | Call_chat of { call_id : string  (** The call owning the thread. *) }
      (** The call's own thread on the call parent. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let call_discussion_of_yojson : Yojson.Safe.t -> call_discussion =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "channel_thread" ->
      Channel_thread
        {
          channel_id = Json.required fields "channel_id" Json.string;
          root_id = Json.required fields "root_id" Json.string;
        }
  | "call_chat" ->
      Call_chat { call_id = Json.required fields "call_id" Json.string }
  | _ -> Unknown json

and yojson_of_call_discussion : call_discussion -> Yojson.Safe.t =
 fun value ->
  match value with
  | Channel_thread case ->
      Json.record
        [
          ("kind", Some (`String "channel_thread"));
          ("channel_id", Some (Json.of_string case.channel_id));
          ("root_id", Some (Json.of_string case.root_id));
        ]
  | Call_chat case ->
      Json.record
        [
          ("kind", Some (`String "call_chat"));
          ("call_id", Some (Json.of_string case.call_id));
        ]
  | Unknown json -> json

let make_call_discussion_channel_thread ~(channel_id : string)
    ~(root_id : string) () =
  (Channel_thread { channel_id; root_id } : call_discussion)

let make_call_discussion_call_chat ~(call_id : string) () =
  (Call_chat { call_id } : call_discussion)

(** A channel call's life, as its timeline row shows it. *)
type nonrec call_entry_status =
  | Live  (** The call has not ended. *)
  | Ended of {
      duration_ms : int64;  (** How long it lasted. *)
      ended_at : string;  (** When it ended. *)
    }  (** The call ended. *)
  | Record_deleted
      (** The call's record was deleted; its discussion stays in the channel. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let call_entry_status_of_yojson : Yojson.Safe.t -> call_entry_status =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "state" with
  | "live" -> Live
  | "ended" ->
      Ended
        {
          duration_ms = Json.required fields "duration_ms" Json.int64;
          ended_at = Json.required fields "ended_at" Json.string;
        }
  | "record_deleted" -> Record_deleted
  | _ -> Unknown json

and yojson_of_call_entry_status : call_entry_status -> Yojson.Safe.t =
 fun value ->
  match value with
  | Live -> Json.record [ ("state", Some (`String "live")) ]
  | Ended case ->
      Json.record
        [
          ("state", Some (`String "ended"));
          ("duration_ms", Some (Json.of_int64 case.duration_ms));
          ("ended_at", Some (Json.of_string case.ended_at));
        ]
  | Record_deleted -> Json.record [ ("state", Some (`String "record_deleted")) ]
  | Unknown json -> json

let make_call_entry_status_ended ~(duration_ms : int64) ~(ended_at : string) ()
    =
  (Ended { duration_ms; ended_at } : call_entry_status)

(** Viewer-relative attendance status for a call record.
Serializes as [ATTENDED], [MISSED], or [UNATTENDED]. *)
type nonrec call_status =
  | Attended
  | Missed
  | Unattended
  | Unknown of string  (** A value this SDK version does not know. *)

let call_status_of_yojson : Yojson.Safe.t -> call_status =
 fun json ->
  match Json.string json with
  | "ATTENDED" -> Attended
  | "MISSED" -> Missed
  | "UNATTENDED" -> Unattended
  | other -> Unknown other

and yojson_of_call_status : call_status -> Yojson.Safe.t =
 fun value ->
  match value with
  | Attended -> `String "ATTENDED"
  | Missed -> `String "MISSED"
  | Unattended -> `String "UNATTENDED"
  | Unknown other -> `String other

type nonrec call_filters = {
  attended : bool option;
      (** Legacy filter by whether the requesting user attended the call.
Prefer \[[CallFilters::status]\] for new callers.
[None] = no filter, [Some(true)] = only calls the user joined,
[Some(false)] = only calls the user did not join. *)
  call_ids : string list option;
      (** Call record IDs to filter by. Empty to include all calls. *)
  channel_ids : string list option;
      (** Channel IDs to filter calls by. Empty to include all calls. *)
  speaker_ids : string list option;
      (** Speaker macro user ids. Empty to include all. *)
  status : call_status option;
}
