(** Public call events. Private variants carry a recipient on the broker only. *)
type nonrec call_notification_event =
  | Call_started of {
      metadata : call_notification_metadata;  (** A call started. *)
    }  (** A call started. *)
  | Call_ended of {
      metadata : call_notification_metadata;  (** A call ended. *)
    }  (** A call ended. *)
  | Call_participant_joined of {
      metadata : call_notification_metadata;
          (** A participant entered the RTC room. *)
    }  (** A participant entered the RTC room. *)
  | Call_participant_left of {
      metadata : call_notification_metadata;
          (** A participant left the RTC room. *)
    }  (** A participant left the RTC room. *)
  | Call_recording_ready of {
      metadata : call_notification_metadata;
          (** A recording became available. *)
    }  (** A recording became available. *)
  | Call_summarized of {
      metadata : call_notification_metadata;  (** A summary became available. *)
    }  (** A summary became available. *)
  | Call_ringing of {
      metadata : call_notification_metadata;  (** The recipient is being rung. *)
    }  (** The recipient is being rung. *)
  | Call_answered of {
      metadata : call_notification_metadata;  (** The recipient answered. *)
    }  (** The recipient answered. *)
  | Call_declined of {
      metadata : call_notification_metadata;  (** The recipient declined. *)
    }  (** The recipient declined. *)
  | Call_invited of {
      metadata : call_notification_metadata;  (** The recipient was invited. *)
    }  (** The recipient was invited. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let call_notification_event_of_yojson : Yojson.Safe.t -> call_notification_event
    =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "event_type" with
  | "call.started" ->
      Call_started
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.ended" ->
      Call_ended
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.participant_joined" ->
      Call_participant_joined
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.participant_left" ->
      Call_participant_left
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.recording_ready" ->
      Call_recording_ready
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.summarized" ->
      Call_summarized
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.ringing" ->
      Call_ringing
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.answered" ->
      Call_answered
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.declined" ->
      Call_declined
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | "call.invited" ->
      Call_invited
        {
          metadata =
            Json.required fields "metadata" call_notification_metadata_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_call_notification_event : call_notification_event -> Yojson.Safe.t
    =
 fun value ->
  match value with
  | Call_started case ->
      Json.record
        [
          ("event_type", Some (`String "call.started"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_ended case ->
      Json.record
        [
          ("event_type", Some (`String "call.ended"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_participant_joined case ->
      Json.record
        [
          ("event_type", Some (`String "call.participant_joined"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_participant_left case ->
      Json.record
        [
          ("event_type", Some (`String "call.participant_left"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_recording_ready case ->
      Json.record
        [
          ("event_type", Some (`String "call.recording_ready"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_summarized case ->
      Json.record
        [
          ("event_type", Some (`String "call.summarized"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_ringing case ->
      Json.record
        [
          ("event_type", Some (`String "call.ringing"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_answered case ->
      Json.record
        [
          ("event_type", Some (`String "call.answered"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_declined case ->
      Json.record
        [
          ("event_type", Some (`String "call.declined"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Call_invited case ->
      Json.record
        [
          ("event_type", Some (`String "call.invited"));
          ("metadata", Some (yojson_of_call_notification_metadata case.metadata));
        ]
  | Unknown json -> json

