  | Unknown other -> `String other

type nonrec guest_id = string
(** A non-account guest of a single call session.

The id doubles as the guest's RTC participant identity, so identities are
opaque UUIDs and never share a namespace (or a column) with Macro user
ids. Only the server mints them; Macro users keep [macro|…] identities,
so an RTC identity classifies as exactly one of the two. *)

let guest_id_of_yojson : Yojson.Safe.t -> guest_id =
 fun json -> Json.string json

and yojson_of_guest_id : guest_id -> Yojson.Safe.t =
 fun value -> Json.of_string value

type nonrec call_record_guest = {
  display_name : string;  (** Guest-provided display name. *)
  id : guest_id;
      (** Opaque guest identity; matches the guest's transcript [speaker_id]. *)
  joined_at : string;  (** When the guest joined the call. *)
  left_at : string option;
      (** When the guest left (None if still in an active call). *)
}
(** A non-account guest as returned in a \[[CallRecord]\]. *)

let call_record_guest_of_yojson : Yojson.Safe.t -> call_record_guest =
 fun json ->
  let fields = Json.obj json in
  {
    display_name = Json.required fields "displayName" Json.string;
    id = Json.required fields "id" guest_id_of_yojson;
    joined_at = Json.required fields "joinedAt" Json.string;
    left_at = Json.optional fields "leftAt" Json.string;
  }

and yojson_of_call_record_guest : call_record_guest -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("displayName", Some (Json.of_string value.display_name));
      ("id", Some (yojson_of_guest_id value.id));
      ("joinedAt", Some (Json.of_string value.joined_at));
      ("leftAt", Option.map Json.of_string value.left_at);
    ]

let make_call_record_guest ~(display_name : string) ~(id : guest_id)
    ~(joined_at : string) ?left_at () =
  ({ display_name; id; joined_at; left_at } : call_record_guest)

