type nonrec call_record = {
  call_id : string;  (** The call identifier. *)
  channel_id : string option;  (** The channel this call belongs to. *)
  channel_name : string option;  (** Resolved display name for the channel. *)
  created_by : string;  (** User who created the call. *)
  custom_name : string option;
      (** User-supplied or AI-generated display name for the call. Only set on
archived [call_records]; active calls always return [None]. *)
  discussion : call_discussion;  (** Where this call's discussion lives. *)
  duration_ms : int64 option;
      (** Call duration in milliseconds (None if still active). *)
  egress_id : string option;  (** Recording egress ID, if any. *)
  ended_at : string option;  (** When the call ended (None if still active). *)
  guests : call_record_guest list;
      (** Non-account guests (both active and historic). Guests only ever exist
on standalone meeting calls, never on channel calls. *)
  is_active : bool;
      (** Whether the call is currently active (from [calls] table). *)
  participants : call_record_participant list;
      (** Macro-account participants (both active and historic). *)
  recording_preview_url : string option;
      (** Presigned URL for the call recording preview image, if available. *)
  recording_started_at : string option;
      (** When the egress recording actually began. [None] until the
[egress_started] webhook arrives (typically a few seconds after
[started_at]). Frontend should anchor transcript-to-audio sync to
this value when present, falling back to [started_at] otherwise. *)
  recording_url : string option;
      (** Presigned URL for the call recording, if available. *)
  room_name : string option;
      (** The RTC room name. [None] for imported calls, which never had a room. *)
  share_with_team : bool;
      (** Whether the call is shared with the creator's team. While the call is
live this is the pending toggle applied at archive; afterwards it
mirrors [team_share_access_level]. *)
  source : call_record_source option;
  started_at : string;
      (** When the call started (created_at for active, started_at for archived). *)
  status : call_status option;
  summary : string option;
      (** AI-generated summary of the call. Only set on archived [call_records]
once summarization has run; active calls always return [None]. *)
  team_share_access_level : access_level option;
  transcript : call_record_transcript_segment list;
      (** Transcript segments ordered by [sequence_num]. *)
  user_access_level : access_level option;
  viewer_has_declined : bool option;
      (** Whether the authenticated viewer has declined this call on any device.
Set on the single-record read so clients that missed [call_declined]
can still stop ringing via reconciliation; [false] in list contexts. *)
}
(** Full record of a call, unifying rows from [calls] (active) and
[call_records] (archived) into a single response shape. *)

let call_record_of_yojson : Yojson.Safe.t -> call_record =
 fun json ->
  let fields = Json.obj json in
  {
    call_id = Json.required fields "callId" Json.string;
    channel_id = Json.optional fields "channelId" Json.string;
    channel_name = Json.optional fields "channelName" Json.string;
    created_by = Json.required fields "createdBy" Json.string;
    custom_name = Json.optional fields "customName" Json.string;
    discussion = Json.required fields "discussion" call_discussion_of_yojson;
    duration_ms = Json.optional fields "durationMs" Json.int64;
    egress_id = Json.optional fields "egressId" Json.string;
    ended_at = Json.optional fields "endedAt" Json.string;
    guests =
      Json.required fields "guests" (Json.list call_record_guest_of_yojson);
    is_active = Json.required fields "isActive" Json.bool;
    participants =
      Json.required fields "participants"
        (Json.list call_record_participant_of_yojson);
    recording_preview_url =
      Json.optional fields "recordingPreviewUrl" Json.string;
    recording_started_at = Json.optional fields "recordingStartedAt" Json.string;
    recording_url = Json.optional fields "recordingUrl" Json.string;
    room_name = Json.optional fields "roomName" Json.string;
    share_with_team = Json.required fields "shareWithTeam" Json.bool;
    source = Json.optional fields "source" call_record_source_of_yojson;
    started_at = Json.required fields "startedAt" Json.string;
    status = Json.optional fields "status" call_status_of_yojson;
    summary = Json.optional fields "summary" Json.string;
    team_share_access_level =
      Json.optional fields "teamShareAccessLevel" access_level_of_yojson;
    transcript =
      Json.required fields "transcript"
        (Json.list call_record_transcript_segment_of_yojson);
    user_access_level =
      Json.optional fields "userAccessLevel" access_level_of_yojson;
    viewer_has_declined = Json.optional fields "viewerHasDeclined" Json.bool;
  }

and yojson_of_call_record : call_record -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("callId", Some (Json.of_string value.call_id));
      ("channelId", Option.map Json.of_string value.channel_id);
      ("channelName", Option.map Json.of_string value.channel_name);
      ("createdBy", Some (Json.of_string value.created_by));
      ("customName", Option.map Json.of_string value.custom_name);
      ("discussion", Some (yojson_of_call_discussion value.discussion));
      ("durationMs", Option.map Json.of_int64 value.duration_ms);
      ("egressId", Option.map Json.of_string value.egress_id);
      ("endedAt", Option.map Json.of_string value.ended_at);
      ("guests", Some ((Json.of_list yojson_of_call_record_guest) value.guests));
      ("isActive", Some (Json.of_bool value.is_active));
      ( "participants",
        Some
          ((Json.of_list yojson_of_call_record_participant) value.participants)
      );
      ( "recordingPreviewUrl",
        Option.map Json.of_string value.recording_preview_url );
      ( "recordingStartedAt",
        Option.map Json.of_string value.recording_started_at );
      ("recordingUrl", Option.map Json.of_string value.recording_url);
      ("roomName", Option.map Json.of_string value.room_name);
      ("shareWithTeam", Some (Json.of_bool value.share_with_team));
      ("source", Option.map yojson_of_call_record_source value.source);
      ("startedAt", Some (Json.of_string value.started_at));
      ("status", Option.map yojson_of_call_status value.status);
      ("summary", Option.map Json.of_string value.summary);
      ( "teamShareAccessLevel",
        Option.map yojson_of_access_level value.team_share_access_level );
      ( "transcript",
        Some
          ((Json.of_list yojson_of_call_record_transcript_segment)
             value.transcript) );
      ( "userAccessLevel",
        Option.map yojson_of_access_level value.user_access_level );
      ("viewerHasDeclined", Option.map Json.of_bool value.viewer_has_declined);
    ]

let make_call_record ~(call_id : string) ?channel_id ?channel_name
    ~(created_by : string) ?custom_name ~(discussion : call_discussion)
    ?duration_ms ?egress_id ?ended_at ~(guests : call_record_guest list)
    ~(is_active : bool) ~(participants : call_record_participant list)
    ?recording_preview_url ?recording_started_at ?recording_url ?room_name
    ~(share_with_team : bool) ?source ~(started_at : string) ?status ?summary
    ?team_share_access_level ~(transcript : call_record_transcript_segment list)
    ?user_access_level ?viewer_has_declined () =
  ({
