     custom_name;
     discussion;
     duration_ms;
     egress_id;
     ended_at;
     guests;
     is_active;
     participants;
     recording_preview_url;
     recording_started_at;
     recording_url;
     room_name;
     share_with_team;
     source;
     started_at;
     status;
     summary;
     team_share_access_level;
     transcript;
     user_access_level;
     viewer_has_declined;
   }
    : call_record)

