type nonrec with_call_id = { call_id : string  (** The call identifier. *) }
(** Wrapper carrying just a call id. Used by the \[[CallRecordPreview::DoesNotExist]\]
variant. *)

let with_call_id_of_yojson : Yojson.Safe.t -> with_call_id =
 fun json ->
  let fields = Json.obj json in
  { call_id = Json.required fields "callId" Json.string }

and yojson_of_with_call_id : with_call_id -> Yojson.Safe.t =
 fun value -> Json.record [ ("callId", Some (Json.of_string value.call_id)) ]

let make_with_call_id ~(call_id : string) () = ({ call_id } : with_call_id)

(** Lightweight preview of a call record, returned by the batch preview endpoint.

Each requested id resolves to one of two outcomes: the call exists
([Exists]) or it does not ([DoesNotExist]). The endpoint does not perform
access checks, so there is no separate "not authorized" variant. *)
type nonrec call_record_preview =
  | Exists of call_record_preview_data
      (** The call exists (in either the active or archived table). *)
  | Does_not_exist of with_call_id
      (** No call with this id exists in either the active or archived tables. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let call_record_preview_of_yojson : Yojson.Safe.t -> call_record_preview =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "exists" -> Exists (call_record_preview_data_of_yojson json)
  | "does_not_exist" -> Does_not_exist (with_call_id_of_yojson json)
  | _ -> Unknown json

and yojson_of_call_record_preview : call_record_preview -> Yojson.Safe.t =
 fun value ->
  match value with
  | Exists inner ->
      Json.with_tag "type" "exists" (yojson_of_call_record_preview_data inner)
  | Does_not_exist inner ->
      Json.with_tag "type" "does_not_exist" (yojson_of_with_call_id inner)
  | Unknown json -> json

