type nonrec canvas_error_code =
  | Invalid_request
  | Revision_conflict
  | Edit_rejected
  | Edit_refused
  | Edit_failed
  | Internal
  | Unknown of string  (** A value this SDK version does not know. *)

let canvas_error_code_of_yojson : Yojson.Safe.t -> canvas_error_code =
 fun json ->
  match Json.string json with
  | "invalid_request" -> Invalid_request
  | "revision_conflict" -> Revision_conflict
  | "edit_rejected" -> Edit_rejected
  | "edit_refused" -> Edit_refused
  | "edit_failed" -> Edit_failed
  | "internal" -> Internal
  | other -> Unknown other

and yojson_of_canvas_error_code : canvas_error_code -> Yojson.Safe.t =
 fun value ->
  match value with
  | Invalid_request -> `String "invalid_request"
  | Revision_conflict -> `String "revision_conflict"
  | Edit_rejected -> `String "edit_rejected"
  | Edit_refused -> `String "edit_refused"
  | Edit_failed -> `String "edit_failed"
  | Internal -> `String "internal"
  | Unknown other -> `String other

