  | No_access inner ->
      Json.with_tag "type" "no_access" (yojson_of_with_channel_id inner)
  | Does_not_exist inner ->
      Json.with_tag "type" "does_not_exist" (yojson_of_with_channel_id inner)
  | Unknown json -> json

