(** Events that can be published to \[[MacroChannelsTopic]\]. *)
type nonrec channel_topic_event =
  | Channel_picture_changed of {
      metadata : channel_picture_changed_metadata;
          (** A channel's profile picture changed. *)
    }  (** A channel's profile picture changed. *)
  | Channel_created of {
      metadata : channel_created_metadata;  (** A channel was created. *)
    }  (** A channel was created. *)
  | Channel_updated of {
      metadata : channel_updated_metadata;
          (** A channel's metadata was updated (rename). *)
    }  (** A channel's metadata was updated (rename). *)
  | Channel_deleted of {
      metadata : channel_deleted_metadata;  (** A channel was deleted. *)
    }  (** A channel was deleted. *)
  | Channel_participant_added of {
      metadata : channel_participant_added_metadata;
          (** Participants were added to a channel (admin invite or self-join). *)
    }  (** Participants were added to a channel (admin invite or self-join). *)
  | Channel_participant_removed of {
      metadata : channel_participant_removed_metadata;
          (** Participants were removed from a channel (admin removal or self-leave). *)
    }
      (** Participants were removed from a channel (admin removal or self-leave). *)
  | Channel_access_requested of {
      metadata : channel_access_requested_metadata;
          (** Someone outside a channel asked to join it. *)
    }  (** Someone outside a channel asked to join it. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let channel_topic_event_of_yojson : Yojson.Safe.t -> channel_topic_event =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "event_type" with
  | "channel.picture_changed" ->
      Channel_picture_changed
        {
          metadata =
            Json.required fields "metadata"
              channel_picture_changed_metadata_of_yojson;
        }
  | "channel.created" ->
      Channel_created
        {
          metadata =
            Json.required fields "metadata" channel_created_metadata_of_yojson;
        }
  | "channel.updated" ->
      Channel_updated
        {
          metadata =
            Json.required fields "metadata" channel_updated_metadata_of_yojson;
        }
  | "channel.deleted" ->
      Channel_deleted
        {
          metadata =
            Json.required fields "metadata" channel_deleted_metadata_of_yojson;
        }
  | "channel.participant_added" ->
      Channel_participant_added
        {
          metadata =
            Json.required fields "metadata"
              channel_participant_added_metadata_of_yojson;
        }
  | "channel.participant_removed" ->
      Channel_participant_removed
        {
          metadata =
            Json.required fields "metadata"
              channel_participant_removed_metadata_of_yojson;
        }
  | "channel.access_requested" ->
      Channel_access_requested
        {
          metadata =
            Json.required fields "metadata"
              channel_access_requested_metadata_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_channel_topic_event : channel_topic_event -> Yojson.Safe.t =
 fun value ->
  match value with
  | Channel_picture_changed case ->
      Json.record
        [
          ("event_type", Some (`String "channel.picture_changed"));
          ( "metadata",
            Some (yojson_of_channel_picture_changed_metadata case.metadata) );
        ]
  | Channel_created case ->
      Json.record
        [
          ("event_type", Some (`String "channel.created"));
          ("metadata", Some (yojson_of_channel_created_metadata case.metadata));
        ]
  | Channel_updated case ->
      Json.record
        [
          ("event_type", Some (`String "channel.updated"));
          ("metadata", Some (yojson_of_channel_updated_metadata case.metadata));
        ]
  | Channel_deleted case ->
      Json.record
        [
          ("event_type", Some (`String "channel.deleted"));
          ("metadata", Some (yojson_of_channel_deleted_metadata case.metadata));
        ]
  | Channel_participant_added case ->
      Json.record
        [
          ("event_type", Some (`String "channel.participant_added"));
          ( "metadata",
            Some (yojson_of_channel_participant_added_metadata case.metadata) );
        ]
  | Channel_participant_removed case ->
      Json.record
        [
          ("event_type", Some (`String "channel.participant_removed"));
          ( "metadata",
            Some (yojson_of_channel_participant_removed_metadata case.metadata)
          );
        ]
  | Channel_access_requested case ->
      Json.record
        [
          ("event_type", Some (`String "channel.access_requested"));
          ( "metadata",
            Some (yojson_of_channel_access_requested_metadata case.metadata) );
        ]
  | Unknown json -> json

let make_channel_topic_event_channel_picture_changed
    ~(metadata : channel_picture_changed_metadata) () =
  (Channel_picture_changed { metadata } : channel_topic_event)

let make_channel_topic_event_channel_created
    ~(metadata : channel_created_metadata) () =
  (Channel_created { metadata } : channel_topic_event)

let make_channel_topic_event_channel_updated
    ~(metadata : channel_updated_metadata) () =
  (Channel_updated { metadata } : channel_topic_event)

let make_channel_topic_event_channel_deleted
    ~(metadata : channel_deleted_metadata) () =
  (Channel_deleted { metadata } : channel_topic_event)

let make_channel_topic_event_channel_participant_added
    ~(metadata : channel_participant_added_metadata) () =
  (Channel_participant_added { metadata } : channel_topic_event)

let make_channel_topic_event_channel_participant_removed
    ~(metadata : channel_participant_removed_metadata) () =
  (Channel_participant_removed { metadata } : channel_topic_event)

let make_channel_topic_event_channel_access_requested
    ~(metadata : channel_access_requested_metadata) () =
  (Channel_access_requested { metadata } : channel_topic_event)

