type nonrec harness = {
  access : harness_access option;
      (** What the caller may do with it. Reported as [none] where no caller is
in question, such as to the daemon itself. *)
  allow_permission_bypass : bool option;
      (** Whether agents may bypass ACP permission requests on this harness. *)
  claude_mode : claude_mode option;
      (** How Claude Code on this machine is paid for, derived from whether
it has an active Claude login. Only meaningful for Macro computers. *)
  computer_id : computer_id option;
  connected : bool;
      (** Whether the daemon currently holds a runtime connection. *)
  created_at : string;  (** Creation timestamp. *)
  created_by : string;  (** User that registered this harness. *)
  id : harness_id;  (** Harness id. *)
  kind : string;  (** Runtime kind. Currently always [macrod]. *)
  last_connected_at : string option;
      (** When the daemon last attached a runtime connection. *)
  name : string;  (** Display name. *)
  owner : harness_owner;  (** Owner. *)
  shared_team_ids : string list option;
      (** Teams it is a team machine for: their every member is a user of it. *)
  team_agent_user_id : macro_user_id_str option;
  updated_at : string;  (** Update timestamp. *)
}
(** A registered user-run harness.

Clients deserialize this, so both derives are used. *)

let harness_of_yojson : Yojson.Safe.t -> harness =
 fun json ->
  let fields = Json.obj json in
  {
    access = Json.optional fields "access" harness_access_of_yojson;
    allow_permission_bypass =
      Json.optional fields "allow_permission_bypass" Json.bool;
    claude_mode = Json.optional fields "claude_mode" claude_mode_of_yojson;
    computer_id = Json.optional fields "computer_id" computer_id_of_yojson;
    connected = Json.required fields "connected" Json.bool;
    created_at = Json.required fields "created_at" Json.string;
    created_by = Json.required fields "created_by" Json.string;
    id = Json.required fields "id" harness_id_of_yojson;
    kind = Json.required fields "kind" Json.string;
    last_connected_at = Json.optional fields "last_connected_at" Json.string;
    name = Json.required fields "name" Json.string;
    owner = Json.required fields "owner" harness_owner_of_yojson;
    shared_team_ids =
      Json.optional fields "shared_team_ids" (Json.list Json.string);
    team_agent_user_id =
      Json.optional fields "team_agent_user_id" macro_user_id_str_of_yojson;
    updated_at = Json.required fields "updated_at" Json.string;
  }

and yojson_of_harness : harness -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("access", Option.map yojson_of_harness_access value.access);
      ( "allow_permission_bypass",
        Option.map Json.of_bool value.allow_permission_bypass );
      ("claude_mode", Option.map yojson_of_claude_mode value.claude_mode);
      ("computer_id", Option.map yojson_of_computer_id value.computer_id);
      ("connected", Some (Json.of_bool value.connected));
      ("created_at", Some (Json.of_string value.created_at));
      ("created_by", Some (Json.of_string value.created_by));
      ("id", Some (yojson_of_harness_id value.id));
      ("kind", Some (Json.of_string value.kind));
      ("last_connected_at", Option.map Json.of_string value.last_connected_at);
      ("name", Some (Json.of_string value.name));
      ("owner", Some (yojson_of_harness_owner value.owner));
      ( "shared_team_ids",
        Option.map (Json.of_list Json.of_string) value.shared_team_ids );
      ( "team_agent_user_id",
        Option.map yojson_of_macro_user_id_str value.team_agent_user_id );
      ("updated_at", Some (Json.of_string value.updated_at));
    ]

let make_harness ?access ?allow_permission_bypass ?claude_mode ?computer_id
    ~(connected : bool) ~(created_at : string) ~(created_by : string)
    ~(id : harness_id) ~(kind : string) ?last_connected_at ~(name : string)
    ~(owner : harness_owner) ?shared_team_ids ?team_agent_user_id
    ~(updated_at : string) () =
  ({
     access;
     allow_permission_bypass;
     claude_mode;
     computer_id;
     connected;
     created_at;
     created_by;
     id;
     kind;
     last_connected_at;
     name;
     owner;
     shared_team_ids;
     team_agent_user_id;
     updated_at;
   }
    : harness)

