(** Lifecycle state of a collab surface.

[Pending] means the row exists but the sync-service session may not: the
row is inserted before the durable object is initialized and flipped to
[Ready] once the initial snapshot is stored. A persisted [Pending] row is
an ensure that died or failed mid-init; the next ensure for the same id
retries initialization (the initializer tolerates an already-initialized
session), so [Pending] is self-healing rather than terminal. *)
type nonrec surface_state =
  | Pending
  | Ready
  | Unknown of string  (** A value this SDK version does not know. *)

let surface_state_of_yojson : Yojson.Safe.t -> surface_state =
 fun json ->
  match Json.string json with
  | "pending" -> Pending
  | "ready" -> Ready
  | other -> Unknown other

and yojson_of_surface_state : surface_state -> Yojson.Safe.t =
 fun value ->
  match value with
  | Pending -> `String "pending"
  | Ready -> `String "ready"
  | Unknown other -> `String other

type nonrec collab_surface_response = {
  id : string;  (** The surface id — also the sync-service session key. *)
  parent_entity_id : string;  (** Id of the parent entity. *)
  parent_entity_type : collab_surface_response_parent_entity_type;
      (** Type of the parent entity. *)
  state : surface_state;
      (** Lifecycle state ([ready] for every surface visible via the API). *)
}
(** A collab surface, as returned by the API. *)

let collab_surface_response_of_yojson : Yojson.Safe.t -> collab_surface_response
    =
 fun json ->
  let fields = Json.obj json in
  {
    id = Json.required fields "id" Json.string;
    parent_entity_id = Json.required fields "parentEntityId" Json.string;
    parent_entity_type =
      Json.required fields "parentEntityType"
        collab_surface_response_parent_entity_type_of_yojson;
    state = Json.required fields "state" surface_state_of_yojson;
  }

and yojson_of_collab_surface_response : collab_surface_response -> Yojson.Safe.t
    =
 fun value ->
  Json.record
    [
      ("id", Some (Json.of_string value.id));
      ("parentEntityId", Some (Json.of_string value.parent_entity_id));
      ( "parentEntityType",
        Some
          (yojson_of_collab_surface_response_parent_entity_type
             value.parent_entity_type) );
      ("state", Some (yojson_of_surface_state value.state));
    ]

let make_collab_surface_response ~(id : string) ~(parent_entity_id : string)
    ~(parent_entity_type : collab_surface_response_parent_entity_type)
    ~(state : surface_state) () =
  ({ id; parent_entity_id; parent_entity_type; state }
    : collab_surface_response)

