  | Delete -> `String "delete"
  | Change_type -> `String "change_type"
  | Unknown other -> `String other

type nonrec column = {
  config : column_config option;
  display_name : string option;
      (** The placement's own label, which also names it in SQL; [None] shows
the definition's name. *)
  id : string;  (** Identifier of the placement. *)
  infer_type : bool;
      (** Whether the first nonempty value may settle this new text column's type. *)
  nullable : bool option;
      (** Whether a row may omit this cell; empty collections also count as absent. *)
  position : string;  (** Fractional index for column ordering. *)
  property_definition_id : string;  (** The bound property definition. *)
  protections : column_protection list option;
      (** Schema operations reserved by a feature; ordinary edits cannot clear them. *)
  table_id : string;  (** Table the column appears on. *)
}
(** A column: the placement of a property definition on a table.

The definition carries name, \[[DataType]\], multi-select flag, and options;
this carries only where it appears and column-kind configuration. *)

let column_of_yojson : Yojson.Safe.t -> column =
 fun json ->
  let fields = Json.obj json in
  {
    config = Json.optional fields "config" column_config_of_yojson;
    display_name = Json.optional fields "display_name" Json.string;
    id = Json.required fields "id" Json.string;
    infer_type = Json.required fields "infer_type" Json.bool;
    nullable = Json.optional fields "nullable" Json.bool;
    position = Json.required fields "position" Json.string;
    property_definition_id =
      Json.required fields "property_definition_id" Json.string;
    protections =
      Json.optional fields "protections" (Json.list column_protection_of_yojson);
    table_id = Json.required fields "table_id" Json.string;
  }

and yojson_of_column : column -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("config", Some ((Json.of_option yojson_of_column_config) value.config));
      ("display_name", Some ((Json.of_option Json.of_string) value.display_name));
      ("id", Some (Json.of_string value.id));
      ("infer_type", Some (Json.of_bool value.infer_type));
      ("nullable", Option.map Json.of_bool value.nullable);
      ("position", Some (Json.of_string value.position));
      ( "property_definition_id",
        Some (Json.of_string value.property_definition_id) );
      ( "protections",
        Option.map (Json.of_list yojson_of_column_protection) value.protections
      );
      ("table_id", Some (Json.of_string value.table_id));
    ]

let make_column ?config ?display_name ~(id : string) ~(infer_type : bool)
    ?nullable ~(position : string) ~(property_definition_id : string)
    ?protections ~(table_id : string) () =
  ({
     config;
     display_name;
     id;
     infer_type;
     nullable;
     position;
     property_definition_id;
     protections;
     table_id;
   }
    : column)

