type nonrec column_cast = {
  cast : cast_verdict;  (** Whether the values convert. *)
  data_type : data_type;  (** The target property type. *)
  examples : string list;
      (** Up to three of the values that would not convert. *)
  failures : int;
      (** For a [checked] cast, how many cells would not convert. *)
  is_multi_select : bool;  (** Whether the target holds several values. *)
  reason : string option;  (** Why nothing converts, for a [never] cast. *)
  relation : bool;
      (** Whether the target is a relation to another table's rows. *)
  specific_entity_type : entity_type option;
  summary : string option;
      (** For a [checked] cast with failures, what is wrong with them, as in
[3 values aren't numbers]. *)
}
(** What changing a column to one type would do to its values: the dry run
of a type change, for one target. *)

let column_cast_of_yojson : Yojson.Safe.t -> column_cast =
 fun json ->
  let fields = Json.obj json in
  {
    cast = Json.required fields "cast" cast_verdict_of_yojson;
    data_type = Json.required fields "data_type" data_type_of_yojson;
    examples = Json.required fields "examples" (Json.list Json.string);
    failures = Json.required fields "failures" Json.int;
    is_multi_select = Json.required fields "is_multi_select" Json.bool;
    reason = Json.optional fields "reason" Json.string;
    relation = Json.required fields "relation" Json.bool;
    specific_entity_type =
      Json.optional fields "specific_entity_type" entity_type_of_yojson;
    summary = Json.optional fields "summary" Json.string;
  }

and yojson_of_column_cast : column_cast -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("cast", Some (yojson_of_cast_verdict value.cast));
      ("data_type", Some (yojson_of_data_type value.data_type));
      ("examples", Some ((Json.of_list Json.of_string) value.examples));
      ("failures", Some (Json.of_int value.failures));
      ("is_multi_select", Some (Json.of_bool value.is_multi_select));
      ("reason", Some ((Json.of_option Json.of_string) value.reason));
      ("relation", Some (Json.of_bool value.relation));
      ( "specific_entity_type",
        Some ((Json.of_option yojson_of_entity_type) value.specific_entity_type)
      );
      ("summary", Some ((Json.of_option Json.of_string) value.summary));
    ]

let make_column_cast ~(cast : cast_verdict) ~(data_type : data_type)
    ~(examples : string list) ~(failures : int) ~(is_multi_select : bool)
    ?reason ~(relation : bool) ?specific_entity_type ?summary () =
  ({
     cast;
     data_type;
     examples;
     failures;
     is_multi_select;
     reason;
     relation;
     specific_entity_type;
     summary;
   }
    : column_cast)

