type nonrec converted_cell = {
  row : string;  (** The row. *)
  value : cell_value;  (** Its value under the new type. *)
}
(** One row's converted value. *)

let converted_cell_of_yojson : Yojson.Safe.t -> converted_cell =
 fun json ->
  let fields = Json.obj json in
  {
    row = Json.required fields "row" Json.string;
    value = Json.required fields "value" cell_value_of_yojson;
  }

and yojson_of_converted_cell : converted_cell -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("row", Some (Json.of_string value.row));
      ("value", Some (yojson_of_cell_value value.value));
    ]

let make_converted_cell ~(row : string) ~(value : cell_value) () =
  ({ row; value } : converted_cell)

type nonrec column_conversion = {
  cells : converted_cell list;
      (** Each row whose value converts, with that value, options named by
label. *)
  misfits : int;  (** How many values do not convert, and are left out. *)
  options : string list;
      (** The option labels a new select or tag column needs, in order. *)
  table_version : table_version;
      (** The table's version the cells were read at; a batch writing the new
column sends it as its base version. *)
}
(** What a column's values become under another type, for a new column of
that type beside it: the values that convert, the options they need,
and how many do not convert. Nothing is changed by reading it. *)

let column_conversion_of_yojson : Yojson.Safe.t -> column_conversion =
 fun json ->
  let fields = Json.obj json in
  {
    cells = Json.required fields "cells" (Json.list converted_cell_of_yojson);
    misfits = Json.required fields "misfits" Json.int;
    options = Json.required fields "options" (Json.list Json.string);
    table_version = Json.required fields "tableVersion" table_version_of_yojson;
  }

and yojson_of_column_conversion : column_conversion -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
