type nonrec message = {
  attachments : message_attachment list;  (** Attached entities. *)
  bot_profile : bot_sender_profile option;
  content : string;  (** Macro Markdown body. *)
  created_at : string;  (** Creation time. *)
  deleted_at : string option;
      (** Message tombstone, independent of thread deletion. *)
  edited_at : string option;  (** Last content edit, if any. *)
  guest_name : string option;
      (** Display name of a verified call guest, retained after the call ends. *)
  id : string;  (** Message UUID. *)
  imported_author : imported_author option;
  kind : message_kind option;  (** What this message is. *)
  mentions : simple_mention list;
      (** Tracked mentions, retained when a caller changes attachments only. *)
  parent : message_parent;  (** Entity that owns this conversation. *)
  reactions : counted_reaction list;  (** Aggregated reactions. *)
  sender_id : string;  (** Authenticated actor or owner of imported content. *)
  thread_id : string option;
      (** Root message UUID for replies; absent on roots. *)
  triggered_by : string option;
      (** User who triggered a bot-authored message. *)
  triggered_via : string option;
      (** Self-reported name of the client the user triggered it through, such
as "Claude Code"; a display label only. *)
  updated_at : string;  (** Last persisted update. *)
}
(** Shared message representation for channel timelines and entity discussions. *)

let message_of_yojson : Yojson.Safe.t -> message =
 fun json ->
  let fields = Json.obj json in
  {
    attachments =
      Json.required fields "attachments"
        (Json.list message_attachment_of_yojson);
    bot_profile =
      Json.optional fields "bot_profile" bot_sender_profile_of_yojson;
    content = Json.required fields "content" Json.string;
    created_at = Json.required fields "created_at" Json.string;
    deleted_at = Json.optional fields "deleted_at" Json.string;
    edited_at = Json.optional fields "edited_at" Json.string;
    guest_name = Json.optional fields "guest_name" Json.string;
    id = Json.required fields "id" Json.string;
    imported_author =
      Json.optional fields "imported_author" imported_author_of_yojson;
    kind = Json.optional fields "kind" message_kind_of_yojson;
    mentions =
      Json.required fields "mentions" (Json.list simple_mention_of_yojson);
    parent = Json.required fields "parent" message_parent_of_yojson;
    reactions =
      Json.required fields "reactions" (Json.list counted_reaction_of_yojson);
    sender_id = Json.required fields "sender_id" Json.string;
    thread_id = Json.optional fields "thread_id" Json.string;
    triggered_by = Json.optional fields "triggered_by" Json.string;
    triggered_via = Json.optional fields "triggered_via" Json.string;
    updated_at = Json.required fields "updated_at" Json.string;
  }

and yojson_of_message : message -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "attachments",
        Some ((Json.of_list yojson_of_message_attachment) value.attachments) );
      ("bot_profile", Option.map yojson_of_bot_sender_profile value.bot_profile);
      ("content", Some (Json.of_string value.content));
      ("created_at", Some (Json.of_string value.created_at));
      ("deleted_at", Option.map Json.of_string value.deleted_at);
      ("edited_at", Option.map Json.of_string value.edited_at);
      ("guest_name", Option.map Json.of_string value.guest_name);
      ("id", Some (Json.of_string value.id));
      ( "imported_author",
        Option.map yojson_of_imported_author value.imported_author );
      ("kind", Option.map yojson_of_message_kind value.kind);
      ("mentions", Some ((Json.of_list yojson_of_simple_mention) value.mentions));
      ("parent", Some (yojson_of_message_parent value.parent));
      ( "reactions",
        Some ((Json.of_list yojson_of_counted_reaction) value.reactions) );
      ("sender_id", Some (Json.of_string value.sender_id));
      ("thread_id", Option.map Json.of_string value.thread_id);
      ("triggered_by", Option.map Json.of_string value.triggered_by);
      ("triggered_via", Option.map Json.of_string value.triggered_via);
      ("updated_at", Some (Json.of_string value.updated_at));
    ]

let make_message ~(attachments : message_attachment list) ?bot_profile
    ~(content : string) ~(created_at : string) ?deleted_at ?edited_at
    ?guest_name ~(id : string) ?imported_author ?kind
    ~(mentions : simple_mention list) ~(parent : message_parent)
    ~(reactions : counted_reaction list) ~(sender_id : string) ?thread_id
    ?triggered_by ?triggered_via ~(updated_at : string) () =
  ({
     attachments;
     bot_profile;
     content;
     created_at;
     deleted_at;
     edited_at;
     guest_name;
     id;
     imported_author;
     kind;
     mentions;
     parent;
     reactions;
     sender_id;
     thread_id;
     triggered_by;
     triggered_via;
