type nonrec pipeline_import_response = {
  added : int;  (** Entries added. *)
  added_options : field_options list;
      (** Labels added to select fields so the CSV's values fit. *)
  already_present : int;  (** Rows whose record the pipeline already had. *)
  created_records : int;  (** Companies or contacts the import created. *)
  filled_fields : string list;  (** Pipeline fields the CSV filled. *)
  ignored_columns : string list;
      (** CSV columns matching no field the import can fill. *)
  invalid : skipped_import_record list;
      (** Rows refused for a value their field cannot hold. *)
  pipeline_id : string;  (** The pipeline filled. *)
  pipeline_name : string;  (** Its name. *)
  skipped_rows : int;  (** Rows without a domain or email. *)
  unresolved : skipped_import_record list;
      (** Records that could not be found or created. *)
}
(** What a pipeline import did. *)

let pipeline_import_response_of_yojson :
    Yojson.Safe.t -> pipeline_import_response =
 fun json ->
  let fields = Json.obj json in
  {
    added = Json.required fields "added" Json.int;
    added_options =
      Json.required fields "addedOptions" (Json.list field_options_of_yojson);
    already_present = Json.required fields "alreadyPresent" Json.int;
    created_records = Json.required fields "createdRecords" Json.int;
    filled_fields = Json.required fields "filledFields" (Json.list Json.string);
    ignored_columns =
      Json.required fields "ignoredColumns" (Json.list Json.string);
    invalid =
      Json.required fields "invalid" (Json.list skipped_import_record_of_yojson);
    pipeline_id = Json.required fields "pipelineId" Json.string;
    pipeline_name = Json.required fields "pipelineName" Json.string;
    skipped_rows = Json.required fields "skippedRows" Json.int;
    unresolved =
      Json.required fields "unresolved"
        (Json.list skipped_import_record_of_yojson);
  }

and yojson_of_pipeline_import_response :
    pipeline_import_response -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("added", Some (Json.of_int value.added));
      ( "addedOptions",
        Some ((Json.of_list yojson_of_field_options) value.added_options) );
      ("alreadyPresent", Some (Json.of_int value.already_present));
      ("createdRecords", Some (Json.of_int value.created_records));
      ("filledFields", Some ((Json.of_list Json.of_string) value.filled_fields));
      ( "ignoredColumns",
        Some ((Json.of_list Json.of_string) value.ignored_columns) );
      ( "invalid",
        Some ((Json.of_list yojson_of_skipped_import_record) value.invalid) );
      ("pipelineId", Some (Json.of_string value.pipeline_id));
      ("pipelineName", Some (Json.of_string value.pipeline_name));
      ("skippedRows", Some (Json.of_int value.skipped_rows));
      ( "unresolved",
        Some ((Json.of_list yojson_of_skipped_import_record) value.unresolved)
      );
    ]

let make_pipeline_import_response ~(added : int)
    ~(added_options : field_options list) ~(already_present : int)
    ~(created_records : int) ~(filled_fields : string list)
    ~(ignored_columns : string list) ~(invalid : skipped_import_record list)
    ~(pipeline_id : string) ~(pipeline_name : string) ~(skipped_rows : int)
    ~(unresolved : skipped_import_record list) () =
  ({
     added;
     added_options;
     already_present;
     created_records;
     filled_fields;
     ignored_columns;
     invalid;
     pipeline_id;
     pipeline_name;
     skipped_rows;
     unresolved;
   }
    : pipeline_import_response)

