type nonrec conversation_seal = {
  manifest_sha256 : sha256_digest;
      (** SHA-256 of canonical descriptor lines; zero parts hash the empty byte string. *)
  part_count : int;
      (** Exact number of registered parts, starting at index zero. *)
  slack_channel_id : conversation_id;  (** Selected source conversation. *)
}
(** Complete immutable expected part set for one conversation, including zero parts. *)

let conversation_seal_of_yojson : Yojson.Safe.t -> conversation_seal =
 fun json ->
  let fields = Json.obj json in
  {
    manifest_sha256 =
      Json.required fields "manifestSha256" sha256_digest_of_yojson;
    part_count = Json.required fields "partCount" Json.int;
    slack_channel_id =
      Json.required fields "slackChannelId" conversation_id_of_yojson;
  }

and yojson_of_conversation_seal : conversation_seal -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("manifestSha256", Some (yojson_of_sha256_digest value.manifest_sha256));
      ("partCount", Some (Json.of_int value.part_count));
      ("slackChannelId", Some (yojson_of_conversation_id value.slack_channel_id));
    ]

let make_conversation_seal ~(manifest_sha256 : sha256_digest)
    ~(part_count : int) ~(slack_channel_id : conversation_id) () =
  ({ manifest_sha256; part_count; slack_channel_id } : conversation_seal)

(** Identity in a job's persisted manifest. No user-supplied object keys. *)
type nonrec upload_id =
  | Users
      (** One normalized users payload from users.json and/or org_users.json. *)
  | Conversation_part of {
      part_index : int;
          (** Zero-based part index; sealed manifests must be contiguous. *)
      slack_channel_id : conversation_id;  (** Selected Slack conversation. *)
    }  (** One NDJSON part in a selected conversation. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let upload_id_of_yojson : Yojson.Safe.t -> upload_id =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "users" -> Users
  | "conversation_part" ->
      Conversation_part
        {
          part_index = Json.required fields "partIndex" Json.int;
          slack_channel_id =
            Json.required fields "slackChannelId" conversation_id_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_upload_id : upload_id -> Yojson.Safe.t =
 fun value ->
  match value with
  | Users -> Json.record [ ("kind", Some (`String "users")) ]
  | Conversation_part case ->
      Json.record
        [
          ("kind", Some (`String "conversation_part"));
          ("partIndex", Some (Json.of_int case.part_index));
          ( "slackChannelId",
            Some (yojson_of_conversation_id case.slack_channel_id) );
        ]
  | Unknown json -> json

let make_upload_id_conversation_part ~(part_index : int)
    ~(slack_channel_id : conversation_id) () =
  (Conversation_part { part_index; slack_channel_id } : upload_id)

type nonrec complete_uploads = {
  seal : conversation_seal option;
  uploads : upload_id list;
      (** Registered identities to verify against storage (at most 50). *)
}
(** Explicit upload completion; a seal can be submitted separately with an empty list. *)

let complete_uploads_of_yojson : Yojson.Safe.t -> complete_uploads =
 fun json ->
  let fields = Json.obj json in
  {
    seal = Json.optional fields "seal" conversation_seal_of_yojson;
    uploads = Json.required fields "uploads" (Json.list upload_id_of_yojson);
  }

and yojson_of_complete_uploads : complete_uploads -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("seal", Option.map yojson_of_conversation_seal value.seal);
      ("uploads", Some ((Json.of_list yojson_of_upload_id) value.uploads));
    ]

let make_complete_uploads ?seal ~(uploads : upload_id list) () =
  ({ seal; uploads } : complete_uploads)

