  let fields = Json.obj json in
  {
    archived = Json.required fields "archived" Json.bool;
    created_at = Json.optional fields "createdAt" slack_timestamp_of_yojson;
    creator_id = Json.optional fields "creatorId" slack_user_id_of_yojson;
    folder = Json.required fields "folder" key_segment_of_yojson;
    kind = Json.required fields "kind" conversation_kind_of_yojson;
    member_ids =
      Json.required fields "memberIds" (Json.list slack_user_id_of_yojson);
    message_count = Json.optional fields "messageCount" Json.int64;
    name = Json.required fields "name" Json.string;
    slack_channel_id =
      Json.required fields "slackChannelId" conversation_id_of_yojson;
  }

