 fun value ->
  Json.record
    [
      ("archived", Some (Json.of_bool value.archived));
      ("createdAt", Option.map yojson_of_slack_timestamp value.created_at);
      ("creatorId", Option.map yojson_of_slack_user_id value.creator_id);
      ("folder", Some (yojson_of_key_segment value.folder));
      ("kind", Some (yojson_of_conversation_kind value.kind));
      ( "memberIds",
        Some ((Json.of_list yojson_of_slack_user_id) value.member_ids) );
      ("messageCount", Option.map Json.of_int64 value.message_count);
      ("name", Some (Json.of_string value.name));
      ("slackChannelId", Some (yojson_of_conversation_id value.slack_channel_id));
    ]

let make_conversation_metadata ~(archived : bool) ?created_at ?creator_id
    ~(folder : key_segment) ~(kind : conversation_kind)
    ~(member_ids : slack_user_id list) ?message_count ~(name : string)
    ~(slack_channel_id : conversation_id) () =
  ({
     archived;
