 fun value ->
  Json.record
    [
      ("duplicates", Some (Json.of_int64 value.duplicates));
      ("imported", Some (Json.of_int64 value.imported));
      ("processed", Some (Json.of_int64 value.processed));
      ("reactions", Some (Json.of_int64 value.reactions));
      ("skipped", Some (Json.of_int64 value.skipped));
    ]

let make_import_counters ~(duplicates : int64) ~(imported : int64)
    ~(processed : int64) ~(reactions : int64) ~(skipped : int64) () =
  ({ duplicates; imported; processed; reactions; skipped } : import_counters)

(** Public error codes; never carry raw provider errors, keys, emails or source text. *)
type nonrec import_error =
  | Disabled
  | Invalid_input
  | Limit_exceeded
  | Unavailable
  | Admin_required
  | Source_mismatch
  | Conflict
  | Upload_mismatch
  | Lease_lost
  | Retryable
  | Internal
  | Unknown of string  (** A value this SDK version does not know. *)

let import_error_of_yojson : Yojson.Safe.t -> import_error =
 fun json ->
  match Json.string json with
  | "disabled" -> Disabled
  | "invalid_input" -> Invalid_input
  | "limit_exceeded" -> Limit_exceeded
  | "unavailable" -> Unavailable
  | "admin_required" -> Admin_required
  | "source_mismatch" -> Source_mismatch
  | "conflict" -> Conflict
  | "upload_mismatch" -> Upload_mismatch
  | "lease_lost" -> Lease_lost
  | "retryable" -> Retryable
  | "internal" -> Internal
  | other -> Unknown other

and yojson_of_import_error : import_error -> Yojson.Safe.t =
 fun value ->
  match value with
  | Disabled -> `String "disabled"
  | Invalid_input -> `String "invalid_input"
  | Limit_exceeded -> `String "limit_exceeded"
  | Unavailable -> `String "unavailable"
  | Admin_required -> `String "admin_required"
  | Source_mismatch -> `String "source_mismatch"
  | Conflict -> `String "conflict"
  | Upload_mismatch -> `String "upload_mismatch"
  | Lease_lost -> `String "lease_lost"
  | Retryable -> `String "retryable"
  | Internal -> `String "internal"
  | Unknown other -> `String other

(** Search publication/receipt state. Acceptance is not completed publication;
even completed publication still awaits consumer indexing and refresh. *)
type nonrec search_state =
  | Not_needed  (** No committed history requires indexing. *)
  | Pending
      (** Committed history requires an outbox-backed scoped submission. *)
  | Submitted of {
      receipt_id : string;  (** Receipt from the search service. *)
    }  (** Search service accepted the request, but has not completed it. *)
  | Completed
      (** Search service durably published the scope; eventual indexing is separate. *)
  | Failed
      (** Publication failed; retained history must be retried independently. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let search_state_of_yojson : Yojson.Safe.t -> search_state =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "status" with
  | "not_needed" -> Not_needed
  | "pending" -> Pending
  | "submitted" ->
      Submitted { receipt_id = Json.required fields "receiptId" Json.string }
  | "completed" -> Completed
  | "failed" -> Failed
  | _ -> Unknown json

and yojson_of_search_state : search_state -> Yojson.Safe.t =
 fun value ->
  match value with
  | Not_needed -> Json.record [ ("status", Some (`String "not_needed")) ]
  | Pending -> Json.record [ ("status", Some (`String "pending")) ]
  | Submitted case ->
      Json.record
        [
          ("status", Some (`String "submitted"));
          ("receiptId", Some (Json.of_string case.receipt_id));
        ]
  | Completed -> Json.record [ ("status", Some (`String "completed")) ]
  | Failed -> Json.record [ ("status", Some (`String "failed")) ]
  | Unknown json -> json

let make_search_state_submitted ~(receipt_id : string) () =
  (Submitted { receipt_id } : search_state)

