  | "creation_time_from_job" -> Creation_time_from_job
  | "unresolvable_direct_message" -> Unresolvable_direct_message
  | "target_unavailable" -> Target_unavailable
  | "uploads_incomplete" -> Uploads_incomplete
  | other -> Unknown other

and yojson_of_import_warning : import_warning -> Yojson.Safe.t =
 fun value ->
  match value with
  | Creation_time_from_message -> `String "creation_time_from_message"
  | Creation_time_from_job -> `String "creation_time_from_job"
  | Unresolvable_direct_message -> `String "unresolvable_direct_message"
