type nonrec conversation_progress = {
  archived : bool;
      (** Whether the selected source conversation was archived. *)
  channel_id : string option;
      (** Authorized target only; absent for inaccessible reused targets. *)
  counters : import_counters;  (** Durably committed record counts. *)
  error : import_error option;
  kind : conversation_kind;  (** Persisted source kind. *)
  name : string;
      (** Persisted source display name, never the reused Macro target's name. *)
  part_count : int option;
      (** Null until sealed; zero is a valid sealed empty manifest. *)
  search : search_state;  (** Independent indexing state. *)
  slack_channel_id : conversation_id;
