(** The document sub type enum represents all values of document sub types.
These values should match the [document_sub_type_value] table in macrodb.

Wire, database, and [Display] spellings are all [snake_case] so a
multi-word variant serializes identically in every system. *)
type nonrec document_sub_type =
  | Task
  | Snippet
  | Skill
  | Initiative_description
  | Unknown of string  (** A value this SDK version does not know. *)

let document_sub_type_of_yojson : Yojson.Safe.t -> document_sub_type =
 fun json ->
  match Json.string json with
  | "task" -> Task
  | "snippet" -> Snippet
  | "skill" -> Skill
  | "initiative_description" -> Initiative_description
  | other -> Unknown other

and yojson_of_document_sub_type : document_sub_type -> Yojson.Safe.t =
 fun value ->
  match value with
  | Task -> `String "task"
  | Snippet -> `String "snippet"
  | Skill -> `String "skill"
  | Initiative_description -> `String "initiative_description"
  | Unknown other -> `String other

(** Where document content is, or is expected to be, read from. *)
type nonrec document_content_location =
  | Object_storage
  | Sync_service
  | Docx_bom_parts
  | Converted_pdf
  | Unknown_
  | Unknown of string  (** A value this SDK version does not know. *)

let document_content_location_of_yojson :
    Yojson.Safe.t -> document_content_location =
 fun json ->
  match Json.string json with
  | "object_storage" -> Object_storage
  | "sync_service" -> Sync_service
  | "docx_bom_parts" -> Docx_bom_parts
  | "converted_pdf" -> Converted_pdf
  | "unknown" -> Unknown_
  | other -> Unknown other

and yojson_of_document_content_location :
    document_content_location -> Yojson.Safe.t =
 fun value ->
  match value with
  | Object_storage -> `String "object_storage"
  | Sync_service -> `String "sync_service"
  | Docx_bom_parts -> `String "docx_bom_parts"
  | Converted_pdf -> `String "converted_pdf"
  | Unknown_ -> `String "unknown"
  | Unknown other -> `String other

(** API-visible content lifecycle state derived from current document metadata. *)
type nonrec document_content_state =
  | Unknown_
  | Pending
  | Ready
  | Unknown of string  (** A value this SDK version does not know. *)

let document_content_state_of_yojson : Yojson.Safe.t -> document_content_state =
 fun json ->
  match Json.string json with
  | "unknown" -> Unknown_
  | "pending" -> Pending
  | "ready" -> Ready
  | other -> Unknown other

and yojson_of_document_content_state : document_content_state -> Yojson.Safe.t =
 fun value ->
  match value with
  | Unknown_ -> `String "unknown"
  | Pending -> `String "pending"
  | Ready -> `String "ready"
  | Unknown other -> `String other

