type nonrec document_response_metadata_with_content = {
  appearance : entity_appearance option;
  branched_from_id : string option;
      (** The id of the document this document branched from *)
  branched_from_version_id : int64 option;
      (** The id of the version this document branched from
This could be either DocumentInstance or DocumentBom id depending on
the file type *)
  created_at : string option;  (** The time the document was created *)
  document_bom : bom_part list option;
      (** If the document is a DOCX document, the document_bom will be present *)
  document_family_id : int64 option;
      (** The id of the document family this document belongs to *)
  document_id : string;  (** The document id *)
  document_name : string;  (** The name of the document *)
  document_version_id : int64;
      (** The version of the document
This could be the document_instance_id or document_bom_id depending on
the file type *)
  file_type : string option;  (** The file type of the document *)
  modification_data : Yojson.Safe.t option;
      (** The modification data for the document instance.
This is only used for PDF documents. *)
  owner : string;  (** The owner of the document *)
  sha : string option;
      (** If the document is a PDF, this is the SHA of the pdf
If the document is a DOCX, this will not be present *)
  sub_type : document_sub_type option;
  updated_at : string option;
      (** The time the document instance / document BOM was updated *)
  content : document_content;  (** Content lifecycle and location metadata. *)
  team_id : string option;
      (** The team this task number is scoped to, for task documents. *)
  team_task_id : int option;
      (** The task number assigned within the team, for task documents. *)
}
