    document_id = Json.required fields "documentId" Json.string;
    document_name = Json.required fields "documentName" Json.string;
    document_version_id = Json.required fields "documentVersionId" Json.int64;
    file_type = Json.optional fields "fileType" Json.string;
    modification_data = Json.optional fields "modificationData" Json.json;
    owner = Json.required fields "owner" Json.string;
    sha = Json.optional fields "sha" Json.string;
    sub_type = Json.optional fields "subType" document_sub_type_of_yojson;
    updated_at = Json.optional fields "updatedAt" Json.string;
    content = Json.required fields "content" document_content_of_yojson;
