(** Where a new form's responses go. *)
type nonrec form_source =
  | New of {
      anonymous : bool option;
          (** Make the form anonymous from the start: its table gets no
Respondent column. *)
      is_hidden_in_drive : bool option;
          (** Keep the form, and the database made for it, out of Drive, as
for a channel poll. *)
    }
      (** A new database named like the form, whose one table, "Responses",
starts with only the form's own columns. *)
  | Table of {
      database_id : string;  (** The table's database. *)
      table_id : string;  (** The table. *)
    }
      (** An existing table in a database the caller owns. The form starts with a
question per column. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let form_source_of_yojson : Yojson.Safe.t -> form_source =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "new" ->
      New
        {
          anonymous = Json.optional fields "anonymous" Json.bool;
          is_hidden_in_drive = Json.optional fields "isHiddenInDrive" Json.bool;
        }
  | "table" ->
      Table
        {
          database_id = Json.required fields "databaseId" Json.string;
          table_id = Json.required fields "tableId" Json.string;
        }
  | _ -> Unknown json

and yojson_of_form_source : form_source -> Yojson.Safe.t =
 fun value ->
  match value with
  | New case ->
      Json.record
        [
          ("kind", Some (`String "new"));
          ("anonymous", Option.map Json.of_bool case.anonymous);
          ("isHiddenInDrive", Option.map Json.of_bool case.is_hidden_in_drive);
        ]
  | Table case ->
      Json.record
        [
          ("kind", Some (`String "table"));
          ("databaseId", Some (Json.of_string case.database_id));
          ("tableId", Some (Json.of_string case.table_id));
        ]
  | Unknown json -> json

let make_form_source_new ?anonymous ?is_hidden_in_drive () =
  (New { anonymous; is_hidden_in_drive } : form_source)

let make_form_source_table ~(database_id : string) ~(table_id : string) () =
  (Table { database_id; table_id } : form_source)

