type nonrec source_id = string
(** Known Slack workspace identity (T prefix); an enterprise ID alone is insufficient. *)

let source_id_of_yojson : Yojson.Safe.t -> source_id =
 fun json -> Json.string json

and yojson_of_source_id : source_id -> Yojson.Safe.t =
 fun value -> Json.of_string value

(** Source identity supplied when creating a job. One binding per Macro team in v1. *)
type nonrec source_identity =
  | Known of {
      source_id : source_id;  (** Workspace identifier in the archive. *)
    }
      (** Archive names its Slack workspace; reject a conflicting team binding. *)
  | Confirmed_unknown
      (** Explicit confirmation that an unidentified archive belongs to this team's source.
Choosing this variant is affirmative confirmation, not an inferred default. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let source_identity_of_yojson : Yojson.Safe.t -> source_identity =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "known" ->
      Known { source_id = Json.required fields "sourceId" source_id_of_yojson }
  | "confirmed_unknown" -> Confirmed_unknown
  | _ -> Unknown json

and yojson_of_source_identity : source_identity -> Yojson.Safe.t =
 fun value ->
  match value with
  | Known case ->
      Json.record
        [
          ("kind", Some (`String "known"));
          ("sourceId", Some (yojson_of_source_id case.source_id));
        ]
  | Confirmed_unknown ->
      Json.record [ ("kind", Some (`String "confirmed_unknown")) ]
  | Unknown json -> json

let make_source_identity_known ~(source_id : source_id) () =
  (Known { source_id } : source_identity)

