 fun value ->
  Json.record
    [
      ("description", Option.map Json.of_string value.description);
      ("memberIds", Option.map (Json.of_list Json.of_string) value.member_ids);
      ("name", Some (Json.of_string value.name));
      ( "propertyValues",
        Option.map
          (Json.of_list yojson_of_initial_property_value)
          value.property_values );
      ("shareWithTeam", Option.map Json.of_bool value.share_with_team);
    ]

