(** The type of a field to add. *)
type nonrec new_field_type =
  | Text
  | Number
  | Checkbox
  | Date
  | Link
  | Select
  | Multi_select
  | Person
  | People
  | Unknown of string  (** A value this SDK version does not know. *)

let new_field_type_of_yojson : Yojson.Safe.t -> new_field_type =
 fun json ->
  match Json.string json with
  | "text" -> Text
  | "number" -> Number
  | "checkbox" -> Checkbox
  | "date" -> Date
  | "link" -> Link
  | "select" -> Select
  | "multi_select" -> Multi_select
  | "person" -> Person
  | "people" -> People
  | other -> Unknown other

and yojson_of_new_field_type : new_field_type -> Yojson.Safe.t =
 fun value ->
  match value with
  | Text -> `String "text"
  | Number -> `String "number"
  | Checkbox -> `String "checkbox"
  | Date -> `String "date"
  | Link -> `String "link"
  | Select -> `String "select"
  | Multi_select -> `String "multi_select"
  | Person -> `String "person"
  | People -> `String "people"
  | Unknown other -> `String other

type nonrec new_field_request = {
  name : string;  (** Its name, unique in the pipeline ignoring case. *)
  options : string list option;  (** A select field's labels, in order. *)
  type_ : new_field_type;  (** Its type. *)
}
(** A field to add. *)

let new_field_request_of_yojson : Yojson.Safe.t -> new_field_request =
 fun json ->
  let fields = Json.obj json in
  {
    name = Json.required fields "name" Json.string;
    options = Json.optional fields "options" (Json.list Json.string);
    type_ = Json.required fields "type" new_field_type_of_yojson;
  }

and yojson_of_new_field_request : new_field_request -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("name", Some (Json.of_string value.name));
      ("options", Option.map (Json.of_list Json.of_string) value.options);
      ("type", Some (yojson_of_new_field_type value.type_));
    ]

let make_new_field_request ~(name : string) ?options ~(type_ : new_field_type)
    () =
  ({ name; options; type_ } : new_field_request)

