type nonrec document_content_uploaded_metadata = {
  document_id : string;
      (** The id of the document whose stored bytes changed. *)
  document_version_id : string option;
      (** Version written, or the converted-file marker; [None] for unversioned
writes (mirrors [SearchExtractorMessage::document_version_id]). *)
  file_type : file_type;
      (** File type of the uploaded object (may differ from the document's own
type, e.g. [pdf] for the converted rendition of a docx). *)
  owner : string;
      (** The owner of the document (used by the extractor to resolve S3 keys). *)
}
(** Metadata for \[[DocumentTopicEvent::ContentUploaded]\]. *)

let document_content_uploaded_metadata_of_yojson :
    Yojson.Safe.t -> document_content_uploaded_metadata =
 fun json ->
  let fields = Json.obj json in
  {
    document_id = Json.required fields "document_id" Json.string;
    document_version_id = Json.optional fields "document_version_id" Json.string;
    file_type = Json.required fields "file_type" file_type_of_yojson;
    owner = Json.required fields "owner" Json.string;
  }

and yojson_of_document_content_uploaded_metadata :
    document_content_uploaded_metadata -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("document_id", Some (Json.of_string value.document_id));
      ( "document_version_id",
        Option.map Json.of_string value.document_version_id );
      ("file_type", Some (yojson_of_file_type value.file_type));
      ("owner", Some (Json.of_string value.owner));
    ]

let make_document_content_uploaded_metadata ~(document_id : string)
    ?document_version_id ~(file_type : file_type) ~(owner : string) () =
  ({ document_id; document_version_id; file_type; owner }
    : document_content_uploaded_metadata)

type nonrec document_copied_metadata = {
  actor : string option;  (** Who mechanically created the copy. *)
  document_id : string;  (** The id of the newly created copy. *)
  document_name : string;  (** The name of the new document. *)
  file_type : file_type option;
  on_behalf_of : macro_user_id_str option;
  owner : string;  (** The principal who owns the new copy. *)
  project_id : string option;  (** Project the copy belongs to, when any. *)
  source_document_id : string;  (** The id of the document that was copied. *)
  source_version_id : int64 option;
      (** The specific source version copied, when requested. *)
  sub_type : document_sub_type option;
}
