(** The sub type of a document preview with associated properties.
Task-related properties are encoded within the variant to ensure valid states. *)
type nonrec document_preview_data_sub_type =
  | Task of {
      is_completed : bool;
          (** Whether the task is completed.
True if the Status property is set to "Completed". *)
    }  (** A task document with completion status *)
  | Snippet  (** A snippet document — reusable markdown *)
  | Skill  (** A skill document — markdown instructions for AI *)
  | Initiative_description  (** The description document of an initiative *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let document_preview_data_sub_type_of_yojson :
    Yojson.Safe.t -> document_preview_data_sub_type =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "task" ->
      Task { is_completed = Json.required fields "is_completed" Json.bool }
  | "snippet" -> Snippet
  | "skill" -> Skill
  | "initiative_description" -> Initiative_description
  | _ -> Unknown json

and yojson_of_document_preview_data_sub_type :
    document_preview_data_sub_type -> Yojson.Safe.t =
 fun value ->
  match value with
  | Task case ->
      Json.record
        [
          ("type", Some (`String "task"));
          ("is_completed", Some (Json.of_bool case.is_completed));
        ]
  | Snippet -> Json.record [ ("type", Some (`String "snippet")) ]
  | Skill -> Json.record [ ("type", Some (`String "skill")) ]
  | Initiative_description ->
      Json.record [ ("type", Some (`String "initiative_description")) ]
  | Unknown json -> json

let make_document_preview_data_sub_type_task ~(is_completed : bool) () =
  (Task { is_completed } : document_preview_data_sub_type)

