  match value with
  | Access inner ->
      Json.with_tag "type" "access" (yojson_of_document_preview_data inner)
  | No_access inner ->
      Json.with_tag "type" "no_access" (yojson_of_with_document_id inner)
  | Does_not_exist inner ->
      Json.with_tag "type" "does_not_exist" (yojson_of_with_document_id inner)
  | Unknown json -> json

