(** Represents a file type update: either set to a specific type or clear to null. *)
type nonrec file_type_update =
  | Set of file_type  (** Set the file type to a specific value. *)
  | Clear  (** Clear the file type (set to null). *)

let file_type_update_of_yojson : Yojson.Safe.t -> file_type_update =
 fun json ->
  match Json.external_case json with
  | "set", value -> Set (file_type_of_yojson (Json.payload "set" value))
  | "clear", None -> Clear
  | name, _ -> Json.fail "unknown case %S" name

and yojson_of_file_type_update : file_type_update -> Yojson.Safe.t =
 fun value ->
  match value with
  | Set inner -> Json.external_value "set" (yojson_of_file_type inner)
  | Clear -> `String "clear"

type nonrec document_updated_metadata = {
  actor : string option;
      (** Who mechanically updated the document. Absent on events published
before attribution, and on user-receipt writes (ingest then uses
\[[Self::actor_user_id]\]). *)
  actor_user_id : macro_user_id_str option;
  appearance_change : entity_appearance list option;
      (** Previous and new presentation overrides, in that order; no content edit occurred. *)
  document_id : string;  (** The id of the updated document. *)
  document_name : string option;
      (** New (cleaned) document name; [None] when unchanged. *)
  file_type : file_type_update option;
  on_behalf_of : macro_user_id_str option;
  owner : string;  (** The owner of the document. *)
  previous_project_id : string option;  (** Project id before the update. *)
  project_id : string option;
      (** New project id; [None] when unchanged, [Some("")] when removed from
its project (mirrors the edit repo args semantics). *)
  share_permission_updated : bool;
      (** Whether share permissions were updated. *)
}
(** Metadata for \[[DocumentTopicEvent::Updated]\]. *)

let document_updated_metadata_of_yojson :
    Yojson.Safe.t -> document_updated_metadata =
 fun json ->
  let fields = Json.obj json in
  {
    actor = Json.optional fields "actor" Json.string;
    actor_user_id =
      Json.optional fields "actor_user_id" macro_user_id_str_of_yojson;
    appearance_change =
      Json.optional fields "appearance_change"
        (Json.list entity_appearance_of_yojson);
    document_id = Json.required fields "document_id" Json.string;
    document_name = Json.optional fields "document_name" Json.string;
    file_type = Json.optional fields "file_type" file_type_update_of_yojson;
    on_behalf_of =
      Json.optional fields "on_behalf_of" macro_user_id_str_of_yojson;
    owner = Json.required fields "owner" Json.string;
    previous_project_id = Json.optional fields "previous_project_id" Json.string;
    project_id = Json.optional fields "project_id" Json.string;
    share_permission_updated =
      Json.required fields "share_permission_updated" Json.bool;
  }

and yojson_of_document_updated_metadata :
    document_updated_metadata -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("actor", Option.map Json.of_string value.actor);
      ( "actor_user_id",
        Option.map yojson_of_macro_user_id_str value.actor_user_id );
      ( "appearance_change",
        Option.map
          (Json.of_list yojson_of_entity_appearance)
          value.appearance_change );
      ("document_id", Some (Json.of_string value.document_id));
      ("document_name", Option.map Json.of_string value.document_name);
      ("file_type", Option.map yojson_of_file_type_update value.file_type);
      ("on_behalf_of", Option.map yojson_of_macro_user_id_str value.on_behalf_of);
      ("owner", Some (Json.of_string value.owner));
      ( "previous_project_id",
        Option.map Json.of_string value.previous_project_id );
      ("project_id", Option.map Json.of_string value.project_id);
      ( "share_permission_updated",
        Some (Json.of_bool value.share_permission_updated) );
    ]

let make_document_updated_metadata ?actor ?actor_user_id ?appearance_change
    ~(document_id : string) ?document_name ?file_type ?on_behalf_of
    ~(owner : string) ?previous_project_id ?project_id
    ~(share_permission_updated : bool) () =
  ({
     actor;
     actor_user_id;
     appearance_change;
     document_id;
     document_name;
     file_type;
     on_behalf_of;
     owner;
     previous_project_id;
     project_id;
     share_permission_updated;
   }
    : document_updated_metadata)

(** Events that can be published to \[[MacroDocumentsTopic]\]. *)
type nonrec document_topic_event =
  | Document_created of {
      metadata : document_created_metadata;  (** A document was created. *)
    }  (** A document was created. *)
  | Document_updated of {
      metadata : document_updated_metadata;
          (** A document's metadata / permissions were updated. *)
    }  (** A document's metadata / permissions were updated. *)
  | Document_deleted of {
      metadata : document_deleted_metadata;  (** A document was soft-deleted. *)
    }  (** A document was soft-deleted. *)
  | Document_content_uploaded of {
      metadata : document_content_uploaded_metadata;
          (** The document's stored bytes were (re)written to S3. *)
    }  (** The document's stored bytes were (re)written to S3. *)
  | Document_sync_content_updated of {
      metadata : document_sync_content_updated_metadata;
          (** A live-collab (sync) document's content changed and should be re-extracted. *)
    }
      (** A live-collab (sync) document's content changed and should be re-extracted. *)
  | Document_purged of {
      metadata : document_purged_metadata;
          (** The document row was permanently deleted (hard delete). *)
    }  (** The document row was permanently deleted (hard delete). *)
  | Document_copied of {
      metadata : document_copied_metadata;  (** A document was copied. *)
    }  (** A document was copied. *)
  | Document_interaction of {
      metadata : document_interaction_metadata;
          (** A peer joined, left, or a periodic save occurred. *)
    }  (** A peer joined, left, or a periodic save occurred. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let document_topic_event_of_yojson : Yojson.Safe.t -> document_topic_event =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "event_type" with
  | "document.created" ->
      Document_created
        {
          metadata =
            Json.required fields "metadata" document_created_metadata_of_yojson;
        }
  | "document.updated" ->
      Document_updated
        {
          metadata =
            Json.required fields "metadata" document_updated_metadata_of_yojson;
        }
  | "document.deleted" ->
      Document_deleted
        {
          metadata =
            Json.required fields "metadata" document_deleted_metadata_of_yojson;
        }
  | "document.content_uploaded" ->
      Document_content_uploaded
        {
          metadata =
            Json.required fields "metadata"
              document_content_uploaded_metadata_of_yojson;
        }
  | "document.sync_content_updated" ->
      Document_sync_content_updated
        {
          metadata =
            Json.required fields "metadata"
              document_sync_content_updated_metadata_of_yojson;
        }
  | "document.purged" ->
      Document_purged
        {
          metadata =
            Json.required fields "metadata" document_purged_metadata_of_yojson;
        }
  | "document.copied" ->
      Document_copied
        {
          metadata =
            Json.required fields "metadata" document_copied_metadata_of_yojson;
        }
  | "document.interaction" ->
      Document_interaction
        {
          metadata =
            Json.required fields "metadata"
              document_interaction_metadata_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_document_topic_event : document_topic_event -> Yojson.Safe.t =
 fun value ->
  match value with
  | Document_created case ->
      Json.record
        [
          ("event_type", Some (`String "document.created"));
          ("metadata", Some (yojson_of_document_created_metadata case.metadata));
        ]
  | Document_updated case ->
      Json.record
        [
          ("event_type", Some (`String "document.updated"));
          ("metadata", Some (yojson_of_document_updated_metadata case.metadata));
        ]
  | Document_deleted case ->
      Json.record
        [
          ("event_type", Some (`String "document.deleted"));
          ("metadata", Some (yojson_of_document_deleted_metadata case.metadata));
        ]
  | Document_content_uploaded case ->
      Json.record
        [
          ("event_type", Some (`String "document.content_uploaded"));
          ( "metadata",
            Some (yojson_of_document_content_uploaded_metadata case.metadata) );
        ]
  | Document_sync_content_updated case ->
      Json.record
        [
          ("event_type", Some (`String "document.sync_content_updated"));
          ( "metadata",
            Some
              (yojson_of_document_sync_content_updated_metadata case.metadata)
          );
        ]
  | Document_purged case ->
      Json.record
        [
          ("event_type", Some (`String "document.purged"));
          ("metadata", Some (yojson_of_document_purged_metadata case.metadata));
        ]
  | Document_copied case ->
      Json.record
        [
          ("event_type", Some (`String "document.copied"));
          ("metadata", Some (yojson_of_document_copied_metadata case.metadata));
        ]
  | Document_interaction case ->
      Json.record
        [
          ("event_type", Some (`String "document.interaction"));
          ( "metadata",
            Some (yojson_of_document_interaction_metadata case.metadata) );
        ]
  | Unknown json -> json

let make_document_topic_event_document_created
    ~(metadata : document_created_metadata) () =
  (Document_created { metadata } : document_topic_event)

let make_document_topic_event_document_updated
    ~(metadata : document_updated_metadata) () =
  (Document_updated { metadata } : document_topic_event)

let make_document_topic_event_document_deleted
    ~(metadata : document_deleted_metadata) () =
  (Document_deleted { metadata } : document_topic_event)

let make_document_topic_event_document_content_uploaded
    ~(metadata : document_content_uploaded_metadata) () =
  (Document_content_uploaded { metadata } : document_topic_event)

let make_document_topic_event_document_sync_content_updated
    ~(metadata : document_sync_content_updated_metadata) () =
  (Document_sync_content_updated { metadata } : document_topic_event)

let make_document_topic_event_document_purged
    ~(metadata : document_purged_metadata) () =
  (Document_purged { metadata } : document_topic_event)

let make_document_topic_event_document_copied
    ~(metadata : document_copied_metadata) () =
  (Document_copied { metadata } : document_topic_event)

let make_document_topic_event_document_interaction
    ~(metadata : document_interaction_metadata) () =
  (Document_interaction { metadata } : document_topic_event)

