type nonrec run_patch = {
  baseline : float option;
      (** Baseline shift in percent (30 = superscript, -25 = subscript, 0 = normal). *)
  bold : bool option;  (** Bold. *)
  color : string option;  (** Text color as [RRGGBB]. *)
  font : string option;  (** Latin typeface. *)
  glow : effect_spec_glow_options option;
  highlight : string option;
      (** Highlight color as [RRGGBB], or [""] to remove. *)
  italic : bool option;  (** Italic. *)
  link : string option;
      (** Hyperlink, or [""] to remove: an address ([https://…], [mailto:…]),
[#slide=<id>] for another slide by stable id, or a slide show jump
([#nextslide], [#previousslide], [#firstslide], [#lastslide],
[#lastslideviewed], [#endshow]). *)
  link_tip : string option;  (** The link's ScreenTip (written with [link]). *)
  shadow : effect_spec_shadow_options option;
  size : float option;  (** Size in points. *)
  spacing : float option;
      (** Character spacing in points added between letters (negative
condenses; 0 = normal). *)
  strike : bool option;  (** Strikethrough. *)
  underline : bool option;  (** Underline. *)
}
(** Character formatting changes ([None] = leave unchanged). *)

let run_patch_of_yojson : Yojson.Safe.t -> run_patch =
