    glow = Json.optional fields "glow" effect_spec_glow_options_of_yojson;
    highlight = Json.optional fields "highlight" Json.string;
    italic = Json.optional fields "italic" Json.bool;
    link = Json.optional fields "link" Json.string;
    link_tip = Json.optional fields "linkTip" Json.string;
    shadow = Json.optional fields "shadow" effect_spec_shadow_options_of_yojson;
    size = Json.optional fields "size" Json.float;
    spacing = Json.optional fields "spacing" Json.float;
    strike = Json.optional fields "strike" Json.bool;
    underline = Json.optional fields "underline" Json.bool;
  }

