 fun value ->
  Json.record
    [
      ("baseline", Option.map Json.of_float value.baseline);
      ("bold", Option.map Json.of_bool value.bold);
      ("color", Option.map Json.of_string value.color);
      ("font", Option.map Json.of_string value.font);
      ("glow", Option.map yojson_of_effect_spec_glow_options value.glow);
      ("highlight", Option.map Json.of_string value.highlight);
      ("italic", Option.map Json.of_bool value.italic);
