(** A fill specification. *)
type nonrec fill_spec =
  | None_  (** No fill. *)
  | Solid of {
      alpha : float option;  (** Opacity 0-1. *)
      color : string;
          (** [RRGGBB], or a theme color name ([accent1], [tx1], [bg1]...). *)
    }  (** Solid color. *)
  | Gradient of {
      angle : float option;  (** Angle in degrees. *)
      colors : string list;
          (** Stop colors ([RRGGBB] or theme names), evenly spaced. *)
    }  (** Linear gradient. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let fill_spec_of_yojson : Yojson.Safe.t -> fill_spec =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "none" -> None_
  | "solid" ->
      Solid
        {
          alpha = Json.optional fields "alpha" Json.float;
          color = Json.required fields "color" Json.string;
        }
  | "gradient" ->
      Gradient
        {
          angle = Json.optional fields "angle" Json.float;
          colors = Json.required fields "colors" (Json.list Json.string);
        }
  | _ -> Unknown json

and yojson_of_fill_spec : fill_spec -> Yojson.Safe.t =
 fun value ->
  match value with
  | None_ -> Json.record [ ("kind", Some (`String "none")) ]
  | Solid case ->
      Json.record
        [
          ("kind", Some (`String "solid"));
          ("alpha", Option.map Json.of_float case.alpha);
          ("color", Some (Json.of_string case.color));
        ]
  | Gradient case ->
      Json.record
        [
          ("kind", Some (`String "gradient"));
          ("angle", Option.map Json.of_float case.angle);
          ("colors", Some ((Json.of_list Json.of_string) case.colors));
        ]
  | Unknown json -> json

let make_fill_spec_solid ?alpha ~(color : string) () =
  (Solid { alpha; color } : fill_spec)

let make_fill_spec_gradient ?angle ~(colors : string list) () =
  (Gradient { angle; colors } : fill_spec)

