type nonrec smart_art_item = {
  level : int option;
      (** Outline level: 1 for top-level shapes, 2 for their sub-bullets (or
child shapes in hierarchies), and so on. The first item must be at
level 1, and each item at most one level below the one before it.
Omitted (or null) means 1. *)
  text : string;
      (** The node's text ([""] leaves the "\[Text\]" prompt; [\u{b}] is a line break). *)
}
(** One bullet of a SmartArt graphic's text: a node and its outline level. *)

let smart_art_item_of_yojson : Yojson.Safe.t -> smart_art_item =
 fun json ->
  let fields = Json.obj json in
  {
    level = Json.optional fields "level" Json.int;
    text = Json.required fields "text" Json.string;
  }

and yojson_of_smart_art_item : smart_art_item -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("level", Option.map Json.of_int value.level);
      ("text", Some (Json.of_string value.text));
    ]

let make_smart_art_item ?level ~(text : string) () =
  ({ level; text } : smart_art_item)

(** What to add with \[[EditOp::AddShape]\](super::EditOp::AddShape). *)
type nonrec new_shape =
  | Text_box of {
      text : string option;  (** Initial text ([\n] separates paragraphs). *)
    }  (** A text box. *)
  | Shape of {
      preset : string;  (** Preset geometry name. *)
      text : string option;  (** Initial text. *)
    }  (** A preset shape ([rect], [roundRect], [ellipse], [rightArrow]...). *)
  | Line of { arrow : bool option  (** Arrowhead at the end. *) }
      (** A straight line from the top-left to the bottom-right of the box. *)
  | Image of {
      data : string;  (** Base64-encoded PNG, JPEG, or GIF bytes. *)
      description : string option;  (** Alt text. *)
    }  (** A picture. *)
  | Video of {
      content_type : string;  (** The file's MIME type ([video/mp4]...). *)
      data : string;
          (** Base64-encoded MP4, M4V, MOV, WebM, WMV, or AVI bytes. *)
      description : string option;  (** Alt text. *)
      poster : string;
          (** Base64-encoded PNG or JPEG shown until it plays (its first frame). *)
    }
      (** A video, played when clicked in a slide show. A zero width or height
takes the poster's aspect ratio. *)
  | Audio of {
      content_type : string;  (** The file's MIME type ([audio/mpeg]...). *)
      data : string;  (** Base64-encoded MP3, M4A, WAV, or OGG bytes. *)
      description : string option;  (** Alt text. *)
      poster : string;  (** Base64-encoded PNG or JPEG icon. *)
    }
      (** An audio clip, shown as its poster (a speaker icon) and played when
clicked in a slide show. *)
  | Table of { cells : string list list  (** Cell text, row by row. *) }
      (** A table. *)
  | Chart of {
      categories : string list;  (** Category labels. *)
      chart_type : string;
          (** [bar] (horizontal), [column], [line], [pie], [doughnut], or [area]. *)
      grouping : string option;
          (** [clustered], [stacked], [percentStacked], or [standard] (the type's default when omitted). *)
      series : chart_series_data list;  (** Series in plot order. *)
      title : string option;
          (** Chart title (no title when omitted or empty). *)
    }  (** A chart with an embedded workbook holding its data. *)
  | Smart_art of {
      colors : string option;
          (** Color variation ([accent1_2] when omitted; see [editSmartArt]'s
[setColors]). *)
      items : smart_art_item list option;
          (** The text as an outline (one item per node); omit for the
layout's sample nodes showing the "\[Text\]" prompt. *)
      layout : string;
          (** Layout: [default] (Basic Block List), [vList2] (Vertical Bullet
List), [hList1] (Horizontal Bullet List), [process1] (Basic
Process), [chevron1] (Basic Chevron Process), [cycle2] (Basic
Cycle), [radial1] (Basic Radial: the first item is the center,
level-2 items around it), [hierarchy1] (Hierarchy), [orgChart1]
(Organization Chart), [venn1] (Basic Venn), or [pyramid1] (Basic
Pyramid). *)
      style : string option;
          (** SmartArt style ([simple1] when omitted; see [editSmartArt]'s
[setStyle]). *)
    }
      (** A SmartArt graphic (PowerPoint's Insert ▸ SmartArt), laid out to
fill the box. PowerPoint's default box on a 16:9 slide is 640 x 426.7
points at (160, 56.7). *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let new_shape_of_yojson : Yojson.Safe.t -> new_shape =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "textBox" -> Text_box { text = Json.optional fields "text" Json.string }
  | "shape" ->
      Shape
        {
          preset = Json.required fields "preset" Json.string;
          text = Json.optional fields "text" Json.string;
        }
  | "line" -> Line { arrow = Json.optional fields "arrow" Json.bool }
  | "image" ->
      Image
        {
          data = Json.required fields "data" Json.string;
          description = Json.optional fields "description" Json.string;
        }
  | "video" ->
      Video
        {
          content_type = Json.required fields "contentType" Json.string;
          data = Json.required fields "data" Json.string;
          description = Json.optional fields "description" Json.string;
          poster = Json.required fields "poster" Json.string;
        }
  | "audio" ->
      Audio
        {
          content_type = Json.required fields "contentType" Json.string;
          data = Json.required fields "data" Json.string;
          description = Json.optional fields "description" Json.string;
          poster = Json.required fields "poster" Json.string;
        }
  | "table" ->
      Table
        {
          cells =
            Json.required fields "cells" (Json.list (Json.list Json.string));
        }
  | "chart" ->
      Chart
        {
          categories = Json.required fields "categories" (Json.list Json.string);
          chart_type = Json.required fields "chartType" Json.string;
          grouping = Json.optional fields "grouping" Json.string;
          series =
            Json.required fields "series"
              (Json.list chart_series_data_of_yojson);
          title = Json.optional fields "title" Json.string;
        }
  | "smartArt" ->
      Smart_art
        {
          colors = Json.optional fields "colors" Json.string;
          items =
            Json.optional fields "items" (Json.list smart_art_item_of_yojson);
          layout = Json.required fields "layout" Json.string;
          style = Json.optional fields "style" Json.string;
        }
  | _ -> Unknown json

and yojson_of_new_shape : new_shape -> Yojson.Safe.t =
 fun value ->
  match value with
  | Text_box case ->
      Json.record
        [
          ("kind", Some (`String "textBox"));
          ("text", Option.map Json.of_string case.text);
        ]
  | Shape case ->
      Json.record
        [
          ("kind", Some (`String "shape"));
          ("preset", Some (Json.of_string case.preset));
          ("text", Option.map Json.of_string case.text);
        ]
  | Line case ->
      Json.record
        [
          ("kind", Some (`String "line"));
          ("arrow", Option.map Json.of_bool case.arrow);
        ]
  | Image case ->
      Json.record
        [
          ("kind", Some (`String "image"));
          ("data", Some (Json.of_string case.data));
          ("description", Option.map Json.of_string case.description);
        ]
  | Video case ->
      Json.record
        [
          ("kind", Some (`String "video"));
          ("contentType", Some (Json.of_string case.content_type));
          ("data", Some (Json.of_string case.data));
          ("description", Option.map Json.of_string case.description);
