(** One drawing command of a \[[GeometryPath]\], in shape-local points:
[(0, 0)] is the top-left corner of the shape's box before rotation and
flips, x grows to the right and y downward. *)
type nonrec path_command =
  | Move_to of { x : float;  (** X (points). *) y : float  (** Y (points). *) }
      (** Starts a sub-path at a point (every path starts with one). *)
  | Line_to of { x : float;  (** X (points). *) y : float  (** Y (points). *) }
      (** A straight line to a point. *)
  | Cubic_bez_to of {
      x : float;  (** End X (points). *)
      x1 : float;  (** First control point X (points). *)
      x2 : float;  (** Second control point X (points). *)
      y : float;  (** End Y (points). *)
      y1 : float;  (** First control point Y (points). *)
      y2 : float;  (** Second control point Y (points). *)
    }
      (** A cubic Bézier curve to [(x, y)] with control points [(x1, y1)] and [(x2, y2)]. *)
  | Quad_bez_to of {
      x : float;  (** End X (points). *)
      x1 : float;  (** Control point X (points). *)
      y : float;  (** End Y (points). *)
      y1 : float;  (** Control point Y (points). *)
    }
      (** A quadratic Bézier curve to [(x, y)] with control point [(x1, y1)]. *)
  | Arc_to of {
      h_r : float;  (** Vertical radius (points). *)
      st_ang : float;  (** Start angle in degrees. *)
      sw_ang : float;
          (** Sweep in degrees (negative sweeps counter-clockwise). *)
      w_r : float;  (** Horizontal radius (points). *)
    }
      (** An elliptical arc continuing from the current point, as DrawingML's
[arcTo]: the ellipse has radii [wR] and [hR], the arc starts at angle
[stAng] on it and sweeps [swAng] (degrees, clockwise on screen; 0° is
the ellipse's rightmost point). *)
  | Close  (** Closes the sub-path with a straight line back to its start. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let path_command_of_yojson : Yojson.Safe.t -> path_command =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "cmd" with
  | "moveTo" ->
      Move_to
        {
          x = Json.required fields "x" Json.float;
          y = Json.required fields "y" Json.float;
        }
  | "lineTo" ->
      Line_to
        {
          x = Json.required fields "x" Json.float;
          y = Json.required fields "y" Json.float;
        }
  | "cubicBezTo" ->
      Cubic_bez_to
        {
          x = Json.required fields "x" Json.float;
          x1 = Json.required fields "x1" Json.float;
          x2 = Json.required fields "x2" Json.float;
          y = Json.required fields "y" Json.float;
          y1 = Json.required fields "y1" Json.float;
          y2 = Json.required fields "y2" Json.float;
        }
  | "quadBezTo" ->
      Quad_bez_to
        {
          x = Json.required fields "x" Json.float;
          x1 = Json.required fields "x1" Json.float;
          y = Json.required fields "y" Json.float;
          y1 = Json.required fields "y1" Json.float;
        }
  | "arcTo" ->
      Arc_to
        {
          h_r = Json.required fields "hR" Json.float;
          st_ang = Json.required fields "stAng" Json.float;
          sw_ang = Json.required fields "swAng" Json.float;
          w_r = Json.required fields "wR" Json.float;
        }
  | "close" -> Close
  | _ -> Unknown json

and yojson_of_path_command : path_command -> Yojson.Safe.t =
 fun value ->
  match value with
  | Move_to case ->
      Json.record
        [
          ("cmd", Some (`String "moveTo"));
          ("x", Some (Json.of_float case.x));
          ("y", Some (Json.of_float case.y));
        ]
  | Line_to case ->
      Json.record
        [
          ("cmd", Some (`String "lineTo"));
          ("x", Some (Json.of_float case.x));
          ("y", Some (Json.of_float case.y));
        ]
  | Cubic_bez_to case ->
      Json.record
        [
          ("cmd", Some (`String "cubicBezTo"));
          ("x", Some (Json.of_float case.x));
          ("x1", Some (Json.of_float case.x1));
          ("x2", Some (Json.of_float case.x2));
          ("y", Some (Json.of_float case.y));
          ("y1", Some (Json.of_float case.y1));
          ("y2", Some (Json.of_float case.y2));
        ]
  | Quad_bez_to case ->
      Json.record
        [
          ("cmd", Some (`String "quadBezTo"));
          ("x", Some (Json.of_float case.x));
          ("x1", Some (Json.of_float case.x1));
          ("y", Some (Json.of_float case.y));
          ("y1", Some (Json.of_float case.y1));
        ]
  | Arc_to case ->
      Json.record
        [
          ("cmd", Some (`String "arcTo"));
          ("hR", Some (Json.of_float case.h_r));
          ("stAng", Some (Json.of_float case.st_ang));
          ("swAng", Some (Json.of_float case.sw_ang));
          ("wR", Some (Json.of_float case.w_r));
        ]
  | Close -> Json.record [ ("cmd", Some (`String "close")) ]
  | Unknown json -> json

let make_path_command_move_to ~(x : float) ~(y : float) () =
  (Move_to { x; y } : path_command)

let make_path_command_line_to ~(x : float) ~(y : float) () =
  (Line_to { x; y } : path_command)

let make_path_command_cubic_bez_to ~(x : float) ~(x1 : float) ~(x2 : float)
    ~(y : float) ~(y1 : float) ~(y2 : float) () =
  (Cubic_bez_to { x; x1; x2; y; y1; y2 } : path_command)

let make_path_command_quad_bez_to ~(x : float) ~(x1 : float) ~(y : float)
    ~(y1 : float) () =
  (Quad_bez_to { x; x1; y; y1 } : path_command)

let make_path_command_arc_to ~(h_r : float) ~(st_ang : float) ~(sw_ang : float)
    ~(w_r : float) () =
  (Arc_to { h_r; st_ang; sw_ang; w_r } : path_command)

