    fill = Json.optional fields "fill" path_fill_mode_of_yojson;
    stroke = Json.optional fields "stroke" Json.bool;
  }

and yojson_of_geometry_path : geometry_path -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("commands", Some ((Json.of_list yojson_of_path_command) value.commands));
      ("fill", Option.map yojson_of_path_fill_mode value.fill);
      ("stroke", Option.map Json.of_bool value.stroke);
