(** One change to a SmartArt graphic. *)
type nonrec smart_art_edit =
  | Set_text of {
      node : string;  (** Node id (from the outline's [smartArt.nodes]). *)
      text : string;  (** New text. *)
    }
      (** Replaces a node's text, keeping the formatting of its first run
([\n] separates paragraphs inside the node, [\u{b}] is a line break). *)
  | Add_node of {
      node : string option;
          (** The node to add next to; omit to add a last top-level node. *)
      position : smart_art_position option;
          (** Where to add it ([after] when omitted). *)
      text : string option;
          (** Text of the new node (empty: the "\[Text\]" prompt). *)
    }  (** Adds a node (PowerPoint's Add Shape). *)
  | Delete_node of { node : string  (** Node id. *) }
      (** Deletes a node; its children move up into its place. *)
  | Promote of { node : string  (** Node id. *) }
      (** Moves a node one level up (Promote, Shift+Tab in the text pane).
Its following siblings become its children. *)
  | Demote of { node : string  (** Node id. *) }
      (** Moves a node one level down (Demote, Tab in the text pane): it
becomes the last child of its previous sibling, with its children. *)
  | Move_up of { node : string  (** Node id. *) }
      (** Swaps a node (with its children) with its previous sibling. *)
  | Move_down of { node : string  (** Node id. *) }
      (** Swaps a node (with its children) with its next sibling. *)
  | Set_nodes of { items : smart_art_item list  (** The bullets, in order. *) }
      (** Replaces all the text: one node per item, as typed in the text pane.
Existing nodes are reused in order, keeping their formatting. *)
  | Set_layout of {
      layout : string;
          (** Layout: [default] (Basic Block List), [vList2] (Vertical Bullet
List), [hList1] (Horizontal Bullet List), [process1] (Basic
Process), [chevron1] (Basic Chevron Process), [cycle2] (Basic
Cycle), [radial1] (Basic Radial), [hierarchy1] (Hierarchy),
[orgChart1] (Organization Chart), [venn1] (Basic Venn), or
[pyramid1] (Basic Pyramid); a full id
([urn:microsoft.com/office/officeart/2005/8/layout/process1]) or
the display name also works. *)
    }
      (** Changes the layout (PowerPoint's Layouts gallery), keeping the text. *)
  | Set_colors of {
      colors : string;
          (** Color variation: [accent0_1] Dark 1 Outline, [accent0_2] Dark 2
Outline, [accent0_3] Dark 2 Fill, [colorful1] Colorful - Accent
Colors, [colorful2]-[colorful5] Colorful Range - Accent Colors
2 to 3 ... 5 to 6, and for accent N = 1-6: [accentN_1] Colored
Outline, [accentN_2] Colored Fill (PowerPoint's default
[accent1_2]), [accentN_3] Gradient Range, [accentN_4] Gradient
Loop, [accentN_5] Transparent Gradient Range. Full ids
([urn:microsoft.com/office/officeart/2005/8/colors/colorful1])
and display names also work. *)
    }  (** Changes the colors (PowerPoint's Change Colors). *)
  | Set_style of {
      style : string;
          (** Style: [simple1] Simple Fill (the default), [simple2] White
Outline, [simple3] Subtle Effect, [simple4] Moderate Effect, or
[simple5] Intense Effect (or a full id or display name). *)
    }  (** Changes the SmartArt style (PowerPoint's SmartArt Styles gallery). *)
  | Reset
      (** Reset Graphic: discards changes to the shapes' sizes, positions, and
formatting, keeping the text, layout, colors, and style. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let smart_art_edit_of_yojson : Yojson.Safe.t -> smart_art_edit =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "action" with
  | "setText" ->
      Set_text
        {
          node = Json.required fields "node" Json.string;
          text = Json.required fields "text" Json.string;
        }
  | "addNode" ->
      Add_node
        {
          node = Json.optional fields "node" Json.string;
          position =
            Json.optional fields "position" smart_art_position_of_yojson;
          text = Json.optional fields "text" Json.string;
        }
  | "deleteNode" ->
      Delete_node { node = Json.required fields "node" Json.string }
  | "promote" -> Promote { node = Json.required fields "node" Json.string }
  | "demote" -> Demote { node = Json.required fields "node" Json.string }
  | "moveUp" -> Move_up { node = Json.required fields "node" Json.string }
  | "moveDown" -> Move_down { node = Json.required fields "node" Json.string }
  | "setNodes" ->
      Set_nodes
        {
          items =
            Json.required fields "items" (Json.list smart_art_item_of_yojson);
        }
  | "setLayout" ->
      Set_layout { layout = Json.required fields "layout" Json.string }
  | "setColors" ->
      Set_colors { colors = Json.required fields "colors" Json.string }
  | "setStyle" -> Set_style { style = Json.required fields "style" Json.string }
  | "reset" -> Reset
  | _ -> Unknown json

and yojson_of_smart_art_edit : smart_art_edit -> Yojson.Safe.t =
 fun value ->
  match value with
  | Set_text case ->
      Json.record
        [
          ("action", Some (`String "setText"));
          ("node", Some (Json.of_string case.node));
          ("text", Some (Json.of_string case.text));
        ]
  | Add_node case ->
      Json.record
        [
          ("action", Some (`String "addNode"));
          ("node", Option.map Json.of_string case.node);
          ("position", Option.map yojson_of_smart_art_position case.position);
          ("text", Option.map Json.of_string case.text);
        ]
  | Delete_node case ->
      Json.record
        [
          ("action", Some (`String "deleteNode"));
          ("node", Some (Json.of_string case.node));
        ]
  | Promote case ->
      Json.record
        [
          ("action", Some (`String "promote"));
          ("node", Some (Json.of_string case.node));
        ]
  | Demote case ->
      Json.record
        [
          ("action", Some (`String "demote"));
          ("node", Some (Json.of_string case.node));
        ]
  | Move_up case ->
      Json.record
        [
          ("action", Some (`String "moveUp"));
          ("node", Some (Json.of_string case.node));
        ]
  | Move_down case ->
      Json.record
        [
          ("action", Some (`String "moveDown"));
          ("node", Some (Json.of_string case.node));
        ]
  | Set_nodes case ->
      Json.record
        [
          ("action", Some (`String "setNodes"));
          ("items", Some ((Json.of_list yojson_of_smart_art_item) case.items));
        ]
  | Set_layout case ->
      Json.record
        [
          ("action", Some (`String "setLayout"));
          ("layout", Some (Json.of_string case.layout));
        ]
  | Set_colors case ->
      Json.record
        [
          ("action", Some (`String "setColors"));
          ("colors", Some (Json.of_string case.colors));
        ]
  | Set_style case ->
      Json.record
        [
          ("action", Some (`String "setStyle"));
          ("style", Some (Json.of_string case.style));
        ]
  | Reset -> Json.record [ ("action", Some (`String "reset")) ]
  | Unknown json -> json

let make_smart_art_edit_set_text ~(node : string) ~(text : string) () =
  (Set_text { node; text } : smart_art_edit)

let make_smart_art_edit_add_node ?node ?position ?text () =
  (Add_node { node; position; text } : smart_art_edit)

let make_smart_art_edit_delete_node ~(node : string) () =
  (Delete_node { node } : smart_art_edit)

let make_smart_art_edit_promote ~(node : string) () =
  (Promote { node } : smart_art_edit)

let make_smart_art_edit_demote ~(node : string) () =
  (Demote { node } : smart_art_edit)

let make_smart_art_edit_move_up ~(node : string) () =
  (Move_up { node } : smart_art_edit)

let make_smart_art_edit_move_down ~(node : string) () =
  (Move_down { node } : smart_art_edit)

let make_smart_art_edit_set_nodes ~(items : smart_art_item list) () =
  (Set_nodes { items } : smart_art_edit)

let make_smart_art_edit_set_layout ~(layout : string) () =
  (Set_layout { layout } : smart_art_edit)

let make_smart_art_edit_set_colors ~(colors : string) () =
  (Set_colors { colors } : smart_art_edit)

let make_smart_art_edit_set_style ~(style : string) () =
  (Set_style { style } : smart_art_edit)

(** What [convertSmartArt] turns a SmartArt graphic into. *)
type nonrec smart_art_target =
  | Shapes
  | Text
  | Unknown of string  (** A value this SDK version does not know. *)

let smart_art_target_of_yojson : Yojson.Safe.t -> smart_art_target =
 fun json ->
  match Json.string json with
  | "shapes" -> Shapes
  | "text" -> Text
  | other -> Unknown other

and yojson_of_smart_art_target : smart_art_target -> Yojson.Safe.t =
 fun value ->
  match value with
  | Shapes -> `String "shapes"
  | Text -> `String "text"
  | Unknown other -> `String other

(** One edit operation. *)
type nonrec edit_op =
  | Set_text of {
      cell : cell_ref option;
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
      text : string;  (** New text. *)
    }
      (** Replaces all text of a shape ([\n] separates paragraphs, [\u{b}] is a line
break), keeping the formatting of the first run of each paragraph. *)
  | Insert_text of {
      at : text_pos;  (** Where to insert. *)
      cell : cell_ref option;
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
      text : string;  (** Text to insert. *)
    }  (** Inserts text at a position ([\n] splits paragraphs). *)
  | Delete_text of {
      cell : cell_ref option;
      end_ : text_pos;  (** End (exclusive). *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
      start : text_pos;  (** Start (inclusive). *)
    }  (** Deletes text between two positions (may span paragraphs). *)
  | Format_text of {
      cell : cell_ref option;
      end_ : text_pos option;
      props : run_patch;  (** Changes. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
      start : text_pos option;
    }
      (** Applies character formatting to a range (whole shape when omitted). *)
  | Format_paragraphs of {
      cell : cell_ref option;
      from : int option;  (** First paragraph. *)
      props : para_patch;  (** Changes. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
      to_ : int option;  (** Last paragraph. *)
    }
      (** Applies paragraph formatting to paragraphs [from..=to] (all when omitted). *)
  | Format_body of {
      cell : cell_ref option;
      props : body_patch;  (** Changes. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Changes text box properties. *)
  | Set_transform of {
      flip_h : bool option;  (** Horizontal flip. *)
      flip_v : bool option;  (** Vertical flip. *)
      h : float option;  (** Height (points). *)
      rotation : float option;  (** Rotation in degrees. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
      w : float option;  (** Width (points). *)
      x : float option;  (** Left (points). *)
      y : float option;  (** Top (points). *)
    }
      (** Moves, resizes, rotates, or flips a shape (omitted fields stay).
Values are in slide space, also for group members (as the outline
reports them); their group grows or shrinks to fit. *)
  | Set_fill of {
      fill : fill_spec;  (** The fill. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Sets a shape's fill. *)
  | Set_line of {
      line : line_patch;  (** Changes. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Changes a shape's outline. *)
  | Set_geometry of {
      preset : string;  (** Preset name. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Changes a shape's preset geometry. *)
  | Add_shape of {
      h : float;  (** Height (points). *)
      shape : new_shape;  (** What to add. *)
      slide : int;  (** Slide id. *)
      w : float;  (** Width (points). *)
      x : float;  (** Left (points). *)
      y : float;  (** Top (points). *)
    }  (** Adds a shape (its id is reported in the result). *)
  | Delete_shape of {
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Deletes a shape. *)
  | Duplicate_shape of {
      dx : float option;  (** Horizontal offset. *)
      dy : float option;  (** Vertical offset. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Duplicates a shape, offset by (dx, dy) points. *)
  | Reorder_shape of {
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
      to_ : z_order;  (** Where to move it. *)
    }  (** Changes a shape's z-order. *)
  | Replace_image of {
      data : string;  (** Base64-encoded PNG, JPEG, or GIF bytes. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Replaces a picture's image. *)
  | Set_cell_text of {
      col : int;  (** Column. *)
      row : int;  (** Row. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
      text : string;  (** Text. *)
    }  (** Sets the text of a table cell. *)
  | Insert_table_row of {
      at : int;  (** Index of the new row. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
    }  (** Inserts a table row (copying the formatting of an adjacent row). *)
  | Delete_table_row of {
      row : int;  (** Row index. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
    }  (** Deletes a table row. *)
  | Insert_table_column of {
      at : int;  (** Index of the new column. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
    }
      (** Inserts a table column (copying the formatting of an adjacent column). *)
  | Delete_table_column of {
      col : int;  (** Column index. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
    }  (** Deletes a table column. *)
  | Merge_cells of {
      from : cell_ref;  (** One corner of the rectangle. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
      to_ : cell_ref;  (** The opposite corner. *)
    }
      (** Merges the rectangle of table cells between two corners into one cell.
The top-left cell keeps its formatting; the text of the other cells is
appended to it as paragraphs. Merged cells already inside the rectangle
are absorbed; a rectangle that cuts through a merged cell is rejected. *)
  | Split_cell of {
      cell : cell_ref;  (** Any grid cell the merged cell covers. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
    }
      (** Splits a merged cell back into the grid cells it covers. The revealed
cells are empty and take the merged cell's fill and outer borders. *)
  | Format_cells of {
      anchor : string option;
          (** Vertical text alignment: [top], [middle], or [bottom]. *)
      borders : cell_borders option;
      fill : fill_spec option;
      from : cell_ref;  (** One corner of the rectangle. *)
      margins : float list option;
          (** Cell margins `\[left, top, right, bottom\]` in points. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
      to_ : cell_ref;  (** The opposite corner. *)
    }
      (** Formats the table cells in the rectangle between two corners (widened
to whole merged cells). Omitted fields stay unchanged. *)
  | Set_table_style of {
      band_col : bool option;  (** Alternate the shading of columns. *)
      band_row : bool option;  (** Alternate the shading of rows. *)
      first_col : bool option;  (** Emphasize the first column. *)
      first_row : bool option;  (** Emphasize the first (header) row. *)
      last_col : bool option;  (** Emphasize the last column. *)
      last_row : bool option;  (** Emphasize the last (total) row. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
      style : string option;
          (** Style id (a GUID from the deck outline's [tableStyles], e.g.
[{5C22544A-7EE6-4342-B048-85BDC9FD1C3A}] = Medium Style 2 - Accent 1),
or [""] for no style. *)
    }
      (** Sets a table's style and which of its parts the style emphasizes
(omitted fields stay unchanged). Applying a different style clears
fills and borders set directly on cells, as PowerPoint does, so the
table shows the new style. *)
  | Set_table_grid of {
      column_widths : float list option;  (** One width per column. *)
      row_heights : float list option;  (** One minimum height per row. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
    }
      (** Sets table column widths and minimum row heights in points (rows still
grow to fit their text). The frame is resized to match. *)
  | Add_slide of {
      after : int option;
          (** Insert after this slide (end of deck when omitted). *)
      body : string option;
          (** Body placeholder text ([\n] separates paragraphs). *)
      layout : string option;
          (** Layout name (e.g. "Title and Content"); defaults to the layout of the reference slide. *)
      title : string option;  (** Title placeholder text. *)
    }  (** Adds a slide based on a layout (its id is reported in the result). *)
  | Duplicate_slide of { slide : int  (** Slide id. *) }
      (** Duplicates a slide right after itself. *)
  | Delete_slide of { slide : int  (** Slide id. *) }  (** Deletes a slide. *)
  | Move_slide of {
      slide : int;  (** Slide id. *)
      to_ : int;  (** New index. *)
    }  (** Moves a slide to a 0-based position. *)
  | Set_slide_hidden of {
      hidden : bool;  (** Hidden. *)
      slide : int;  (** Slide id. *)
    }  (** Hides or shows a slide in slideshows. *)
  | Set_notes of {
      slide : int;  (** Slide id. *)
      text : string;  (** Notes text ([\n] separates paragraphs). *)
    }  (** Replaces the speaker notes of a slide. *)
  | Set_background of { fill : fill_spec option; slide : int  (** Slide id. *) }
      (** Sets a slide's background. *)
  | Set_chart_data of {
      categories : string list;  (** Category labels. *)
      series : chart_series_data list;
          (** Series in plot order (one value per category). *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
    }
      (** Replaces a chart's categories and series (the chart must be [editable]
in the outline). Existing series keep their formatting; new series
copy the last one's with the next theme accent color. The embedded
workbook is rewritten to match. *)
  | Set_chart_type of {
      grouping : string option;
          (** [clustered], [stacked], [percentStacked], or [standard] (kept or the type's default when omitted). *)
      kind : string;
          (** [bar] (horizontal), [column], [line], [pie], [doughnut], or [area]. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
    }
      (** Changes a chart's type (the chart must be [editable] in the outline). *)
  | Format_chart of {
      data_labels : bool option;
          (** Show or hide value data labels on every series. *)
      legend : string option;
          (** Legend position: [right], [left], [top], [bottom], [topRight], or [none]. *)
      series_colors : chart_series_color list option;  (** Series colors. *)
      shape : int;  (** Graphic frame id. *)
      slide : int;  (** Slide id. *)
      title : string option;  (** Title text ([""] removes the title). *)
    }
      (** Changes a chart's title, legend, data labels, or series colors (omitted fields stay). *)
  | Group_shapes of {
      shapes : int list;  (** Ids of the shapes to group (at least two). *)
      slide : int;  (** Slide id. *)
    }
      (** Groups two or more shapes that share a parent (usually top-level
shapes) into a new group placed at the z-position of the topmost of
them. They keep their order and exactly where they are. The group's id
is reported in the result. Placeholders cannot be grouped. *)
  | Ungroup_shape of {
      shape : int;  (** Group id. *)
      slide : int;  (** Slide id. *)
    }
      (** Ungroups a group: its members take its place in the z-order and keep
exactly where and how they appear (the group's offset, scale,
rotation, and flips are applied to each). The members' ids are
reported in the result, back to front. *)
  | Paste_shapes of {
      dx : float option;  (** Horizontal offset in points. *)
      dy : float option;  (** Vertical offset in points. *)
      payload : string;
          (** The clipboard payload JSON returned by [copyShapes]. *)
      slide : int;  (** Slide id. *)
    }
      (** Pastes shapes copied with [copyShapes] (from this or another
presentation) on top of a slide, with fresh ids, offset by (dx, dy)
points. Pictures, media, charts, and links come along. Theme colors,
theme fonts, and style references take this presentation's theme
(PowerPoint's "Use Destination Theme"). The new top-level shape ids are
reported in the result, back to front. *)
  | Paste_slides of {
      after : int option;
          (** Insert after this slide (end of deck when omitted). *)
      payload : string;
          (** The clipboard payload JSON returned by [copySlides]. *)
    }
      (** Pastes slides copied with [copySlides] (from this or another
presentation), with their speaker notes. Each slide takes this deck's
layout of the same name, else the first with the same placeholder
types, else "Title and Content", else the first layout; theme colors
and fonts follow this deck's theme. New slide ids are reported in the
result, in order. *)
  | Set_slide_layout of {
      layout : string;
          (** Layout name (e.g. "Title Only"), as listed in the deck's layouts. *)
      slide : int;  (** Slide id. *)
    }
      (** Changes a slide's layout. Placeholders are matched to the new layout's
placeholders by type and index and take their position; placeholders
without a match stay where they are. Content is kept, and the new
layout's other placeholders are added empty. *)
  | Set_transition of {
      advance_after_ms : int option;
          (** Advance automatically after this many milliseconds; [0] turns
automatic advance off, and an omitted (or null) field keeps the
current setting. *)
      advance_on_click : bool option;
          (** Whether a click advances to the next slide. *)
      apply_to_all : bool option;
          (** Give every slide of the deck the resulting transition. *)
      direction : string option;
          (** Effect option: [fade]: [smooth] or [black]; [push], [wipe]: [l],
[r], [u], [d]; [cover], [uncover]: those or [lu], [ru], [ld], [rd];
[split]: [horzOut], [horzIn], [vertOut], [vertIn]; [reveal]: [l],
[r]; [randomBar]: [horz], [vert]; [shape]: [circle], [diamond],
[plus]; [zoom]: [in], [out]; [morph]: [byObject], [byWord],
[byChar]. Directions are the OOXML [dir] values. *)
      duration_ms : int option;
          (** Duration in milliseconds (at most 60000). *)
      kind : string;
          (** Effect: [none] (removes the transition), [cut], [fade], [push],
[wipe], [split], [reveal], [randomBar], [shape], [uncover],
[cover], [zoom], [dissolve], [flash], or [morph]. *)
      slide : int;  (** Slide id. *)
    }
      (** Sets the transition into a slide. Omitted fields keep the slide's
current value, or take the effect's default for a new transition. *)
  | Set_animations of {
      animations : animation_spec list;  (** Animations in playback order. *)
      slide : int;  (** Slide id. *)
    }
      (** Replaces a slide's animations (its main sequence, which plays as the
presenter clicks through the slide) with these, in playback order;
`\[\]` removes them all. An entry matching an animation the slide has
(same shape, class, effect, and paragraph, and direction when given)
keeps it, with its other settings unless the entry gives them, so
listing the current animations in a new order reorders them.
Animations started by clicking a shape (triggers) are kept. *)
  | Add_animation of {
      animation : animation_spec;  (** The animation. *)
      index : int option;
          (** 0-based position in playback order (the end when omitted). *)
      slide : int;  (** Slide id. *)
    }  (** Adds a new animation to a slide's sequence. *)
  | Remove_animations of {
      indexes : int list option;  (** 0-based playback positions to remove. *)
      shape_ids : int list option;  (** Shapes whose animations to remove. *)
      slide : int;  (** Slide id. *)
    }
      (** Removes animations from a slide's sequence: every animation of the
listed shapes and the animations at the listed playback positions.
Give at least one of the lists ([setAnimations] with `\[\]` removes all). *)
  | Replace_text of {
      find : string;  (** Text to find (within one paragraph). *)
      match_case : bool option;
          (** Match upper and lower case exactly (default: ignore case). *)
      replace : string;
          (** Replacement text (may be empty; no paragraph or line breaks). *)
      slide : int option;  (** Slide id; omit to replace on every slide. *)
      whole_word : bool option;
          (** Only match whole words (no letter, digit, or [_] on either side). *)
    }
      (** Replaces text in shapes, group members, and table cells, on one slide
or on every slide. A match may span differently formatted runs but not
paragraphs; the replacement takes the formatting of the first matched
character. The number of replacements is reported in the result. *)
  | Set_alt_text of {
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
      text : string;  (** Alt text. *)
    }
      (** Sets a shape's alt text (its description for screen readers); [""] removes it. *)
  | Set_shape_name of {
      name : string;  (** New name. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Renames a shape (the name shown in the selection pane). *)
  | Set_shape_link of {
      link : string;
          (** An address ([https://…], [mailto:…]), [#slide=<id>], a slide show
jump ([#nextslide], [#previousslide], [#firstslide], [#lastslide],
[#lastslideviewed], [#endshow]), or [""] to remove the link. *)
      shapes : int list;  (** Shape ids. *)
      slide : int;  (** Slide id. *)
      tip : string option;  (** The ScreenTip shown on hover. *)
    }
      (** Links whole shapes: clicking one in a slide show follows the link.
Links on text are set with formatText's [link]. *)
  | Set_shape_hidden of {
      hidden : bool;  (** Hidden. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }  (** Hides or shows a shape (hidden shapes are not drawn). *)
  | Paste_format of {
      from_shape : int;
          (** Shape id to copy from (a shape, line, or picture). *)
      from_slide : int;  (** Slide id of the shape to copy from. *)
      shapes : int list;  (** Shape ids to restyle. *)
      slide : int;  (** Slide id of the shapes to restyle. *)
    }
      (** Format painter: gives shapes the look of another shape — its fill,
outline, effects, theme style, and text margins and anchoring.
Character and paragraph formatting are not copied (use formatText and
formatParagraphs). Group targets paint every member. *)
  | Crop_picture of {
      bottom : float option;
          (** Fraction of the image's height cropped off its bottom edge. *)
      left : float option;
          (** Fraction of the image's width cropped off its left edge. *)
      mode : crop_mode option;
      right : float option;
          (** Fraction of the image's width cropped off its right edge. *)
      shape : int;  (** Picture id. *)
      slide : int;  (** Slide id. *)
      top : float option;
          (** Fraction of the image's height cropped off its top edge. *)
    }
      (** Crops a picture (PowerPoint's Crop). Edges are fractions of the
original image: 0.1 crops 10% of its width (left, right) or height
(top, bottom) off that edge, 0 shows the edge, and a negative value
adds empty padding; omitted edges keep their current crop. The image
keeps its size and place on the slide, so the picture's frame moves
and resizes to the part left visible. With [mode] (and no edges), the
image is instead cropped ([fill]) or padded ([fit]) to the frame's
aspect ratio, centered, and the frame stays. To crop to a shape, use
[setGeometry] on the picture. *)
  | Format_picture of {
      brightness : float option;
          (** Brightness from -1 to 1 (0 = unchanged, 0.2 = +20%). *)
      contrast : float option;  (** Contrast from -1 to 1 (0 = unchanged). *)
      recolor : string option;
          (** Recolor: [none], [grayscale], [sepia], [washout], [blackWhite]
(50% threshold), [blackWhite25], [blackWhite75],
[duotone:<color>] (the image in dark shades of the color, on
white), [duotoneLight:<color>] (in light shades of it, on black),
or [duotone:<dark>,<light>] (black and white become these
colors). Colors are [RRGGBB] or theme names ([accent1]...). *)
      reset : bool option;
          (** First remove the crop (the frame grows back to the whole image at
its current scale) and every adjustment; the other fields then
apply. *)
      shapes : int list;  (** Ids of the pictures. *)
      slide : int;  (** Slide id. *)
      transparency : float option;  (** Transparency from 0 (opaque) to 1. *)
    }
      (** Adjusts pictures (PowerPoint's Corrections, Color, and Transparency).
Omitted fields keep their current value. *)
  | Set_shape_effects of {
      glow : effect_spec_glow_options option;
      reflection : effect_spec_reflection_options option;
      shadow : effect_spec_shadow_options option;
      shapes : int list;  (** Shape ids. *)
      slide : int;  (** Slide id. *)
      soft_edge : effect_spec_soft_edge_options option;
    }
      (** Sets shape effects (PowerPoint's Shape Effects and Picture Effects)
on shapes, pictures, lines, or groups. Each effect is kept when
omitted (or null), removed with ["none"], or set from a preset name
or an options object (omitted options keep the current values). A
shape that inherits effects from the theme starts from those. *)
  | Set_custom_geometry of {
      fit : bool option;
          (** When true (the default when omitted or null), the shape's box is
moved and resized to the paths' bounds so the outline stays
exactly where it is drawn on the slide, as PowerPoint does after
Edit Points; points may then lie outside the current box. When
false, the box stays and the paths are drawn in it as given
(resizing the shape later stretches them). *)
      paths : geometry_path list;
          (** The outline's paths, in shape-local points (see [PathCommand]). *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }
      (** Replaces a shape's outline with custom geometry (PowerPoint's Edit
Points; a preset shape becomes a freeform). Fill, outline, effects,
text, rotation, and flips stay. Works on drawn shapes, text boxes,
placeholders, and pictures (it reshapes their crop outline). The
text area keeps its place on the slide. *)
  | Merge_shapes of {
      mode : merge_mode;
          (** [union], [combine], [fragment], [intersect], or [subtract]. *)
      shapes : int list;
          (** Ids of two or more shapes in selection order; the first one's
formatting wins (and [subtract] cuts the others out of it). *)
      slide : int;  (** Slide id. *)
    }
      (** Merges shapes into new outlines (PowerPoint's Shape Format ▸ Merge
Shapes), working in slide space with each shape's rotation, flips,
and group transform. The result takes the formatting, text, and
effects of the first shape (and its rotation, so its fill and text
keep their orientation) and replaces the shapes. The result's shape
ids are reported as created: the first is the first shape's id, which
the result keeps ([fragment] adds the other pieces as new shapes).
Lines, connectors, tables, charts, and groups cannot be merged; a
merge that leaves nothing is an error. *)
  | Set_theme_colors of {
      colors : theme_color list;  (** Slots to set. *)
      name : string option;  (** New name of the color scheme. *)
    }
      (** Recolors the deck: sets theme color slots in every slide master's
theme, so everything that uses theme colors (most text, shapes,
charts, and tables) follows. Omitted slots keep their color. *)
  | Set_theme_fonts of {
      major : string option;  (** Heading font (kept when omitted). *)
      minor : string option;  (** Body font (kept when omitted). *)
      name : string option;  (** New name of the font scheme. *)
    }
      (** Sets the theme's heading ([major]) and body ([minor]) Latin fonts in
every slide master's theme; text that uses theme fonts follows. *)
  | Set_header_footer of {
      date : bool option;  (** Show the date. *)
      date_format : string option;
          (** Format of an automatic date: [datetime1] (10/12/2007, the
default), [datetime2] (Friday, October 12, 2007), [datetime3] (12
October 2007), [datetime4] (October 12, 2007), [datetime5]
(12-Oct-07), [datetime6] (October 07), [datetime7] (Oct-07),
[datetime8] (10/12/2007 4:28 PM), [datetime9] (10/12/2007 4:28:34
PM), [datetime10] (16:28), [datetime11] (16:28:34), [datetime12]
(4:28 PM), or [datetime13] (4:28:34 PM). A format without
[dateText] makes the date automatic. *)
      date_text : string option;
          (** Fixed date text (e.g. "Q3 2026"); [""] makes the date automatic
(it shows the current date). Changes slides that show a date, so
pass [date: true] to turn it on. *)
      footer : bool option;  (** Show the footer. *)
      footer_text : string option;
          (** Footer text. Changes slides that show a footer, so pass
[footer: true] to turn it on. *)
      not_on_title : bool option;
          (** Don't show the elements on slides whose layout is a Title Slide
layout (they are removed there). *)
      slide_number : bool option;  (** Show the slide number. *)
      slides : int list option;
          (** Slide ids to change; omit (or null) for every slide ("Apply to
All", which also makes slides added later show the same elements). *)
    }
      (** Shows, hides, or changes the slide number, date, and footer of slides
(PowerPoint's Insert ▸ Header & Footer). Each element shown is a
placeholder that takes its position and style from the slide's
layout; a slide whose layout has no such placeholder cannot show it.
Omitted fields keep each slide's current state. *)
  | Set_slide_size of {
      height : float;
          (** Height in points, 72-4032 (540 for widescreen, 4:3, and A4; 405
for 16:9 on-screen show). *)
      scale : slide_scale option;
      width : float;
          (** Width in points, 72-4032 (960 for 16:9 widescreen, 720 for 4:3
and 16:9 on-screen show, 780 for A4). *)
    }
      (** Changes the slide size of the deck (PowerPoint's Design ▸ Slide
Size). Every slide, layout, and master changes; speaker notes keep
their size. *)
  | Add_section of {
      before_slide : int;  (** Id of the section's first slide. *)
      name : string;  (** Section name. *)
    }
      (** Starts a new section at a slide: the section takes that slide and the
slides after it in its current section. In a deck without sections,
the slides before it go into a "Default Section", as in PowerPoint.
The new section's id is reported in the result. *)
  | Rename_section of {
      id : string;
          (** Section id (a GUID from the deck outline's [sections]). *)
      name : string;  (** New name. *)
    }  (** Renames a section. *)
  | Remove_section of {
      delete_slides : bool option;  (** Delete the section's slides too. *)
      id : string;  (** Section id. *)
    }
      (** Removes a section. Its slides join the previous section (the next
one when it is the first), or are deleted with [deleteSlides].
Removing the only section leaves the deck without sections. *)
  | Move_section of {
      id : string;  (** Section id. *)
      to_index : int;  (** New index among the sections. *)
    }
      (** Moves a section and all its slides to a 0-based position among the
sections; the slides are reordered to match. *)
  | Set_guides of { guides : guide_spec list  (** The guides, in order. *) }
      (** Replaces the deck's drawing guides (PowerPoint's View ▸ Guides): the
dashed lines shown over every slide for lining shapes up, which
shapes snap to while dragged. Pass the whole list (the deck outline's
[guides], changed); an empty list removes every guide. Guides that
slide layouts and masters define are not affected. *)
  | Add_layout of {
      after : int option;
          (** Id of the layout to insert it after; a master's id puts it first
(default: right after [duplicate], else after the master's last
layout). *)
      duplicate : int option;
          (** Id of a layout to copy, with its shapes and background. *)
      master : int option;
          (** Id of the master to add it to (default: the master of [after]
or [duplicate], else the first master). *)
      name : string option;
          (** Name (default: "Custom Layout", or for a copy the original's name
prefixed "1_", numbered further when the master has one already). *)
    }
      (** Adds a slide layout to a slide master (PowerPoint's Slide Master ▸
Insert Layout): a layout with a title placeholder and the master's
date, footer, and slide number placeholders, or with [duplicate] a
copy of that layout. Masters and layouts are listed in the deck
outline's [masters]. The new layout's id is reported in the result
(as [slide]); it addresses the layout's shapes like a slide id. *)
  | Rename_layout of {
      layout : int;  (** Layout or master id. *)
      name : string;  (** New name. *)
    }
      (** Renames a slide layout, or a slide master (a master's name is its
theme's name, as PowerPoint shows it). *)
  | Delete_layout of { layout : int  (** Layout or master id. *) }
      (** Deletes a slide layout no slide uses (give those slides another
layout with [setSlideLayout] first). A master keeps at least one
layout. With a master's id, deletes that master and its layouts when
no slide uses any of them and another master remains. *)
  | Insert_placeholder of {
      h : float;  (** Height (points). *)
      kind : placeholder_kind;
          (** What it holds: [content], [text], [picture], [chart], [table],
[smartArt], or [media]. *)
      layout : int;  (** Layout id. *)
      vertical : bool option;
          (** Vertical text (PowerPoint's "Content (Vertical)" and "Text
(Vertical)"); content and text placeholders only. *)
      w : float;  (** Width (points). *)
      x : float;  (** Left (points). *)
      y : float;  (** Top (points). *)
    }
      (** Adds a placeholder to a slide layout (PowerPoint's Slide Master ▸
Insert Placeholder). Slides added with the layout afterwards get it,
empty, where the layout has it; existing slides get it when their
layout is applied again ([setSlideLayout]). Content and text
placeholders take the master's text styles. The new shape's id is
reported in the result. *)
  | Set_layout_options of {
      footers : bool option;
          (** Show the date, footer, and slide number placeholders the master
has (added where the master has them, or removed). *)
      hide_background_graphics : bool option;
          (** Hide the master's shapes (logos, lines, pictures) on the layout
and its slides. *)
      layout : int;  (** Layout id. *)
      title : bool option;
          (** Show a title placeholder (added where the master's title is, or
removed). *)
    }
      (** Sets what a slide layout shows (PowerPoint's Slide Master ▸ Title,
Footers, and Hide Background Graphics). Omitted fields keep the
layout's current state. *)
  | Set_background_style of {
      slide : int;  (** Slide, master, or layout id. *)
      style : int;  (** Style number, 1-12. *)
    }
      (** Gives a slide, slide master, or layout one of the theme's background
styles (PowerPoint's Background Styles gallery), which follow the
theme's colors and background fills. Styles 1-4 are the theme's
first background fill (usually solid) in Light 1, Dark 1, Light 2,
and Dark 2; 5-8 its second and 9-12 its third, in the same colors. *)
  | Add_comment of {
      author : string;  (** The author's name, as the Comments pane shows it. *)
      initials : string option;
          (** The author's initials (omit or null: the first letters of the
first two words of [author]). *)
      shape : int option;
          (** Shape id to attach the comment to (its marker sits at the
shape's top-right corner); omit or null for the slide itself. *)
      slide : int;  (** Slide id. *)
      text : string;  (** The comment ([\n] separates paragraphs). *)
      x : float option;
          (** Where the comment's marker sits, in points from the slide's left
edge, for a comment on the slide (omit or null with [y] for
PowerPoint's default, the slide's top-left corner). Ignored with
[shape]. *)
      y : float option;
          (** Marker position in points from the slide's top edge. *)
    }
      (** Adds a comment thread to a slide (PowerPoint's Review ▸ New
Comment), attached to a shape or to the slide. Written as PowerPoint
for Microsoft 365 writes comments. Read threads and their ids from
the slide outline's [comments]. *)
  | Reply_comment of {
      author : string;  (** The author's name. *)
      comment : string;
          (** Thread id (a comment's [id] in the outline). Legacy comments
([legacy-…] ids) cannot be replied to. *)
      initials : string option;
          (** The author's initials (omit or null: derived from [author]). *)
      slide : int;  (** Slide id. *)
      text : string;  (** The reply ([\n] separates paragraphs). *)
    }  (** Replies to a comment thread. *)
  | Edit_comment of {
      comment : string;  (** Thread or reply id. *)
      slide : int;  (** Slide id. *)
      text : string;  (** The new text. *)
    }
      (** Replaces the text of a comment: a thread's first comment or a reply. *)
  | Resolve_comment of {
      comment : string;  (** Thread id. *)
      resolved : bool;  (** [true] resolves; [false] reopens. *)
      slide : int;  (** Slide id. *)
    }
      (** Resolves a comment thread, or reopens it (PowerPoint's Resolve
thread / Reopen). Legacy comments cannot be resolved. *)
  | Delete_comment of {
      comment : string;  (** Thread or reply id. *)
      slide : int;  (** Slide id. *)
    }  (** Deletes a comment thread with its replies, or a single reply. *)
  | Delete_all_comments of {
      slide : int option;  (** Slide id (omit or null: all slides). *)
    }
      (** Deletes every comment on a slide, or with [slide] omitted (or null)
every comment in the presentation. *)
  | Insert_equation of {
      at : text_pos option;
      cell : cell_ref option;
      display : bool option;
          (** [true]: a display equation on a line (paragraph) of its own,
centered, with large operators and fractions at full size (what
PowerPoint inserts); [false]: inline, flowing with the text
around it. Omit (or null) for display in an empty paragraph or a
new text box, inline otherwise. *)
      latex : string;
          (** The equation, e.g. [x=\frac{-b\pm\sqrt{b^2-4ac}}{2a}]. *)
      shape : int option;
          (** Shape whose text gets the equation; omit (or null) to add a new
text box holding only the equation. *)
      slide : int;  (** Slide id. *)
    }
      (** Inserts an equation (PowerPoint's Insert ▸ Equation) written in the
LaTeX-style linear format: into a shape's text at [at], or, without
[shape], in a new text box centered on the slide (its id is reported
in the result). In text an equation counts as one character (U+FFFC
in the outline's paragraph text, listed in the paragraph's
[equations]): delete it with [deleteText], change it with
[setEquation]. Supported: [\frac{a}{b}], [^], [_], `\sqrt\[n\]\{x\}`,
[\sum_{i=1}^{n}], [\prod], [\int_{a}^{b}], [\oint], [\lim_{x\to 0}],
[\sin] and other functions, [\left( \right)] (brackets such as
[(…)] pair and grow by themselves), [\begin{matrix}] / [pmatrix] /
[bmatrix] / [vmatrix] / [cases] / [aligned], [\binom{n}{k}], accents
([\hat \bar \vec \dot \ddot \tilde]), [\overline], [\underline],
[\overbrace{x}^{a}], [\underbrace{x}_{a}], [\boxed], Greek letters,
symbols (`\infty \pm \times \cdot \le \ge \ne \approx \to
\Rightarrow \partial \nabla[...), ]\mathrm\{\}[, ]\mathbf\{\}`,
[\mathbb{}], [\mathcal{}], [\text{}], and spaces ([\, \; \quad]). *)
  | Set_equation of {
      cell : cell_ref option;
      display : bool option;
          (** Make it a display ([true]) or inline ([false]) equation; omit
(or null) to keep. *)
      index : int;
          (** The equation's character index in the paragraph (its [index] in
the outline). *)
      latex : string;
          (** The new equation in the linear format (see [insertEquation]). *)
      paragraph : int;  (** Paragraph index. *)
      shape : int;  (** Shape id. *)
      slide : int;  (** Slide id. *)
    }
      (** Replaces an equation (one of a paragraph's [equations] in the
outline) with new linear text, keeping its size and color. *)
  | Edit_smart_art of {
      edit : smart_art_edit;  (** The change. *)
      shape : int;  (** The SmartArt graphic frame's id. *)
      slide : int;  (** Slide id. *)
    }
      (** Edits a SmartArt graphic (a shape of kind [diagram] whose outline has
[smartArt]): its nodes and their text as in PowerPoint's text pane,
its layout, colors, or style. The diagram is laid out again, its text
shrinking together to fit. Nodes are addressed by the ids in
[smartArt.nodes]; a new node's id appears there afterwards. Diagrams
whose layout the outline reports as not [supported] take text edits,
colors, styles, and a new supported layout, but not node changes. *)
  | Convert_smart_art of {
      shape : int;  (** The SmartArt graphic frame's id. *)
      slide : int;  (** Slide id. *)
      to_ : smart_art_target;  (** [shapes] or [text]. *)
    }
      (** Converts a SmartArt graphic into ordinary shapes (a group that looks
the same) or into a bulleted text box. The new shape's id is reported
in the result. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let edit_op_of_yojson : Yojson.Safe.t -> edit_op =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "op" with
  | "setText" ->
      Set_text
        {
          cell = Json.optional fields "cell" cell_ref_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          text = Json.required fields "text" Json.string;
        }
  | "insertText" ->
      Insert_text
        {
          at = Json.required fields "at" text_pos_of_yojson;
          cell = Json.optional fields "cell" cell_ref_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          text = Json.required fields "text" Json.string;
        }
  | "deleteText" ->
      Delete_text
        {
          cell = Json.optional fields "cell" cell_ref_of_yojson;
          end_ = Json.required fields "end" text_pos_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          start = Json.required fields "start" text_pos_of_yojson;
        }
  | "formatText" ->
      Format_text
        {
          cell = Json.optional fields "cell" cell_ref_of_yojson;
          end_ = Json.optional fields "end" text_pos_of_yojson;
          props = Json.required fields "props" run_patch_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          start = Json.optional fields "start" text_pos_of_yojson;
        }
  | "formatParagraphs" ->
      Format_paragraphs
        {
          cell = Json.optional fields "cell" cell_ref_of_yojson;
          from = Json.optional fields "from" Json.int;
          props = Json.required fields "props" para_patch_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          to_ = Json.optional fields "to" Json.int;
        }
  | "formatBody" ->
      Format_body
        {
          cell = Json.optional fields "cell" cell_ref_of_yojson;
          props = Json.required fields "props" body_patch_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "setTransform" ->
      Set_transform
        {
          flip_h = Json.optional fields "flipH" Json.bool;
          flip_v = Json.optional fields "flipV" Json.bool;
          h = Json.optional fields "h" Json.float;
          rotation = Json.optional fields "rotation" Json.float;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          w = Json.optional fields "w" Json.float;
          x = Json.optional fields "x" Json.float;
          y = Json.optional fields "y" Json.float;
        }
  | "setFill" ->
      Set_fill
        {
          fill = Json.required fields "fill" fill_spec_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "setLine" ->
      Set_line
        {
          line = Json.required fields "line" line_patch_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "setGeometry" ->
      Set_geometry
        {
          preset = Json.required fields "preset" Json.string;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "addShape" ->
      Add_shape
        {
          h = Json.required fields "h" Json.float;
          shape = Json.required fields "shape" new_shape_of_yojson;
          slide = Json.required fields "slide" Json.int;
          w = Json.required fields "w" Json.float;
          x = Json.required fields "x" Json.float;
          y = Json.required fields "y" Json.float;
        }
  | "deleteShape" ->
      Delete_shape
        {
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "duplicateShape" ->
      Duplicate_shape
        {
          dx = Json.optional fields "dx" Json.float;
          dy = Json.optional fields "dy" Json.float;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "reorderShape" ->
      Reorder_shape
        {
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          to_ = Json.required fields "to" z_order_of_yojson;
        }
  | "replaceImage" ->
      Replace_image
        {
          data = Json.required fields "data" Json.string;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "setCellText" ->
      Set_cell_text
        {
          col = Json.required fields "col" Json.int;
          row = Json.required fields "row" Json.int;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          text = Json.required fields "text" Json.string;
        }
  | "insertTableRow" ->
      Insert_table_row
        {
          at = Json.required fields "at" Json.int;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "deleteTableRow" ->
      Delete_table_row
        {
          row = Json.required fields "row" Json.int;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "insertTableColumn" ->
      Insert_table_column
        {
          at = Json.required fields "at" Json.int;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "deleteTableColumn" ->
      Delete_table_column
        {
          col = Json.required fields "col" Json.int;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "mergeCells" ->
      Merge_cells
        {
          from = Json.required fields "from" cell_ref_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          to_ = Json.required fields "to" cell_ref_of_yojson;
        }
  | "splitCell" ->
      Split_cell
        {
          cell = Json.required fields "cell" cell_ref_of_yojson;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
        }
  | "formatCells" ->
      Format_cells
        {
          anchor = Json.optional fields "anchor" Json.string;
          borders = Json.optional fields "borders" cell_borders_of_yojson;
          fill = Json.optional fields "fill" fill_spec_of_yojson;
          from = Json.required fields "from" cell_ref_of_yojson;
          margins = Json.optional fields "margins" (Json.list Json.float);
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          to_ = Json.required fields "to" cell_ref_of_yojson;
        }
  | "setTableStyle" ->
      Set_table_style
        {
          band_col = Json.optional fields "bandCol" Json.bool;
          band_row = Json.optional fields "bandRow" Json.bool;
          first_col = Json.optional fields "firstCol" Json.bool;
          first_row = Json.optional fields "firstRow" Json.bool;
          last_col = Json.optional fields "lastCol" Json.bool;
          last_row = Json.optional fields "lastRow" Json.bool;
          shape = Json.required fields "shape" Json.int;
          slide = Json.required fields "slide" Json.int;
          style = Json.optional fields "style" Json.string;
        }
  | "setTableGrid" ->
      Set_table_grid
        {
          column_widths =
