and yojson_of_edit_op : edit_op -> Yojson.Safe.t =
 fun value ->
  match value with
  | Set_text case ->
      Json.record
        [
          ("op", Some (`String "setText"));
          ("cell", Option.map yojson_of_cell_ref case.cell);
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("text", Some (Json.of_string case.text));
        ]
  | Insert_text case ->
      Json.record
        [
          ("op", Some (`String "insertText"));
          ("at", Some (yojson_of_text_pos case.at));
          ("cell", Option.map yojson_of_cell_ref case.cell);
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("text", Some (Json.of_string case.text));
        ]
  | Delete_text case ->
      Json.record
        [
          ("op", Some (`String "deleteText"));
          ("cell", Option.map yojson_of_cell_ref case.cell);
          ("end", Some (yojson_of_text_pos case.end_));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("start", Some (yojson_of_text_pos case.start));
        ]
  | Format_text case ->
      Json.record
        [
          ("op", Some (`String "formatText"));
          ("cell", Option.map yojson_of_cell_ref case.cell);
          ("end", Option.map yojson_of_text_pos case.end_);
          ("props", Some (yojson_of_run_patch case.props));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("start", Option.map yojson_of_text_pos case.start);
        ]
  | Format_paragraphs case ->
      Json.record
        [
          ("op", Some (`String "formatParagraphs"));
          ("cell", Option.map yojson_of_cell_ref case.cell);
          ("from", Option.map Json.of_int case.from);
          ("props", Some (yojson_of_para_patch case.props));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("to", Option.map Json.of_int case.to_);
        ]
  | Format_body case ->
      Json.record
        [
          ("op", Some (`String "formatBody"));
          ("cell", Option.map yojson_of_cell_ref case.cell);
          ("props", Some (yojson_of_body_patch case.props));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Set_transform case ->
      Json.record
        [
          ("op", Some (`String "setTransform"));
          ("flipH", Option.map Json.of_bool case.flip_h);
          ("flipV", Option.map Json.of_bool case.flip_v);
          ("h", Option.map Json.of_float case.h);
          ("rotation", Option.map Json.of_float case.rotation);
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("w", Option.map Json.of_float case.w);
          ("x", Option.map Json.of_float case.x);
          ("y", Option.map Json.of_float case.y);
        ]
  | Set_fill case ->
      Json.record
        [
          ("op", Some (`String "setFill"));
          ("fill", Some (yojson_of_fill_spec case.fill));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Set_line case ->
      Json.record
        [
          ("op", Some (`String "setLine"));
          ("line", Some (yojson_of_line_patch case.line));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Set_geometry case ->
      Json.record
        [
          ("op", Some (`String "setGeometry"));
          ("preset", Some (Json.of_string case.preset));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Add_shape case ->
      Json.record
        [
          ("op", Some (`String "addShape"));
          ("h", Some (Json.of_float case.h));
          ("shape", Some (yojson_of_new_shape case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("w", Some (Json.of_float case.w));
          ("x", Some (Json.of_float case.x));
          ("y", Some (Json.of_float case.y));
        ]
  | Delete_shape case ->
      Json.record
        [
          ("op", Some (`String "deleteShape"));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Duplicate_shape case ->
      Json.record
        [
          ("op", Some (`String "duplicateShape"));
          ("dx", Option.map Json.of_float case.dx);
          ("dy", Option.map Json.of_float case.dy);
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Reorder_shape case ->
      Json.record
        [
          ("op", Some (`String "reorderShape"));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("to", Some (yojson_of_z_order case.to_));
        ]
  | Replace_image case ->
      Json.record
        [
          ("op", Some (`String "replaceImage"));
          ("data", Some (Json.of_string case.data));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Set_cell_text case ->
      Json.record
        [
          ("op", Some (`String "setCellText"));
          ("col", Some (Json.of_int case.col));
          ("row", Some (Json.of_int case.row));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("text", Some (Json.of_string case.text));
        ]
  | Insert_table_row case ->
      Json.record
        [
          ("op", Some (`String "insertTableRow"));
          ("at", Some (Json.of_int case.at));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
