  | Delete_table_row case ->
      Json.record
        [
          ("op", Some (`String "deleteTableRow"));
          ("row", Some (Json.of_int case.row));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
