  | Insert_table_column case ->
      Json.record
        [
          ("op", Some (`String "insertTableColumn"));
          ("at", Some (Json.of_int case.at));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Delete_table_column case ->
      Json.record
        [
          ("op", Some (`String "deleteTableColumn"));
          ("col", Some (Json.of_int case.col));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Merge_cells case ->
      Json.record
        [
          ("op", Some (`String "mergeCells"));
          ("from", Some (yojson_of_cell_ref case.from));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("to", Some (yojson_of_cell_ref case.to_));
        ]
  | Split_cell case ->
      Json.record
        [
          ("op", Some (`String "splitCell"));
          ("cell", Some (yojson_of_cell_ref case.cell));
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Format_cells case ->
      Json.record
        [
          ("op", Some (`String "formatCells"));
          ("anchor", Option.map Json.of_string case.anchor);
          ("borders", Option.map yojson_of_cell_borders case.borders);
          ("fill", Option.map yojson_of_fill_spec case.fill);
          ("from", Some (yojson_of_cell_ref case.from));
          ("margins", Option.map (Json.of_list Json.of_float) case.margins);
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("to", Some (yojson_of_cell_ref case.to_));
        ]
  | Set_table_style case ->
      Json.record
        [
          ("op", Some (`String "setTableStyle"));
          ("bandCol", Option.map Json.of_bool case.band_col);
          ("bandRow", Option.map Json.of_bool case.band_row);
          ("firstCol", Option.map Json.of_bool case.first_col);
          ("firstRow", Option.map Json.of_bool case.first_row);
          ("lastCol", Option.map Json.of_bool case.last_col);
          ("lastRow", Option.map Json.of_bool case.last_row);
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
          ("style", Option.map Json.of_string case.style);
        ]
  | Set_table_grid case ->
      Json.record
        [
          ("op", Some (`String "setTableGrid"));
          ( "columnWidths",
            Option.map (Json.of_list Json.of_float) case.column_widths );
          ( "rowHeights",
            Option.map (Json.of_list Json.of_float) case.row_heights );
          ("shape", Some (Json.of_int case.shape));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Add_slide case ->
      Json.record
        [
          ("op", Some (`String "addSlide"));
          ("after", Option.map Json.of_int case.after);
          ("body", Option.map Json.of_string case.body);
          ("layout", Option.map Json.of_string case.layout);
          ("title", Option.map Json.of_string case.title);
        ]
  | Duplicate_slide case ->
      Json.record
        [
          ("op", Some (`String "duplicateSlide"));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Delete_slide case ->
      Json.record
        [
          ("op", Some (`String "deleteSlide"));
          ("slide", Some (Json.of_int case.slide));
        ]
  | Move_slide case ->
      Json.record
        [
          ("op", Some (`String "moveSlide"));
          ("slide", Some (Json.of_int case.slide));
          ("to", Some (Json.of_int case.to_));
        ]
  | Set_slide_hidden case ->
      Json.record
