type nonrec option_removal = {
  field : string;  (** The field. *)
  label : string;  (** The label. *)
}
(** An option to delete, emptying the entries holding it. *)

let option_removal_of_yojson : Yojson.Safe.t -> option_removal =
 fun json ->
  let fields = Json.obj json in
  {
    field = Json.required fields "field" Json.string;
    label = Json.required fields "label" Json.string;
  }

and yojson_of_option_removal : option_removal -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("field", Some (Json.of_string value.field));
      ("label", Some (Json.of_string value.label));
    ]

let make_option_removal ~(field : string) ~(label : string) () =
  ({ field; label } : option_removal)

type nonrec field_rename = {
  from : string;  (** Its current name. *)
  to_ : string;  (** Its new name. *)
}
(** A field to rename. *)

let field_rename_of_yojson : Yojson.Safe.t -> field_rename =
 fun json ->
  let fields = Json.obj json in
  {
    from = Json.required fields "from" Json.string;
    to_ = Json.required fields "to" Json.string;
  }

and yojson_of_field_rename : field_rename -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("from", Some (Json.of_string value.from));
      ("to", Some (Json.of_string value.to_));
    ]

let make_field_rename ~(from : string) ~(to_ : string) () =
  ({ from; to_ } : field_rename)

type nonrec option_rename = {
  field : string;  (** The field. *)
  from : string;  (** The current label. *)
  to_ : string;  (** The new label. *)
}
(** An option to relabel. *)

let option_rename_of_yojson : Yojson.Safe.t -> option_rename =
 fun json ->
  let fields = Json.obj json in
  {
    field = Json.required fields "field" Json.string;
    from = Json.required fields "from" Json.string;
    to_ = Json.required fields "to" Json.string;
  }

and yojson_of_option_rename : option_rename -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("field", Some (Json.of_string value.field));
      ("from", Some (Json.of_string value.from));
      ("to", Some (Json.of_string value.to_));
    ]

let make_option_rename ~(field : string) ~(from : string) ~(to_ : string) () =
  ({ field; from; to_ } : option_rename)

type nonrec edit_pipeline_request = {
  add_fields : new_field_request list option;  (** Fields to add. *)
  add_options : field_options list option;
      (** Labels to add to select fields; for Stage, new stages go last. *)
  name : string option;  (** A new name. *)
  remove_fields : string list option;
      (** Fields to delete with their values. *)
  remove_options : option_removal list option;  (** Options to delete. *)
  rename_fields : field_rename list option;  (** Fields to rename. *)
  rename_options : option_rename list option;  (** Options to relabel. *)
  sharing : pipeline_sharing option;
}
(** Changes to a pipeline's name, sharing, fields and options, applied
together. *)

let edit_pipeline_request_of_yojson : Yojson.Safe.t -> edit_pipeline_request =
 fun json ->
  let fields = Json.obj json in
  {
    add_fields =
      Json.optional fields "addFields" (Json.list new_field_request_of_yojson);
    add_options =
      Json.optional fields "addOptions" (Json.list field_options_of_yojson);
    name = Json.optional fields "name" Json.string;
    remove_fields = Json.optional fields "removeFields" (Json.list Json.string);
    remove_options =
      Json.optional fields "removeOptions" (Json.list option_removal_of_yojson);
    rename_fields =
      Json.optional fields "renameFields" (Json.list field_rename_of_yojson);
    rename_options =
      Json.optional fields "renameOptions" (Json.list option_rename_of_yojson);
    sharing = Json.optional fields "sharing" pipeline_sharing_of_yojson;
  }

and yojson_of_edit_pipeline_request : edit_pipeline_request -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "addFields",
        Option.map (Json.of_list yojson_of_new_field_request) value.add_fields
      );
      ( "addOptions",
        Option.map (Json.of_list yojson_of_field_options) value.add_options );
      ("name", Option.map Json.of_string value.name);
      ( "removeFields",
        Option.map (Json.of_list Json.of_string) value.remove_fields );
      ( "removeOptions",
        Option.map (Json.of_list yojson_of_option_removal) value.remove_options
      );
      ( "renameFields",
        Option.map (Json.of_list yojson_of_field_rename) value.rename_fields );
      ( "renameOptions",
        Option.map (Json.of_list yojson_of_option_rename) value.rename_options
      );
      ("sharing", Option.map yojson_of_pipeline_sharing value.sharing);
    ]

let make_edit_pipeline_request ?add_fields ?add_options ?name ?remove_fields
    ?remove_options ?rename_fields ?rename_options ?sharing () =
  ({
     add_fields;
     add_options;
     name;
     remove_fields;
     remove_options;
     rename_fields;
     rename_options;
     sharing;
   }
    : edit_pipeline_request)

(** Excel border line style. *)
type nonrec spreadsheet_border_style =
  | Reset
  | Thin
  | Medium
  | Thick
  | Double
  | Dotted
  | Dashed
  | Dash_dot
  | Dash_dot_dot
  | Slant_dash_dot
  | Hair
  | Medium_dashed
  | Medium_dash_dot
  | Medium_dash_dot_dot
  | Unknown of string  (** A value this SDK version does not know. *)

let spreadsheet_border_style_of_yojson :
    Yojson.Safe.t -> spreadsheet_border_style =
 fun json ->
  match Json.string json with
  | "reset" -> Reset
  | "thin" -> Thin
  | "medium" -> Medium
  | "thick" -> Thick
  | "double" -> Double
  | "dotted" -> Dotted
  | "dashed" -> Dashed
  | "dashDot" -> Dash_dot
  | "dashDotDot" -> Dash_dot_dot
  | "slantDashDot" -> Slant_dash_dot
  | "hair" -> Hair
  | "mediumDashed" -> Medium_dashed
  | "mediumDashDot" -> Medium_dash_dot
  | "mediumDashDotDot" -> Medium_dash_dot_dot
  | other -> Unknown other

and yojson_of_spreadsheet_border_style :
    spreadsheet_border_style -> Yojson.Safe.t =
 fun value ->
  match value with
  | Reset -> `String "reset"
  | Thin -> `String "thin"
  | Medium -> `String "medium"
  | Thick -> `String "thick"
  | Double -> `String "double"
  | Dotted -> `String "dotted"
  | Dashed -> `String "dashed"
  | Dash_dot -> `String "dashDot"
  | Dash_dot_dot -> `String "dashDotDot"
  | Slant_dash_dot -> `String "slantDashDot"
  | Hair -> `String "hair"
  | Medium_dashed -> `String "mediumDashed"
  | Medium_dash_dot -> `String "mediumDashDot"
  | Medium_dash_dot_dot -> `String "mediumDashDotDot"
  | Unknown other -> `String other

(** Font family. *)
type nonrec spreadsheet_font =
  | Sans
  | Serif
  | Mono
  | Unknown of string  (** A value this SDK version does not know. *)

let spreadsheet_font_of_yojson : Yojson.Safe.t -> spreadsheet_font =
