  | "sans" -> Sans
  | "serif" -> Serif
  | "mono" -> Mono
  | other -> Unknown other

and yojson_of_spreadsheet_font : spreadsheet_font -> Yojson.Safe.t =
 fun value ->
  match value with
  | Sans -> `String "sans"
  | Serif -> `String "serif"
  | Mono -> `String "mono"
  | Unknown other -> `String other

