type nonrec spreadsheet_style = {
  bold : bool option;  (** Bold text. *)
  border_bottom : bool option;  (** Bottom border. *)
  border_bottom_color : string option;  (** Bottom border color. *)
  border_bottom_style : spreadsheet_border_style option;
  border_left : bool option;  (** Left border. *)
  border_left_color : string option;  (** Left border color. *)
  border_left_style : spreadsheet_border_style option;
  border_right : bool option;  (** Right border. *)
  border_right_color : string option;  (** Right border color. *)
  border_right_style : spreadsheet_border_style option;
  border_top : bool option;  (** Top border. *)
  border_top_color : string option;  (** Top border color. *)
  border_top_style : spreadsheet_border_style option;
  checkbox : bool option;
      (** Show the cell's TRUE/FALSE value as a checkbox; false removes it and keeps the value. *)
  decimals : int option;
      (** Decimal places, 0 through 10; -1 restores automatic. *)
  fill_color : string option;
      (** Fill color as #RRGGBB; empty string resets it. *)
  font_family : spreadsheet_font option;
  font_name : string option;
      (** Exact Excel font name, up to 128 characters. *)
  font_size : int option;  (** Font size in points, 8 through 36. *)
  format : spreadsheet_number_format option;
  horizontal_align : spreadsheet_horizontal_align option;
  indent : int option;
      (** Indent level, 0 through 250, as Excel's Increase Indent: each level is three spaces from the
left edge, or from the right edge of right-aligned cells. Centered cells ignore it. *)
  italic : bool option;  (** Italic text. *)
  number_format : string option;
      (** Exact Excel number format, up to 512 characters; it overrides the display of [format].
Show dates with format=date and a date code such as mmm yyyy (Jan 2026), mmm dd, yyyy,
mm/dd/yyyy, dd/mm/yyyy, yyyy-mm-dd, d mmm yyyy or dddd, mmmm d, yyyy; times with
format=time and a code such as h:mm AM/PM. *)
  strikethrough : bool option;  (** Struck-through text. *)
  text_color : string option;
      (** Text color as #RRGGBB; empty string resets it. *)
  underline : bool option;  (** Underlined text. *)
  vertical_align : spreadsheet_vertical_align option;
  wrap : bool option;  (** Wrap text. *)
}
(** Sparse cell styling patch. Omitted fields remain unchanged. *)

let spreadsheet_style_of_yojson : Yojson.Safe.t -> spreadsheet_style =
 fun json ->
  let fields = Json.obj json in
  {
    bold = Json.optional fields "bold" Json.bool;
    border_bottom = Json.optional fields "borderBottom" Json.bool;
    border_bottom_color = Json.optional fields "borderBottomColor" Json.string;
    border_bottom_style =
      Json.optional fields "borderBottomStyle"
        spreadsheet_border_style_of_yojson;
    border_left = Json.optional fields "borderLeft" Json.bool;
    border_left_color = Json.optional fields "borderLeftColor" Json.string;
    border_left_style =
      Json.optional fields "borderLeftStyle" spreadsheet_border_style_of_yojson;
    border_right = Json.optional fields "borderRight" Json.bool;
    border_right_color = Json.optional fields "borderRightColor" Json.string;
    border_right_style =
      Json.optional fields "borderRightStyle" spreadsheet_border_style_of_yojson;
    border_top = Json.optional fields "borderTop" Json.bool;
    border_top_color = Json.optional fields "borderTopColor" Json.string;
    border_top_style =
      Json.optional fields "borderTopStyle" spreadsheet_border_style_of_yojson;
    checkbox = Json.optional fields "checkbox" Json.bool;
    decimals = Json.optional fields "decimals" Json.int;
    fill_color = Json.optional fields "fillColor" Json.string;
    font_family = Json.optional fields "fontFamily" spreadsheet_font_of_yojson;
    font_name = Json.optional fields "fontName" Json.string;
    font_size = Json.optional fields "fontSize" Json.int;
    format = Json.optional fields "format" spreadsheet_number_format_of_yojson;
    horizontal_align =
      Json.optional fields "horizontalAlign"
        spreadsheet_horizontal_align_of_yojson;
    indent = Json.optional fields "indent" Json.int;
    italic = Json.optional fields "italic" Json.bool;
    number_format = Json.optional fields "numberFormat" Json.string;
    strikethrough = Json.optional fields "strikethrough" Json.bool;
    text_color = Json.optional fields "textColor" Json.string;
    underline = Json.optional fields "underline" Json.bool;
    vertical_align =
      Json.optional fields "verticalAlign" spreadsheet_vertical_align_of_yojson;
    wrap = Json.optional fields "wrap" Json.bool;
  }

and yojson_of_spreadsheet_style : spreadsheet_style -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("bold", Option.map Json.of_bool value.bold);
      ("borderBottom", Option.map Json.of_bool value.border_bottom);
      ("borderBottomColor", Option.map Json.of_string value.border_bottom_color);
      ( "borderBottomStyle",
        Option.map yojson_of_spreadsheet_border_style value.border_bottom_style
      );
      ("borderLeft", Option.map Json.of_bool value.border_left);
      ("borderLeftColor", Option.map Json.of_string value.border_left_color);
      ( "borderLeftStyle",
        Option.map yojson_of_spreadsheet_border_style value.border_left_style );
      ("borderRight", Option.map Json.of_bool value.border_right);
      ("borderRightColor", Option.map Json.of_string value.border_right_color);
      ( "borderRightStyle",
        Option.map yojson_of_spreadsheet_border_style value.border_right_style
      );
      ("borderTop", Option.map Json.of_bool value.border_top);
      ("borderTopColor", Option.map Json.of_string value.border_top_color);
      ( "borderTopStyle",
        Option.map yojson_of_spreadsheet_border_style value.border_top_style );
      ("checkbox", Option.map Json.of_bool value.checkbox);
      ("decimals", Option.map Json.of_int value.decimals);
      ("fillColor", Option.map Json.of_string value.fill_color);
      ("fontFamily", Option.map yojson_of_spreadsheet_font value.font_family);
      ("fontName", Option.map Json.of_string value.font_name);
      ("fontSize", Option.map Json.of_int value.font_size);
      ("format", Option.map yojson_of_spreadsheet_number_format value.format);
      ( "horizontalAlign",
        Option.map yojson_of_spreadsheet_horizontal_align value.horizontal_align
      );
      ("indent", Option.map Json.of_int value.indent);
      ("italic", Option.map Json.of_bool value.italic);
      ("numberFormat", Option.map Json.of_string value.number_format);
      ("strikethrough", Option.map Json.of_bool value.strikethrough);
      ("textColor", Option.map Json.of_string value.text_color);
      ("underline", Option.map Json.of_bool value.underline);
      ( "verticalAlign",
        Option.map yojson_of_spreadsheet_vertical_align value.vertical_align );
      ("wrap", Option.map Json.of_bool value.wrap);
    ]

let make_spreadsheet_style ?bold ?border_bottom ?border_bottom_color
    ?border_bottom_style ?border_left ?border_left_color ?border_left_style
