(** What a table column holds, as Google Sheets types table columns. *)
type nonrec spreadsheet_column_type =
  | Text
  | Number
  | Percent
  | Currency
  | Date
  | Datetime
  | Time
  | Checkbox
  | Dropdown
  | Person
  | Unknown of string  (** A value this SDK version does not know. *)

let spreadsheet_column_type_of_yojson : Yojson.Safe.t -> spreadsheet_column_type
    =
 fun json ->
  match Json.string json with
  | "text" -> Text
  | "number" -> Number
  | "percent" -> Percent
  | "currency" -> Currency
  | "date" -> Date
  | "datetime" -> Datetime
  | "time" -> Time
  | "checkbox" -> Checkbox
  | "dropdown" -> Dropdown
  | "person" -> Person
  | other -> Unknown other

and yojson_of_spreadsheet_column_type : spreadsheet_column_type -> Yojson.Safe.t
    =
 fun value ->
  match value with
  | Text -> `String "text"
  | Number -> `String "number"
  | Percent -> `String "percent"
  | Currency -> `String "currency"
  | Date -> `String "date"
  | Datetime -> `String "datetime"
  | Time -> `String "time"
  | Checkbox -> `String "checkbox"
  | Dropdown -> `String "dropdown"
  | Person -> `String "person"
  | Unknown other -> `String other

type nonrec spreadsheet_table_column_type = {
  column : string;  (** Header name of the column, ignoring case. *)
  type_ : spreadsheet_column_type;  (** What the column holds. *)
}
(** A table column's type, by its header name. *)

let spreadsheet_table_column_type_of_yojson :
    Yojson.Safe.t -> spreadsheet_table_column_type =
 fun json ->
  let fields = Json.obj json in
  {
    column = Json.required fields "column" Json.string;
    type_ = Json.required fields "type" spreadsheet_column_type_of_yojson;
  }

and yojson_of_spreadsheet_table_column_type :
    spreadsheet_table_column_type -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("column", Some (Json.of_string value.column));
      ("type", Some (yojson_of_spreadsheet_column_type value.type_));
    ]

let make_spreadsheet_table_column_type ~(column : string)
    ~(type_ : spreadsheet_column_type) () =
  ({ column; type_ } : spreadsheet_table_column_type)

(** One operation in an atomic workbook edit. All operations validate before any write. *)
type nonrec spreadsheet_operation =
  | Set_cells of {
      cells : spreadsheet_cell_input list;
          (** Cells and their new source inputs. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
    }  (** Set raw values/formulas while preserving existing formatting. *)
  | Format_cells of {
      range : string;  (** A1 rectangle, for example A1:D20. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
      style : spreadsheet_style;
          (** Properties to change; omitted properties remain unchanged. *)
    }  (** Apply a sparse formatting patch to a rectangle. *)
  | Clear_cells of {
      clear_formatting : bool option;
          (** Defaults to false; preserves formatting unless requested. *)
      range : string;  (** A1 rectangle. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
    }  (** Clear a rectangle's inputs, optionally its formatting too. *)
  | Fill_cells of {
      sheet_id : string;  (** Stable sheet ID or exact name. *)
      source_range : string;  (** Source rectangle. *)
      target_range : string;  (** Target rectangle. *)
    }
      (** Repeat a source rectangle into a target using relative formula translation. *)
  | Add_sheet of {
      name : string;  (** Unique Excel-compatible name, at most 31 characters. *)
    }  (** Add an empty sheet; later operations may address it by this name. *)
  | Rename_sheet of {
      name : string;  (** New unique name. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
    }
      (** Rename a sheet; rejected when existing formulas directly reference its current name. *)
  | Duplicate_sheet of {
      name : string option;  (** Optional unique name for the copy. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
    }  (** Duplicate a sheet, including values, formulas, styles, and layout. *)
  | Delete_sheet of { sheet_id : string  (** Stable sheet ID or exact name. *) }
      (** Delete a sheet; the final sheet and directly referenced sheets are protected. *)
  | Append_rows of {
      count : int;  (** Number of rows to append. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
    }  (** Append rows, up to the 100,000-row sheet limit. *)
  | Resize_columns of {
      columns : spreadsheet_column_width list;  (** Column widths to set. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
    }  (** Resize one or more columns. *)
  | Set_dropdown of {
      colors : spreadsheet_dropdown_color list option;
          (** Optional color per choice, shown as a colored chip in cells and in the open list. With typed items, each must name one of them. *)
      items : string list option;
          (** Typed choices, without commas, at most 253 characters in total. *)
      range : string;  (** A1 rectangle, for example C2:C200. *)
      reject_invalid : bool option;
          (** Defaults to true: reject typed entries that are not a choice. False only suggests the choices. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
      source : string option;
          (** Range holding the choices, for example 'Lists'!A2:A20 or A2:A20 on the same sheet. *)
    }
      (** Add an in-cell dropdown (list data validation) to a rectangle, replacing any validation there.
Give exactly one of items or source. Cell values are unchanged; set them separately. *)
  | Clear_validation of {
      range : string;  (** A1 rectangle. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
    }  (** Remove dropdowns and any other data validation from a rectangle. *)
  | Insert_checkboxes of {
      range : string;  (** A1 rectangle, for example D2:D50. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
    }
      (** Turn a rectangle into checkboxes backed by TRUE/FALSE values: blank cells become FALSE
(unchecked) and other values are kept. Check or uncheck them with set_cells TRUE or FALSE. *)
  | Create_table of {
      column_types : spreadsheet_table_column_type list option;
          (** Column types by header name. A type formats the column's data cells; checkbox makes
them checkboxes and dropdown offers the column's values as colored choices. *)
      name : string option;
          (** Unique table name, such as Sales; spaces become underscores. Defaults to the next free
TableN. *)
      range : string;
          (** A1 rectangle including the header row, for example A1:D20. Must not overlap a table. *)
      sheet_id : string;  (** Stable sheet ID or exact name. *)
      totals_row : bool option;
          (** Add a total row below the data, which must be empty. Defaults to false. *)
    }
      (** Convert a rectangle to a named table (an Excel table). Its first row becomes the header
row; blank or repeated headers are named. Formulas can then use structured references
such as Table1\[Amount\], \[\@Amount\] or Table1 for its data, and each header gets sort and
filter controls. Columns take the type their values suggest unless column_types says. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let spreadsheet_operation_of_yojson : Yojson.Safe.t -> spreadsheet_operation =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "set_cells" ->
      Set_cells
        {
          cells =
            Json.required fields "cells"
              (Json.list spreadsheet_cell_input_of_yojson);
          sheet_id = Json.required fields "sheetId" Json.string;
        }
  | "format_cells" ->
      Format_cells
        {
          range = Json.required fields "range" Json.string;
          sheet_id = Json.required fields "sheetId" Json.string;
          style = Json.required fields "style" spreadsheet_style_of_yojson;
        }
  | "clear_cells" ->
      Clear_cells
        {
          clear_formatting = Json.optional fields "clearFormatting" Json.bool;
          range = Json.required fields "range" Json.string;
          sheet_id = Json.required fields "sheetId" Json.string;
        }
  | "fill_cells" ->
      Fill_cells
        {
          sheet_id = Json.required fields "sheetId" Json.string;
          source_range = Json.required fields "sourceRange" Json.string;
          target_range = Json.required fields "targetRange" Json.string;
        }
  | "add_sheet" -> Add_sheet { name = Json.required fields "name" Json.string }
  | "rename_sheet" ->
      Rename_sheet
        {
          name = Json.required fields "name" Json.string;
          sheet_id = Json.required fields "sheetId" Json.string;
        }
  | "duplicate_sheet" ->
      Duplicate_sheet
        {
          name = Json.optional fields "name" Json.string;
          sheet_id = Json.required fields "sheetId" Json.string;
        }
  | "delete_sheet" ->
      Delete_sheet { sheet_id = Json.required fields "sheetId" Json.string }
  | "append_rows" ->
      Append_rows
        {
          count = Json.required fields "count" Json.int;
          sheet_id = Json.required fields "sheetId" Json.string;
        }
  | "resize_columns" ->
      Resize_columns
        {
          columns =
            Json.required fields "columns"
              (Json.list spreadsheet_column_width_of_yojson);
          sheet_id = Json.required fields "sheetId" Json.string;
        }
  | "set_dropdown" ->
      Set_dropdown
        {
          colors =
            Json.optional fields "colors"
              (Json.list spreadsheet_dropdown_color_of_yojson);
          items = Json.optional fields "items" (Json.list Json.string);
          range = Json.required fields "range" Json.string;
          reject_invalid = Json.optional fields "rejectInvalid" Json.bool;
          sheet_id = Json.required fields "sheetId" Json.string;
          source = Json.optional fields "source" Json.string;
        }
  | "clear_validation" ->
      Clear_validation
        {
          range = Json.required fields "range" Json.string;
          sheet_id = Json.required fields "sheetId" Json.string;
        }
  | "insert_checkboxes" ->
      Insert_checkboxes
        {
          range = Json.required fields "range" Json.string;
          sheet_id = Json.required fields "sheetId" Json.string;
        }
  | "create_table" ->
      Create_table
        {
          column_types =
            Json.optional fields "columnTypes"
              (Json.list spreadsheet_table_column_type_of_yojson);
          name = Json.optional fields "name" Json.string;
          range = Json.required fields "range" Json.string;
          sheet_id = Json.required fields "sheetId" Json.string;
          totals_row = Json.optional fields "totalsRow" Json.bool;
        }
  | _ -> Unknown json

and yojson_of_spreadsheet_operation : spreadsheet_operation -> Yojson.Safe.t =
 fun value ->
  match value with
  | Set_cells case ->
      Json.record
        [
          ("type", Some (`String "set_cells"));
          ( "cells",
            Some ((Json.of_list yojson_of_spreadsheet_cell_input) case.cells) );
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Format_cells case ->
      Json.record
        [
          ("type", Some (`String "format_cells"));
          ("range", Some (Json.of_string case.range));
          ("sheetId", Some (Json.of_string case.sheet_id));
          ("style", Some (yojson_of_spreadsheet_style case.style));
        ]
  | Clear_cells case ->
      Json.record
        [
          ("type", Some (`String "clear_cells"));
          ("clearFormatting", Option.map Json.of_bool case.clear_formatting);
          ("range", Some (Json.of_string case.range));
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Fill_cells case ->
      Json.record
        [
          ("type", Some (`String "fill_cells"));
          ("sheetId", Some (Json.of_string case.sheet_id));
          ("sourceRange", Some (Json.of_string case.source_range));
          ("targetRange", Some (Json.of_string case.target_range));
        ]
  | Add_sheet case ->
      Json.record
        [
          ("type", Some (`String "add_sheet"));
          ("name", Some (Json.of_string case.name));
        ]
  | Rename_sheet case ->
      Json.record
        [
          ("type", Some (`String "rename_sheet"));
          ("name", Some (Json.of_string case.name));
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Duplicate_sheet case ->
      Json.record
        [
          ("type", Some (`String "duplicate_sheet"));
          ("name", Option.map Json.of_string case.name);
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Delete_sheet case ->
      Json.record
        [
          ("type", Some (`String "delete_sheet"));
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Append_rows case ->
      Json.record
        [
          ("type", Some (`String "append_rows"));
          ("count", Some (Json.of_int case.count));
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Resize_columns case ->
      Json.record
        [
          ("type", Some (`String "resize_columns"));
          ( "columns",
            Some
              ((Json.of_list yojson_of_spreadsheet_column_width) case.columns)
          );
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Set_dropdown case ->
      Json.record
        [
          ("type", Some (`String "set_dropdown"));
          ( "colors",
            Option.map
              (Json.of_list yojson_of_spreadsheet_dropdown_color)
              case.colors );
          ("items", Option.map (Json.of_list Json.of_string) case.items);
          ("range", Some (Json.of_string case.range));
          ("rejectInvalid", Option.map Json.of_bool case.reject_invalid);
          ("sheetId", Some (Json.of_string case.sheet_id));
          ("source", Option.map Json.of_string case.source);
        ]
  | Clear_validation case ->
      Json.record
        [
          ("type", Some (`String "clear_validation"));
          ("range", Some (Json.of_string case.range));
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Insert_checkboxes case ->
      Json.record
        [
          ("type", Some (`String "insert_checkboxes"));
          ("range", Some (Json.of_string case.range));
          ("sheetId", Some (Json.of_string case.sheet_id));
        ]
  | Create_table case ->
      Json.record
        [
          ("type", Some (`String "create_table"));
          ( "columnTypes",
            Option.map
              (Json.of_list yojson_of_spreadsheet_table_column_type)
              case.column_types );
          ("name", Option.map Json.of_string case.name);
          ("range", Some (Json.of_string case.range));
          ("sheetId", Some (Json.of_string case.sheet_id));
          ("totalsRow", Option.map Json.of_bool case.totals_row);
        ]
  | Unknown json -> json

let make_spreadsheet_operation_set_cells ~(cells : spreadsheet_cell_input list)
    ~(sheet_id : string) () =
  (Set_cells { cells; sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_format_cells ~(range : string)
    ~(sheet_id : string) ~(style : spreadsheet_style) () =
  (Format_cells { range; sheet_id; style } : spreadsheet_operation)

let make_spreadsheet_operation_clear_cells ?clear_formatting ~(range : string)
    ~(sheet_id : string) () =
  (Clear_cells { clear_formatting; range; sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_fill_cells ~(sheet_id : string)
    ~(source_range : string) ~(target_range : string) () =
  (Fill_cells { sheet_id; source_range; target_range } : spreadsheet_operation)

let make_spreadsheet_operation_add_sheet ~(name : string) () =
  (Add_sheet { name } : spreadsheet_operation)

let make_spreadsheet_operation_rename_sheet ~(name : string)
    ~(sheet_id : string) () =
  (Rename_sheet { name; sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_duplicate_sheet ?name ~(sheet_id : string) () =
  (Duplicate_sheet { name; sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_delete_sheet ~(sheet_id : string) () =
  (Delete_sheet { sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_append_rows ~(count : int) ~(sheet_id : string)
    () =
  (Append_rows { count; sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_resize_columns
    ~(columns : spreadsheet_column_width list) ~(sheet_id : string) () =
  (Resize_columns { columns; sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_set_dropdown ?colors ?items ~(range : string)
    ?reject_invalid ~(sheet_id : string) ?source () =
  (Set_dropdown { colors; items; range; reject_invalid; sheet_id; source }
    : spreadsheet_operation)

let make_spreadsheet_operation_clear_validation ~(range : string)
    ~(sheet_id : string) () =
  (Clear_validation { range; sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_insert_checkboxes ~(range : string)
    ~(sheet_id : string) () =
  (Insert_checkboxes { range; sheet_id } : spreadsheet_operation)

let make_spreadsheet_operation_create_table ?column_types ?name
    ~(range : string) ~(sheet_id : string) ?totals_row () =
  (Create_table { column_types; name; range; sheet_id; totals_row }
    : spreadsheet_operation)

type nonrec edit_spreadsheet_request = {
  expected_revision : string;
      (** The revision a read returned; a changed workbook rejects the batch. *)
  operations : spreadsheet_operation list;
      (** Between 1 and 25 operations, validated and saved together. *)
}
(** One atomic batch of operations against the revision it was planned on. *)

let edit_spreadsheet_request_of_yojson :
    Yojson.Safe.t -> edit_spreadsheet_request =
 fun json ->
  let fields = Json.obj json in
  {
    expected_revision = Json.required fields "expectedRevision" Json.string;
    operations =
      Json.required fields "operations"
        (Json.list spreadsheet_operation_of_yojson);
  }

and yojson_of_edit_spreadsheet_request :
    edit_spreadsheet_request -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("expectedRevision", Some (Json.of_string value.expected_revision));
      ( "operations",
        Some ((Json.of_list yojson_of_spreadsheet_operation) value.operations)
      );
    ]

let make_edit_spreadsheet_request ~(expected_revision : string)
    ~(operations : spreadsheet_operation list) () =
  ({ expected_revision; operations } : edit_spreadsheet_request)

