    Yojson.Safe.t -> email_reminder_condition =
 fun json ->
  match Json.string json with
  | "if_no_reply" -> If_no_reply
  | "regardless" -> Regardless
  | other -> Unknown other

and yojson_of_email_reminder_condition :
    email_reminder_condition -> Yojson.Safe.t =
 fun value ->
  match value with
  | If_no_reply -> `String "if_no_reply"
  | Regardless -> `String "regardless"
  | Unknown other -> `String other

(** Durable progress of an email operation. *)
