  match Json.string json with
  | "archiving" -> Archiving
  | "pending" -> Pending
  | "returning" -> Returning
  | "returned" -> Returned
  | "cancelled" -> Cancelled
  | "removed" -> Removed
  | other -> Unknown other

and yojson_of_followup_state : followup_state -> Yojson.Safe.t =
 fun value ->
  match value with
  | Archiving -> `String "archiving"
  | Pending -> `String "pending"
  | Returning -> `String "returning"
  | Returned -> `String "returned"
  | Cancelled -> `String "cancelled"
  | Removed -> `String "removed"
  | Unknown other -> `String other

type nonrec email_followup = {
  condition : email_reminder_condition;
      (** Condition, defaulting to no reply for new follow-ups. *)
  link_id : string;  (** Canonical owned/delegated inbox. *)
  remind_at : string;  (** Confirmed schedule. *)
  reminder_id : string;  (** Identity of the snooze and its delivery records. *)
  revision : string;
      (** Last accepted operation; edits/removal compare this to prevent stale undo. *)
  state : followup_state;  (** Durable lifecycle progress. *)
  thread_id : string;  (** Conversation identity. *)
}
(** Public status shown on email and in the Reminders editor. *)

let email_followup_of_yojson : Yojson.Safe.t -> email_followup =
