      Json.required fields "condition" email_reminder_condition_of_yojson;
    link_id = Json.required fields "linkId" Json.string;
    remind_at = Json.required fields "remindAt" Json.string;
    reminder_id = Json.required fields "reminderId" Json.string;
    revision = Json.required fields "revision" Json.string;
    state = Json.required fields "state" followup_state_of_yojson;
    thread_id = Json.required fields "threadId" Json.string;
  }

and yojson_of_email_followup : email_followup -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("condition", Some (yojson_of_email_reminder_condition value.condition));
      ("linkId", Some (Json.of_string value.link_id));
      ("remindAt", Some (Json.of_string value.remind_at));
      ("reminderId", Some (Json.of_string value.reminder_id));
      ("revision", Some (Json.of_string value.revision));
      ("state", Some (yojson_of_followup_state value.state));
      ("threadId", Some (Json.of_string value.thread_id));
    ]

let make_email_followup ~(condition : email_reminder_condition)
    ~(link_id : string) ~(remind_at : string) ~(reminder_id : string)
    ~(revision : string) ~(state : followup_state) ~(thread_id : string) () =
  ({ condition; link_id; remind_at; reminder_id; revision; state; thread_id }
    : email_followup)

(** Idempotent email command. Reusing an operation ID with different data fails. *)
type nonrec email_followup_command =
  | Set of {
      condition : email_reminder_condition;  (** Reply condition. *)
      expected_revision : string option;
          (** None for creation, the current revision for edits. *)
      operation_id : string;
          (** Unique request identity retained across network retries. *)
      remind_at : string;
          (** One future instant; conditional recurrence is deliberately absent. *)
    }
      (** Create or edit one follow-up. An edit requires the displayed revision. *)
  | Remove of {
      expected_revision : string;
          (** Reject removal if a newer edit has replaced this operation. *)
      operation_id : string;  (** Unique request identity. *)
      undo : bool option;
          (** Undo restores original visibility; ordinary Remove returns to inbox. *)
    }
      (** Cancel and restore the conversation without leaving a future alert. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let email_followup_command_of_yojson : Yojson.Safe.t -> email_followup_command =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "set" ->
      Set
        {
          condition =
            Json.required fields "condition" email_reminder_condition_of_yojson;
          expected_revision =
            Json.optional fields "expectedRevision" Json.string;
          operation_id = Json.required fields "operationId" Json.string;
          remind_at = Json.required fields "remindAt" Json.string;
        }
  | "remove" ->
      Remove
        {
          expected_revision =
            Json.required fields "expectedRevision" Json.string;
          operation_id = Json.required fields "operationId" Json.string;
          undo = Json.optional fields "undo" Json.bool;
        }
  | _ -> Unknown json

and yojson_of_email_followup_command : email_followup_command -> Yojson.Safe.t =
 fun value ->
  match value with
  | Set case ->
      Json.record
        [
          ("type", Some (`String "set"));
          ("condition", Some (yojson_of_email_reminder_condition case.condition));
          ("expectedRevision", Option.map Json.of_string case.expected_revision);
          ("operationId", Some (Json.of_string case.operation_id));
          ("remindAt", Some (Json.of_string case.remind_at));
        ]
  | Remove case ->
      Json.record
        [
          ("type", Some (`String "remove"));
          ("expectedRevision", Some (Json.of_string case.expected_revision));
          ("operationId", Some (Json.of_string case.operation_id));
          ("undo", Option.map Json.of_bool case.undo);
        ]
  | Unknown json -> json

let make_email_followup_command_set ~(condition : email_reminder_condition)
    ?expected_revision ~(operation_id : string) ~(remind_at : string) () =
  (Set { condition; expected_revision; operation_id; remind_at }
    : email_followup_command)

let make_email_followup_command_remove ~(expected_revision : string)
    ~(operation_id : string) ?undo () =
  (Remove { expected_revision; operation_id; undo } : email_followup_command)

type nonrec email_followup_response = { followup : email_followup option }
(** Lookup response, including an email with no follow-up yet. *)

let email_followup_response_of_yojson : Yojson.Safe.t -> email_followup_response
    =
