(** One explicit privacy change, avoiding lost updates to whole blocklists. *)
type nonrec email_privacy_change =
  | Set_consent of {
      enabled : bool;
          (** False withdraws this mailbox's CRM contribution without deleting records. *)
      link_id : string option;
          (** Required when enabling; must match the displayed primary connection. *)
    }
      (** Consent covers all available past and future emails in the primary mailbox. *)
  | Add_domain of {
      domain : string;  (** Bare company domain. *)
      scope : email_block_scope;
          (** Which contributions the exclusion affects. *)
    }  (** Add a domain and its subdomains to an exclusion list. *)
  | Remove_domain of {
      domain : string;  (** Bare company domain. *)
      scope : email_block_scope;  (** Which list to edit. *)
    }  (** Remove an exclusion; other exclusions still apply. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let email_privacy_change_of_yojson : Yojson.Safe.t -> email_privacy_change =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "action" with
  | "set_consent" ->
      Set_consent
        {
          enabled = Json.required fields "enabled" Json.bool;
          link_id = Json.optional fields "link_id" Json.string;
        }
  | "add_domain" ->
      Add_domain
        {
          domain = Json.required fields "domain" Json.string;
          scope = Json.required fields "scope" email_block_scope_of_yojson;
        }
  | "remove_domain" ->
      Remove_domain
        {
          domain = Json.required fields "domain" Json.string;
          scope = Json.required fields "scope" email_block_scope_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_email_privacy_change : email_privacy_change -> Yojson.Safe.t =
 fun value ->
  match value with
  | Set_consent case ->
      Json.record
        [
          ("action", Some (`String "set_consent"));
          ("enabled", Some (Json.of_bool case.enabled));
          ("link_id", Option.map Json.of_string case.link_id);
        ]
  | Add_domain case ->
      Json.record
        [
          ("action", Some (`String "add_domain"));
          ("domain", Some (Json.of_string case.domain));
          ("scope", Some (yojson_of_email_block_scope case.scope));
        ]
  | Remove_domain case ->
      Json.record
        [
          ("action", Some (`String "remove_domain"));
          ("domain", Some (Json.of_string case.domain));
          ("scope", Some (yojson_of_email_block_scope case.scope));
        ]
  | Unknown json -> json

let make_email_privacy_change_set_consent ~(enabled : bool) ?link_id () =
  (Set_consent { enabled; link_id } : email_privacy_change)

let make_email_privacy_change_add_domain ~(domain : string)
    ~(scope : email_block_scope) () =
  (Add_domain { domain; scope } : email_privacy_change)

let make_email_privacy_change_remove_domain ~(domain : string)
    ~(scope : email_block_scope) () =
  (Remove_domain { domain; scope } : email_privacy_change)

