(** The role a user has within a team.

Ordered least to most privileged so comparisons reflect access strength. *)
type nonrec team_role =
  | Member
  | Admin
  | Owner
  | Unknown of string  (** A value this SDK version does not know. *)

let team_role_of_yojson : Yojson.Safe.t -> team_role =
 fun json ->
  match Json.string json with
  | "member" -> Member
  | "admin" -> Admin
  | "owner" -> Owner
  | other -> Unknown other

and yojson_of_team_role : team_role -> Yojson.Safe.t =
 fun value ->
  match value with
  | Member -> `String "member"
  | Admin -> `String "admin"
  | Owner -> `String "owner"
  | Unknown other -> `String other

(** A user's permission for an entity, discriminated by entity kind.

Items (documents, chats, projects, threads) use access levels.
Channels use view-only permission or participant roles. *)
type nonrec entity_permission =
  | Access_level of {
      access_level : access_level;  (** The access level the user has. *)
    }
      (** Permission for item-based entities (document, chat, project, thread). *)
  | Channel_view_only
      (** View-only permission for a channel without an active participant role. *)
  | Channel_role of {
      role : participant_role;  (** The role the user has in the channel. *)
    }
      (** Permission for channel-based entities with an active participant role. *)
  | Team_role of { role : team_role  (** The role the user has in the team. *) }
      (** Permission for team-based entities. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let entity_permission_of_yojson : Yojson.Safe.t -> entity_permission =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "access_level" ->
      Access_level
        {
          access_level =
            Json.required fields "access_level" access_level_of_yojson;
        }
  | "channel_view_only" -> Channel_view_only
  | "channel_role" ->
      Channel_role
        { role = Json.required fields "role" participant_role_of_yojson }
  | "team_role" ->
      Team_role { role = Json.required fields "role" team_role_of_yojson }
  | _ -> Unknown json

and yojson_of_entity_permission : entity_permission -> Yojson.Safe.t =
 fun value ->
  match value with
  | Access_level case ->
      Json.record
        [
          ("type", Some (`String "access_level"));
          ("access_level", Some (yojson_of_access_level case.access_level));
        ]
  | Channel_view_only ->
      Json.record [ ("type", Some (`String "channel_view_only")) ]
  | Channel_role case ->
      Json.record
        [
          ("type", Some (`String "channel_role"));
          ("role", Some (yojson_of_participant_role case.role));
        ]
  | Team_role case ->
      Json.record
        [
          ("type", Some (`String "team_role"));
          ("role", Some (yojson_of_team_role case.role));
        ]
  | Unknown json -> json

let make_entity_permission_access_level ~(access_level : access_level) () =
  (Access_level { access_level } : entity_permission)

let make_entity_permission_channel_role ~(role : participant_role) () =
  (Channel_role { role } : entity_permission)

let make_entity_permission_team_role ~(role : team_role) () =
  (Team_role { role } : entity_permission)

(** API response envelope for entity permissions. *)
type nonrec entity_permission_response =
  | Access of { permission : entity_permission }
  | No_access
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let entity_permission_response_of_yojson :
    Yojson.Safe.t -> entity_permission_response =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "status" with
  | "access" ->
      Access
        {
          permission =
            Json.required fields "permission" entity_permission_of_yojson;
        }
  | "no_access" -> No_access
  | _ -> Unknown json

and yojson_of_entity_permission_response :
    entity_permission_response -> Yojson.Safe.t =
 fun value ->
  match value with
  | Access case ->
      Json.record
        [
          ("status", Some (`String "access"));
          ("permission", Some (yojson_of_entity_permission case.permission));
        ]
  | No_access -> Json.record [ ("status", Some (`String "no_access")) ]
  | Unknown json -> json

let make_entity_permission_response_access ~(permission : entity_permission) ()
    =
  (Access { permission } : entity_permission_response)

