(** Structured content of a message besides its body. *)
type nonrec external_chat_rich_content =
  | Poll of external_chat_poll  (** A poll with current votes. *)
  | Location of external_chat_location
      (** A place (or the start of a live location); link to a maps URL. *)
  | Contacts of external_chat_contacts  (** Contact cards. *)
  | Event of external_chat_event  (** An event invitation. *)
  | System of external_chat_system_line  (** A system line. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let external_chat_rich_content_of_yojson :
    Yojson.Safe.t -> external_chat_rich_content =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "poll" -> Poll (external_chat_poll_of_yojson json)
  | "location" -> Location (external_chat_location_of_yojson json)
  | "contacts" -> Contacts (external_chat_contacts_of_yojson json)
  | "event" -> Event (external_chat_event_of_yojson json)
  | "system" -> System (external_chat_system_line_of_yojson json)
  | _ -> Unknown json

and yojson_of_external_chat_rich_content :
    external_chat_rich_content -> Yojson.Safe.t =
 fun value ->
  match value with
  | Poll inner ->
      Json.with_tag "type" "poll" (yojson_of_external_chat_poll inner)
  | Location inner ->
      Json.with_tag "type" "location" (yojson_of_external_chat_location inner)
  | Contacts inner ->
      Json.with_tag "type" "contacts" (yojson_of_external_chat_contacts inner)
  | Event inner ->
      Json.with_tag "type" "event" (yojson_of_external_chat_event inner)
  | System inner ->
      Json.with_tag "type" "system" (yojson_of_external_chat_system_line inner)
  | Unknown json -> json

