(** Content of a deliberate send. *)
type nonrec external_chat_reply_content =
  | Text of {
      mentions : string list option;
          (** Group participants the text \@-mentions, by their WhatsApp id
([jid] of a roster participant); the text must contain
[@<digits before the @ of the id>] for each. *)
      text : string;  (** UTF-8 text, at most \[[TEXT_LIMIT_BYTES]\] bytes. *)
    }  (** Plain text. *)
  | Media of {
      caption : string option;  (** Optional caption; audio has none. *)
      upload_id : string;
          (** The staged upload, imported as the message's static file. *)
    }  (** One attachment staged through the attachments route. *)
  | Mutation of {
      message_id : string;
          (** Existing message, resolved to its provider source by the server. *)
      operation : external_chat_mutation;  (** Explicit operation. *)
      text : string option;
          (** Replacement text or emoji; absent for delete, empty to remove a reaction. *)
    }  (** An operation on an existing message in this chat. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let external_chat_reply_content_of_yojson :
    Yojson.Safe.t -> external_chat_reply_content =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "text" ->
      Text
        {
          mentions = Json.optional fields "mentions" (Json.list Json.string);
          text = Json.required fields "text" Json.string;
        }
  | "media" ->
      Media
        {
          caption = Json.optional fields "caption" Json.string;
          upload_id = Json.required fields "uploadId" Json.string;
        }
  | "mutation" ->
      Mutation
        {
          message_id = Json.required fields "messageId" Json.string;
          operation =
            Json.required fields "operation" external_chat_mutation_of_yojson;
          text = Json.optional fields "text" Json.string;
        }
  | _ -> Unknown json

and yojson_of_external_chat_reply_content :
    external_chat_reply_content -> Yojson.Safe.t =
 fun value ->
  match value with
  | Text case ->
      Json.record
        [
          ("type", Some (`String "text"));
          ("mentions", Option.map (Json.of_list Json.of_string) case.mentions);
          ("text", Some (Json.of_string case.text));
        ]
  | Media case ->
      Json.record
        [
          ("type", Some (`String "media"));
          ("caption", Option.map Json.of_string case.caption);
          ("uploadId", Some (Json.of_string case.upload_id));
        ]
  | Mutation case ->
      Json.record
        [
          ("type", Some (`String "mutation"));
          ("messageId", Some (Json.of_string case.message_id));
          ("operation", Some (yojson_of_external_chat_mutation case.operation));
          ("text", Option.map Json.of_string case.text);
        ]
  | Unknown json -> json

let make_external_chat_reply_content_text ?mentions ~(text : string) () =
  (Text { mentions; text } : external_chat_reply_content)

let make_external_chat_reply_content_media ?caption ~(upload_id : string) () =
  (Media { caption; upload_id } : external_chat_reply_content)

let make_external_chat_reply_content_mutation ~(message_id : string)
    ~(operation : external_chat_mutation) ?text () =
  (Mutation { message_id; operation; text } : external_chat_reply_content)

