type nonrec favorite = {
  channel_id : string option;
      (** Owning channel id of the favorited channel message, when applicable. *)
  channel_type : string option;
      (** Channel type (e.g. [public], [direct_message]) of the favorited channel, when applicable. *)
  created_at : string;  (** When the favorite was created. *)
  document_sub_type : string option;
      (** Document sub type (e.g. [task]) of the favorited document, when applicable. *)
  entity_id : string;  (** The id of the favorited entity. *)
  entity_type : favorite_entity_type;  (** The type of the favorited entity. *)
  file_type : string option;
      (** File type of the favorited document, when applicable. *)
  sort_order : float;  (** Manual ordering value; lower sorts first. *)
}
(** A single favorited entity, including display metadata hydrated from the
favorited entity where available. Display names are deliberately not
included: clients resolve them from the entity previews pipeline, which
is viewer-relative for DM channels and updated by renames.

A favorite is identified by [(entity_type, entity_id)] within the user's
collection; there is no surrogate id. *)

let favorite_of_yojson : Yojson.Safe.t -> favorite =
 fun json ->
  let fields = Json.obj json in
  {
    channel_id = Json.optional fields "channelId" Json.string;
    channel_type = Json.optional fields "channelType" Json.string;
    created_at = Json.required fields "createdAt" Json.string;
    document_sub_type = Json.optional fields "documentSubType" Json.string;
    entity_id = Json.required fields "entityId" Json.string;
    entity_type =
      Json.required fields "entityType" favorite_entity_type_of_yojson;
    file_type = Json.optional fields "fileType" Json.string;
    sort_order = Json.required fields "sortOrder" Json.float;
  }

and yojson_of_favorite : favorite -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("channelId", Option.map Json.of_string value.channel_id);
      ("channelType", Option.map Json.of_string value.channel_type);
      ("createdAt", Some (Json.of_string value.created_at));
      ("documentSubType", Option.map Json.of_string value.document_sub_type);
      ("entityId", Some (Json.of_string value.entity_id));
      ("entityType", Some (yojson_of_favorite_entity_type value.entity_type));
      ("fileType", Option.map Json.of_string value.file_type);
      ("sortOrder", Some (Json.of_float value.sort_order));
    ]

let make_favorite ?channel_id ?channel_type ~(created_at : string)
    ?document_sub_type ~(entity_id : string)
    ~(entity_type : favorite_entity_type) ?file_type ~(sort_order : float) () =
  ({
     channel_id;
     channel_type;
     created_at;
     document_sub_type;
     entity_id;
     entity_type;
     file_type;
     sort_order;
   }
    : favorite)

