type file_system_node_with_ids =
  | File of { document_id : string; item : folder_item }
  | Folder of {
      content : (string * file_system_node_with_ids) list;
      project_id : string;
    }
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let rec file_system_node_with_ids_of_yojson :
    Yojson.Safe.t -> file_system_node_with_ids =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "file" ->
      File
        {
          document_id = Json.required fields "document_id" Json.string;
          item = Json.required fields "item" folder_item_of_yojson;
        }
  | "folder" ->
      Folder
        {
          content =
            Json.required fields "content"
              (Json.map file_system_node_with_ids_of_yojson);
          project_id = Json.required fields "project_id" Json.string;
        }
  | _ -> Unknown json

and yojson_of_file_system_node_with_ids :
    file_system_node_with_ids -> Yojson.Safe.t =
 fun value ->
  match value with
  | File case ->
      Json.record
        [
          ("type", Some (`String "file"));
          ("document_id", Some (Json.of_string case.document_id));
          ("item", Some (yojson_of_folder_item case.item));
        ]
  | Folder case ->
      Json.record
        [
          ("type", Some (`String "folder"));
          ( "content",
            Some
              ((Json.of_map yojson_of_file_system_node_with_ids) case.content)
          );
          ("project_id", Some (Json.of_string case.project_id));
        ]
  | Unknown json -> json

let make_file_system_node_with_ids_file ~(document_id : string)
    ~(item : folder_item) () =
  (File { document_id; item } : file_system_node_with_ids)

let make_file_system_node_with_ids_folder
    ~(content : (string * file_system_node_with_ids) list)
    ~(project_id : string) () =
  (Folder { content; project_id } : file_system_node_with_ids)

