type nonrec form = {
  anonymous : bool;
      (** Whether nobody, the owner included, can see who gave which response.
Who responded is kept apart from the responses, only so nobody
responds twice. Fixed once anyone has responded. *)
  appearance : entity_appearance option;
  audience : audience;  (** Who may respond. *)
  branding : form_branding;  (** Its logo, cover image and accent color. *)
  closes_at : string option;  (** When it stops taking responses, if it does. *)
  confirmation_message : string;
      (** What a respondent reads once their response is saved; empty for the
default. *)
  created_at : string;  (** When it was created. *)
  database_id : string;  (** The database holding its responses. *)
  description : string;  (** What respondents read under the name. *)
  id : string;  (** The form. *)
  is_hidden_in_drive : bool;
      (** Whether Drive leaves it, and the database behind it, out of its
listings, as for a channel poll. *)
  name : string;
      (** Its display name. A standalone form follows the database it created;
a form attached to an existing table has its own name. *)
  owner_id : string;  (** Its owner. *)
  project_id : string option;
      (** The folder it is filed in; [null] at the root. *)
  respondent_column_id : string option;
      (** The person column each signed-in submission names its respondent in;
[null] once deleted, and on a form created anonymous. An anonymous
form never writes it. *)
  responses_visible : bool;
      (** Whether people with View may read individual response rows. *)
  status : form_status;  (** Whether its owner closed it. *)
  submitted_column_id : string option;
      (** The date column each submission stamps; [null] once deleted. *)
  table_id : string;  (** The table whose rows are its responses. *)
  tally_visible : bool;  (** Whether respondents may read option tallies. *)
  updated_at : string;  (** When its facts or layout last changed. *)
}
(** A form: a view of one database table whose rows are its responses. *)

let form_of_yojson : Yojson.Safe.t -> form =
 fun json ->
  let fields = Json.obj json in
  {
    anonymous = Json.required fields "anonymous" Json.bool;
    appearance = Json.optional fields "appearance" entity_appearance_of_yojson;
    audience = Json.required fields "audience" audience_of_yojson;
    branding = Json.required fields "branding" form_branding_of_yojson;
    closes_at = Json.optional fields "closesAt" Json.string;
    confirmation_message =
      Json.required fields "confirmationMessage" Json.string;
    created_at = Json.required fields "createdAt" Json.string;
    database_id = Json.required fields "databaseId" Json.string;
    description = Json.required fields "description" Json.string;
    id = Json.required fields "id" Json.string;
    is_hidden_in_drive = Json.required fields "isHiddenInDrive" Json.bool;
    name = Json.required fields "name" Json.string;
    owner_id = Json.required fields "ownerId" Json.string;
    project_id = Json.optional fields "projectId" Json.string;
    respondent_column_id = Json.optional fields "respondentColumnId" Json.string;
    responses_visible = Json.required fields "responsesVisible" Json.bool;
    status = Json.required fields "status" form_status_of_yojson;
    submitted_column_id = Json.optional fields "submittedColumnId" Json.string;
    table_id = Json.required fields "tableId" Json.string;
    tally_visible = Json.required fields "tallyVisible" Json.bool;
    updated_at = Json.required fields "updatedAt" Json.string;
  }

and yojson_of_form : form -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("anonymous", Some (Json.of_bool value.anonymous));
      ("appearance", Option.map yojson_of_entity_appearance value.appearance);
      ("audience", Some (yojson_of_audience value.audience));
      ("branding", Some (yojson_of_form_branding value.branding));
      ("closesAt", Some ((Json.of_option Json.of_string) value.closes_at));
      ("confirmationMessage", Some (Json.of_string value.confirmation_message));
      ("createdAt", Some (Json.of_string value.created_at));
      ("databaseId", Some (Json.of_string value.database_id));
      ("description", Some (Json.of_string value.description));
      ("id", Some (Json.of_string value.id));
      ("isHiddenInDrive", Some (Json.of_bool value.is_hidden_in_drive));
      ("name", Some (Json.of_string value.name));
      ("ownerId", Some (Json.of_string value.owner_id));
      ("projectId", Some ((Json.of_option Json.of_string) value.project_id));
      ( "respondentColumnId",
        Some ((Json.of_option Json.of_string) value.respondent_column_id) );
      ("responsesVisible", Some (Json.of_bool value.responses_visible));
      ("status", Some (yojson_of_form_status value.status));
      ( "submittedColumnId",
        Some ((Json.of_option Json.of_string) value.submitted_column_id) );
      ("tableId", Some (Json.of_string value.table_id));
      ("tallyVisible", Some (Json.of_bool value.tally_visible));
      ("updatedAt", Some (Json.of_string value.updated_at));
    ]

