(** One section of a form as it reads. *)
type nonrec form_section_detail =
  | Questions of {
      description : string;  (** Its description. *)
      id : string;  (** The section. *)
      questions : form_question_detail list;  (** Its questions, in order. *)
      show_when : filter_group option;
          (** When to show it, from earlier shown sections' answers; absent,
it is always shown. Sent to every caller so a respondent's page
can skip it. *)
      title : string;  (** Its title. *)
    }  (** Questions asked together. *)
  | Gate of {
      description : string;  (** Its description. *)
      id : string;  (** The section. *)
      message : string;  (** What a stopped respondent reads. *)
      rules : filter_group;  (** The rules. *)
      title : string;  (** Its title. *)
    }
      (** A check of earlier answers. The rules are sent to every caller so a
respondent's page can stop them before submitting; respondents are
never shown them. *)
  | Booking of {
      description : string;  (** Its description. *)
      id : string;  (** The section. *)
      target : booking_target option;
          (** Editors can configure the destination; respondent layouts omit it. *)
