(** Why a layout does not fit the form's table. *)
type nonrec layout_problem =
  | Booking_must_be_last
      (** A booking step must be unique and follow all questions and gates. *)
  | Unknown_column of { column : string  (** The column. *) }
      (** A question names a column the form's table does not have. *)
  | Managed_column of { column : string  (** The column. *) }
      (** A question names a column the form writes itself. *)
  | Repeated_column of { column : string  (** The column. *) }
      (** Two questions name one column. *)
  | Repeated_id of { id : string  (** The id. *) }
      (** Two sections or questions share an id. *)
  | Gate_names_later_column of { column : string  (** The column. *) }
      (** A gate tests a column no earlier section asks. *)
  | Gate_rule of { reason : string  (** Why. *) }
      (** A gate's rule does not fit its column. *)
  | Condition_names_later_column of { column : string  (** The column. *) }
      (** A section's show-when rules test a column no earlier section asks. *)
  | Condition_rule of { reason : string  (** Why. *) }
      (** A section's show-when rule does not fit its column. *)
  | Text_too_long of { max : int  (** The longest allowed. *) }
      (** A text is longer than allowed. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let layout_problem_of_yojson : Yojson.Safe.t -> layout_problem =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "bookingMustBeLast" -> Booking_must_be_last
  | "unknownColumn" ->
      Unknown_column { column = Json.required fields "column" Json.string }
  | "managedColumn" ->
      Managed_column { column = Json.required fields "column" Json.string }
  | "repeatedColumn" ->
      Repeated_column { column = Json.required fields "column" Json.string }
  | "repeatedId" -> Repeated_id { id = Json.required fields "id" Json.string }
  | "gateNamesLaterColumn" ->
      Gate_names_later_column
        { column = Json.required fields "column" Json.string }
  | "gateRule" ->
      Gate_rule { reason = Json.required fields "reason" Json.string }
  | "conditionNamesLaterColumn" ->
      Condition_names_later_column
        { column = Json.required fields "column" Json.string }
  | "conditionRule" ->
      Condition_rule { reason = Json.required fields "reason" Json.string }
  | "textTooLong" -> Text_too_long { max = Json.required fields "max" Json.int }
  | _ -> Unknown json

and yojson_of_layout_problem : layout_problem -> Yojson.Safe.t =
 fun value ->
  match value with
  | Booking_must_be_last ->
      Json.record [ ("kind", Some (`String "bookingMustBeLast")) ]
  | Unknown_column case ->
      Json.record
        [
          ("kind", Some (`String "unknownColumn"));
          ("column", Some (Json.of_string case.column));
        ]
  | Managed_column case ->
      Json.record
        [
          ("kind", Some (`String "managedColumn"));
          ("column", Some (Json.of_string case.column));
        ]
  | Repeated_column case ->
      Json.record
        [
          ("kind", Some (`String "repeatedColumn"));
          ("column", Some (Json.of_string case.column));
        ]
  | Repeated_id case ->
      Json.record
        [
          ("kind", Some (`String "repeatedId"));
          ("id", Some (Json.of_string case.id));
        ]
  | Gate_names_later_column case ->
      Json.record
        [
          ("kind", Some (`String "gateNamesLaterColumn"));
          ("column", Some (Json.of_string case.column));
        ]
  | Gate_rule case ->
      Json.record
        [
          ("kind", Some (`String "gateRule"));
          ("reason", Some (Json.of_string case.reason));
        ]
  | Condition_names_later_column case ->
      Json.record
        [
          ("kind", Some (`String "conditionNamesLaterColumn"));
          ("column", Some (Json.of_string case.column));
        ]
  | Condition_rule case ->
      Json.record
        [
          ("kind", Some (`String "conditionRule"));
          ("reason", Some (Json.of_string case.reason));
        ]
  | Text_too_long case ->
      Json.record
        [
          ("kind", Some (`String "textTooLong"));
          ("max", Some (Json.of_int case.max));
        ]
  | Unknown json -> json

let make_layout_problem_unknown_column ~(column : string) () =
  (Unknown_column { column } : layout_problem)

let make_layout_problem_managed_column ~(column : string) () =
  (Managed_column { column } : layout_problem)

let make_layout_problem_repeated_column ~(column : string) () =
  (Repeated_column { column } : layout_problem)

let make_layout_problem_repeated_id ~(id : string) () =
