let make_layout_problem_gate_rule ~(reason : string) () =
  (Gate_rule { reason } : layout_problem)

let make_layout_problem_condition_names_later_column ~(column : string) () =
  (Condition_names_later_column { column } : layout_problem)

let make_layout_problem_condition_rule ~(reason : string) () =
  (Condition_rule { reason } : layout_problem)

let make_layout_problem_text_too_long ~(max : int) () =
  (Text_too_long { max } : layout_problem)

(** An editor's saved draft is not yet the version respondents can use. *)
type nonrec form_publication_problem =
  | Invalid_draft
      (** The draft contains unsupported or malformed layout records. An explicit
layout replacement can repair it without replacing its document history. *)
  | Layout of {
      problem : layout_problem;  (** The invariant the editor needs to repair. *)
    }  (** The layout violates a form invariant. *)
  | Widget_mismatch of { question : string  (** The question to repair. *) }
      (** A question's widget no longer fits its column. *)
  | File_upload_needs_sign_in
      (** File questions require a signed-in audience. *)
  | Pending
      (** The draft was saved, but publication could not finish. Reading the
collaboration endpoint retries publication; do not repeat the write. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let form_publication_problem_of_yojson :
    Yojson.Safe.t -> form_publication_problem =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "invalidDraft" -> Invalid_draft
  | "layout" ->
      Layout
        { problem = Json.required fields "problem" layout_problem_of_yojson }
  | "widgetMismatch" ->
      Widget_mismatch { question = Json.required fields "question" Json.string }
  | "fileUploadNeedsSignIn" -> File_upload_needs_sign_in
  | "pending" -> Pending
  | _ -> Unknown json

and yojson_of_form_publication_problem :
    form_publication_problem -> Yojson.Safe.t =
 fun value ->
  match value with
  | Invalid_draft -> Json.record [ ("kind", Some (`String "invalidDraft")) ]
  | Layout case ->
      Json.record
        [
          ("kind", Some (`String "layout"));
          ("problem", Some (yojson_of_layout_problem case.problem));
        ]
  | Widget_mismatch case ->
      Json.record
        [
          ("kind", Some (`String "widgetMismatch"));
          ("question", Some (Json.of_string case.question));
        ]
  | File_upload_needs_sign_in ->
      Json.record [ ("kind", Some (`String "fileUploadNeedsSignIn")) ]
  | Pending -> Json.record [ ("kind", Some (`String "pending")) ]
  | Unknown json -> json

let make_form_publication_problem_layout ~(problem : layout_problem) () =
  (Layout { problem } : form_publication_problem)

let make_form_publication_problem_widget_mismatch ~(question : string) () =
  (Widget_mismatch { question } : form_publication_problem)

type nonrec form_collaboration = {
  detail : form_detail;
      (** The latest validated form. The form id also identifies its surface. *)
  publication_error : form_publication_problem option;
      (** Why the current draft cannot yet replace the respondent layout.
Only editors can request this result. *)
}
(** A ready collaborative form and the result of publishing its latest draft. *)

let form_collaboration_of_yojson : Yojson.Safe.t -> form_collaboration =
 fun json ->
  let fields = Json.obj json in
  {
    detail = Json.required fields "detail" form_detail_of_yojson;
    publication_error =
      Json.optional fields "publicationError" form_publication_problem_of_yojson;
  }

and yojson_of_form_collaboration : form_collaboration -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("detail", Some (yojson_of_form_detail value.detail));
      ( "publicationError",
        Option.map yojson_of_form_publication_problem value.publication_error );
    ]

let make_form_collaboration ~(detail : form_detail) ?publication_error () =
  ({ detail; publication_error } : form_collaboration)

(** What went wrong with a forms request. *)
type nonrec form_error_code =
  | Table_already_has_form
  | Not_found
  | Forbidden
  | Owner_only
  | Sign_in_required
  | Closed
  | Table_gone
  | Already_responded
  | No_response
  | Anonymous_response_final
  | Unknown_question
  | Repeated_answer
  | Missing_answer
  | Invalid_answer
  | Widget_mismatch
  | File_upload_needs_sign_in
  | Invalid_layout
  | Invalid_name
  | Invalid_sharing
  | Invalid_appearance
  | Tally_hidden
  | Invalid_branding
  | Conflict
  | Internal
  | Unknown of string  (** A value this SDK version does not know. *)

let form_error_code_of_yojson : Yojson.Safe.t -> form_error_code =
 fun json ->
  match Json.string json with
  | "tableAlreadyHasForm" -> Table_already_has_form
  | "notFound" -> Not_found
  | "forbidden" -> Forbidden
  | "ownerOnly" -> Owner_only
  | "signInRequired" -> Sign_in_required
  | "closed" -> Closed
  | "tableGone" -> Table_gone
  | "alreadyResponded" -> Already_responded
  | "noResponse" -> No_response
  | "anonymousResponseFinal" -> Anonymous_response_final
  | "unknownQuestion" -> Unknown_question
  | "repeatedAnswer" -> Repeated_answer
  | "missingAnswer" -> Missing_answer
  | "invalidAnswer" -> Invalid_answer
  | "widgetMismatch" -> Widget_mismatch
  | "fileUploadNeedsSignIn" -> File_upload_needs_sign_in
  | "invalidLayout" -> Invalid_layout
  | "invalidName" -> Invalid_name
  | "invalidSharing" -> Invalid_sharing
  | "invalidAppearance" -> Invalid_appearance
  | "tallyHidden" -> Tally_hidden
  | "invalidBranding" -> Invalid_branding
  | "conflict" -> Conflict
  | "internal" -> Internal
  | other -> Unknown other

and yojson_of_form_error_code : form_error_code -> Yojson.Safe.t =
 fun value ->
  match value with
  | Table_already_has_form -> `String "tableAlreadyHasForm"
  | Not_found -> `String "notFound"
  | Forbidden -> `String "forbidden"
  | Owner_only -> `String "ownerOnly"
  | Sign_in_required -> `String "signInRequired"
  | Closed -> `String "closed"
  | Table_gone -> `String "tableGone"
  | Already_responded -> `String "alreadyResponded"
  | No_response -> `String "noResponse"
  | Anonymous_response_final -> `String "anonymousResponseFinal"
  | Unknown_question -> `String "unknownQuestion"
  | Repeated_answer -> `String "repeatedAnswer"
  | Missing_answer -> `String "missingAnswer"
  | Invalid_answer -> `String "invalidAnswer"
  | Widget_mismatch -> `String "widgetMismatch"
  | File_upload_needs_sign_in -> `String "fileUploadNeedsSignIn"
  | Invalid_layout -> `String "invalidLayout"
  | Invalid_name -> `String "invalidName"
  | Invalid_sharing -> `String "invalidSharing"
  | Invalid_appearance -> `String "invalidAppearance"
  | Tally_hidden -> `String "tallyHidden"
  | Invalid_branding -> `String "invalidBranding"
  | Conflict -> `String "conflict"
  | Internal -> `String "internal"
  | Unknown other -> `String other

