(** One section of a layout: questions on one screen, or a gate the answers
so far must pass. *)
type nonrec form_section =
  | Questions of {
      description : string;  (** What respondents read under the title. *)
      id : string;  (** The section, under an id the client mints. *)
      questions : question_layout list;  (** Its questions, in order. *)
      show_when : filter_group option;
          (** When to show it: the rules answers of earlier shown sections must
pass, naming only their columns. A section whose rules fail is
skipped: its questions are not required and their answers are
not written. Absent, it is always shown. *)
      title : string;  (** Its title; may be empty. *)
    }  (** Questions asked together. *)
  | Gate of {
      description : string;  (** Its description, for editors. *)
      id : string;  (** The section, under an id the client mints. *)
      message : string;  (** What a stopped respondent reads. *)
      rules : filter_group;
          (** The rules, naming only columns asked in earlier sections. *)
      title : string;  (** Its title, for editors. *)
    }
      (** A check of earlier answers: a respondent whose answers fail the rules
is stopped here with the message, and nothing is written. *)
  | Booking of {
      description : string;
          (** What respondents read before choosing a time. *)
      id : string;  (** The section, under an id the client mints. *)
      target : booking_target;
          (** The native booking event. Respondent layouts never include this target. *)
      title : string;  (** Its title. *)
    }
      (** The final step, revealed only after the server accepts the response. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

