 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "questions" ->
      Questions
        {
          description = Json.required fields "description" Json.string;
          id = Json.required fields "id" Json.string;
          questions =
            Json.required fields "questions"
              (Json.list question_layout_of_yojson);
          show_when = Json.optional fields "showWhen" filter_group_of_yojson;
          title = Json.required fields "title" Json.string;
        }
  | "gate" ->
      Gate
        {
          description = Json.required fields "description" Json.string;
          id = Json.required fields "id" Json.string;
          message = Json.required fields "message" Json.string;
          rules = Json.required fields "rules" filter_group_of_yojson;
          title = Json.required fields "title" Json.string;
        }
  | "booking" ->
      Booking
        {
          description = Json.required fields "description" Json.string;
          id = Json.required fields "id" Json.string;
          target = Json.required fields "target" booking_target_of_yojson;
          title = Json.required fields "title" Json.string;
        }
  | _ -> Unknown json

