 fun value ->
  match value with
  | Questions case ->
      Json.record
        [
          ("kind", Some (`String "questions"));
          ("description", Some (Json.of_string case.description));
          ("id", Some (Json.of_string case.id));
          ( "questions",
            Some ((Json.of_list yojson_of_question_layout) case.questions) );
