      (** The row holding the answers; [null] when stopped, or once the row was
deleted from the table. *)
  status : response_status;  (** Saved, or stopped at a gate. *)
  stopped_at_section : string option;  (** The gate that stopped it. *)
  submitted_at : string;  (** When it was first submitted. *)
  updated_at : string;  (** When it last changed. *)
}
(** One entry of a form's submission ledger: who answered, when, and where
the answers went. *)

let form_response_of_yojson : Yojson.Safe.t -> form_response =
 fun json ->
  let fields = Json.obj json in
  {
    form_id = Json.required fields "formId" Json.string;
    id = Json.required fields "id" Json.string;
    row = Json.optional fields "row" Json.string;
    status = Json.required fields "status" response_status_of_yojson;
    stopped_at_section = Json.optional fields "stoppedAtSection" Json.string;
    submitted_at = Json.required fields "submittedAt" Json.string;
    updated_at = Json.required fields "updatedAt" Json.string;
  }

and yojson_of_form_response : form_response -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("formId", Some (Json.of_string value.form_id));
      ("id", Some (Json.of_string value.id));
      ("row", Some ((Json.of_option Json.of_string) value.row));
      ("status", Some (yojson_of_response_status value.status));
      ( "stoppedAtSection",
        Some ((Json.of_option Json.of_string) value.stopped_at_section) );
      ("submittedAt", Some (Json.of_string value.submitted_at));
      ("updatedAt", Some (Json.of_string value.updated_at));
    ]

let make_form_response ~(form_id : string) ~(id : string) ?row
    ~(status : response_status) ?stopped_at_section ~(submitted_at : string)
    ~(updated_at : string) () =
  ({ form_id; id; row; status; stopped_at_section; submitted_at; updated_at }
    : form_response)

(** A value a tally counts. *)
type nonrec tally_value =
  | Option of { option : string  (** The option. *) }
      (** One option of the column. *)
  | Checkbox of { checked : bool  (** Checked, or not. *) }
      (** A checkbox state. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let tally_value_of_yojson : Yojson.Safe.t -> tally_value =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "option" -> Option { option = Json.required fields "option" Json.string }
  | "checkbox" ->
      Checkbox { checked = Json.required fields "checked" Json.bool }
  | _ -> Unknown json

and yojson_of_tally_value : tally_value -> Yojson.Safe.t =
 fun value ->
  match value with
  | Option case ->
      Json.record
        [
          ("kind", Some (`String "option"));
          ("option", Some (Json.of_string case.option));
        ]
  | Checkbox case ->
      Json.record
        [
          ("kind", Some (`String "checkbox"));
          ("checked", Some (Json.of_bool case.checked));
        ]
  | Unknown json -> json

let make_tally_value_option ~(option : string) () =
  (Option { option } : tally_value)

let make_tally_value_checkbox ~(checked : bool) () =
  (Checkbox { checked } : tally_value)

type nonrec tally_bucket = {
  count : int64;  (** How many rows hold it. *)
  value : tally_value;  (** The value. *)
  voters : string list option;
      (** Who chose it, as Macro user ids in submission order: present only
for the form's editors, or its viewers when it shares its responses,
and never when it hides respondents. Rows no signed-in respondent
submitted count without a voter. *)
}
(** How many rows hold one value. *)

let tally_bucket_of_yojson : Yojson.Safe.t -> tally_bucket =
 fun json ->
  let fields = Json.obj json in
  {
    count = Json.required fields "count" Json.int64;
    value = Json.required fields "value" tally_value_of_yojson;
    voters = Json.optional fields "voters" (Json.list Json.string);
  }

and yojson_of_tally_bucket : tally_bucket -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("count", Some (Json.of_int64 value.count));
      ("value", Some (yojson_of_tally_value value.value));
      ("voters", Option.map (Json.of_list Json.of_string) value.voters);
    ]

let make_tally_bucket ~(count : int64) ~(value : tally_value) ?voters () =
  ({ count; value; voters } : tally_bucket)

type nonrec question_tally = {
  buckets : tally_bucket list;
      (** A count per option in the column's order, zeros included; for a
checkbox, checked then unchecked. *)
  question : string;  (** The question. *)
  responses : int64;  (** Rows with a value in its column. *)
}
(** One question's counts. *)

let question_tally_of_yojson : Yojson.Safe.t -> question_tally =
 fun json ->
