    [
      ("buckets", Some ((Json.of_list yojson_of_tally_bucket) value.buckets));
      ("question", Some (Json.of_string value.question));
      ("responses", Some (Json.of_int64 value.responses));
    ]

let make_question_tally ~(buckets : tally_bucket list) ~(question : string)
    ~(responses : int64) () =
