(** What a field holds. *)
type nonrec pipeline_field_type =
  | Company
  | Contact
  | Text
  | Number
  | Checkbox
  | Date
  | Date_range
  | Link
  | Select
  | Tags
  | Person
  | Item
  | Relation
  | Formula
  | Unknown of string  (** A value this SDK version does not know. *)

let pipeline_field_type_of_yojson : Yojson.Safe.t -> pipeline_field_type =
 fun json ->
  match Json.string json with
  | "company" -> Company
  | "contact" -> Contact
  | "text" -> Text
  | "number" -> Number
  | "checkbox" -> Checkbox
  | "date" -> Date
  | "date_range" -> Date_range
  | "link" -> Link
  | "select" -> Select
  | "tags" -> Tags
  | "person" -> Person
  | "item" -> Item
  | "relation" -> Relation
  | "formula" -> Formula
  | other -> Unknown other

and yojson_of_pipeline_field_type : pipeline_field_type -> Yojson.Safe.t =
 fun value ->
  match value with
  | Company -> `String "company"
  | Contact -> `String "contact"
  | Text -> `String "text"
  | Number -> `String "number"
  | Checkbox -> `String "checkbox"
  | Date -> `String "date"
  | Date_range -> `String "date_range"
  | Link -> `String "link"
  | Select -> `String "select"
  | Tags -> `String "tags"
  | Person -> `String "person"
  | Item -> `String "item"
  | Relation -> `String "relation"
  | Formula -> `String "formula"
  | Unknown other -> `String other

type nonrec pipeline_field_summary = {
  currency_field : string option;
      (** For a monetary amount, the field holding each entry's currency code. *)
  multiple : bool;  (** Whether it holds several values. *)
  name : string;  (** The name entries and filters use. *)
  options : string list;
      (** A select or tags field's labels in order: for Stage, the stages from
first to last. *)
  read_only : bool;  (** Whether the caller cannot write it. *)
  required : bool;  (** Whether every entry must have a value. *)
  type_ : pipeline_field_type;  (** What it holds. *)
}
(** One field of a pipeline, named as people see it. *)

let pipeline_field_summary_of_yojson : Yojson.Safe.t -> pipeline_field_summary =
 fun json ->
  let fields = Json.obj json in
  {
    currency_field = Json.optional fields "currencyField" Json.string;
    multiple = Json.required fields "multiple" Json.bool;
    name = Json.required fields "name" Json.string;
    options = Json.required fields "options" (Json.list Json.string);
    read_only = Json.required fields "readOnly" Json.bool;
    required = Json.required fields "required" Json.bool;
    type_ = Json.required fields "type" pipeline_field_type_of_yojson;
  }

and yojson_of_pipeline_field_summary : pipeline_field_summary -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("currencyField", Option.map Json.of_string value.currency_field);
      ("multiple", Some (Json.of_bool value.multiple));
      ("name", Some (Json.of_string value.name));
      ("options", Some ((Json.of_list Json.of_string) value.options));
      ("readOnly", Some (Json.of_bool value.read_only));
      ("required", Some (Json.of_bool value.required));
      ("type", Some (yojson_of_pipeline_field_type value.type_));
    ]

let make_pipeline_field_summary ?currency_field ~(multiple : bool)
    ~(name : string) ~(options : string list) ~(read_only : bool)
    ~(required : bool) ~(type_ : pipeline_field_type) () =
  ({ currency_field; multiple; name; options; read_only; required; type_ }
    : pipeline_field_summary)

type nonrec pipeline_fields = {
  commercial_fields : commercial_fields;
      (** Stable identities for Outcome and amount/currency fields. *)
  created_at : string;  (** Creation time. *)
  database_id : string;  (** Dedicated backing database. *)
  id : string;  (** Entity identity, used with [CrmPipeline] access receipts. *)
  name : string;  (** Pipeline display name. *)
  primary_column_id : string;
      (** A tracked pipeline's protected record reference. A generic pipeline's
Name, which names no column once someone deletes it. *)
  record_type : pipeline_record_type option;
  sharing : pipeline_sharing;  (** Whether the pipeline has a team grant. *)
  table_id : string;  (** Table of entries. *)
  team_id : string;
      (** Team owning the pipeline; references retain their own access controls. *)
  trashed_at : string option;
      (** Trashed pipelines are omitted from navigation. *)
  user_id : string;  (** Owning user; sharing never changes ownership. *)
  grant : access_level;  (** Highest effective access. *)
  fields : pipeline_field_summary list;
      (** Its fields in column order; a tracked pipeline's first names its record. *)
  version : int64;  (** Its table's version when read. *)
}
(** A pipeline with its fields. *)

let pipeline_fields_of_yojson : Yojson.Safe.t -> pipeline_fields =
 fun json ->
  let fields = Json.obj json in
  {
    commercial_fields =
      Json.required fields "commercialFields" commercial_fields_of_yojson;
    created_at = Json.required fields "createdAt" Json.string;
    database_id = Json.required fields "databaseId" Json.string;
    id = Json.required fields "id" Json.string;
    name = Json.required fields "name" Json.string;
    primary_column_id = Json.required fields "primaryColumnId" Json.string;
    record_type =
      Json.optional fields "recordType" pipeline_record_type_of_yojson;
    sharing = Json.required fields "sharing" pipeline_sharing_of_yojson;
    table_id = Json.required fields "tableId" Json.string;
    team_id = Json.required fields "teamId" Json.string;
    trashed_at = Json.optional fields "trashedAt" Json.string;
    user_id = Json.required fields "userId" Json.string;
    grant = Json.required fields "grant" access_level_of_yojson;
    fields =
      Json.required fields "fields" (Json.list pipeline_field_summary_of_yojson);
    version = Json.required fields "version" Json.int64;
  }

and yojson_of_pipeline_fields : pipeline_fields -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "commercialFields",
        Some (yojson_of_commercial_fields value.commercial_fields) );
      ("createdAt", Some (Json.of_string value.created_at));
      ("databaseId", Some (Json.of_string value.database_id));
      ("id", Some (Json.of_string value.id));
      ("name", Some (Json.of_string value.name));
      ("primaryColumnId", Some (Json.of_string value.primary_column_id));
      ( "recordType",
        Some ((Json.of_option yojson_of_pipeline_record_type) value.record_type)
      );
      ("sharing", Some (yojson_of_pipeline_sharing value.sharing));
      ("tableId", Some (Json.of_string value.table_id));
      ("teamId", Some (Json.of_string value.team_id));
      ("trashedAt", Some ((Json.of_option Json.of_string) value.trashed_at));
      ("userId", Some (Json.of_string value.user_id));
      ("grant", Some (yojson_of_access_level value.grant));
      ( "fields",
        Some ((Json.of_list yojson_of_pipeline_field_summary) value.fields) );
      ("version", Some (Json.of_int64 value.version));
    ]

let make_pipeline_fields ~(commercial_fields : commercial_fields)
    ~(created_at : string) ~(database_id : string) ~(id : string)
    ~(name : string) ~(primary_column_id : string) ?record_type
    ~(sharing : pipeline_sharing) ~(table_id : string) ~(team_id : string)
    ?trashed_at ~(user_id : string) ~(grant : access_level)
    ~(fields : pipeline_field_summary list) ~(version : int64) () =
  ({
     commercial_fields;
     created_at;
     database_id;
     id;
     name;
     primary_column_id;
     record_type;
     sharing;
     table_id;
     team_id;
     trashed_at;
     user_id;
     grant;
     fields;
     version;
   }
    : pipeline_fields)

type nonrec found_entries_response = {
  complete : bool;
      (** Whether every entry was read; a pipeline beyond 5000 entries is not,
so counts and totals cover only the entries read. *)
  counts : field_option_counts list;
      (** Matched entries per option of each single-select field. *)
  entries : pipeline_entry list;
      (** The first [limit] matches, in the requested order. *)
  matched : int;  (** How many entries matched in all. *)
  pipeline : pipeline_fields;
      (** The pipeline read, with its fields and version. *)
  totals : field_total list;
      (** The sum of each number field over the matched entries. *)
}
(** The entries a query matched. *)

let found_entries_response_of_yojson : Yojson.Safe.t -> found_entries_response =
 fun json ->
  let fields = Json.obj json in
  {
    complete = Json.required fields "complete" Json.bool;
    counts =
      Json.required fields "counts" (Json.list field_option_counts_of_yojson);
    entries =
      Json.required fields "entries" (Json.list pipeline_entry_of_yojson);
    matched = Json.required fields "matched" Json.int;
    pipeline = Json.required fields "pipeline" pipeline_fields_of_yojson;
    totals = Json.required fields "totals" (Json.list field_total_of_yojson);
  }

and yojson_of_found_entries_response : found_entries_response -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("complete", Some (Json.of_bool value.complete));
      ( "counts",
        Some ((Json.of_list yojson_of_field_option_counts) value.counts) );
      ("entries", Some ((Json.of_list yojson_of_pipeline_entry) value.entries));
      ("matched", Some (Json.of_int value.matched));
      ("pipeline", Some (yojson_of_pipeline_fields value.pipeline));
      ("totals", Some ((Json.of_list yojson_of_field_total) value.totals));
    ]

let make_found_entries_response ~(complete : bool)
    ~(counts : field_option_counts list) ~(entries : pipeline_entry list)
    ~(matched : int) ~(pipeline : pipeline_fields) ~(totals : field_total list)
    () =
  ({ complete; counts; entries; matched; pipeline; totals }
    : found_entries_response)

