  | No_access inner ->
      Json.with_tag "access" "no_access" (yojson_of_with_project_id inner)
  | Does_not_exist inner ->
      Json.with_tag "access" "does_not_exist" (yojson_of_with_project_id inner)
  | Unknown json -> json

