(** A single item in the Soup feed. *)
type nonrec soup_item =
  | Document of {
      data : soup_document_soup_properties_field;  (** Document item. *)
    }  (** Document item. *)
  | Chat of { data : soup_chat_soup_properties_field  (** Chat item. *) }
      (** Chat item. *)
  | Project of {
      data : soup_project_soup_properties_field;  (** Project item. *)
    }  (** Project item. *)
  | Initiative of {
      data : soup_initiative_soup_properties_field;  (** Initiative entity. *)
    }  (** Initiative entity. *)
  | Email_thread of {
      data : soup_enriched_email_thread_preview_soup_properties_field;
          (** Email thread item. *)
    }  (** Email thread item. *)
  | Channel of { data : soup_channel  (** Channel item. *) }
      (** Channel item. *)
  | Channel_thread of {
      data : soup_channel_thread;  (** Channel thread item. *)
    }  (** Channel thread item. *)
  | Call of {
      data : soup_call_record_soup_properties_field;  (** Call record item. *)
    }  (** Call record item. *)
  | Calendar_event of {
      data : soup_calendar_event_soup_properties_field;
          (** Calendar event item. *)
    }  (** Calendar event item. *)
  | Crm_company of {
      data : soup_crm_company_soup_properties_field;  (** CRM company item. *)
    }  (** CRM company item. *)
  | Crm_contact of {
      data : soup_crm_contact_soup_properties_field;
          (** Team-owned CRM contact. *)
    }  (** Team-owned CRM contact. *)
  | Foreign_entity of {
      data : soup_foreign_entity;  (** Foreign entity item. *)
    }  (** Foreign entity item. *)
  | Agent_session of {
      data : soup_agent_session_soup_properties_field;
          (** Agent session item. *)
    }  (** Agent session item. *)
  | Database_row of {
      data : soup_database_row_soup_properties_field;  (** Database row item. *)
    }  (** Database row item. *)
  | Harness of {
      data : soup_harness;
          (** Paired runtime, listed only by attention feeds. *)
    }  (** Paired runtime, listed only by attention feeds. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let soup_item_of_yojson : Yojson.Safe.t -> soup_item =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "tag" with
  | "document" ->
