type nonrec soup_api_item = {
  soup_item : soup_item;
  frecency_score : float;
  is_favorited : bool;
      (** Whether the requesting user has favorited this entity. *)
  notified_at : string option;
      (** When the caller was last notified about this entity, present only
when the page was ordered by [notified_at]. Clients keep the notified
feed ordered and date-bucketed on this value. *)
  touched_at : string option;
      (** The caller's latest own mutation of this entity, present only when the
page was ordered by [touched_by_me]. Clients keep the touched feed
ordered on this value, so it can be bumped optimistically. *)
}
(** API representation of a soup item with its per-viewer enrichments. *)

let soup_api_item_of_yojson : Yojson.Safe.t -> soup_api_item =
 fun json ->
  let fields = Json.obj json in
  {
    soup_item = soup_item_of_yojson json;
    frecency_score = Json.required fields "frecency_score" Json.float;
    is_favorited = Json.required fields "is_favorited" Json.bool;
    notified_at = Json.optional fields "notified_at" Json.string;
    touched_at = Json.optional fields "touched_at" Json.string;
  }

and yojson_of_soup_api_item : soup_api_item -> Yojson.Safe.t =
 fun value ->
  Json.merge
    [
      Json.record
        [
          ("frecency_score", Some (Json.of_float value.frecency_score));
          ("is_favorited", Some (Json.of_bool value.is_favorited));
          ("notified_at", Option.map Json.of_string value.notified_at);
          ("touched_at", Option.map Json.of_string value.touched_at);
        ];
      yojson_of_soup_item value.soup_item;
    ]

let make_soup_api_item ~(soup_item : soup_item) ~(frecency_score : float)
    ~(is_favorited : bool) ?notified_at ?touched_at () =
  ({ soup_item; frecency_score; is_favorited; notified_at; touched_at }
    : soup_api_item)

type nonrec grouped_soup_group_page = {
  group : api_group_meta;
      (** Metadata and item membership for the requested group page. *)
  items : (string * soup_api_item) list;
      (** Items in this page, keyed by id. Ordering lives in [group.item_ids]. *)
}
(** Response for fetching a page within one group. *)

let grouped_soup_group_page_of_yojson : Yojson.Safe.t -> grouped_soup_group_page
    =
 fun json ->
  let fields = Json.obj json in
  {
    group = Json.required fields "group" api_group_meta_of_yojson;
    items = Json.required fields "items" (Json.map soup_api_item_of_yojson);
  }

and yojson_of_grouped_soup_group_page : grouped_soup_group_page -> Yojson.Safe.t
    =
 fun value ->
  Json.record
    [
      ("group", Some (yojson_of_api_group_meta value.group));
      ("items", Some ((Json.of_map yojson_of_soup_api_item) value.items));
    ]

let make_grouped_soup_group_page ~(group : api_group_meta)
    ~(items : (string * soup_api_item) list) () =
  ({ group; items } : grouped_soup_group_page)

type nonrec grouped_soup_initial_page = {
  groups : api_group_meta list;
      (** Ordered group metadata for this grouped response. *)
  items : (string * soup_api_item) list;
      (** Items in this page, keyed by id. Ordering lives in `groups\[\].item_ids`. *)
}
(** Response for the initial grouped soup query.

Items are returned as a pool keyed by id; each [ApiGroupMeta.item_ids]
describes the ordered membership of one group. *)

let grouped_soup_initial_page_of_yojson :
    Yojson.Safe.t -> grouped_soup_initial_page =
 fun json ->
  let fields = Json.obj json in
  {
    groups = Json.required fields "groups" (Json.list api_group_meta_of_yojson);
    items = Json.required fields "items" (Json.map soup_api_item_of_yojson);
  }

and yojson_of_grouped_soup_initial_page :
    grouped_soup_initial_page -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("groups", Some ((Json.of_list yojson_of_api_group_meta) value.groups));
      ("items", Some ((Json.of_map yojson_of_soup_api_item) value.items));
    ]

let make_grouped_soup_initial_page ~(groups : api_group_meta list)
    ~(items : (string * soup_api_item) list) () =
  ({ groups; items } : grouped_soup_initial_page)

(** Response for grouped soup queries. *)
type nonrec grouped_soup_page =
  | Initial of grouped_soup_initial_page
      (** Initial grouped response containing multiple groups. *)
  | Group_page of grouped_soup_group_page
      (** Follow-up response for one specific group. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let grouped_soup_page_of_yojson : Yojson.Safe.t -> grouped_soup_page =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "mode" with
  | "initial" -> Initial (grouped_soup_initial_page_of_yojson json)
  | "group_page" -> Group_page (grouped_soup_group_page_of_yojson json)
  | _ -> Unknown json

and yojson_of_grouped_soup_page : grouped_soup_page -> Yojson.Safe.t =
 fun value ->
  match value with
  | Initial inner ->
      Json.with_tag "mode" "initial" (yojson_of_grouped_soup_initial_page inner)
  | Group_page inner ->
      Json.with_tag "mode" "group_page"
        (yojson_of_grouped_soup_group_page inner)
  | Unknown json -> json

