type nonrec hash_map_value =
  | External of presigned_url
  | Internal of s3_object_info
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let hash_map_value_of_yojson : Yojson.Safe.t -> hash_map_value =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "external" -> External (presigned_url_of_yojson json)
  | "internal" -> Internal (s3_object_info_of_yojson json)
  | _ -> Unknown json

and yojson_of_hash_map_value : hash_map_value -> Yojson.Safe.t =
 fun value ->
  match value with
  | External inner ->
      Json.with_tag "type" "external" (yojson_of_presigned_url inner)
  | Internal inner ->
      Json.with_tag "type" "internal" (yojson_of_s3_object_info inner)
  | Unknown json -> json

type nonrec hash_map = (string * hash_map_value) list

let hash_map_of_yojson : Yojson.Safe.t -> hash_map =
 fun json -> (Json.map hash_map_value_of_yojson) json

and yojson_of_hash_map : hash_map -> Yojson.Safe.t =
 fun value -> (Json.of_map yojson_of_hash_map_value) value

