type nonrec job_id = string
(** Import job identity. Generate UUIDv7 in application code. *)

let job_id_of_yojson : Yojson.Safe.t -> job_id = fun json -> Json.string json

and yojson_of_job_id : job_id -> Yojson.Safe.t =
 fun value -> Json.of_string value

(** Job lifecycle. Cancellation remains in progress while any lease is active. *)
type nonrec job_status =
  | Uploading
  | Processing
  | Completed
  | Completed_with_errors
  | Failed
  | Cancelling
  | Cancelled
  | Unknown of string  (** A value this SDK version does not know. *)

let job_status_of_yojson : Yojson.Safe.t -> job_status =
 fun json ->
  match Json.string json with
  | "uploading" -> Uploading
  | "processing" -> Processing
  | "completed" -> Completed
  | "completed_with_errors" -> Completed_with_errors
  | "failed" -> Failed
  | "cancelling" -> Cancelling
  | "cancelled" -> Cancelled
  | other -> Unknown other

and yojson_of_job_status : job_status -> Yojson.Safe.t =
 fun value ->
  match value with
  | Uploading -> `String "uploading"
  | Processing -> `String "processing"
  | Completed -> `String "completed"
  | Completed_with_errors -> `String "completed_with_errors"
  | Failed -> `String "failed"
  | Cancelling -> `String "cancelling"
  | Cancelled -> `String "cancelled"
  | Unknown other -> `String other

type nonrec import_progress = {
  conversations : conversation_progress list;
      (** All selected conversations, bounded by the create limit. *)
  created_at : string;
      (** Persisted creation time, also the final historical-time fallback. *)
  include_message_history : bool;
      (** Immutable history option confirmed when creating this job. *)
  job_id : job_id;  (** Stable job identity. *)
  limits : import_limits;  (** Server bounds for staging and registration. *)
  registration_closed_at : string option;
      (** Registration closure time; cancellation also closes registration. *)
  revision : int64;
      (** Monotonic job revision for polling/websocket invalidation. *)
  source : source_identity;
      (** Immutable source confirmation from this job, not the current team binding. *)
  status : job_status;  (** Durable job lifecycle. *)
  updated_at : string;  (** Last durable lifecycle/progress update. *)
  users_verified : bool;  (** Whether users metadata is verified and pinned. *)
}
(** Common receipt returned by create, completion, finalize, cancel and progress. *)

let import_progress_of_yojson : Yojson.Safe.t -> import_progress =
