    created_at = Json.required fields "createdAt" Json.string;
    include_message_history =
      Json.required fields "includeMessageHistory" Json.bool;
    job_id = Json.required fields "jobId" job_id_of_yojson;
    limits = Json.required fields "limits" import_limits_of_yojson;
    registration_closed_at =
      Json.optional fields "registrationClosedAt" Json.string;
    revision = Json.required fields "revision" Json.int64;
    source = Json.required fields "source" source_identity_of_yojson;
    status = Json.required fields "status" job_status_of_yojson;
    updated_at = Json.required fields "updatedAt" Json.string;
    users_verified = Json.required fields "usersVerified" Json.bool;
  }

and yojson_of_import_progress : import_progress -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "conversations",
        Some
          ((Json.of_list yojson_of_conversation_progress) value.conversations)
      );
      ("createdAt", Some (Json.of_string value.created_at));
      ( "includeMessageHistory",
        Some (Json.of_bool value.include_message_history) );
      ("jobId", Some (yojson_of_job_id value.job_id));
      ("limits", Some (yojson_of_import_limits value.limits));
      ( "registrationClosedAt",
        Option.map Json.of_string value.registration_closed_at );
      ("revision", Some (Json.of_int64 value.revision));
      ("source", Some (yojson_of_source_identity value.source));
      ("status", Some (yojson_of_job_status value.status));
      ("updatedAt", Some (Json.of_string value.updated_at));
      ("usersVerified", Some (Json.of_bool value.users_verified));
    ]

