   }
    : import_progress)

(** Team's durable single-source binding, including confirmed unidentified archives. *)
type nonrec source_binding =
  | Unbound  (** No import has bound this team yet. *)
  | Confirmed_unknown
      (** Legacy/onboarding or explicitly confirmed unidentified source. *)
  | Known of { source_id : source_id  (** Bound source identity. *) }
      (** Known Slack workspace; reject mismatches. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let source_binding_of_yojson : Yojson.Safe.t -> source_binding =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "unbound" -> Unbound
  | "confirmed_unknown" -> Confirmed_unknown
  | "known" ->
      Known { source_id = Json.required fields "sourceId" source_id_of_yojson }
  | _ -> Unknown json

and yojson_of_source_binding : source_binding -> Yojson.Safe.t =
 fun value ->
  match value with
  | Unbound -> Json.record [ ("kind", Some (`String "unbound")) ]
  | Confirmed_unknown ->
      Json.record [ ("kind", Some (`String "confirmed_unknown")) ]
  | Known case ->
      Json.record
        [
          ("kind", Some (`String "known"));
          ("sourceId", Some (yojson_of_source_id case.source_id));
        ]
  | Unknown json -> json

let make_source_binding_known ~(source_id : source_id) () =
  (Known { source_id } : source_binding)

