type nonrec location_response_data =
  | Presigned_url of string
      (** The presigned url of the document if it is not a docx *)
  | Presigned_urls of presigned_url list
      (** The presigned urls of the docx bom parts if it is a docx *)

let location_response_data_of_yojson : Yojson.Safe.t -> location_response_data =
 fun json ->
  match Json.external_case json with
  | "presignedUrl", value ->
      Presigned_url (Json.string (Json.payload "presignedUrl" value))
  | "presignedUrls", value ->
      Presigned_urls
        ((Json.list presigned_url_of_yojson)
           (Json.payload "presignedUrls" value))
  | name, _ -> Json.fail "unknown case %S" name

and yojson_of_location_response_data : location_response_data -> Yojson.Safe.t =
 fun value ->
  match value with
  | Presigned_url inner ->
      Json.external_value "presignedUrl" (Json.of_string inner)
  | Presigned_urls inner ->
      Json.external_value "presignedUrls"
        ((Json.of_list yojson_of_presigned_url) inner)

(** Location response with content lifecycle metadata. *)
type nonrec location_response_v3 =
  | Presigned_url of {
      content : document_content;
          (** Content lifecycle and location metadata. *)
      metadata : document_basic;  (** Basic document metadata. *)
      presigned_url : string;  (** Presigned URL. *)
    }  (** A single document-storage URL. *)
  | Presigned_urls of {
      content : document_content;
          (** Content lifecycle and location metadata. *)
      metadata : document_basic;  (** Basic document metadata. *)
      presigned_urls : presigned_url list;  (** Presigned URLs. *)
    }  (** Multiple document-storage URLs, currently for DOCX BOM parts. *)
  | Sync_service_content of {
      content : document_content;
          (** Content lifecycle and location metadata. *)
      metadata : document_basic;  (** Basic document metadata. *)
    }  (** Sync-service backed content. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let location_response_v3_of_yojson : Yojson.Safe.t -> location_response_v3 =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "presignedUrl" ->
      Presigned_url
        {
          content = Json.required fields "content" document_content_of_yojson;
          metadata = Json.required fields "metadata" document_basic_of_yojson;
          presigned_url = Json.required fields "presignedUrl" Json.string;
        }
  | "presignedUrls" ->
      Presigned_urls
        {
          content = Json.required fields "content" document_content_of_yojson;
          metadata = Json.required fields "metadata" document_basic_of_yojson;
          presigned_urls =
            Json.required fields "presignedUrls"
              (Json.list presigned_url_of_yojson);
        }
  | "syncServiceContent" ->
      Sync_service_content
        {
          content = Json.required fields "content" document_content_of_yojson;
          metadata = Json.required fields "metadata" document_basic_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_location_response_v3 : location_response_v3 -> Yojson.Safe.t =
 fun value ->
  match value with
  | Presigned_url case ->
      Json.record
        [
          ("type", Some (`String "presignedUrl"));
          ("content", Some (yojson_of_document_content case.content));
          ("metadata", Some (yojson_of_document_basic case.metadata));
          ("presignedUrl", Some (Json.of_string case.presigned_url));
        ]
  | Presigned_urls case ->
      Json.record
        [
          ("type", Some (`String "presignedUrls"));
          ("content", Some (yojson_of_document_content case.content));
          ("metadata", Some (yojson_of_document_basic case.metadata));
          ( "presignedUrls",
            Some ((Json.of_list yojson_of_presigned_url) case.presigned_urls) );
        ]
  | Sync_service_content case ->
      Json.record
        [
          ("type", Some (`String "syncServiceContent"));
          ("content", Some (yojson_of_document_content case.content));
          ("metadata", Some (yojson_of_document_basic case.metadata));
        ]
  | Unknown json -> json

let make_location_response_v3_presigned_url ~(content : document_content)
    ~(metadata : document_basic) ~(presigned_url : string) () =
  (Presigned_url { content; metadata; presigned_url } : location_response_v3)

let make_location_response_v3_presigned_urls ~(content : document_content)
    ~(metadata : document_basic) ~(presigned_urls : presigned_url list) () =
  (Presigned_urls { content; metadata; presigned_urls } : location_response_v3)

let make_location_response_v3_sync_service_content ~(content : document_content)
    ~(metadata : document_basic) () =
  (Sync_service_content { content; metadata } : location_response_v3)

