  | "Default" -> Default
  | "MentionsOnly" -> Mentions_only
  | "Silent" -> Silent
  | other -> Unknown other

and yojson_of_post_message_notification_policy :
    post_message_notification_policy -> Yojson.Safe.t =
 fun value ->
  match value with
  | Default -> `String "Default"
  | Mentions_only -> `String "MentionsOnly"
  | Silent -> `String "Silent"
  | Unknown other -> `String other

(** Internal notification behavior for a patched channel message. *)
type nonrec patch_message_notification_policy =
  | Default
  | Notify_as_posted_message
  | Unknown of string  (** A value this SDK version does not know. *)

let patch_message_notification_policy_of_yojson :
    Yojson.Safe.t -> patch_message_notification_policy =
 fun json ->
  match Json.string json with
  | "Default" -> Default
  | "NotifyAsPostedMessage" -> Notify_as_posted_message
  | other -> Unknown other

and yojson_of_patch_message_notification_policy :
    patch_message_notification_policy -> Yojson.Safe.t =
 fun value ->
  match value with
  | Default -> `String "Default"
  | Notify_as_posted_message -> `String "NotifyAsPostedMessage"
  | Unknown other -> `String other

(** Kind of message change; notification policy only runs for posted messages. *)
type nonrec message_change =
  | Posted of {
      mentions : simple_mention list;  (** Mentions included in this post. *)
      message : message;  (** Persisted message. *)
      notification_policy : post_message_notification_policy;
          (** Trusted notification policy carried with the committed change. *)
    }  (** A message was posted. *)
  | Edited of {
      mentions : simple_mention list;  (** Complete replacement mention set. *)
      message : message;  (** Persisted replacement message. *)
      notification_policy : patch_message_notification_policy;
          (** Trusted notification policy for the edited content. *)
      previous_attachments : message_attachment list;
          (** Attachment identities before the edit, for channel change delivery. *)
    }  (** Message content and references were edited. *)
  | Message_deleted of { message : message  (** Persisted tombstone. *) }
      (** One message was tombstoned; its thread may remain live. *)
  | Reaction_changed of {
      added : bool;
          (** Whether the reaction was added ([true]) or removed ([false]). *)
      emoji : string;  (** Emoji whose membership changed. *)
      message : message;  (** Persisted message. *)
    }  (** The authenticated actor added or removed a reaction. *)
  | Call_root_posted of { message : message  (** Persisted root. *) }
      (** A channel call's thread root was created. It stands for the call, so it
reaches viewers and moves the channel up without any of what a post
causes: no notifications, agents, routines, webhooks or search documents. *)
  | Thread_updated of { state : thread_state  (** Persisted thread state. *) }
      (** Thread resolution, placement, or deletion changed. *)
  | Typing of {
      active : bool;  (** Whether the user is currently typing. *)
      agent : agent_typing option;
      thread_id : string option;
          (** Root being replied to, or no root for the parent composer. *)
    }  (** Transient typing indication. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let message_change_of_yojson : Yojson.Safe.t -> message_change =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "posted" ->
      Posted
        {
          mentions =
            Json.required fields "mentions" (Json.list simple_mention_of_yojson);
          message = Json.required fields "message" message_of_yojson;
          notification_policy =
            Json.required fields "notification_policy"
              post_message_notification_policy_of_yojson;
        }
  | "edited" ->
      Edited
        {
          mentions =
            Json.required fields "mentions" (Json.list simple_mention_of_yojson);
          message = Json.required fields "message" message_of_yojson;
          notification_policy =
            Json.required fields "notification_policy"
              patch_message_notification_policy_of_yojson;
          previous_attachments =
            Json.required fields "previous_attachments"
              (Json.list message_attachment_of_yojson);
        }
  | "message_deleted" ->
      Message_deleted
        { message = Json.required fields "message" message_of_yojson }
  | "reaction_changed" ->
      Reaction_changed
        {
          added = Json.required fields "added" Json.bool;
          emoji = Json.required fields "emoji" Json.string;
          message = Json.required fields "message" message_of_yojson;
        }
  | "call_root_posted" ->
      Call_root_posted
        { message = Json.required fields "message" message_of_yojson }
  | "thread_updated" ->
      Thread_updated
        { state = Json.required fields "state" thread_state_of_yojson }
  | "typing" ->
      Typing
        {
          active = Json.required fields "active" Json.bool;
          agent = Json.optional fields "agent" agent_typing_of_yojson;
          thread_id = Json.optional fields "thread_id" Json.string;
        }
  | _ -> Unknown json

and yojson_of_message_change : message_change -> Yojson.Safe.t =
 fun value ->
  match value with
  | Posted case ->
      Json.record
        [
          ("type", Some (`String "posted"));
          ( "mentions",
            Some ((Json.of_list yojson_of_simple_mention) case.mentions) );
          ("message", Some (yojson_of_message case.message));
          ( "notification_policy",
            Some
              (yojson_of_post_message_notification_policy
                 case.notification_policy) );
        ]
  | Edited case ->
      Json.record
        [
          ("type", Some (`String "edited"));
          ( "mentions",
            Some ((Json.of_list yojson_of_simple_mention) case.mentions) );
          ("message", Some (yojson_of_message case.message));
          ( "notification_policy",
            Some
              (yojson_of_patch_message_notification_policy
                 case.notification_policy) );
          ( "previous_attachments",
            Some
              ((Json.of_list yojson_of_message_attachment)
                 case.previous_attachments) );
        ]
  | Message_deleted case ->
      Json.record
        [
          ("type", Some (`String "message_deleted"));
          ("message", Some (yojson_of_message case.message));
        ]
  | Reaction_changed case ->
      Json.record
        [
          ("type", Some (`String "reaction_changed"));
          ("added", Some (Json.of_bool case.added));
          ("emoji", Some (Json.of_string case.emoji));
          ("message", Some (yojson_of_message case.message));
        ]
  | Call_root_posted case ->
      Json.record
        [
          ("type", Some (`String "call_root_posted"));
          ("message", Some (yojson_of_message case.message));
        ]
  | Thread_updated case ->
      Json.record
        [
          ("type", Some (`String "thread_updated"));
          ("state", Some (yojson_of_thread_state case.state));
        ]
  | Typing case ->
      Json.record
        [
          ("type", Some (`String "typing"));
          ("active", Some (Json.of_bool case.active));
          ("agent", Option.map yojson_of_agent_typing case.agent);
          ("thread_id", Option.map Json.of_string case.thread_id);
        ]
  | Unknown json -> json

let make_message_change_posted ~(mentions : simple_mention list)
    ~(message : message)
    ~(notification_policy : post_message_notification_policy) () =
  (Posted { mentions; message; notification_policy } : message_change)

let make_message_change_edited ~(mentions : simple_mention list)
    ~(message : message)
    ~(notification_policy : patch_message_notification_policy)
    ~(previous_attachments : message_attachment list) () =
  (Edited { mentions; message; notification_policy; previous_attachments }
    : message_change)

let make_message_change_message_deleted ~(message : message) () =
  (Message_deleted { message } : message_change)

let make_message_change_reaction_changed ~(added : bool) ~(emoji : string)
    ~(message : message) () =
  (Reaction_changed { added; emoji; message } : message_change)

let make_message_change_call_root_posted ~(message : message) () =
  (Call_root_posted { message } : message_change)

let make_message_change_thread_updated ~(state : thread_state) () =
  (Thread_updated { state } : message_change)

let make_message_change_typing ~(active : bool) ?agent ?thread_id () =
  (Typing { active; agent; thread_id } : message_change)

