(** One chronological entry in a parent's timeline. *)
type nonrec message_timeline_entry =
  | Message of {
      message : message_list_item;  (** The message and thread state. *)
    }  (** A root message with its bounded thread preview. *)
  | Activity of { activity : timeline_activity  (** The recorded activity. *) }
      (** A recorded fact about the parent, such as a rename or a finished call. *)
  | Call of {
      message : message_list_item;
          (** The call's root message, its thread state and its reply preview. *)
      status : call_entry_status;  (** Where the call is in its life. *)
    }
      (** A channel call and its thread. The root message's id is the call id. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let message_timeline_entry_of_yojson : Yojson.Safe.t -> message_timeline_entry =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "message" ->
      Message
        { message = Json.required fields "message" message_list_item_of_yojson }
  | "activity" ->
      Activity
        {
          activity = Json.required fields "activity" timeline_activity_of_yojson;
        }
  | "call" ->
      Call
        {
          message = Json.required fields "message" message_list_item_of_yojson;
          status = Json.required fields "status" call_entry_status_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_message_timeline_entry : message_timeline_entry -> Yojson.Safe.t =
 fun value ->
  match value with
  | Message case ->
      Json.record
        [
          ("type", Some (`String "message"));
          ("message", Some (yojson_of_message_list_item case.message));
        ]
  | Activity case ->
      Json.record
        [
          ("type", Some (`String "activity"));
          ("activity", Some (yojson_of_timeline_activity case.activity));
        ]
  | Call case ->
      Json.record
        [
          ("type", Some (`String "call"));
          ("message", Some (yojson_of_message_list_item case.message));
          ("status", Some (yojson_of_call_entry_status case.status));
        ]
  | Unknown json -> json

let make_message_timeline_entry_message ~(message : message_list_item) () =
  (Message { message } : message_timeline_entry)

let make_message_timeline_entry_activity ~(activity : timeline_activity) () =
  (Activity { activity } : message_timeline_entry)

let make_message_timeline_entry_call ~(message : message_list_item)
    ~(status : call_entry_status) () =
  (Call { message; status } : message_timeline_entry)

