(** Lifecycle events for the common message service, one per committed fact.
Reactions and typing never reach the topic. *)
type nonrec message_topic_event =
  | Message_posted of {
      metadata : message_posted_metadata;
          (** A user or bot posted a root or reply. *)
    }  (** A user or bot posted a root or reply. *)
  | Message_patched of {
      metadata : message_patched_metadata;
          (** A message's content was patched. *)
    }  (** A message's content was patched. *)
  | Message_deleted of {
      metadata : message_deleted_metadata;  (** A message was tombstoned. *)
    }  (** A message was tombstoned. *)
  | Message_mentioned of {
      metadata : message_mentioned_metadata;
          (** An entity (user, bot, document, …) was mentioned in a posted message. *)
    }
      (** An entity (user, bot, document, …) was mentioned in a posted message. *)
  | Message_attachment_created of {
      metadata : message_attachment_created_metadata;
          (** Attachments were added to a message. *)
    }  (** Attachments were added to a message. *)
  | Message_attachment_removed of {
      metadata : message_attachment_removed_metadata;
          (** Attachments were removed from a message. *)
    }  (** Attachments were removed from a message. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let message_topic_event_of_yojson : Yojson.Safe.t -> message_topic_event =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "event_type" with
  | "message.posted" ->
      Message_posted
        {
          metadata =
            Json.required fields "metadata" message_posted_metadata_of_yojson;
        }
  | "message.patched" ->
      Message_patched
        {
          metadata =
            Json.required fields "metadata" message_patched_metadata_of_yojson;
        }
  | "message.deleted" ->
      Message_deleted
        {
          metadata =
            Json.required fields "metadata" message_deleted_metadata_of_yojson;
        }
  | "message.mentioned" ->
      Message_mentioned
        {
          metadata =
            Json.required fields "metadata" message_mentioned_metadata_of_yojson;
        }
  | "message.attachment_created" ->
      Message_attachment_created
        {
          metadata =
            Json.required fields "metadata"
              message_attachment_created_metadata_of_yojson;
        }
  | "message.attachment_removed" ->
      Message_attachment_removed
        {
          metadata =
            Json.required fields "metadata"
              message_attachment_removed_metadata_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_message_topic_event : message_topic_event -> Yojson.Safe.t =
 fun value ->
  match value with
  | Message_posted case ->
      Json.record
        [
          ("event_type", Some (`String "message.posted"));
          ("metadata", Some (yojson_of_message_posted_metadata case.metadata));
        ]
  | Message_patched case ->
      Json.record
        [
          ("event_type", Some (`String "message.patched"));
          ("metadata", Some (yojson_of_message_patched_metadata case.metadata));
        ]
  | Message_deleted case ->
      Json.record
        [
          ("event_type", Some (`String "message.deleted"));
          ("metadata", Some (yojson_of_message_deleted_metadata case.metadata));
        ]
  | Message_mentioned case ->
      Json.record
        [
          ("event_type", Some (`String "message.mentioned"));
          ("metadata", Some (yojson_of_message_mentioned_metadata case.metadata));
        ]
  | Message_attachment_created case ->
      Json.record
        [
          ("event_type", Some (`String "message.attachment_created"));
          ( "metadata",
            Some (yojson_of_message_attachment_created_metadata case.metadata)
          );
        ]
  | Message_attachment_removed case ->
      Json.record
        [
          ("event_type", Some (`String "message.attachment_removed"));
          ( "metadata",
            Some (yojson_of_message_attachment_removed_metadata case.metadata)
          );
        ]
  | Unknown json -> json

