(** A signed-in respondent's own response. *)
type nonrec my_response =
  | Saved of {
      answers : answer list;
          (** The row's cells for the form's current questions, the empty ones
left out; none when the row is gone. *)
      booking : unlocked_booking option;
          (** The form's booking step, while the saved row still passes the
form's current required questions and gates. *)
      response : form_response;  (** The ledger entry. *)
    }  (** Their ledger entry, with its answers as the row holds them now. *)
  | Anonymous
      (** They responded to an anonymous form. Nothing links them to their
response, so there is nothing more to show. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let my_response_of_yojson : Yojson.Safe.t -> my_response =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "saved" ->
      Saved
        {
          answers = Json.required fields "answers" (Json.list answer_of_yojson);
          booking = Json.optional fields "booking" unlocked_booking_of_yojson;
          response = Json.required fields "response" form_response_of_yojson;
        }
  | "anonymous" -> Anonymous
  | _ -> Unknown json

and yojson_of_my_response : my_response -> Yojson.Safe.t =
 fun value ->
  match value with
  | Saved case ->
      Json.record
        [
          ("kind", Some (`String "saved"));
          ("answers", Some ((Json.of_list yojson_of_answer) case.answers));
          ("booking", Option.map yojson_of_unlocked_booking case.booking);
          ("response", Some (yojson_of_form_response case.response));
        ]
  | Anonymous -> Json.record [ ("kind", Some (`String "anonymous")) ]
  | Unknown json -> json

let make_my_response_saved ~(answers : answer list) ?booking
    ~(response : form_response) () =
  (Saved { answers; booking; response } : my_response)

(** Location supplied when creating a document discussion. *)
type nonrec new_thread_anchor =
  | Markdown of {
      mark_id : string;  (** Serialized mark identifier. *)
      marked_text : string option;
          (** The document text the mark covers, captured by the editor as the
comment is written. Trimmed and bounded before it is stored, so an
oversized or whitespace-only claim cannot reach the thread row. *)
    }  (** Attach a discussion to a stable Markdown mark. *)
  | Pdf_highlight of {
      anchor_id : string;  (** Highlight annotation identifier. *)
    }  (** Attach an independently existing highlight on this document. *)
  | Pdf_placeable of {
      anchor_id : string;
          (** Client-generated annotation identifier used by optimistic rendering. *)
      height_pct : float;  (** Height as a fraction of the page height. *)
      page : int;  (** PDF page number. *)
      width_pct : float;  (** Width as a fraction of the page width. *)
      x_pct : float;
          (** Horizontal position as a fraction of the page width. *)
      y_pct : float;  (** Vertical position as a fraction of the page height. *)
    }  (** Atomically create a placeable annotation with the root message. *)
  | Spreadsheet of {
      range : string;  (** A1 cell or range, such as B4 or B4:C9. *)
      sheet_id : string;  (** Stable sheet identity within the workbook. *)
      sheet_name : string;  (** Sheet name when the discussion was created. *)
    }  (** A cell or rectangular range in a native spreadsheet. *)
  | Fig of {
      node_id : string option;
          (** Layer the pin follows; absent or null for a pin on the bare canvas. *)
      page_id : string;  (** Page (canvas) the pin is on. *)
      x : float;
          (** Horizontal offset from the layer's origin, or the page's when
the pin is on no layer, in design units. *)
      y : float;  (** Vertical offset, measured like [x]. *)
    }
      (** A point pinned on a design ([.fig]): on a layer, or on the page
canvas when no layer was under it. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let new_thread_anchor_of_yojson : Yojson.Safe.t -> new_thread_anchor =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "markdown" ->
      Markdown
        {
          mark_id = Json.required fields "mark_id" Json.string;
          marked_text = Json.optional fields "marked_text" Json.string;
        }
  | "pdf_highlight" ->
      Pdf_highlight { anchor_id = Json.required fields "anchor_id" Json.string }
  | "pdf_placeable" ->
      Pdf_placeable
        {
          anchor_id = Json.required fields "anchor_id" Json.string;
          height_pct = Json.required fields "height_pct" Json.float;
          page = Json.required fields "page" Json.int;
          width_pct = Json.required fields "width_pct" Json.float;
          x_pct = Json.required fields "x_pct" Json.float;
          y_pct = Json.required fields "y_pct" Json.float;
        }
  | "spreadsheet" ->
      Spreadsheet
        {
          range = Json.required fields "range" Json.string;
          sheet_id = Json.required fields "sheetId" Json.string;
          sheet_name = Json.required fields "sheetName" Json.string;
        }
  | "fig" ->
      Fig
        {
          node_id = Json.optional fields "nodeId" Json.string;
          page_id = Json.required fields "pageId" Json.string;
          x = Json.required fields "x" Json.float;
          y = Json.required fields "y" Json.float;
        }
  | _ -> Unknown json

and yojson_of_new_thread_anchor : new_thread_anchor -> Yojson.Safe.t =
 fun value ->
  match value with
  | Markdown case ->
      Json.record
        [
          ("type", Some (`String "markdown"));
          ("mark_id", Some (Json.of_string case.mark_id));
          ("marked_text", Option.map Json.of_string case.marked_text);
        ]
  | Pdf_highlight case ->
      Json.record
        [
          ("type", Some (`String "pdf_highlight"));
          ("anchor_id", Some (Json.of_string case.anchor_id));
        ]
  | Pdf_placeable case ->
      Json.record
        [
          ("type", Some (`String "pdf_placeable"));
          ("anchor_id", Some (Json.of_string case.anchor_id));
          ("height_pct", Some (Json.of_float case.height_pct));
          ("page", Some (Json.of_int case.page));
          ("width_pct", Some (Json.of_float case.width_pct));
          ("x_pct", Some (Json.of_float case.x_pct));
          ("y_pct", Some (Json.of_float case.y_pct));
        ]
  | Spreadsheet case ->
      Json.record
        [
          ("type", Some (`String "spreadsheet"));
          ("range", Some (Json.of_string case.range));
          ("sheetId", Some (Json.of_string case.sheet_id));
          ("sheetName", Some (Json.of_string case.sheet_name));
        ]
  | Fig case ->
      Json.record
        [
          ("type", Some (`String "fig"));
          ("nodeId", Option.map Json.of_string case.node_id);
          ("pageId", Some (Json.of_string case.page_id));
          ("x", Some (Json.of_float case.x));
          ("y", Some (Json.of_float case.y));
        ]
  | Unknown json -> json

let make_new_thread_anchor_markdown ~(mark_id : string) ?marked_text () =
  (Markdown { mark_id; marked_text } : new_thread_anchor)

let make_new_thread_anchor_pdf_highlight ~(anchor_id : string) () =
  (Pdf_highlight { anchor_id } : new_thread_anchor)

let make_new_thread_anchor_pdf_placeable ~(anchor_id : string)
    ~(height_pct : float) ~(page : int) ~(width_pct : float) ~(x_pct : float)
    ~(y_pct : float) () =
  (Pdf_placeable { anchor_id; height_pct; page; width_pct; x_pct; y_pct }
    : new_thread_anchor)

let make_new_thread_anchor_spreadsheet ~(range : string) ~(sheet_id : string)
    ~(sheet_name : string) () =
  (Spreadsheet { range; sheet_id; sheet_name } : new_thread_anchor)

let make_new_thread_anchor_fig ?node_id ~(page_id : string) ~(x : float)
    ~(y : float) () =
  (Fig { node_id; page_id; x; y } : new_thread_anchor)

type nonrec op_batch = {
  base_versions : (string * table_version) list option;
      (** The version each named table must still be at; the batch is refused
as a conflict if one moved. Without one, ops are last-write-wins. *)
  ops : database_op list;  (** The ops, in the order they apply. *)
}
(** A batch of ops for one database and the versions its tables must be at. *)

let op_batch_of_yojson : Yojson.Safe.t -> op_batch =
 fun json ->
  let fields = Json.obj json in
  {
    base_versions =
      Json.optional fields "baseVersions" (Json.map table_version_of_yojson);
    ops = Json.required fields "ops" (Json.list database_op_of_yojson);
  }

and yojson_of_op_batch : op_batch -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "baseVersions",
        Option.map (Json.of_map yojson_of_table_version) value.base_versions );
      ("ops", Some ((Json.of_list yojson_of_database_op) value.ops));
    ]

let make_op_batch ?base_versions ~(ops : database_op list) () =
  ({ base_versions; ops } : op_batch)

(** An id a request minted for something new that already names something,
which refuses the request: a retried request whose first attempt
committed, or an id minted twice. *)
type nonrec taken_id =
  | Table of { id : string  (** A table's. *) }  (** A table's. *)
  | Column of { id : string  (** A column's. *) }  (** A column's. *)
  | Option of { id : string  (** An option's. *) }  (** An option's. *)
  | View of { id : string  (** A view's. *) }  (** A view's. *)
  | Row of { id : string  (** A row's. *) }  (** A row's. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let taken_id_of_yojson : Yojson.Safe.t -> taken_id =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "table" -> Table { id = Json.required fields "id" Json.string }
  | "column" -> Column { id = Json.required fields "id" Json.string }
  | "option" -> Option { id = Json.required fields "id" Json.string }
  | "view" -> View { id = Json.required fields "id" Json.string }
  | "row" -> Row { id = Json.required fields "id" Json.string }
  | _ -> Unknown json

and yojson_of_taken_id : taken_id -> Yojson.Safe.t =
 fun value ->
  match value with
  | Table case ->
      Json.record
        [
          ("kind", Some (`String "table")); ("id", Some (Json.of_string case.id));
        ]
  | Column case ->
      Json.record
        [
          ("kind", Some (`String "column"));
          ("id", Some (Json.of_string case.id));
        ]
  | Option case ->
      Json.record
        [
          ("kind", Some (`String "option"));
          ("id", Some (Json.of_string case.id));
        ]
  | View case ->
      Json.record
        [
          ("kind", Some (`String "view")); ("id", Some (Json.of_string case.id));
        ]
  | Row case ->
      Json.record
        [
          ("kind", Some (`String "row")); ("id", Some (Json.of_string case.id));
        ]
  | Unknown json -> json

let make_taken_id_table ~(id : string) () = (Table { id } : taken_id)
let make_taken_id_column ~(id : string) () = (Column { id } : taken_id)
let make_taken_id_option ~(id : string) () = (Option { id } : taken_id)
let make_taken_id_view ~(id : string) () = (View { id } : taken_id)
let make_taken_id_row ~(id : string) () = (Row { id } : taken_id)

