type nonrec patch_agent_request = {
  auto_accept_permissions : bool option;
      (** Replacement permission choice: approve without asking ([true]) or
prompt ([false]). A patch cannot clear the choice back to unset; an
explicit [false] prompts exactly as unset does. *)
  channels : agent_channel_selection option;
  default_model : string option;  (** Replacement model. *)
  harness : agent_harness_selection option;
  instructions : string option;  (** Replacement instructions, whole. *)
  is_coding : bool option;  (** Replacement coding choice. *)
  mcp : agent_mcp_servers option;
}
(** Request to change part of a persisted agent's instructions or settings.

Every field is optional; an absent field keeps the agent's current value.
Ownership and the bot profile (name, handle, description, avatar) are not
patchable here: the profile has \[[PatchBotRequest]\], and ownership changes
go through \[[UpdateAgentRequest]\]. Unknown fields are refused, so a
misspelled or flattened setting is never silently ignored. *)

let patch_agent_request_of_yojson : Yojson.Safe.t -> patch_agent_request =
 fun json ->
  let fields = Json.obj json in
  {
    auto_accept_permissions =
      Json.optional fields "auto_accept_permissions" Json.bool;
    channels = Json.optional fields "channels" agent_channel_selection_of_yojson;
    default_model = Json.optional fields "default_model" Json.string;
    harness = Json.optional fields "harness" agent_harness_selection_of_yojson;
    instructions = Json.optional fields "instructions" Json.string;
    is_coding = Json.optional fields "is_coding" Json.bool;
    mcp = Json.optional fields "mcp" agent_mcp_servers_of_yojson;
  }

and yojson_of_patch_agent_request : patch_agent_request -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ( "auto_accept_permissions",
        Option.map Json.of_bool value.auto_accept_permissions );
      ("channels", Option.map yojson_of_agent_channel_selection value.channels);
      ("default_model", Option.map Json.of_string value.default_model);
      ("harness", Option.map yojson_of_agent_harness_selection value.harness);
      ("instructions", Option.map Json.of_string value.instructions);
      ("is_coding", Option.map Json.of_bool value.is_coding);
      ("mcp", Option.map yojson_of_agent_mcp_servers value.mcp);
    ]

let make_patch_agent_request ?auto_accept_permissions ?channels ?default_model
    ?harness ?instructions ?is_coding ?mcp () =
  ({
     auto_accept_permissions;
     channels;
     default_model;
     harness;
     instructions;
     is_coding;
     mcp;
   }
    : patch_agent_request)

