type nonrec post_message = {
  anchor : new_thread_anchor option;
  attachments : new_attachment list option;  (** Initial attachments. *)
  content : string;  (** Macro Markdown body. *)
  id : string option;
      (** Client-minted UUIDv7 for the new message, so an optimistic message
already carries its final id; the server mints one when absent. *)
  mentions : simple_mention list option;  (** Mentions tracked by the editor. *)
  nonce : string option;  (** Client nonce for optimistic reconciliation. *)
  thread_id : string option;  (** Root to reply to, if this is a reply. *)
}
(** Create a root or reply. Thread state may only be supplied on a root. *)

let post_message_of_yojson : Yojson.Safe.t -> post_message =
 fun json ->
  let fields = Json.obj json in
  {
    anchor = Json.optional fields "anchor" new_thread_anchor_of_yojson;
    attachments =
      Json.optional fields "attachments" (Json.list new_attachment_of_yojson);
    content = Json.required fields "content" Json.string;
    id = Json.optional fields "id" Json.string;
    mentions =
      Json.optional fields "mentions" (Json.list simple_mention_of_yojson);
    nonce = Json.optional fields "nonce" Json.string;
    thread_id = Json.optional fields "thread_id" Json.string;
  }

and yojson_of_post_message : post_message -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("anchor", Option.map yojson_of_new_thread_anchor value.anchor);
      ( "attachments",
        Option.map (Json.of_list yojson_of_new_attachment) value.attachments );
      ("content", Some (Json.of_string value.content));
      ("id", Option.map Json.of_string value.id);
      ( "mentions",
        Option.map (Json.of_list yojson_of_simple_mention) value.mentions );
      ("nonce", Option.map Json.of_string value.nonce);
      ("thread_id", Option.map Json.of_string value.thread_id);
    ]

let make_post_message ?anchor ?attachments ~(content : string) ?id ?mentions
    ?nonce ?thread_id () =
  ({ anchor; attachments; content; id; mentions; nonce; thread_id }
    : post_message)

type nonrec post_soup_ast_request = {
  asf : Yojson.Safe.t option;
      (** Filters applied to agent sessions (wire key [asf]). An empty or
omitted filter returns **no** agent sessions: they are opt-in, so the
caller must send [inc], an id, or an owner to get any. *)
  calf : Yojson.Safe.t option;
      (** filters applied to canonical calendar events *)
  callf : Yojson.Safe.t option;
      (** the filters that should be applied to the call entity *)
  ccf : Yojson.Safe.t option;
      (** Filters applied to the crm_company entity (wire key [ccf]).
Empty/omitted = team's full visible list. *)
  cf : Yojson.Safe.t option;
      (** the filters that should be applied to the chat entity *)
  chanf : Yojson.Safe.t option;
      (** the filters that should be applied to the channel entity *)
  crma : crm_association option;
  crmf : Yojson.Safe.t option;
      (** Opt-in filters for viewer-accessible CRM contacts (wire key [crmf]). *)
  cthf : Yojson.Safe.t option;
      (** the filters that should be applied to the channel-thread entity *)
  df : Yojson.Safe.t option;
      (** the filters that should be applied to the document entity *)
  eca : string list option;
      (** CRM-scoped address filter (wire key: [eca]). Symmetric counterpart
to [ecd] for fully-qualified email addresses. *)
  ecd : string list option;
      (** CRM-scoped domain filter (wire key: [ecd]). Parallel to the
freeform [ef] AST. Expanded by the router into an any-direction
OR sub-tree AND-merged into [ef], plus a [CrmScope] tag stamped
on the resulting \[[item_filters::ast::EmailFilterAst::crm_scope]\].
Drives the per-team CRM authorization pre-check and candidate-set
widening downstream. Mutually exclusive with [eca]. *)
  ef : Yojson.Safe.t option;
      (** the filters that should be applied to the email entity (raw AST
tree only; CRM scope is carried by the [ecd] / [eca] sibling
fields). On this endpoint the email filter stays a bare tree,
unlike the materialized \[[EntityFilterAst]\] used for cursors. *)
  favorites_only : bool option;
      (** Restrict to the authenticated viewer's favorites before pagination when true. *)
  fef : Yojson.Safe.t option;
      (** the filters that should be applied to foreign entity records *)
  ghprf : Yojson.Safe.t option;
      (** the filters that should be applied to GitHub pull request records, on top of [fef] *)
  if_ : Yojson.Safe.t option;
      (** Filters applied to initiatives (wire key [if]). Opt-in like agent
sessions: an omitted filter returns no initiatives, and any literal,
a notification state included, opts them in. *)
  pf : Yojson.Safe.t option;
      (** the filters that should be applied to the project entity *)
  propf : Yojson.Safe.t option;
      (** the filters that should be applied based on entity properties *)
  expand : bool option;  (** Whether to expand projects. Defaults to true. *)
  limit : int option;
      (** Limit the number of items returned. Defaults to 20. Max 500. *)
  sort_direction : soup_api_sort_direction option;
  sort_method : soup_api_sort option;
  sort_property_definition_id : string option;
      (** Property definition selected for numeric property sorting. *)
  email_view : string option;  (** the view of specific emails to display *)
}
(** Request body for the AST soup endpoint. *)

let post_soup_ast_request_of_yojson : Yojson.Safe.t -> post_soup_ast_request =
