    df = Json.optional fields "df" Json.json;
    eca = Json.optional fields "eca" (Json.list Json.string);
    ecd = Json.optional fields "ecd" (Json.list Json.string);
    ef = Json.optional fields "ef" Json.json;
    favorites_only = Json.optional fields "favorites_only" Json.bool;
    fef = Json.optional fields "fef" Json.json;
    ghprf = Json.optional fields "ghprf" Json.json;
    if_ = Json.optional fields "if" Json.json;
    pf = Json.optional fields "pf" Json.json;
    propf = Json.optional fields "propf" Json.json;
    expand = Json.optional fields "expand" Json.bool;
    limit = Json.optional fields "limit" Json.int;
    sort_direction =
      Json.optional fields "sort_direction" soup_api_sort_direction_of_yojson;
    sort_method = Json.optional fields "sort_method" soup_api_sort_of_yojson;
    sort_property_definition_id =
      Json.optional fields "sort_property_definition_id" Json.string;
    email_view = Json.optional fields "emailView" Json.string;
  }

and yojson_of_post_soup_ast_request : post_soup_ast_request -> Yojson.Safe.t =
