type nonrec save_bom_part = {
  path : string;  (** The file path of the bom part content *)
  sha : string;
      (** The sha of the bom part content
There is an index on sha for more performant queries based on it. *)
}

let save_bom_part_of_yojson : Yojson.Safe.t -> save_bom_part =
 fun json ->
  let fields = Json.obj json in
  {
    path = Json.required fields "path" Json.string;
    sha = Json.required fields "sha" Json.string;
  }

and yojson_of_save_bom_part : save_bom_part -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("path", Some (Json.of_string value.path));
      ("sha", Some (Json.of_string value.sha));
    ]

let make_save_bom_part ~(path : string) ~(sha : string) () =
  ({ path; sha } : save_bom_part)

type nonrec pre_save_document_request = {
  new_bom : save_bom_part list;
      (** The updated BOM for the document
Containing the file path and the sha *)
}

let pre_save_document_request_of_yojson :
    Yojson.Safe.t -> pre_save_document_request =
 fun json ->
  let fields = Json.obj json in
  {
    new_bom = Json.required fields "newBom" (Json.list save_bom_part_of_yojson);
  }

and yojson_of_pre_save_document_request :
    pre_save_document_request -> Yojson.Safe.t =
 fun value ->
  Json.record
    [ ("newBom", Some ((Json.of_list yojson_of_save_bom_part) value.new_bom)) ]

let make_pre_save_document_request ~(new_bom : save_bom_part list) () =
  ({ new_bom } : pre_save_document_request)

