(** The upload status of the document *)
type nonrec upload_document_status =
  | Pending
  | Completed
  | Failed
  | Unknown_
  | Unknown of string  (** A value this SDK version does not know. *)

let upload_document_status_of_yojson : Yojson.Safe.t -> upload_document_status =
 fun json ->
  match Json.string json with
  | "pending" -> Pending
  | "completed" -> Completed
  | "failed" -> Failed
  | "unknown" -> Unknown_
  | other -> Unknown other

and yojson_of_upload_document_status : upload_document_status -> Yojson.Safe.t =
 fun value ->
  match value with
  | Pending -> `String "pending"
  | Completed -> `String "completed"
  | Failed -> `String "failed"
  | Unknown_ -> `String "unknown"
  | Unknown other -> `String other

