(** What an entity column's references point at: a kind of Macro entity, or
the rows of another table for a relation.

Spelled as the properties system spells entity types ([USER],
[DATABASE_ROW]), on the wire and in SQL, where it parses
case-insensitively. *)
type nonrec sql_entity_kind =
  | User
  | Document
  | Task
  | Company
  | Contact
  | Call_record
  | Channel
  | Chat
  | Project
  | Thread
  | Calendar_event
  | Initiative
  | Database_row
  | Unknown of string  (** A value this SDK version does not know. *)

let sql_entity_kind_of_yojson : Yojson.Safe.t -> sql_entity_kind =
 fun json ->
  match Json.string json with
  | "USER" -> User
  | "DOCUMENT" -> Document
  | "TASK" -> Task
  | "COMPANY" -> Company
  | "CONTACT" -> Contact
  | "CALL_RECORD" -> Call_record
  | "CHANNEL" -> Channel
  | "CHAT" -> Chat
  | "PROJECT" -> Project
  | "THREAD" -> Thread
  | "CALENDAR_EVENT" -> Calendar_event
  | "INITIATIVE" -> Initiative
  | "DATABASE_ROW" -> Database_row
  | other -> Unknown other

and yojson_of_sql_entity_kind : sql_entity_kind -> Yojson.Safe.t =
 fun value ->
  match value with
  | User -> `String "USER"
  | Document -> `String "DOCUMENT"
  | Task -> `String "TASK"
  | Company -> `String "COMPANY"
  | Contact -> `String "CONTACT"
  | Call_record -> `String "CALL_RECORD"
  | Channel -> `String "CHANNEL"
  | Chat -> `String "CHAT"
  | Project -> `String "PROJECT"
  | Thread -> `String "THREAD"
  | Calendar_event -> `String "CALENDAR_EVENT"
  | Initiative -> `String "INITIATIVE"
  | Database_row -> `String "DATABASE_ROW"
  | Unknown other -> `String other

type nonrec result_column = {
  kind : sql_outcome_kind;  (** What its cells hold. *)
  name : string;  (** The name or alias the statement gave it. *)
  options : sql_select_option list option;
      (** For a select column, its options: its cells hold their ids. *)
  related_table : table_id option;
  target : sql_entity_kind option;
}
(** One result column, with what its cells mean. *)

let result_column_of_yojson : Yojson.Safe.t -> result_column =
 fun json ->
  let fields = Json.obj json in
  {
    kind = Json.required fields "kind" sql_outcome_kind_of_yojson;
    name = Json.required fields "name" Json.string;
    options =
      Json.optional fields "options" (Json.list sql_select_option_of_yojson);
    related_table = Json.optional fields "relatedTable" table_id_of_yojson;
    target = Json.optional fields "target" sql_entity_kind_of_yojson;
  }

and yojson_of_result_column : result_column -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("kind", Some (yojson_of_sql_outcome_kind value.kind));
      ("name", Some (Json.of_string value.name));
      ( "options",
        Option.map (Json.of_list yojson_of_sql_select_option) value.options );
      ("relatedTable", Option.map yojson_of_table_id value.related_table);
      ("target", Option.map yojson_of_sql_entity_kind value.target);
    ]

let make_result_column ~(kind : sql_outcome_kind) ~(name : string) ?options
    ?related_table ?target () =
  ({ kind; name; options; related_table; target } : result_column)

type nonrec row_id = string
(** Identifier of a row. *)

let row_id_of_yojson : Yojson.Safe.t -> row_id = fun json -> Json.string json

and yojson_of_row_id : row_id -> Yojson.Safe.t =
 fun value -> Json.of_string value

(** A cell as fetched. An absent cell is [NULL]; an absent multi-valued cell
is the empty set. *)
type nonrec sql_cell =
  | Text of { value : string  (** Text or link. *) }  (** Text or link. *)
  | Number of { value : float  (** A number. *) }  (** A number. *)
  | Bool of { value : bool  (** A checkbox. *) }  (** A checkbox. *)
  | Date of { value : string  (** A date-time. *) }  (** A date-time. *)
  | Date_range of {
      value : date_range;  (** A span from one date-time to another. *)
    }  (** A span from one date-time to another. *)
  | Options of {
      value : option_id list;
          (** The selected option ids; one for single-select columns. *)
    }  (** The selected option ids; one for single-select columns. *)
  | Entities of {
      value : string list;
          (** The referenced entity ids; one for single-valued columns. *)
    }  (** The referenced entity ids; one for single-valued columns. *)
  | Row of { value : row_id  (** A table row's own id, the [row_id] column. *) }
      (** A table row's own id, the [row_id] column. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let sql_cell_of_yojson : Yojson.Safe.t -> sql_cell =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "text" -> Text { value = Json.required fields "value" Json.string }
  | "number" -> Number { value = Json.required fields "value" Json.float }
  | "bool" -> Bool { value = Json.required fields "value" Json.bool }
  | "date" -> Date { value = Json.required fields "value" Json.string }
  | "dateRange" ->
      Date_range { value = Json.required fields "value" date_range_of_yojson }
  | "options" ->
      Options
        { value = Json.required fields "value" (Json.list option_id_of_yojson) }
  | "entities" ->
      Entities { value = Json.required fields "value" (Json.list Json.string) }
  | "row" -> Row { value = Json.required fields "value" row_id_of_yojson }
  | _ -> Unknown json

and yojson_of_sql_cell : sql_cell -> Yojson.Safe.t =
 fun value ->
  match value with
  | Text case ->
      Json.record
        [
          ("type", Some (`String "text"));
          ("value", Some (Json.of_string case.value));
        ]
  | Number case ->
      Json.record
        [
          ("type", Some (`String "number"));
          ("value", Some (Json.of_float case.value));
        ]
  | Bool case ->
      Json.record
        [
          ("type", Some (`String "bool"));
          ("value", Some (Json.of_bool case.value));
        ]
  | Date case ->
      Json.record
        [
          ("type", Some (`String "date"));
          ("value", Some (Json.of_string case.value));
        ]
  | Date_range case ->
      Json.record
        [
          ("type", Some (`String "dateRange"));
          ("value", Some (yojson_of_date_range case.value));
        ]
  | Options case ->
      Json.record
        [
          ("type", Some (`String "options"));
          ("value", Some ((Json.of_list yojson_of_option_id) case.value));
        ]
  | Entities case ->
      Json.record
        [
          ("type", Some (`String "entities"));
          ("value", Some ((Json.of_list Json.of_string) case.value));
        ]
  | Row case ->
      Json.record
        [
          ("type", Some (`String "row"));
          ("value", Some (yojson_of_row_id case.value));
        ]
  | Unknown json -> json

let make_sql_cell_text ~(value : string) () = (Text { value } : sql_cell)
let make_sql_cell_number ~(value : float) () = (Number { value } : sql_cell)
let make_sql_cell_bool ~(value : bool) () = (Bool { value } : sql_cell)
let make_sql_cell_date ~(value : string) () = (Date { value } : sql_cell)

let make_sql_cell_date_range ~(value : date_range) () =
  (Date_range { value } : sql_cell)

let make_sql_cell_options ~(value : option_id list) () =
  (Options { value } : sql_cell)

let make_sql_cell_entities ~(value : string list) () =
  (Entities { value } : sql_cell)

let make_sql_cell_row ~(value : row_id) () = (Row { value } : sql_cell)

type nonrec result_set = {
  columns : result_column list;  (** The columns, in select-list order. *)
  row_ids : row_id list;
      (** For a row-shaped result, the id of the row behind each result row;
empty for an aggregate. *)
  rows : sql_cell option list list;
      (** One cell per column per row; [null] is an empty cell. *)
  source_table : table_id option;
}
(** A [SELECT]'s rows, as the engine's typed cells. *)

let result_set_of_yojson : Yojson.Safe.t -> result_set =
 fun json ->
  let fields = Json.obj json in
  {
    columns = Json.required fields "columns" (Json.list result_column_of_yojson);
    row_ids = Json.required fields "rowIds" (Json.list row_id_of_yojson);
    rows =
      Json.required fields "rows"
        (Json.list (Json.list (Json.option sql_cell_of_yojson)));
    source_table = Json.optional fields "sourceTable" table_id_of_yojson;
  }

and yojson_of_result_set : result_set -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("columns", Some ((Json.of_list yojson_of_result_column) value.columns));
      ("rowIds", Some ((Json.of_list yojson_of_row_id) value.row_ids));
      ( "rows",
        Some
          ((Json.of_list (Json.of_list (Json.of_option yojson_of_sql_cell)))
             value.rows) );
      ("sourceTable", Option.map yojson_of_table_id value.source_table);
    ]

let make_result_set ~(columns : result_column list) ~(row_ids : row_id list)
    ~(rows : sql_cell option list list) ?source_table () =
  ({ columns; row_ids; rows; source_table } : result_set)

