type nonrec row_history_entry = {
  acting_bot : string option;  (** The agent acting for them, if one was. *)
  actor : string option;
      (** Who made it; [null] for an internal caller, or a removed user. *)
  after : (string * cell_value) list;
      (** Those columns' values it wrote, by column id; a cell it emptied is
left out. *)
  at : string;  (** When it committed. *)
  before : (string * cell_value) list;
      (** Those columns' values before it, by column id; an empty cell is
left out. *)
  change : int64;  (** The change's id in the journal. *)
  columns : string list;
      (** The columns it wrote; for a removal, those the row had values in. *)
  kind : row_change_kind;  (** How it touched the row. *)
  version : int64;  (** The table version it produced. *)
}
(** One change of a row, as its history shows it. *)

let row_history_entry_of_yojson : Yojson.Safe.t -> row_history_entry =
 fun json ->
  let fields = Json.obj json in
  {
    acting_bot = Json.optional fields "actingBot" Json.string;
    actor = Json.optional fields "actor" Json.string;
    after = Json.required fields "after" (Json.map cell_value_of_yojson);
    at = Json.required fields "at" Json.string;
    before = Json.required fields "before" (Json.map cell_value_of_yojson);
    change = Json.required fields "change" Json.int64;
    columns = Json.required fields "columns" (Json.list Json.string);
    kind = Json.required fields "kind" row_change_kind_of_yojson;
    version = Json.required fields "version" Json.int64;
  }

and yojson_of_row_history_entry : row_history_entry -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("actingBot", Some ((Json.of_option Json.of_string) value.acting_bot));
      ("actor", Some ((Json.of_option Json.of_string) value.actor));
      ("after", Some ((Json.of_map yojson_of_cell_value) value.after));
      ("at", Some (Json.of_string value.at));
      ("before", Some ((Json.of_map yojson_of_cell_value) value.before));
      ("change", Some (Json.of_int64 value.change));
      ("columns", Some ((Json.of_list Json.of_string) value.columns));
      ("kind", Some (yojson_of_row_change_kind value.kind));
      ("version", Some (Json.of_int64 value.version));
    ]

let make_row_history_entry ?acting_bot ?actor
    ~(after : (string * cell_value) list) ~(at : string)
    ~(before : (string * cell_value) list) ~(change : int64)
    ~(columns : string list) ~(kind : row_change_kind) ~(version : int64) () =
  ({ acting_bot; actor; after; at; before; change; columns; kind; version }
    : row_history_entry)

