(** An entity type with an existing Share surface. *)
type nonrec share_entity_type =
  | Document
  | Chat
  | Project
  | Initiative
  | Database
  | Call
  | Email_thread
  | Agent_session
  | External_chat
  | Harness
  | Unknown of string  (** A value this SDK version does not know. *)

let share_entity_type_of_yojson : Yojson.Safe.t -> share_entity_type =
 fun json ->
  match Json.string json with
  | "document" -> Document
  | "chat" -> Chat
  | "project" -> Project
  | "initiative" -> Initiative
  | "database" -> Database
  | "call" -> Call
  | "email_thread" -> Email_thread
  | "agent_session" -> Agent_session
  | "external_chat" -> External_chat
  | "harness" -> Harness
  | other -> Unknown other

and yojson_of_share_entity_type : share_entity_type -> Yojson.Safe.t =
 fun value ->
  match value with
  | Document -> `String "document"
  | Chat -> `String "chat"
  | Project -> `String "project"
  | Initiative -> `String "initiative"
  | Database -> `String "database"
  | Call -> `String "call"
  | Email_thread -> `String "email_thread"
  | Agent_session -> `String "agent_session"
  | External_chat -> `String "external_chat"
  | Harness -> `String "harness"
  | Unknown other -> `String other

