(** The calculation result kind. *)
type nonrec spreadsheet_value_kind =
  | Blank
  | Number
  | Text
  | Boolean
  | Error_
  | Unknown of string  (** A value this SDK version does not know. *)

let spreadsheet_value_kind_of_yojson : Yojson.Safe.t -> spreadsheet_value_kind =
 fun json ->
  match Json.string json with
  | "blank" -> Blank
  | "number" -> Number
  | "text" -> Text
  | "boolean" -> Boolean
  | "error" -> Error_
  | other -> Unknown other

and yojson_of_spreadsheet_value_kind : spreadsheet_value_kind -> Yojson.Safe.t =
 fun value ->
  match value with
  | Blank -> `String "blank"
  | Number -> `String "number"
  | Text -> `String "text"
  | Boolean -> `String "boolean"
  | Error_ -> `String "error"
  | Unknown other -> `String other

