(** Structured output from a deterministic workbook operation. *)
type nonrec spreadsheet_response =
  | Read of {
      ranges : spreadsheet_read_range list;
          (** Addressed cells with raw inputs and calculated results. *)
      revision : string;  (** Opaque revision required for EditSpreadsheet. *)
      sheets : spreadsheet_sheet_summary list;
          (** All visible sheets and their used bounds. *)
      warnings : string list;
          (** Limits or issues the caller should account for. *)
    }  (** Workbook inspection result. *)
  | Calculate of {
      results : spreadsheet_formula_result list;  (** Results in input order. *)
      revision : string;  (** Revision used for these calculations. *)
      warnings : string list;  (** Calculation limits or issues. *)
    }  (** Scratch calculation result. No persistent changes were made. *)
  | Edit of {
      applied : bool;  (** Whether a new change was persisted. *)
      changes : spreadsheet_change list;  (** Applied operation summaries. *)
      revision : string;
          (** Revision after the edit; use a fresh read before further editing. *)
      sheets : spreadsheet_sheet_summary list;
          (** Sheet metadata after editing. *)
      warnings : string list;
          (** Issues requiring inspection, including formula errors. *)
    }  (** Result of a persisted atomic edit. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let spreadsheet_response_of_yojson : Yojson.Safe.t -> spreadsheet_response =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "action" with
  | "read" ->
      Read
        {
          ranges =
            Json.required fields "ranges"
              (Json.list spreadsheet_read_range_of_yojson);
          revision = Json.required fields "revision" Json.string;
          sheets =
            Json.required fields "sheets"
              (Json.list spreadsheet_sheet_summary_of_yojson);
          warnings = Json.required fields "warnings" (Json.list Json.string);
        }
  | "calculate" ->
      Calculate
        {
          results =
            Json.required fields "results"
              (Json.list spreadsheet_formula_result_of_yojson);
          revision = Json.required fields "revision" Json.string;
          warnings = Json.required fields "warnings" (Json.list Json.string);
        }
  | "edit" ->
      Edit
        {
          applied = Json.required fields "applied" Json.bool;
          changes =
            Json.required fields "changes"
              (Json.list spreadsheet_change_of_yojson);
          revision = Json.required fields "revision" Json.string;
          sheets =
            Json.required fields "sheets"
              (Json.list spreadsheet_sheet_summary_of_yojson);
          warnings = Json.required fields "warnings" (Json.list Json.string);
        }
  | _ -> Unknown json

and yojson_of_spreadsheet_response : spreadsheet_response -> Yojson.Safe.t =
 fun value ->
  match value with
  | Read case ->
      Json.record
        [
          ("action", Some (`String "read"));
          ( "ranges",
            Some ((Json.of_list yojson_of_spreadsheet_read_range) case.ranges)
          );
          ("revision", Some (Json.of_string case.revision));
          ( "sheets",
            Some
              ((Json.of_list yojson_of_spreadsheet_sheet_summary) case.sheets)
          );
          ("warnings", Some ((Json.of_list Json.of_string) case.warnings));
        ]
  | Calculate case ->
      Json.record
        [
          ("action", Some (`String "calculate"));
          ( "results",
            Some
              ((Json.of_list yojson_of_spreadsheet_formula_result) case.results)
          );
          ("revision", Some (Json.of_string case.revision));
          ("warnings", Some ((Json.of_list Json.of_string) case.warnings));
        ]
  | Edit case ->
      Json.record
        [
          ("action", Some (`String "edit"));
          ("applied", Some (Json.of_bool case.applied));
          ( "changes",
            Some ((Json.of_list yojson_of_spreadsheet_change) case.changes) );
          ("revision", Some (Json.of_string case.revision));
          ( "sheets",
            Some
              ((Json.of_list yojson_of_spreadsheet_sheet_summary) case.sheets)
          );
          ("warnings", Some ((Json.of_list Json.of_string) case.warnings));
        ]
  | Unknown json -> json

let make_spreadsheet_response_read ~(ranges : spreadsheet_read_range list)
    ~(revision : string) ~(sheets : spreadsheet_sheet_summary list)
    ~(warnings : string list) () =
  (Read { ranges; revision; sheets; warnings } : spreadsheet_response)

let make_spreadsheet_response_calculate
    ~(results : spreadsheet_formula_result list) ~(revision : string)
    ~(warnings : string list) () =
  (Calculate { results; revision; warnings } : spreadsheet_response)

let make_spreadsheet_response_edit ~(applied : bool)
    ~(changes : spreadsheet_change list) ~(revision : string)
    ~(sheets : spreadsheet_sheet_summary list) ~(warnings : string list) () =
  (Edit { applied; changes; revision; sheets; warnings } : spreadsheet_response)

