(** The statement that ran: a read, or the table (and for a type change, the
column) it wrote. *)
type nonrec sql_statement =
  | Schema of {
      database_id : database_id;  (** Owning database. *)
      summary : string;
          (** What changed and how to read the resulting schema. *)
    }
      (** A committed schema command. IDs remain available even without a follow-up read. *)
  | Select  (** A [SELECT]. *)
  | Insert of {
      table_id : table_id;  (** The table written. *)
      table_name : string;  (** Its name. *)
    }  (** An [INSERT]. *)
  | Update of {
      table_id : table_id;  (** The table written. *)
      table_name : string;  (** Its name. *)
    }  (** An [UPDATE]. *)
  | Delete of {
      table_id : table_id;  (** The table written. *)
      table_name : string;  (** Its name. *)
    }  (** A [DELETE]. *)
  | Alter_column_type of {
      column_id : column_id;
          (** The column placement; its id survives the change. *)
      column_name : string;  (** The column's name. *)
      table_id : table_id;  (** The table. *)
      table_name : string;  (** Its name. *)
      to_ : string;
          (** The type it became, as SQL spells it, e.g. `select\[\]`. *)
    }  (** An [ALTER COLUMN … TYPE]. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let sql_statement_of_yojson : Yojson.Safe.t -> sql_statement =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "schema" ->
      Schema
        {
          database_id = Json.required fields "databaseId" database_id_of_yojson;
          summary = Json.required fields "summary" Json.string;
        }
  | "select" -> Select
  | "insert" ->
      Insert
        {
          table_id = Json.required fields "tableId" table_id_of_yojson;
          table_name = Json.required fields "tableName" Json.string;
        }
  | "update" ->
      Update
        {
          table_id = Json.required fields "tableId" table_id_of_yojson;
          table_name = Json.required fields "tableName" Json.string;
        }
  | "delete" ->
      Delete
        {
          table_id = Json.required fields "tableId" table_id_of_yojson;
          table_name = Json.required fields "tableName" Json.string;
        }
  | "alterColumnType" ->
      Alter_column_type
        {
          column_id = Json.required fields "columnId" column_id_of_yojson;
          column_name = Json.required fields "columnName" Json.string;
          table_id = Json.required fields "tableId" table_id_of_yojson;
          table_name = Json.required fields "tableName" Json.string;
          to_ = Json.required fields "to" Json.string;
        }
  | _ -> Unknown json

and yojson_of_sql_statement : sql_statement -> Yojson.Safe.t =
 fun value ->
  match value with
  | Schema case ->
      Json.record
        [
          ("kind", Some (`String "schema"));
          ("databaseId", Some (yojson_of_database_id case.database_id));
          ("summary", Some (Json.of_string case.summary));
        ]
  | Select -> Json.record [ ("kind", Some (`String "select")) ]
  | Insert case ->
      Json.record
        [
          ("kind", Some (`String "insert"));
          ("tableId", Some (yojson_of_table_id case.table_id));
          ("tableName", Some (Json.of_string case.table_name));
        ]
  | Update case ->
      Json.record
        [
          ("kind", Some (`String "update"));
          ("tableId", Some (yojson_of_table_id case.table_id));
          ("tableName", Some (Json.of_string case.table_name));
        ]
  | Delete case ->
      Json.record
        [
          ("kind", Some (`String "delete"));
          ("tableId", Some (yojson_of_table_id case.table_id));
          ("tableName", Some (Json.of_string case.table_name));
        ]
  | Alter_column_type case ->
      Json.record
        [
          ("kind", Some (`String "alterColumnType"));
          ("columnId", Some (yojson_of_column_id case.column_id));
          ("columnName", Some (Json.of_string case.column_name));
          ("tableId", Some (yojson_of_table_id case.table_id));
          ("tableName", Some (Json.of_string case.table_name));
          ("to", Some (Json.of_string case.to_));
        ]
  | Unknown json -> json

let make_sql_statement_schema ~(database_id : database_id) ~(summary : string)
    () =
  (Schema { database_id; summary } : sql_statement)

let make_sql_statement_insert ~(table_id : table_id) ~(table_name : string) () =
  (Insert { table_id; table_name } : sql_statement)

let make_sql_statement_update ~(table_id : table_id) ~(table_name : string) () =
  (Update { table_id; table_name } : sql_statement)

let make_sql_statement_delete ~(table_id : table_id) ~(table_name : string) () =
  (Delete { table_id; table_name } : sql_statement)

let make_sql_statement_alter_column_type ~(column_id : column_id)
    ~(column_name : string) ~(table_id : table_id) ~(table_name : string)
    ~(to_ : string) () =
  (Alter_column_type { column_id; column_name; table_id; table_name; to_ }
    : sql_statement)

type nonrec sql_outcome = {
  changes_applied : int;  (** How many rows a write changed. *)
  inserted_row_ids : row_id list;
      (** The rows an [INSERT] created, in statement order. *)
  new_versions : (string * table_version) list;
      (** The new version of every table written. *)
  read_versions : (string * table_version) list;
      (** The version of every table read, for a follow-up write to guard on. *)
  result : result_set option;
  statement : sql_statement;
      (** What kind of statement ran, and what it wrote. *)
  table_databases : (string * database_id) list;
      (** Owning database of each visible table referenced by this outcome. *)
  truncated_tables : string list;
      (** Every table the statement read, when any read hit the engine's row
cap: the engine reports the cap per statement, so aggregates over any
of them may be partial. *)
}
(** The answer to one statement. *)

let sql_outcome_of_yojson : Yojson.Safe.t -> sql_outcome =
 fun json ->
  let fields = Json.obj json in
  {
    changes_applied = Json.required fields "changesApplied" Json.int;
    inserted_row_ids =
      Json.required fields "insertedRowIds" (Json.list row_id_of_yojson);
    new_versions =
      Json.required fields "newVersions" (Json.map table_version_of_yojson);
    read_versions =
      Json.required fields "readVersions" (Json.map table_version_of_yojson);
    result = Json.optional fields "result" result_set_of_yojson;
    statement = Json.required fields "statement" sql_statement_of_yojson;
    table_databases =
      Json.required fields "tableDatabases" (Json.map database_id_of_yojson);
    truncated_tables =
      Json.required fields "truncatedTables" (Json.list Json.string);
  }

and yojson_of_sql_outcome : sql_outcome -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("changesApplied", Some (Json.of_int value.changes_applied));
      ( "insertedRowIds",
        Some ((Json.of_list yojson_of_row_id) value.inserted_row_ids) );
      ( "newVersions",
        Some ((Json.of_map yojson_of_table_version) value.new_versions) );
      ( "readVersions",
        Some ((Json.of_map yojson_of_table_version) value.read_versions) );
      ("result", Option.map yojson_of_result_set value.result);
      ("statement", Some (yojson_of_sql_statement value.statement));
      ( "tableDatabases",
        Some ((Json.of_map yojson_of_database_id) value.table_databases) );
      ( "truncatedTables",
        Some ((Json.of_list Json.of_string) value.truncated_tables) );
    ]

let make_sql_outcome ~(changes_applied : int) ~(inserted_row_ids : row_id list)
    ~(new_versions : (string * table_version) list)
    ~(read_versions : (string * table_version) list) ?result
    ~(statement : sql_statement)
    ~(table_databases : (string * database_id) list)
    ~(truncated_tables : string list) () =
  ({
     changes_applied;
     inserted_row_ids;
     new_versions;
     read_versions;
     result;
     statement;
     table_databases;
     truncated_tables;
   }
    : sql_outcome)

