let stored_github_pull_request_status_of_yojson :
    Yojson.Safe.t -> stored_github_pull_request_status =
 fun json ->
  match Json.string json with
  | "open" -> Open
  | "closed" -> Closed
  | "merged" -> Merged
  | other -> Unknown other

and yojson_of_stored_github_pull_request_status :
    stored_github_pull_request_status -> Yojson.Safe.t =
 fun value ->
  match value with
  | Open -> `String "open"
  | Closed -> `String "closed"
  | Merged -> `String "merged"
  | Unknown other -> `String other

type nonrec stored_github_pull_request = {
  additions : int64 option;
      (** Lines added across the pull request's changes. *)
  assignees : github_pull_request_user list;
      (** The users assigned to the pull request. *)
  author_github_user_id : string option;
      (** Stable numeric GitHub user id of the author. *)
  author_login : string option;
      (** The author's GitHub login when the pull request was last synced. *)
  base : git_ref_dto option;
  checks : github_pull_request_check_run list;
      (** The latest check runs on the pull request's head commit. *)
  comments : github_pull_request_comment list;
      (** Comments from the pull request's conversation, reviews, and review threads.
Comment [authorId] intentionally retains the shared numeric GitHub comment contract;
convert it to a decimal string before comparing it with [authorGithubUserId]. *)
  deletions : int64 option;
      (** Lines deleted across the pull request's changes. *)
  description : string option;
      (** The pull request body, as GitHub markdown. *)
  draft : bool;  (** Whether the pull request is a draft. *)
  github_key : string;  (** The pull request's [owner/repo/pull/number] key. *)
  github_updated_at : string option;
      (** When GitHub last updated the pull request. *)
  head : git_ref_dto option;
  id : string;  (** The caller's record for the pull request. *)
  labels : github_pull_request_label list;  (** The pull request's labels. *)
  number : int64;  (** The pull request number within its repository. *)
  owner : string;
      (** The repository owner the pull request was last synced under. *)
  repo : string;
      (** The repository name the pull request was last synced under. *)
  requested_reviewer_github_user_ids : string list;
      (** Stable numeric GitHub user ids of the users asked to review. *)
  review_decision : github_pull_request_review_decision option;
  reviews : github_pull_request_review list;
      (** Each reviewer's latest submitted review. *)
  status : stored_github_pull_request_status option;
      (** The normalized pull request status. *)
  title : string option;  (** The pull request title. *)
  url : string;  (** The pull request's page on GitHub. *)
}
(** A GitHub pull request as Macro stores it, read through one of the caller's records. *)

let stored_github_pull_request_of_yojson :
    Yojson.Safe.t -> stored_github_pull_request =
 fun json ->
  let fields = Json.obj json in
  {
    additions = Json.optional fields "additions" Json.int64;
    assignees =
      Json.required fields "assignees"
        (Json.list github_pull_request_user_of_yojson);
    author_github_user_id =
      Json.optional fields "authorGithubUserId" Json.string;
    author_login = Json.optional fields "authorLogin" Json.string;
    base = Json.optional fields "base" git_ref_dto_of_yojson;
    checks =
      Json.required fields "checks"
        (Json.list github_pull_request_check_run_of_yojson);
    comments =
      Json.required fields "comments"
        (Json.list github_pull_request_comment_of_yojson);
    deletions = Json.optional fields "deletions" Json.int64;
    description = Json.optional fields "description" Json.string;
    draft = Json.required fields "draft" Json.bool;
    github_key = Json.required fields "githubKey" Json.string;
    github_updated_at = Json.optional fields "githubUpdatedAt" Json.string;
    head = Json.optional fields "head" git_ref_dto_of_yojson;
    id = Json.required fields "id" Json.string;
    labels =
      Json.required fields "labels"
        (Json.list github_pull_request_label_of_yojson);
    number = Json.required fields "number" Json.int64;
    owner = Json.required fields "owner" Json.string;
    repo = Json.required fields "repo" Json.string;
    requested_reviewer_github_user_ids =
      Json.required fields "requestedReviewerGithubUserIds"
        (Json.list Json.string);
    review_decision =
      Json.optional fields "reviewDecision"
        github_pull_request_review_decision_of_yojson;
    reviews =
      Json.required fields "reviews"
        (Json.list github_pull_request_review_of_yojson);
    status =
      Json.optional fields "status" stored_github_pull_request_status_of_yojson;
    title = Json.optional fields "title" Json.string;
    url = Json.required fields "url" Json.string;
  }

and yojson_of_stored_github_pull_request :
    stored_github_pull_request -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("additions", Option.map Json.of_int64 value.additions);
      ( "assignees",
        Some ((Json.of_list yojson_of_github_pull_request_user) value.assignees)
      );
      ( "authorGithubUserId",
        Option.map Json.of_string value.author_github_user_id );
      ("authorLogin", Option.map Json.of_string value.author_login);
      ("base", Option.map yojson_of_git_ref_dto value.base);
      ( "checks",
        Some
          ((Json.of_list yojson_of_github_pull_request_check_run) value.checks)
      );
      ( "comments",
        Some
          ((Json.of_list yojson_of_github_pull_request_comment) value.comments)
      );
      ("deletions", Option.map Json.of_int64 value.deletions);
      ("description", Option.map Json.of_string value.description);
      ("draft", Some (Json.of_bool value.draft));
      ("githubKey", Some (Json.of_string value.github_key));
      ("githubUpdatedAt", Option.map Json.of_string value.github_updated_at);
      ("head", Option.map yojson_of_git_ref_dto value.head);
      ("id", Some (Json.of_string value.id));
      ( "labels",
        Some ((Json.of_list yojson_of_github_pull_request_label) value.labels)
      );
      ("number", Some (Json.of_int64 value.number));
      ("owner", Some (Json.of_string value.owner));
      ("repo", Some (Json.of_string value.repo));
      ( "requestedReviewerGithubUserIds",
        Some
          ((Json.of_list Json.of_string)
             value.requested_reviewer_github_user_ids) );
      ( "reviewDecision",
        Option.map yojson_of_github_pull_request_review_decision
          value.review_decision );
      ( "reviews",
        Some ((Json.of_list yojson_of_github_pull_request_review) value.reviews)
      );
      ( "status",
        Option.map yojson_of_stored_github_pull_request_status value.status );
      ("title", Option.map Json.of_string value.title);
      ("url", Some (Json.of_string value.url));
    ]

let make_stored_github_pull_request ?additions
    ~(assignees : github_pull_request_user list) ?author_github_user_id
    ?author_login ?base ~(checks : github_pull_request_check_run list)
    ~(comments : github_pull_request_comment list) ?deletions ?description
    ~(draft : bool) ~(github_key : string) ?github_updated_at ?head
    ~(id : string) ~(labels : github_pull_request_label list) ~(number : int64)
    ~(owner : string) ~(repo : string)
    ~(requested_reviewer_github_user_ids : string list) ?review_decision
    ~(reviews : github_pull_request_review list) ?status ?title ~(url : string)
