type nonrec submission = {
  answers : answer list;
      (** One answer per answered question; a question left out is unanswered. *)
}
(** A whole set of answers, sent at once. *)

let submission_of_yojson : Yojson.Safe.t -> submission =
 fun json ->
  let fields = Json.obj json in
  { answers = Json.required fields "answers" (Json.list answer_of_yojson) }

and yojson_of_submission : submission -> Yojson.Safe.t =
 fun value ->
  Json.record
    [ ("answers", Some ((Json.of_list yojson_of_answer) value.answers)) ]

let make_submission ~(answers : answer list) () = ({ answers } : submission)

(** What a submission came to. *)
type nonrec submission_outcome =
  | Submitted of {
      booking : unlocked_booking option;
          (** The form's booking step, unlocked by this accepted response. *)
      response : string;  (** The ledger entry. *)
      row : string;  (** The row holding the answers. *)
    }  (** The answers are saved as a row of the form's table. *)
  | Stopped of {
      message : string;  (** The gate's message. *)
      section : string;  (** The gate. *)
    }  (** A gate stopped the response; nothing was written to the table. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let submission_outcome_of_yojson : Yojson.Safe.t -> submission_outcome =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "outcome" with
  | "submitted" ->
      Submitted
        {
          booking = Json.optional fields "booking" unlocked_booking_of_yojson;
          response = Json.required fields "response" Json.string;
          row = Json.required fields "row" Json.string;
        }
  | "stopped" ->
      Stopped
        {
          message = Json.required fields "message" Json.string;
          section = Json.required fields "section" Json.string;
        }
  | _ -> Unknown json

and yojson_of_submission_outcome : submission_outcome -> Yojson.Safe.t =
 fun value ->
  match value with
  | Submitted case ->
      Json.record
        [
          ("outcome", Some (`String "submitted"));
          ("booking", Option.map yojson_of_unlocked_booking case.booking);
          ("response", Some (Json.of_string case.response));
          ("row", Some (Json.of_string case.row));
        ]
  | Stopped case ->
      Json.record
        [
          ("outcome", Some (`String "stopped"));
          ("message", Some (Json.of_string case.message));
          ("section", Some (Json.of_string case.section));
        ]
  | Unknown json -> json

let make_submission_outcome_submitted ?booking ~(response : string)
    ~(row : string) () =
  (Submitted { booking; response; row } : submission_outcome)

let make_submission_outcome_stopped ~(message : string) ~(section : string) () =
  (Stopped { message; section } : submission_outcome)

