  column : string;  (** The column. *)
  kind : column_change_kind;  (** How. *)
}
(** A column a table's changes since some version touched. *)

let touched_column_of_yojson : Yojson.Safe.t -> touched_column =
 fun json ->
  let fields = Json.obj json in
  {
    column = Json.required fields "column" Json.string;
    kind = Json.required fields "kind" column_change_kind_of_yojson;
  }

