  ({ column; kind } : touched_column)

type nonrec touched_row = {
  kind : row_change_kind;
      (** How it changed overall: added, written, or removed. *)
  row : string;  (** The row. *)
}
(** A row a table's changes since some version touched, and how it stands. *)

let touched_row_of_yojson : Yojson.Safe.t -> touched_row =
 fun json ->
  let fields = Json.obj json in
  {
    kind = Json.required fields "kind" row_change_kind_of_yojson;
    row = Json.required fields "row" Json.string;
  }

