type nonrec table_changes = {
  columns : touched_column list;
      (** The columns that changed; any of them means the table's shape moved. *)
  complete : bool;
      (** Whether every version since is journaled; without it, read the table
whole. *)
  rows : touched_row list;
      (** The rows that changed, each once, as they stand now: a row added
and written is [insert], one removed is [delete], and one added and
removed since is left out. *)
  truncated : bool;
      (** Whether more rows changed than are listed; then read the table whole. *)
  version : int64;  (** The version the changes reach. *)
}
(** What changed in a table since a version, for a reader holding it at
that version. *)

let table_changes_of_yojson : Yojson.Safe.t -> table_changes =
 fun json ->
  let fields = Json.obj json in
  {
    columns =
      Json.required fields "columns" (Json.list touched_column_of_yojson);
    complete = Json.required fields "complete" Json.bool;
    rows = Json.required fields "rows" (Json.list touched_row_of_yojson);
    truncated = Json.required fields "truncated" Json.bool;
    version = Json.required fields "version" Json.int64;
  }

and yojson_of_table_changes : table_changes -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("columns", Some ((Json.of_list yojson_of_touched_column) value.columns));
      ("complete", Some (Json.of_bool value.complete));
      ("rows", Some ((Json.of_list yojson_of_touched_row) value.rows));
      ("truncated", Some (Json.of_bool value.truncated));
      ("version", Some (Json.of_int64 value.version));
    ]

let make_table_changes ~(columns : touched_column list) ~(complete : bool)
    ~(rows : touched_row list) ~(truncated : bool) ~(version : int64) () =
  ({ columns; complete; rows; truncated; version } : table_changes)

