(** Why an undo was refused. Nothing was written. *)
type nonrec undo_refusal =
  | Row_in_use
  | Option_in_use
  | Not_yours
  | Not_undoable
  | Row_edited_since
  | Column_written_since
  | Changed_since
  | Already_back
  | Unknown of string  (** A value this SDK version does not know. *)

let undo_refusal_of_yojson : Yojson.Safe.t -> undo_refusal =
 fun json ->
  match Json.string json with
  | "row_in_use" -> Row_in_use
  | "option_in_use" -> Option_in_use
  | "not_yours" -> Not_yours
  | "not_undoable" -> Not_undoable
  | "row_edited_since" -> Row_edited_since
  | "column_written_since" -> Column_written_since
  | "changed_since" -> Changed_since
  | "already_back" -> Already_back
  | other -> Unknown other

and yojson_of_undo_refusal : undo_refusal -> Yojson.Safe.t =
 fun value ->
  match value with
  | Row_in_use -> `String "row_in_use"
  | Option_in_use -> `String "option_in_use"
  | Not_yours -> `String "not_yours"
  | Not_undoable -> `String "not_undoable"
  | Row_edited_since -> `String "row_edited_since"
  | Column_written_since -> `String "column_written_since"
  | Changed_since -> `String "changed_since"
  | Already_back -> `String "already_back"
  | Unknown other -> `String other

(** What undoing a change did. *)
type nonrec undo_outcome =
  | Reverted of {
      changes : committed_change list;
          (** The journal's changes the undo made, one per table version; undo
one of them to redo. *)
    }  (** Everything the change did is undone. *)
  | Partial of {
      changes : committed_change list;
          (** The journal's changes the undo made. *)
      skipped : skipped_cell list;
          (** The cells left alone, each with who changed it. *)
    }
      (** Some cells were changed by someone since, and were left alone; the
rest is undone. With no changes, nothing was left to undo. *)
  | Refused of {
      by : string option;  (** Whose change stands in the way, when one does. *)
      reason : undo_refusal;  (** Why. *)
    }  (** Nothing was undone. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let undo_outcome_of_yojson : Yojson.Safe.t -> undo_outcome =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "kind" with
  | "reverted" ->
      Reverted
        {
          changes =
            Json.required fields "changes"
              (Json.list committed_change_of_yojson);
        }
  | "partial" ->
      Partial
        {
          changes =
            Json.required fields "changes"
              (Json.list committed_change_of_yojson);
          skipped =
            Json.required fields "skipped" (Json.list skipped_cell_of_yojson);
        }
  | "refused" ->
      Refused
        {
          by = Json.optional fields "by" Json.string;
          reason = Json.required fields "reason" undo_refusal_of_yojson;
        }
  | _ -> Unknown json

and yojson_of_undo_outcome : undo_outcome -> Yojson.Safe.t =
 fun value ->
  match value with
  | Reverted case ->
      Json.record
        [
          ("kind", Some (`String "reverted"));
          ( "changes",
            Some ((Json.of_list yojson_of_committed_change) case.changes) );
        ]
  | Partial case ->
      Json.record
        [
          ("kind", Some (`String "partial"));
          ( "changes",
            Some ((Json.of_list yojson_of_committed_change) case.changes) );
          ("skipped", Some ((Json.of_list yojson_of_skipped_cell) case.skipped));
        ]
  | Refused case ->
      Json.record
        [
          ("kind", Some (`String "refused"));
          ("by", Some ((Json.of_option Json.of_string) case.by));
          ("reason", Some (yojson_of_undo_refusal case.reason));
        ]
  | Unknown json -> json

let make_undo_outcome_reverted ~(changes : committed_change list) () =
  (Reverted { changes } : undo_outcome)

let make_undo_outcome_partial ~(changes : committed_change list)
    ~(skipped : skipped_cell list) () =
  (Partial { changes; skipped } : undo_outcome)

let make_undo_outcome_refused ?by ~(reason : undo_refusal) () =
  (Refused { by; reason } : undo_outcome)

type nonrec undo_change_response = {
  outcome : undo_outcome;
      (** The outcome: reverted, partly reverted with the cells others changed
since left alone, or refused with why and whose change stands in the
way. *)
}
(** What undoing a change did. *)

let undo_change_response_of_yojson : Yojson.Safe.t -> undo_change_response =
 fun json ->
  let fields = Json.obj json in
  { outcome = Json.required fields "outcome" undo_outcome_of_yojson }

and yojson_of_undo_change_response : undo_change_response -> Yojson.Safe.t =
 fun value ->
  Json.record [ ("outcome", Some (yojson_of_undo_outcome value.outcome)) ]

let make_undo_change_response ~(outcome : undo_outcome) () =
  ({ outcome } : undo_change_response)

