(** The upload status of the folder *)
type nonrec upload_folder_status =
  | Pending
  | Uploaded
  | Processing
  | Partially_completed
  | Completed
  | Failed
  | Unknown_
  | Unknown of string  (** A value this SDK version does not know. *)

let upload_folder_status_of_yojson : Yojson.Safe.t -> upload_folder_status =
 fun json ->
  match Json.string json with
  | "pending" -> Pending
  | "uploaded" -> Uploaded
  | "processing" -> Processing
  | "partially_completed" -> Partially_completed
  | "completed" -> Completed
  | "failed" -> Failed
  | "unknown" -> Unknown_
  | other -> Unknown other

and yojson_of_upload_folder_status : upload_folder_status -> Yojson.Safe.t =
 fun value ->
  match value with
  | Pending -> `String "pending"
  | Uploaded -> `String "uploaded"
  | Processing -> `String "processing"
  | Partially_completed -> `String "partially_completed"
  | Completed -> `String "completed"
  | Failed -> `String "failed"
  | Unknown_ -> `String "unknown"
  | Unknown other -> `String other

type nonrec upload_grant = {
  descriptor : upload_descriptor;
      (** Exact immutable descriptor being signed. *)
  expires_at : string;
      (** Grant expiry; callers renew by re-registering the identical descriptor. *)
  required_headers : (string * string) list;
      (** Required signed upload headers (including checksum, content type and create-only
condition). Browser-forbidden Content-Length is derived from the exact Blob bytes. *)
  url : string;  (** Short-lived signed destination; must not be logged. *)
}
(** Signed upload permission returned just before PUT; never persisted as an identity. *)

let upload_grant_of_yojson : Yojson.Safe.t -> upload_grant =
 fun json ->
  let fields = Json.obj json in
  {
    descriptor = Json.required fields "descriptor" upload_descriptor_of_yojson;
    expires_at = Json.required fields "expiresAt" Json.string;
    required_headers =
      Json.required fields "requiredHeaders" (Json.map Json.string);
    url = Json.required fields "url" Json.string;
  }

and yojson_of_upload_grant : upload_grant -> Yojson.Safe.t =
 fun value ->
  Json.record
    [
      ("descriptor", Some (yojson_of_upload_descriptor value.descriptor));
      ("expiresAt", Some (Json.of_string value.expires_at));
      ( "requiredHeaders",
        Some ((Json.of_map Json.of_string) value.required_headers) );
      ("url", Some (Json.of_string value.url));
    ]

let make_upload_grant ~(descriptor : upload_descriptor) ~(expires_at : string)
    ~(required_headers : (string * string) list) ~(url : string) () =
  ({ descriptor; expires_at; required_headers; url } : upload_grant)

