(** Any entity event deliverable to a webhook endpoint.

Serialized bodies carry an [event_type] tag naming the event (for example
[document.created] or [message.posted]) and a [metadata] object
with the event payload. Endpoint validation additionally sends a
[WebhookValidationTestEvent], which is not part of this union. *)
type nonrec webhook_event =
  | Document_topic_event of document_topic_event
      (** Document lifecycle events from the [macro.documents] topic. *)
  | Channel_topic_event of channel_topic_event
      (** Channel lifecycle events from the [macro.channels] topic. *)
  | Call_notification_event of call_notification_event
      (** Access-checked call notifications from [macro.call_notifications]. *)
  | Message_topic_event of message_topic_event
      (** Message facts for channels and documents from the [macro.messages] topic. *)
  | Agent_session_lifecycle_event of agent_session_lifecycle_event
      (** Agent session lifecycle events from the [macro.agent_session_lifecycle]
topic. *)
  | User_topic_event of user_topic_event
      (** User profile events from the [macro.users] topic. *)

let webhook_event_of_yojson : Yojson.Safe.t -> webhook_event =
 fun json ->
  Json.first_ok
    [
      (fun json ->
        Document_topic_event
          (match document_topic_event_of_yojson json with
          | Unknown _ -> Json.fail "unknown value"
          | known -> known));
      (fun json ->
        Channel_topic_event
          (match channel_topic_event_of_yojson json with
          | Unknown _ -> Json.fail "unknown value"
          | known -> known));
      (fun json ->
        Call_notification_event
          (match call_notification_event_of_yojson json with
          | Unknown _ -> Json.fail "unknown value"
          | known -> known));
      (fun json ->
        Message_topic_event
          (match message_topic_event_of_yojson json with
          | Unknown _ -> Json.fail "unknown value"
          | known -> known));
      (fun json ->
        Agent_session_lifecycle_event
          (match agent_session_lifecycle_event_of_yojson json with
          | Unknown _ -> Json.fail "unknown value"
          | known -> known));
      (fun json ->
        User_topic_event
          (match user_topic_event_of_yojson json with
          | Unknown _ -> Json.fail "unknown value"
          | known -> known));
    ]
    json

and yojson_of_webhook_event : webhook_event -> Yojson.Safe.t =
 fun value ->
  match value with
  | Document_topic_event inner -> yojson_of_document_topic_event inner
  | Channel_topic_event inner -> yojson_of_channel_topic_event inner
  | Call_notification_event inner -> yojson_of_call_notification_event inner
  | Message_topic_event inner -> yojson_of_message_topic_event inner
  | Agent_session_lifecycle_event inner ->
      yojson_of_agent_session_lifecycle_event inner
  | User_topic_event inner -> yojson_of_user_topic_event inner

