 fun value ->
  Json.record
    [
      ("challenge", Option.map Json.of_json value.challenge);
      ("code", Option.map Json.of_string value.code);
      ("expiresAt", Some (Json.of_string value.expires_at));
      ("identityJid", Option.map Json.of_string value.identity_jid);
      ("qr", Option.map Json.of_string value.qr);
      ("state", Some (yojson_of_whats_app_pairing_state value.state));
    ]

