(** One change to a Word document's body. Ids are the paragraph, table and
block ids [ReadWordDocument] reports. *)
type nonrec word_document_operation =
  | Replace_text of {
      find : string;  (** Exact text to find in that paragraph's plain text. *)
      occurrence : int option;
          (** Which match (1-based) when [find] appears more than once. *)
      paragraph : string;  (** Paragraph id. *)
      replace : string;
          (** Replacement text, empty to delete. No line breaks; tabs are kept. *)
    }
      (** Replace text inside one paragraph. The new text takes the formatting of
the text it replaces; everything else in the paragraph is kept. *)
  | Set_text of {
      paragraph : string;  (** Paragraph id. *)
      text : string;
          (** The new text. No line breaks; use insertParagraph for more paragraphs. *)
    }
      (** Rewrite a paragraph's whole text, keeping its style and the formatting
of its first run. *)
  | Format_text of {
      bold : bool option;  (** Bold. *)
      find : string option;
          (** Exact text to format; omit for the whole paragraph. *)
      italic : bool option;  (** Italic. *)
      occurrence : int option;
          (** Which match (1-based) when [find] appears more than once. *)
      paragraph : string;  (** Paragraph id. *)
      strikethrough : bool option;  (** Strikethrough. *)
      underline : bool option;  (** Single underline. *)
    }
      (** Turn character formatting on or off for found text, or the whole
paragraph when [find] is omitted. Omitted properties are unchanged. *)
  | Insert_paragraph of {
      after : string option;  (** Insert after this paragraph or block id. *)
      before : string option;  (** Insert before this paragraph or block id. *)
      style : string option;
          (** Paragraph style id or name. Omitted: after a heading the style's
next style (usually Normal), otherwise the neighbour's formatting. *)
      text : string;  (** Text; newlines separate paragraphs. *)
    }
      (** Insert paragraphs next to a paragraph or block; each line of [text]
becomes one paragraph. Inside a table cell they stay in that cell. *)
  | Delete of { id : string  (** Paragraph, table or block id. *) }
      (** Delete a paragraph, table or other block. *)
  | Set_style of {
      paragraph : string;  (** Paragraph id. *)
      style : string;
          (** Paragraph style id or name, from the list ReadWordDocument shows. *)
    }
      (** Apply a paragraph style, such as Heading1, Title, Normal or ListBullet. *)
  | Add_comment of {
      find : string option;
          (** Exact text to comment on; omit for the whole paragraph. *)
      occurrence : int option;
          (** Which match (1-based) when [find] appears more than once. *)
      paragraph : string;  (** Paragraph id. *)
      text : string;  (** The comment. Newlines separate its paragraphs. *)
    }
      (** Add a Word comment on found text, or on the whole paragraph when
[find] is omitted. The comment is written into the file, attributed
to the edit's author, so it travels with the document into Word. *)
  | Unknown of Yojson.Safe.t
      (** A case this SDK version does not know, as received. *)

let word_document_operation_of_yojson : Yojson.Safe.t -> word_document_operation
    =
 fun json ->
  let fields = Json.obj json in
  match Json.tag fields "type" with
  | "replaceText" ->
      Replace_text
        {
          find = Json.required fields "find" Json.string;
          occurrence = Json.optional fields "occurrence" Json.int;
          paragraph = Json.required fields "paragraph" Json.string;
          replace = Json.required fields "replace" Json.string;
        }
  | "setText" ->
      Set_text
        {
          paragraph = Json.required fields "paragraph" Json.string;
          text = Json.required fields "text" Json.string;
        }
  | "formatText" ->
      Format_text
        {
          bold = Json.optional fields "bold" Json.bool;
          find = Json.optional fields "find" Json.string;
          italic = Json.optional fields "italic" Json.bool;
          occurrence = Json.optional fields "occurrence" Json.int;
          paragraph = Json.required fields "paragraph" Json.string;
          strikethrough = Json.optional fields "strikethrough" Json.bool;
          underline = Json.optional fields "underline" Json.bool;
        }
  | "insertParagraph" ->
      Insert_paragraph
        {
          after = Json.optional fields "after" Json.string;
          before = Json.optional fields "before" Json.string;
          style = Json.optional fields "style" Json.string;
          text = Json.required fields "text" Json.string;
        }
  | "delete" -> Delete { id = Json.required fields "id" Json.string }
  | "setStyle" ->
      Set_style
        {
          paragraph = Json.required fields "paragraph" Json.string;
          style = Json.required fields "style" Json.string;
        }
  | "addComment" ->
      Add_comment
        {
          find = Json.optional fields "find" Json.string;
          occurrence = Json.optional fields "occurrence" Json.int;
          paragraph = Json.required fields "paragraph" Json.string;
          text = Json.required fields "text" Json.string;
        }
  | _ -> Unknown json

and yojson_of_word_document_operation : word_document_operation -> Yojson.Safe.t
    =
 fun value ->
  match value with
  | Replace_text case ->
      Json.record
        [
          ("type", Some (`String "replaceText"));
          ("find", Some (Json.of_string case.find));
          ("occurrence", Option.map Json.of_int case.occurrence);
          ("paragraph", Some (Json.of_string case.paragraph));
          ("replace", Some (Json.of_string case.replace));
        ]
  | Set_text case ->
      Json.record
        [
          ("type", Some (`String "setText"));
          ("paragraph", Some (Json.of_string case.paragraph));
          ("text", Some (Json.of_string case.text));
        ]
  | Format_text case ->
      Json.record
        [
          ("type", Some (`String "formatText"));
          ("bold", Option.map Json.of_bool case.bold);
          ("find", Option.map Json.of_string case.find);
          ("italic", Option.map Json.of_bool case.italic);
          ("occurrence", Option.map Json.of_int case.occurrence);
          ("paragraph", Some (Json.of_string case.paragraph));
          ("strikethrough", Option.map Json.of_bool case.strikethrough);
          ("underline", Option.map Json.of_bool case.underline);
        ]
  | Insert_paragraph case ->
      Json.record
        [
          ("type", Some (`String "insertParagraph"));
          ("after", Option.map Json.of_string case.after);
          ("before", Option.map Json.of_string case.before);
          ("style", Option.map Json.of_string case.style);
          ("text", Some (Json.of_string case.text));
        ]
  | Delete case ->
      Json.record
        [
          ("type", Some (`String "delete"));
          ("id", Some (Json.of_string case.id));
        ]
  | Set_style case ->
      Json.record
        [
          ("type", Some (`String "setStyle"));
          ("paragraph", Some (Json.of_string case.paragraph));
          ("style", Some (Json.of_string case.style));
        ]
  | Add_comment case ->
      Json.record
        [
          ("type", Some (`String "addComment"));
          ("find", Option.map Json.of_string case.find);
          ("occurrence", Option.map Json.of_int case.occurrence);
          ("paragraph", Some (Json.of_string case.paragraph));
          ("text", Some (Json.of_string case.text));
        ]
  | Unknown json -> json

let make_word_document_operation_replace_text ~(find : string) ?occurrence
    ~(paragraph : string) ~(replace : string) () =
  (Replace_text { find; occurrence; paragraph; replace }
    : word_document_operation)

let make_word_document_operation_set_text ~(paragraph : string) ~(text : string)
    () =
  (Set_text { paragraph; text } : word_document_operation)

let make_word_document_operation_format_text ?bold ?find ?italic ?occurrence
    ~(paragraph : string) ?strikethrough ?underline () =
  (Format_text
     { bold; find; italic; occurrence; paragraph; strikethrough; underline }
    : word_document_operation)

let make_word_document_operation_insert_paragraph ?after ?before ?style
    ~(text : string) () =
  (Insert_paragraph { after; before; style; text } : word_document_operation)

let make_word_document_operation_delete ~(id : string) () =
  (Delete { id } : word_document_operation)

let make_word_document_operation_set_style ~(paragraph : string)
    ~(style : string) () =
  (Set_style { paragraph; style } : word_document_operation)

let make_word_document_operation_add_comment ?find ?occurrence
    ~(paragraph : string) ~(text : string) () =
  (Add_comment { find; occurrence; paragraph; text } : word_document_operation)

