type nonrec create_document_reply_data = {
  document_metadata : document_response_metadata_with_content;
      (** The document metadata. *)
  presigned_url : string option;
      (** Presigned upload URL, when the caller still needs to upload bytes. *)
  content_type : string;
      (** Content type of the document converted from file type. *)
  file_type : string option;  (** The file type of the document. *)
