  | Bad_request of op_refusal_response  (** HTTP 400. *)
  | Unauthorized of error_response  (** HTTP 401. *)
  | Forbidden of error_response  (** HTTP 403. *)
  | Not_found of error_response  (** HTTP 404. *)
  | Conflict of error_response  (** HTTP 409. *)
  | Internal_server_error of error_response  (** HTTP 500. *)

and edit_document_with_ai_error =
  | Bad_request of error_response  (** HTTP 400. *)
  | Payment_required of ai_admission_error_body  (** HTTP 402. *)
  | Unprocessable_entity of document_ai_edit_refused  (** HTTP 422. *)
  | Internal_server_error of error_response  (** HTTP 500. *)
  | Bad_gateway of document_ai_edit_failed  (** HTTP 502. *)
  | Service_unavailable of ai_admission_error_body  (** HTTP 503. *)

and edit_canvas_with_ai_error =
  | Bad_request of canvas_error_body  (** HTTP 400. *)
  | Payment_required of ai_admission_error_body  (** HTTP 402. *)
  | Unprocessable_entity of canvas_error_body  (** HTTP 422. *)
  | Internal_server_error of canvas_error_body  (** HTTP 500. *)
  | Bad_gateway of canvas_error_body  (** HTTP 502. *)
  | Service_unavailable of ai_admission_error_body  (** HTTP 503. *)

and comment_on_document_text_error =
