  | Forbidden of error_response  (** HTTP 403. *)
  | Unprocessable_entity of comment_on_text_refused  (** HTTP 422. *)
  | Internal_server_error of error_response  (** HTTP 500. *)
  | Bad_gateway of error_response  (** HTTP 502. *)

and export_document_error =
  | Status_304 of generic_error_response  (** HTTP 304. *)
  | Unauthorized of generic_error_response  (** HTTP 401. *)
  | Not_found of generic_error_response  (** HTTP 404. *)
  | Conflict of error_response  (** HTTP 409. *)
  | Internal_server_error of generic_error_response  (** HTTP 500. *)

and get_document_markdown_error =
