(** [POST /databases/webhooks/{token}]

Insert rows through a webhook. The body is a JSON object, one row, or
an array of up to 100 objects, one row each. Keys name columns by name
(ignoring case) or id; [null] leaves a cell empty. Values may be loose:
["45"] for a number, ["true"] for a checkbox, a label or labels for a
select, [2026-10-09] for a date. Nothing is written unless every row fits. *)
let deliver_database_webhook ~(token : string) ~(body : Yojson.Safe.t) () =
  ({
     Request.service = "storage";
     operation = "deliver_database_webhook";
     meth = `POST;
     path =
       String.concat ""
         [
           "/databases/webhooks/"; Request.segment ((fun value -> value) token);
         ];
     query = List.filter (fun (_, values) -> values <> []) [];
     headers =
       List.concat_map
         (fun (name, values) -> List.map (fun v -> (name, v)) values)
         [];
     body = Some (Request.Json (Json.of_json body));
     decode_reply = Request.json database_webhook_delivery_response_of_yojson;
     decode_error =
       (fun ~status body ->
         match status with
         | 400 ->
             Some
               (Bad_request
                  (invalid_database_webhook_payload_response_of_yojson
                     (Yojson.Safe.from_string body))
                 : deliver_database_webhook_error)
         | 403 ->
             Some
               (Forbidden
                  (error_response_of_yojson (Yojson.Safe.from_string body))
                 : deliver_database_webhook_error)
         | 404 ->
             Some
               (Not_found
                  (error_response_of_yojson (Yojson.Safe.from_string body))
                 : deliver_database_webhook_error)
         | 500 ->
             Some
               (Internal_server_error
                  (error_response_of_yojson (Yojson.Safe.from_string body))
                 : deliver_database_webhook_error)
         | _ -> None);
   }
    : ( database_webhook_delivery_response,
        deliver_database_webhook_error )
      Macro_sdk_runtime.Request.t)

