     body = None;
     decode_reply = Request.json undo_change_response_of_yojson;
     decode_error =
       Request.error_json [ 401; 403; 404; 409; 500 ] error_response_of_yojson;
   }
    : (undo_change_response, error_response) Macro_sdk_runtime.Request.t)

