(** [POST /documents/{document_id}/ai-edit]

Edit a markdown document or task by instructions with the caller's edit
access. Runs EditDocument's pipeline as a live collaborator, with its AI
admission and billing. *)
let edit_document_with_ai ~(document_id : string) ~(instructions : string) ?fast
    () =
  ({
     Request.service = "storage";
     operation = "edit_document_with_ai";
     meth = `POST;
     path =
       String.concat ""
         [
           "/documents/";
           Request.segment ((fun value -> value) document_id);
           "/ai-edit";
         ];
     query = List.filter (fun (_, values) -> values <> []) [];
     headers =
       List.concat_map
         (fun (name, values) -> List.map (fun v -> (name, v)) values)
         [];
     body =
       Some
         (Request.Json
            (yojson_of_document_ai_edit_request
               ({ fast; instructions } : document_ai_edit_request)));
     decode_reply = Request.json document_ai_edited_of_yojson;
     decode_error =
       (fun ~status body ->
         match status with
         | 400 ->
             Some
               (Bad_request
                  (error_response_of_yojson (Yojson.Safe.from_string body))
                 : edit_document_with_ai_error)
         | 402 ->
             Some
               (Payment_required
                  (ai_admission_error_body_of_yojson
                     (Yojson.Safe.from_string body))
                 : edit_document_with_ai_error)
         | 422 ->
             Some
               (Unprocessable_entity
                  (document_ai_edit_refused_of_yojson
                     (Yojson.Safe.from_string body))
                 : edit_document_with_ai_error)
         | 500 ->
             Some
               (Internal_server_error
                  (error_response_of_yojson (Yojson.Safe.from_string body))
                 : edit_document_with_ai_error)
         | 502 ->
             Some
               (Bad_gateway
                  (document_ai_edit_failed_of_yojson
                     (Yojson.Safe.from_string body))
                 : edit_document_with_ai_error)
         | 503 ->
             Some
               (Service_unavailable
                  (ai_admission_error_body_of_yojson
                     (Yojson.Safe.from_string body))
                 : edit_document_with_ai_error)
         | _ -> None);
   }
    : ( document_ai_edited,
        edit_document_with_ai_error )
      Macro_sdk_runtime.Request.t)

