                 : edit_spreadsheet_with_ai_error)
         | 402 ->
             Some
               (Payment_required
                  (ai_admission_error_body_of_yojson
                     (Yojson.Safe.from_string body))
                 : edit_spreadsheet_with_ai_error)
         | 409 ->
             Some
               (Conflict
                  (error_response_of_yojson (Yojson.Safe.from_string body))
                 : edit_spreadsheet_with_ai_error)
         | 422 ->
             Some
               (Unprocessable_entity
                  (document_ai_edit_refused_of_yojson
                     (Yojson.Safe.from_string body))
                 : edit_spreadsheet_with_ai_error)
         | 500 ->
             Some
               (Internal_server_error
                  (error_response_of_yojson (Yojson.Safe.from_string body))
                 : edit_spreadsheet_with_ai_error)
         | 502 ->
             Some
               (Bad_gateway
                  (document_ai_edit_failed_of_yojson
                     (Yojson.Safe.from_string body))
                 : edit_spreadsheet_with_ai_error)
         | 503 ->
             Some
               (Service_unavailable
                  (ai_admission_error_body_of_yojson
                     (Yojson.Safe.from_string body))
                 : edit_spreadsheet_with_ai_error)
         | _ -> None);
   }
    : ( spreadsheet_ai_edited,
